$archivosmasivo=array('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
$archivospermitidos=array('image/jpeg','image/png','image/gif','application/pdf','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain','application/x-zip-compressed','application/octet-stream','image/heic');


$app->get('/almacenes', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $almacenes=[];
    $result = $conexion->query("SELECT
        t_almacen.idalmacen,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        t_almacen.idciudad,
        t_ciudad.ciudad,
        t_almacen.direccion
        FROM
        t_almacen
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_ciudad.idempresa=$idempresa;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $almacenes[]=array(
            'idalmacen'=>(int)$row['idalmacen'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'idciudad'=>(int)$row['idciudad'],
            'ciudad'=>$row['ciudad'],
            'direccion'=>$row['direccion']
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'almacenes' => $almacenes
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/almacenes/{idalmacen}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idalmacen = $args['idalmacen'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $almacen_ubicaciones=[];
    $result = $conexion->query("WITH tmp_items as (
        SELECT 
        t_ate_gas_ubicacion.idalmacendetalle,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas', t_ate_gas_ubicacion.idate_gas,
                'chasis', t_ate_gas.chasis
            )
        ) AS items
        FROM 
        t_ate_gas_ubicacion
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle AND t_almacendetalle.idalmacen=$idalmacen
        LEFT JOIN t_ate_gas ON t_ate_gas_ubicacion.idate_gas=t_ate_gas.idate_gas
        WHERE
        t_ate_gas_ubicacion.fecha_salida IS NULL
        GROUP BY
        t_ate_gas_ubicacion.idalmacendetalle)
        select 
        t_almacendetalle.idalmacendetalle,
        t_almacendetalle.nombre,
        IFNULL(t_almacendetalle.ubicacion_unica,0) as ubicacion_unica,
        IFNULL(tmp_items.items,'[]') as items
        FROM 
        t_almacendetalle
        LEFT JOIN tmp_items ON t_almacendetalle.idalmacendetalle=tmp_items.idalmacendetalle
        WHERE 
        t_almacendetalle.idalmacen=$idalmacen
        AND t_almacendetalle.activo=1 
        AND t_almacendetalle.tipo=1 
        ORDER BY 
        t_almacendetalle.nombre;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $almacen_ubicaciones[]=array(
            'idalmacendetalle'=>(int)$row['idalmacendetalle'],
            'ubicacion'=>$row['nombre'],
            'ubicacion_unica'=>boolval($row['ubicacion_unica']),
            'items'=>json_decode($row['items'],true),
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'almacen_ubicaciones' => $almacen_ubicaciones
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/almacenes/{idalmacen}/{fechacorte}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idalmacen = $args['idalmacen'];
    $fechacorte = $args['fechacorte'];
    
    $inventarioactual  = getInventario(0, $idalmacen, $fechacorte, $conexion, true, false,$fechacorte,false);
    
    $almacen=[];
    $result = $conexion->query("SELECT
        t_almacen.idalmacen,
        t_almacen.almacen,
        t_almacen.idciudad,
        t_ciudad.ciudad,
        t_almacen.direccion,
        IFNULL(t_almacen.filas,0) as filas,
        IFNULL(t_almacen.columnas,0) as columnas
        FROM
        t_almacen
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_almacen.idalmacen=$idalmacen;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $detalle=[];
        $resultdetalle = $conexion->query("SELECT
            t_almacendetalle.idalmacendetalle,
            t_almacendetalle.idalmacen,
            t_almacendetalle.filainicial,
            t_almacendetalle.columnainicial,
            t_almacendetalle.tipo,
            t_almacendetalle.idtipoalmacendetalle,
            t_tipoalmacendetalle.tipoalmacendetalle,
            t_almacendetalle.sector,
            t_almacendetalle.texto,
            t_almacendetalle.columna,
            t_almacendetalle.nombre,
            t_almacendetalle.filafinal,
            t_almacendetalle.columnafinal,
            IFNULL(t_almacendetalle.lineasuperior,0) as lineasuperior,
            IFNULL(t_almacendetalle.color,'transparent') as color,
            IFNULL(t_almacendetalle.ubicacion_unica,0) as ubicacion_unica,
            IFNULL(t_almacendetalle.bloqueado,0) as bloqueado
            from
            t_almacendetalle
            LEFT JOIN t_tipoalmacendetalle ON t_almacendetalle.idtipoalmacendetalle=t_tipoalmacendetalle.idtipoalmacendetalle
            WHERE 
            IFNULL(t_almacendetalle.activo,0)=1
            AND t_almacendetalle.idalmacen=$idalmacen;");
        while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
            $items=[];
            
            $cantidadtotal=0;
            foreach ($inventarioactual as $inventario) {
                if((int)$inventario["idalmacendetalle"]==(int)$rowdetalle["idalmacendetalle"] && (float)$inventario['cantidad']>=0.01){
                    $items[]=array(
                        'idingresodetalle'=>$inventario['idingresodetalle'],
                        'cliente'=>$inventario['cliente'],
                        'codigo'=>$inventario['codigo'],
                        'serie'=>$inventario['serie'],
                        'categoria'=>$inventario['categoria'],
                        'centro_distribucion'=>$inventario['centro_distribucion'],
                        'lote'=>$inventario['lote'],
                        'descripcion'=>$inventario['descripcion'],
                        'fechavencimiento'=>$inventario['fechavencimiento'],
                        'cantidad'=>$inventario['cantidad'],
                        'codigoembalaje'=>$inventario['codigoembalaje'],
                        'bultos'=>$inventario['bultos'],
                        'peso'=>$inventario['peso'],
                        'cantidad_no_conf'=>$inventario['cantidad_no_conf'],
                        'numeroingreso'=>$inventario['numeroingreso'],
                        'fechaingreso'=>$inventario['fechaingreso'],
                        'color'=>$inventario['color']
                    );
                    
                    $cantidadtotal=$cantidadtotal+(float)$inventario['cantidad'];
                }
            }
            
            if(count($items)>0 && $cantidadtotal>=0.01){
                if(count(array_unique(array_column($items, 'color')))==1){
                    $color=$items[0]['color'];
                }else{
                    $color='#f5b384';
                }

            }else{
                $color=$rowdetalle['color'];
            }
            
            
            $detalle[]=array(
                'idalmacendetalle'=>$rowdetalle['idalmacendetalle'],
                'idalmacen'=>$rowdetalle['idalmacen'],
                'filainicial'=>$rowdetalle['filainicial'],
                'columnainicial'=>$rowdetalle['columnainicial'],
                'tipo'=>$rowdetalle['tipo'],
                'idtipoalmacendetalle'=>$rowdetalle['idtipoalmacendetalle'],
                'tipoalmacendetalle'=>$rowdetalle['tipoalmacendetalle'],
                'sector'=>$rowdetalle['sector'],
                'texto'=>$rowdetalle['texto'],
                'columna'=>$rowdetalle['columna'],
                'nombre'=>$rowdetalle['nombre'],
                'filafinal'=>$rowdetalle['filafinal'],
                'columnafinal'=>$rowdetalle['columnafinal'],
                'lineasuperior'=> boolval($rowdetalle['lineasuperior']),
                'color'=>$color,
                'ubicacion_unica'=> boolval($rowdetalle['ubicacion_unica']),
                'bloqueado'=> $rowdetalle['bloqueado'],
                'uid'=>$rowdetalle['filainicial']."-".$rowdetalle['columnainicial'],
                'items'=>$items
            );
        }
        
        
        $filas=[];
        for($f=0;$f<$row['filas'];$f++){
            $columnas=[];
            for($c=0;$c<$row['columnas'];$c++){
                $idalmacendetalle=0;
                $tipo=0;
                $idtipoalmacendetalle=null;
                $tipoalmacendetalle='';
                $sector='';
                $texto='';
                $columna='';
                $nombrecorto='';
                $nombre='';
                $filafinal='';
                $columnafinal='';
                $color='transparent';
                $habilitado=false;
                $items=[];
                $key = array_search($f."-".$c, array_column($detalle, 'uid'));
                if(is_numeric($key)){
                    if((int)$detalle[$key]["tipo"]==1){
                        $habilitado=true;
                        if($detalle[$key]["ubicacion_unica"]=="true" && count($detalle[$key]["items"])>=1){
                            $habilitado=false;
                        }
                        if((int)$detalle[$key]["bloqueado"]==1){
                            $habilitado=false;
                        }
                    }
                    $idalmacendetalle=$detalle[$key]["idalmacendetalle"];
                    $tipo=$detalle[$key]["tipo"];
                    $idtipoalmacendetalle=$detalle[$key]["idtipoalmacendetalle"];
                    $tipoalmacendetalle=$detalle[$key]["tipoalmacendetalle"];
                    $sector=$detalle[$key]["sector"];
                    $texto=$detalle[$key]["texto"];
                    $columna=$detalle[$key]["columna"];
                    $nombre=$detalle[$key]["nombre"];
                    $filafinal=$detalle[$key]["filafinal"];
                    $columnafinal=$detalle[$key]["columnafinal"];
                    $color=$detalle[$key]["color"];
                    $ubicacion_unica=$detalle[$key]["ubicacion_unica"];
                    $lineasuperior=$detalle[$key]["lineasuperior"];
                    $items=$detalle[$key]["items"];
                }
                $columnas[]=array(
                    'idalmacendetalle'=>$idalmacendetalle,
                    'tipo'=>$tipo,
                    'idtipoalmacendetalle'=>$idtipoalmacendetalle,
                    'tipoalmacendetalle'=>$tipoalmacendetalle,
                    'sector'=>$sector,
                    'texto'=>$texto,
                    'columna'=>$columna,
                    'nombre'=>$nombre,
                    'color'=>$color,
                    'ubicacion_unica'=>$ubicacion_unica,
                    'habilitado'=>$habilitado,
                    'lineasuperior'=>$lineasuperior,
                    'items'=>$items
                );
            }
            $filas[]=$columnas;
        }
        
        
        
        $almacen=array(
            'idalmacen'=>(int)$row['idalmacen'],
            'almacen'=>$row['almacen'],
            'idciudad'=>(int)$row['idciudad'],
            'ciudad'=>$row['ciudad'],
            'direccion'=>$row['direccion'],
            //'filas'=>(int)$row['filas'],
            //'columnas'=>(int)$row['columnas'],
            'detalle'=>$filas
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'almacen' => $almacen,
        'inventarioactual'=>$inventarioactual
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/almacenes/historial/detalle/{idingresodetalle}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idingresodetalle = $args['idingresodetalle'];
    $historial_inicial=array();
    
    $idingresodetallepadre=$idingresodetalle;
    do {
        $actual=false;
        if($idingresodetallepadre==$idingresodetalle){
            $actual=true;
        }
        
        $resultsalidas = $conexion->query("SELECT
            'SALIDA' as tipomovimiento,
            CONCAT(t_salida.numero,'/',t_salida.gestion) as numero,
            t_salidadetalle.cantidad,
            t_salidadetalle.cantidad_no_conf,
            t_salidadetalle.peso,
            t_salidadetalle.observaciones,
            t_salida.fecha as fechamovimiento
            FROM
            t_salidadetalle
            LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
            WHERE 
            t_salidadetalle.idingresodetalle=$idingresodetallepadre;");
        while ($rowsalidas =  $resultsalidas ->fetch(PDO::FETCH_ASSOC)){
            $historial_inicial[]=array(
                'tipomovimiento'=>$rowsalidas['tipomovimiento'],
                'idtipomovimiento'=>3,
                'numero'=>$rowsalidas['numero'],
                'cantidad'=>$rowsalidas['cantidad'],
                'cantidad_no_conf'=>$rowsalidas['cantidad_no_conf'],
                //'no_conf'=>$rowdiv['no_conf'],
                //'merma'=>$rowdiv['merma'],
                //'relacion_caja'=>$rowdiv['relacion_caja'],
                'peso'=>$rowsalidas['peso'],
                //'temperatura'=>$rowdiv['temperatura'],
                'observaciones'=>$rowsalidas['observaciones'],
                'fechamovimiento'=>$rowsalidas['fechamovimiento'],
                'actual'=>false
            );
        }
        
        $resultdiv = $conexion->query("SELECT 
            IF(t_ingresodetalle.idingresodetallepadre IS NULL,'INGRESO','') as tipomovimiento,
            IF(t_ingresodetalle.idingresodetallepadre IS NULL,CONCAT(t_ingreso.numero,'/',t_ingreso.gestion),'') as numero,
            t_ingresodetalle.cantidad,
            t_ingresodetalle.cantidad_no_conf,
            t_no_conf.no_conf,
            t_merma.merma,
            t_ingresodetalle.relacion_caja,
            t_ingresodetalle.peso,
            t_ingresodetalle.temperatura,
            t_ingresodetalle.observaciones,
            IFNULL(IF(t_ingresodetalle.idingresodetallepadre IS NULL,t_ingreso.fecha,t_ingresodetalle.dividido),CURRENT_TIMESTAMP()) as fechamovimiento,
            t_ingresodetalle.idingresodetallepadre
            FROM 
            t_ingresodetalle 
            LEFT JOIN t_no_conf ON t_ingresodetalle.idno_conf=t_no_conf.idno_conf
            LEFT JOIN t_merma ON t_ingresodetalle.idmerma=t_merma.idmerma
            LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
            WHERE 
            t_ingresodetalle.idingresodetalle=$idingresodetallepadre;");
        while ($rowdiv =  $resultdiv ->fetch(PDO::FETCH_ASSOC)){
            $fechamovimiento=$rowdiv['fechamovimiento'];
            $cantidadotros="";
            $pesootros="";
            if((int)$rowdiv["idingresodetallepadre"]>0){
                $cantidaditems=0;
                $resultcant = $conexion->query("SELECT 
                    COUNT(idingresodetalle) as cantidaditems,
                    GROUP_CONCAT(cantidad SEPARATOR '+') as cantidadotros,
                    GROUP_CONCAT(peso SEPARATOR '+') as pesootros
                    FROM 
                    t_ingresodetalle 
                    WHERE 
                    idingresodetallepadre=".$rowdiv["idingresodetallepadre"]." AND idingresodetalle<>$idingresodetallepadre;");
                while ($rowcant =  $resultcant ->fetch(PDO::FETCH_ASSOC)){
                    $cantidaditems=(int)$rowcant["cantidaditems"];
                    $cantidadotros=$rowcant['cantidadotros'];
                    $pesootros=$rowcant['pesootros'];
                }
                if($cantidaditems>0){
                    $tipomovimiento="DIVISION";
                    $idtipomovimiento=2;
                }else{
                    $tipomovimiento="EDICION";
                    $idtipomovimiento=1;
                    $cantidadotros='';
                    $pesootros='';
                }
                    
                
                $resultcant = $conexion->query("SELECT 
                    dividido
                    FROM 
                    t_ingresodetalle 
                    WHERE 
                    idingresodetalle=".$rowdiv["idingresodetallepadre"].";");
                while ($rowcant =  $resultcant ->fetch(PDO::FETCH_ASSOC)){
                    $fechamovimiento=$rowcant["dividido"];
                }
                
                
            }else{
                $idtipomovimiento=0;
                $tipomovimiento="INGRESO";
            }
            
                
            
            
            $historial_inicial[]=array(
                'tipomovimiento'=>$tipomovimiento,
                'idtipomovimiento'=>$idtipomovimiento,
                'numero'=>$rowdiv['numero'],
                'cantidad'=>$rowdiv['cantidad'],
                'cantidadotros'=>$cantidadotros,
                'cantidad_no_conf'=>$rowdiv['cantidad_no_conf'],
                'no_conf'=>$rowdiv['no_conf'],
                'merma'=>$rowdiv['merma'],
                'relacion_caja'=>$rowdiv['relacion_caja'],
                'peso'=>$rowdiv['peso'],
                'pesootros'=>$pesootros,
                'temperatura'=>$rowdiv['temperatura'],
                'observaciones'=>$rowdiv['observaciones'],
                'fechamovimiento'=>$fechamovimiento,
                'actual'=>$actual
            );
            $idingresodetallepadre=(int)$rowdiv['idingresodetallepadre'];
        }

        
    } while ($idingresodetallepadre>0);
    
    $historial= array_orderby($historial_inicial, 'fechamovimiento', SORT_ASC);
    
    for($it=0;$it<count($historial);$it++){
        if($historial[$it]["idtipomovimiento"]==0 || $historial[$it]["idtipomovimiento"]==1 || $historial[$it]["idtipomovimiento"]==2){
            $saldo=(float)$historial[$it]["cantidad"];
            $saldopeso=(float)$historial[$it]["peso"];
        }
        if($historial[$it]["idtipomovimiento"]==3){
            $saldo=$saldo-(float)$historial[$it]["cantidad"];
            $saldopeso=$saldopeso-(float)$historial[$it]["peso"];
        }
        $historial[$it]["saldo"]=$saldo;
        $historial[$it]["saldopeso"]=$saldopeso;
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'historial' => $historial
    )));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

    
