$app->get('/ingresos/{idcliente}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $filtrocliente='';
    
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=(int)$rowcliente["idcliente"];
    }
    
    
    if($idclientenum>0){
        $filtrocliente="AND t_ingreso.idcliente=$idclientenum";
    }
    
    
    $ingresos=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_cantidadsinubicacion;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_cantidadsinubicacion (idingreso INT, cantidadsinubicacion INT);");
    $conexion->query("INSERT INTO tmp_cantidadsinubicacion (idingreso, cantidadsinubicacion)
        select
        t_ingresodetalle.idingreso,
        COUNT(t_ingresodetalle.idingresodetalle) as cantidadsinubicacion
        from
        t_ingresodetalle
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN t_ubicacionitem ON t_ingresodetalle.idingresodetalle=t_ubicacionitem.idingresodetalle
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        WHERE 
        t_ingreso.idalmacen='".$decoded_array['idalmacen']."'
        AND t_cliente.idempresa=$idempresa 
        $filtrocliente
        AND IFNULL(t_ubicacionitem.idubicacionitem,0)=0
        GROUP BY
        t_ingresodetalle.idingreso;");
    $conexion->query("ALTER TABLE tmp_cantidadsinubicacion ADD INDEX idingreso (idingreso);");
    
    $result = $conexion->query("SELECT 
        t_ingreso.idingreso,
        t_ingreso.idalmacen,
        t_ingreso.numero,
        t_ingreso.gestion,
        t_ingreso.fecha,
        t_ingreso.idcliente,
        t_cliente.cliente,
        IFNULL(t_ingreso.es_vehiculo,0) as es_vehiculo,
        t_ingreso.rubro_producto,
        t_ingreso.no_contrato,
        t_ingreso.piezas_manifestadas,
        t_ingreso.peso_total,
        t_ingreso.proveedor,
        t_ingreso.dui,
        t_ingreso.cantidad_pallet,
        t_ingreso.hora_inicio,
        t_ingreso.hora_fin,
        t_tipocamion.tipocamion,
        t_tipocontenedor.tipocontenedor,
        t_ingreso.idtipoingreso,
        t_tipoingreso.tipoingreso,
        IFNULL(tmp_cantidadsinubicacion.cantidadsinubicacion,0) as cantidadsinubicacion,
        t_ingreso.partida,
        t_ingreso.fecha_cierre_transito,
        t_ingreso.fecha_emision_parte,
        t_ingreso.invoice
        from 
        t_ingreso
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN t_tipocamion ON t_ingreso.idtipocamion=t_tipocamion.idtipocamion
        LEFT JOIN t_tipocontenedor ON t_ingreso.idtipocontenedor=t_tipocontenedor.idtipocontenedor
        LEFT JOIN t_tipoingreso ON t_ingreso.idtipoingreso=t_tipoingreso.idtipoingreso
        LEFT JOIN tmp_cantidadsinubicacion ON t_ingreso.idingreso=tmp_cantidadsinubicacion.idingreso
        WHERE
        t_ingreso.idalmacen='".$decoded_array['idalmacen']."'
        AND t_cliente.idempresa=$idempresa 
        $filtrocliente
        ORDER BY
        t_ingreso.fecha DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $acomodado=true;
        if((int)$row["cantidadsinubicacion"]>0){
            $acomodado=false;
        }
        
        
        
        
        $ingresos[]=array(
            'idingreso'=>(int)$row['idingreso'],
            'idalmacen'=>$row['idalmacen'],
            'numero'=>(int)$row['numero'],
            'gestion'=>$row['gestion'],
            'numeroingreso'=>$row['numero']."/".$row['gestion'],
            'fecha'=>$row['fecha'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'es_vehiculo'=> boolval($row['es_vehiculo']),
            'rubro_producto'=>$row['rubro_producto'],
            'no_contrato'=>$row['no_contrato'],
            'piezas_manifestadas'=>$row['piezas_manifestadas'],
            'peso_total'=>$row['peso_total'],
            'proveedor'=>$row['proveedor'],
            'dui'=>$row['dui'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'hora_inicio'=>$row['hora_inicio'],
            'hora_fin'=>$row['hora_fin'],
            'tipocamion'=>$row['tipocamion'],
            'tipocontenedor'=>$row['tipocontenedor'],
            'idtipoingreso'=>$row['idtipoingreso'],
            'tipoingreso'=>$row['tipoingreso'],
            'partida'=>$row['partida'],
            'fecha_cierre_transito'=>$row['fecha_cierre_transito'],
            'fecha_emision_parte'=>$row['fecha_emision_parte'],
            'invoice'=>$row['invoice'],
            'acomodado'=>$acomodado
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'ingresos'=>$ingresos
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyRole(1, 1))->add($verifyToken);

$app->get('/ingresos/pendientes/{idcliente}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    $idalmacen=$decoded_array['idalmacen'];
    
    $filtrocliente='';
    
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=(int)$rowcliente["idcliente"];
    }
    
    
    if($idclientenum>0){
        $filtrocliente="AND t_salida.idcliente=$idclientenum";
    }
    
    
    $ingresos=[];
    $result = $conexion->query("WITH tmp_inventario_pendiente as (SELECT
        t_salidadetalle_accesorios_pendiente.idsalidadetalle,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idaccesorios_vehiculos', t_salidadetalle_accesorios_pendiente.idaccesorios_vehiculos,
                'accesorios_vehiculos', t_accesorios_vehiculos.accesorios_vehiculos,
                'cantidad', t_salidadetalle_accesorios_pendiente.cantidad,
                'texto', t_salidadetalle_accesorios_pendiente.texto
            )
        ) AS accesorios_vehiculos
        FROM
        t_salidadetalle_accesorios_pendiente
        LEFT JOIN t_salidadetalle ON t_salidadetalle_accesorios_pendiente.idsalidadetalle=t_salidadetalle.idsalidadetalle
        LEFT JOIN t_accesorios_vehiculos ON t_salidadetalle_accesorios_pendiente.idaccesorios_vehiculos=t_accesorios_vehiculos.idaccesorios_vehiculos
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        LEFT JOIN t_ingreso ON t_salida.idsalida=t_ingreso.idsalida_origen
        WHERE
        t_salida.movimiento=1
        AND t_salida.finalizado=1
         $filtrocliente
        AND t_salida.idalmacen_destino=$idalmacen
        AND t_ingreso.idingreso IS NULL
        AND t_salidadetalle_accesorios_pendiente.deleted_at IS NULL
        GROUP BY
        t_salidadetalle_accesorios_pendiente.idsalidadetalle
        ), tmp_chasis as (
        SELECT
        t_salidadetalle.idsalida,
        JSON_ARRAYAGG(
          JSON_OBJECT(
              'idsalidadetalle', t_salidadetalle.idsalidadetalle,
              'chasis', t_ingresodetalle.serie,
              'modelo', t_ingresodetalle.modelo,
              'marca', t_ingresodetalle.marca,
              'color', t_ingresodetalle.color,
              'kilometraje', t_salidadetalle.kilometraje_pendiente,
              'tiene_danios', IF(t_salidadetalle.tiene_danios_pendiente = 1, TRUE, FALSE),
              'danios', t_salidadetalle.danios_pendiente,
              'tiene_faltante', IF(t_salidadetalle.tiene_faltante_pendiente = 1, TRUE, FALSE),
              'faltante', t_salidadetalle.faltante_pendiente,
              'accesorios_vehiculos', COALESCE(tmp_inventario_pendiente.accesorios_vehiculos, JSON_ARRAY())
          )
        ) AS chasis
        FROM
        t_salidadetalle
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
        LEFT JOIN t_ingreso ON t_salida.idsalida=t_ingreso.idsalida_origen
        LEFT JOIN tmp_inventario_pendiente ON t_salidadetalle.idsalidadetalle=tmp_inventario_pendiente.idsalidadetalle
        WHERE
        t_salida.movimiento=1
        AND t_salida.finalizado=1
        $filtrocliente
        AND t_salida.idalmacen_destino=$idalmacen
        AND t_ingreso.idingreso IS NULL
        GROUP BY
        t_salidadetalle.idsalida)
        SELECT 
        t_salida.idsalida,
        md5(t_salida.idsalida) as codigo_salida,
        t_salida.numero,
        t_salida.gestion,
        t_salida.fecha,
        t_salida.idcliente,
        t_cliente.cliente,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        t_movilizador.movilizador,
        tmp_chasis.chasis
        FROM 
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN t_almacen ON t_salida.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_movilizador ON t_salida.idmovilizador=t_movilizador.idmovilizador
        LEFT JOIN tmp_chasis ON t_salida.idsalida=tmp_chasis.idsalida
        LEFT JOIN t_ingreso ON t_salida.idsalida=t_ingreso.idsalida_origen
        WHERE 
        t_salida.movimiento=1
        AND t_salida.finalizado=1
        $filtrocliente
        AND t_salida.idalmacen_destino=$idalmacen
        AND t_ingreso.idingreso IS NULL;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $ingresos[]=array(
            'idsalida'=>(int)$row['idsalida'],
            'codigo_salida'=>$row['codigo_salida'],
            'numero'=>(int)$row['numero'],
            'gestion'=>$row['gestion'],
            'numerosalida'=>$row['numero']."/".$row['gestion'],
            'fecha'=>$row['fecha'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'movilizador'=>$row['movilizador'],
            'chasis'=>json_decode($row['chasis'], true),
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'ingresos'=>$ingresos
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyRole(1, 1))->add($verifyToken);

$app->get('/ingresos/reporte/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
