        $filtrocliente=" AND t_ingreso.idcliente=$idcliente ";
    }
    
    $ingresos=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ultimaubicacion;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_ultimaubicacion (idubicacionitem INT, idingresodetalle INT);");
    $conexion->query("INSERT INTO tmp_ultimaubicacion (idubicacionitem, idingresodetalle)
        SELECT
        MAX(idubicacionitem) as idubicacionitem,
        idingresodetalle
        FROM
        t_ubicacionitem
        GROUP BY
        idingresodetalle;");
    $conexion->query("ALTER TABLE tmp_ultimaubicacion ADD INDEX idubicacionitem (idubicacionitem);");
    $conexion->query("ALTER TABLE tmp_ultimaubicacion ADD INDEX idingresodetalle (idingresodetalle);");
    
    $result = $conexion->query("SELECT
