$app->get('/ingresos/detalle/{idingreso}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idingreso = $args['idingreso'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $ingreso=array();
    $result = $conexion->query("SELECT
        t_ingreso.idingreso,
        t_ingreso.numero,
        t_ingreso.gestion,
        t_ingreso.idalmacen,
        t_ingreso.idcliente,
        t_cliente.cliente,
        IFNULL(t_ingreso.es_vehiculo, 0) as es_vehiculo,
        IFNULL(t_ingreso.idcliente_destino,0) as idcliente_destino,
        t_cliente_destino.cliente as cliente_destino,
        t_ingreso.envio_api,
        IFNULL(t_ingreso.respuesta_api,'') as respuesta_api,
        IF(IFNULL(t_ingreso.idcliente_destino,0)=0,0,IF(t_ingreso.envio_api IS NULL,0,1)) as reportado_api,
        DATE_FORMAT(t_ingreso.fecha,'%Y-%m-%dT%H:%i') as fecha,
        t_ingreso.placa,
        t_ingreso.contenedor,
        t_ingreso.idtipoingreso,
        t_tipoingreso.tipoingreso,
        t_ingreso.precinto,
        t_ingreso.idtipodescarga,
        t_tipodescarga.tipodescarga,
        t_ingreso.idtipocamion,
        t_tipocamion.tipocamion,
        t_ingreso.idtipocontenedor,
        t_tipocontenedor.tipocontenedor,
        t_ingreso.idtipoproducto,
        t_tipoproducto.tipoproducto,
        t_ingreso.piezas_manifestadas,
        t_ingreso.peso_total,
        t_ingreso.proveedor,
        t_ingreso.no_contrato,
        t_ingreso.delivery_batch,
        t_ingreso.rubro_producto,
        t_ingreso.project,
        t_ingreso.invoice,
        t_ingreso.dui,
        t_ingreso.cantidad_pallet,
        t_ingreso.cantidad_cajas,
        t_ingreso.hora_inicio,
        t_ingreso.hora_fin,
        IFNULL(t_ingreso.cantidad_estibadores,0) as cantidad_estibadores,
        t_ingreso.nota_adicional,
        CONCAT(t_ingreso.fechasistema,'T',DATE_FORMAT(t_ingreso.horasistema,'%H:%i')) as fechasistema,
        t_ingreso.idusuario_recibido,
        t_usuario.nombre as usuario_recibido,
        t_usuario.ci as ci_recibido,
        t_ingreso.nombre_entrega,
        t_ingreso.ci_entrega,
        t_ingreso.empresa_entrega,
        t_ingreso.partida,
        t_ingreso.fecha_cierre_transito,
        t_ingreso.fecha_emision_parte,
        t_ingreso.idsalida_origen
        from
        t_ingreso
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN t_cliente as t_cliente_destino ON t_ingreso.idcliente_destino=t_cliente_destino.idcliente
        LEFT JOIN t_tipocamion ON t_ingreso.idtipocamion=t_tipocamion.idtipocamion
        LEFT JOIN t_tipoingreso ON t_ingreso.idtipoingreso=t_tipoingreso.idtipoingreso
        LEFT JOIN t_tipocontenedor ON t_ingreso.idtipocontenedor=t_tipocontenedor.idtipocontenedor
        LEFT JOIN t_tipodescarga ON t_ingreso.idtipodescarga=t_tipodescarga.idtipodescarga
        LEFT JOIN t_tipoproducto ON t_ingreso.idtipoproducto=t_tipoproducto.idtipoproducto
        LEFT JOIN t_usuario ON t_ingreso.idusuario_recibido=t_usuario.idusuario
        WHERE 
        t_ingreso.idingreso=$idingreso;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $adjuntos=[];
        $ruta = folder_files.$idempresa.DIRECTORY_SEPARATOR."almacen/adjuntos_ingresos/$idingreso/";
        if(file_exists($ruta)){
            $directorio = opendir($ruta);
            $iddocumento=0;
            while ($documento = readdir($directorio)){
                if (!is_dir($documento)){
                    $iddocumento++;
                    $adjuntos[] = array(
                        'iddocumento' => $iddocumento,
                        'documento' => $documento
                    );
                }
            }
        }

        
        $ingreso=array(
            'idingreso'=>(int)$row['idingreso'],
            'idalmacen'=>(int)$row['idalmacen'],
            'numero'=>(int)$row['numero'],
            'gestion'=>(int)$row['gestion'],
            'numeroingreso'=>$row['numero']."/".$row['gestion'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'es_vehiculo'=> boolval($row['es_vehiculo']),
            'idcliente_destino'=>$row['idcliente_destino'],
            'cliente_destino'=>$row['cliente_destino'],
            'envio_api'=>$row['envio_api'],
            'respuesta_api'=>$row['respuesta_api'],
            'reportado_api'=> boolval($row['reportado_api']),
            'fecha'=>$row['fecha'],
            'placa'=>$row['placa'],
            'contenedor'=>$row['contenedor'],
            'idtipoingreso'=>$row['idtipoingreso'],
            'tipoingreso'=>$row['tipoingreso'],
            'precinto'=>$row['precinto'],
            'idtipodescarga'=>$row['idtipodescarga'],
            'tipodescarga'=>$row['tipodescarga'],
            'idtipocamion'=>(int)$row['idtipocamion'],
