            'piezas_manifestadas'=>$row['piezas_manifestadas'],
            'peso_total'=>$row['peso_total'],
            'proveedor'=>$row['proveedor'],
            'no_contrato'=>$row['no_contrato'],
            'delivery_batch'=>$row['delivery_batch'],
            'rubro_producto'=>$row['rubro_producto'],
            'project'=>$row['project'],
            'invoice'=>$row['invoice'],
            'dui'=>$row['dui'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'cantidad_cajas'=>$row['cantidad_cajas'],
            'hora_inicio'=>$row['hora_inicio'],
            'hora_fin'=>$row['hora_fin'],
            'cantidad_estibadores'=>(int)$row['cantidad_estibadores'],
            'nota_adicional'=>$row['nota_adicional'],
            'fechasistema'=>$row['fechasistema'],
            'idusuario_recibido'=>(int)$row['idusuario_recibido'],
            'usuario_recibido'=>$row['usuario_recibido'],
            'nombre_entrega'=>$row['nombre_entrega'],
            'ci_recibido'=>$row['ci_recibido'],
            'ci_entrega'=>$row['ci_entrega'],
            'empresa_entrega'=>$row['empresa_entrega'],
            'partida'=>$row['partida'],
            'fecha_cierre_transito'=>$row['fecha_cierre_transito'],
            'fecha_emision_parte'=>$row['fecha_emision_parte'],
            'idsalida_origen'=>(int)$row['idsalida_origen'],
            'detalle'=> getDetalleIngreso($idingreso, $conexion),
            'adjuntos'=>$adjuntos
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'ingreso' => $ingreso
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyRole(1, 1))->add($verifyToken);

$app->put('/ingresos/{idingreso}', function(Request $request, Response $response, array $args) use ($conexion) {

    $idingreso = $args['idingreso'] ?? null;

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'No se guardó la información';

    $conmovimiento = [];
    $guardar_fecha = false;
    $id_asgard = 0;
    $respuesta = null;

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'] ?? '';

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idusuario = $decoded_array["idusuario"] ?? null;
        $asgard_almacen = $decoded_array["asgard_almacen"] ?? false;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros
        |--------------------------------------------------------------------------
        */
        $params = json_decode((string) $request->getBody(), true);

        if (!is_array($params)) {
            $mensaje = 'No se recibieron parámetros válidos';
            $continuar = false;
        }

        if ($continuar) {

            $idcliente = $params['idcliente'] ?? null;
            $idcliente_destino = $params['idcliente_destino'] ?? '';
            $fecha = empty($params['fecha']) ? null : str_replace("T", " ", $params['fecha']);

            $placa = $params['placa'] ?? '';
            $contenedor = $params['contenedor'] ?? '';
            $idtipoingreso = empty($params['idtipoingreso']) ? null : $params['idtipoingreso'];
            $precinto = $params['precinto'] ?? '';
            $idtipodescarga = $params['idtipodescarga'] ?? null;
            $idtipocamion = $params['idtipocamion'] ?? null;
            $idtipocontenedor = $params['idtipocontenedor'] ?? null;
            $idtipoproducto = $params['idtipoproducto'] ?? null;
            $piezas_manifestadas = $params['piezas_manifestadas'] ?? '';
            $peso_total = $params['peso_total'] ?? '';
            $proveedor = $params['proveedor'] ?? '';
            $no_contrato = $params['no_contrato'] ?? '';
            $delivery_batch = $params['delivery_batch'] ?? '';
            $rubro_producto = $params['rubro_producto'] ?? '';
            $project = $params['project'] ?? '';
            $invoice = $params['invoice'] ?? '';
            $dui = $params['dui'] ?? '';
            $cantidad_pallet = $params['cantidad_pallet'] ?? '';
            $cantidad_cajas = $params['cantidad_cajas'] ?? '';
            $hora_inicio = $params['hora_inicio'] ?? '';
            $hora_fin = $params['hora_fin'] ?? '';
            $cantidad_estibadores = $params['cantidad_estibadores'] ?? '';
            $nota_adicional = $params['nota_adicional'] ?? '';
            $idusuario_recibido = $params['idusuario_recibido'] ?? null;
            $nombre_entrega = $params['nombre_entrega'] ?? '';
            $ci_entrega = $params['ci_entrega'] ?? '';
            $empresa_entrega = $params['empresa_entrega'] ?? '';
            $partida = $params['partida'] ?? '';

            $fecha_cierre_transito = empty($params['fecha_cierre_transito'])
                ? null
                : $params['fecha_cierre_transito'];

            $fecha_emision_parte = empty($params['fecha_emision_parte'])
                ? null
                : $params['fecha_emision_parte'];

            $detalle = $params['detalle'] ?? [];

            $fechasistematotal = $params['fechasistema'] ?? date('Y-m-d\TH:i:s');
            $fechasistematotalsplit = explode("T", $fechasistematotal);

            $fechasistema = $fechasistematotalsplit[0] ?? date('Y-m-d');
            $horasistema = $fechasistematotalsplit[1] ?? date('H:i:s');
            $horasistema = substr(str_replace("Z", "", $horasistema), 0, 8);
        }

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if ($continuar && empty($idingreso)) {
            $mensaje = 'No se recibió el ingreso';
            $continuar = false;
        }

        if ($continuar && empty($idusuario)) {
            $mensaje = 'No se recibió el usuario';
            $continuar = false;
        }

        if ($continuar && empty($idcliente)) {
            $mensaje = 'No se recibió el cliente';
            $continuar = false;
        }

        if ($continuar && empty($fecha)) {
            $mensaje = 'No se recibió la fecha';
            $continuar = false;
        }

        if ($continuar && !is_array($detalle)) {
            $mensaje = 'El detalle recibido no tiene un formato válido';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Validar si se intenta eliminar un detalle con movimiento
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idsDetalleRecibidosInicial = [];

            foreach ($detalle as $itemDetalle) {
                $idTmp = $itemDetalle['idingresodetalle'] ?? 0;

                if ((int)$idTmp > 0) {
                    $idsDetalleRecibidosInicial[] = (int)$idTmp;
                }
            }

            $queryDetallesActuales = "
                SELECT
                    idingresodetalle,
                    codigo,
                    cantidad
                FROM t_ingresodetalle
                WHERE idingreso = :idingreso
                  AND IFNULL(idingresodetallepadre, 0) = 0
            ";

            $stmtDetallesActuales = $conexion->prepare($queryDetallesActuales);
            $stmtDetallesActuales->execute([
                ':idingreso' => $idingreso
            ]);

            $stmtCountSalidas = $conexion->prepare("
                SELECT COUNT(idsalidadetalle) AS total
                FROM t_salidadetalle
                WHERE idingresodetalle = :idingresodetalle
            ");

            $stmtDividido = $conexion->prepare("
                SELECT LENGTH(IFNULL(dividido, '')) AS dividido
                FROM t_ingresodetalle
                WHERE idingresodetalle = :idingresodetalle
            ");

            while ($rowDelete = $stmtDetallesActuales->fetch(PDO::FETCH_ASSOC)) {

                $idDetalleActual = (int)$rowDelete['idingresodetalle'];

                if (!in_array($idDetalleActual, $idsDetalleRecibidosInicial)) {

                    $stmtCountSalidas->execute([
                        ':idingresodetalle' => $idDetalleActual
                    ]);

                    $rowSalidas = $stmtCountSalidas->fetch(PDO::FETCH_ASSOC);
                    $totalSalidas = (int)($rowSalidas['total'] ?? 0);

                    $stmtDividido->execute([
                        ':idingresodetalle' => $idDetalleActual
                    ]);

                    $rowDividido = $stmtDividido->fetch(PDO::FETCH_ASSOC);
                    $dividido = (int)($rowDividido['dividido'] ?? 0);

                    if (($totalSalidas + $dividido) > 0) {
                        $conmovimiento[] = array(
                            'codigo' => $rowDelete['codigo'],
                            'cantidad' => $rowDelete['cantidad']
                        );
                    }
                }
            }

            if (count($conmovimiento) > 0) {
                $mensaje = 'No se puede eliminar uno o más detalles porque tienen movimiento';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Función auxiliar para actualizar hijos divididos
        |--------------------------------------------------------------------------
        */
        $actualizarHijosDivididos = function($idsPadres) use ($conexion, &$continuar, &$mensaje) {

            while ($continuar && count($idsPadres) > 0) {

                $placeholders = [];

                foreach ($idsPadres as $index => $idPadre) {
                    $placeholders[] = ':idpadre_' . $index;
                }

                $inPadres = implode(',', $placeholders);

                $queryActualizarHijos = "
                    UPDATE t_ingresodetalle a
                    INNER JOIN t_ingresodetalle b
                        ON a.idingresodetallepadre = b.idingresodetalle
                    SET
                        a.codigo = b.codigo,
                        a.serie = b.serie,
                        a.descripcion = b.descripcion,
                        a.centro_distribucion = b.centro_distribucion,
                        a.categoria = b.categoria,
                        a.idembalaje = b.idembalaje,
                        a.lote = b.lote,
                        a.fechavencimiento = b.fechavencimiento,
                        a.relacion_caja = b.relacion_caja,
                        a.temperatura = b.temperatura,
                        a.modelo = b.modelo,
                        a.marca = b.marca,
                        a.color = b.color,
                        a.partida_especifica = b.partida_especifica,
                        a.invoice = b.invoice,
                        a.no_dim = b.no_dim,
                        a.fecha_pase_salida = b.fecha_pase_salida,
                        a.edited_by = b.edited_by,
                        a.edited_at = b.edited_at
                    WHERE a.idingresodetallepadre IN ($inPadres)
                ";

                $stmtActualizarHijos = $conexion->prepare($queryActualizarHijos);

                foreach ($idsPadres as $index => $idPadre) {
                    $stmtActualizarHijos->bindValue(':idpadre_' . $index, (int)$idPadre, PDO::PARAM_INT);
                }

                $ok = $stmtActualizarHijos->execute();

                if (!$ok) {
                    $mensaje = 'No se pudo actualizar los detalles divididos';
                    $continuar = false;
                    break;
                }

                $queryBuscarHijosDivididos = "
                    SELECT
                        idingresodetalle,
                        IF(dividido IS NULL, 0, 1) AS dividido
                    FROM t_ingresodetalle
                    WHERE idingresodetallepadre IN ($inPadres)
                ";

                $stmtBuscarHijos = $conexion->prepare($queryBuscarHijosDivididos);

                foreach ($idsPadres as $index => $idPadre) {
                    $stmtBuscarHijos->bindValue(':idpadre_' . $index, (int)$idPadre, PDO::PARAM_INT);
                }

                $stmtBuscarHijos->execute();

                $idsSiguienteNivel = [];

                while ($rowHijo = $stmtBuscarHijos->fetch(PDO::FETCH_ASSOC)) {
                    if ((int)$rowHijo['dividido'] === 1) {
                        $idsSiguienteNivel[] = (int)$rowHijo['idingresodetalle'];
                    }
                }

                $idsPadres = $idsSiguienteNivel;
            }
        };

        /*
        |--------------------------------------------------------------------------
        | Guardar cambios
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            /*
            |--------------------------------------------------------------------------
            | Actualizar cabecera de ingreso
            |--------------------------------------------------------------------------
            */
            $queryIngreso = "
                UPDATE t_ingreso
                SET
                    idcliente = :idcliente,
                    idcliente_destino = :idcliente_destino,
                    fecha = :fecha,
                    placa = :placa,
                    contenedor = :contenedor,
                    idtipoingreso = :idtipoingreso,
