                    empresa_entrega = :empresa_entrega,
                    partida = :partida,
                    fecha_cierre_transito = :fecha_cierre_transito,
                    fecha_emision_parte = :fecha_emision_parte
                WHERE idingreso = :idingreso
            ";

            $stmtIngreso = $conexion->prepare($queryIngreso);

            $okIngreso = $stmtIngreso->execute([
                ':idcliente' => $idcliente,
                ':idcliente_destino' => $idcliente_destino,
                ':fecha' => $fecha,
                ':placa' => $placa,
                ':contenedor' => $contenedor,
                ':idtipoingreso' => $idtipoingreso,
                ':precinto' => $precinto,
                ':idtipodescarga' => $idtipodescarga,
                ':idtipocamion' => $idtipocamion,
                ':idtipocontenedor' => $idtipocontenedor,
                ':idtipoproducto' => $idtipoproducto,
                ':piezas_manifestadas' => $piezas_manifestadas,
                ':peso_total' => $peso_total,
                ':proveedor' => $proveedor,
                ':no_contrato' => $no_contrato,
                ':delivery_batch' => $delivery_batch,
                ':rubro_producto' => $rubro_producto,
                ':project' => $project,
                ':invoice' => $invoice,
                ':dui' => $dui,
                ':cantidad_pallet' => $cantidad_pallet,
                ':cantidad_cajas' => $cantidad_cajas,
                ':hora_inicio' => $hora_inicio,
                ':hora_fin' => $hora_fin,
                ':cantidad_estibadores' => $cantidad_estibadores,
                ':nota_adicional' => $nota_adicional,
                ':fechasistema' => $fechasistema,
                ':horasistema' => $horasistema,
                ':idusuario_recibido' => $idusuario_recibido,
                ':nombre_entrega' => $nombre_entrega,
                ':ci_entrega' => $ci_entrega,
                ':empresa_entrega' => $empresa_entrega,
                ':partida' => $partida,
                ':fecha_cierre_transito' => $fecha_cierre_transito,
                ':fecha_emision_parte' => $fecha_emision_parte,
                ':idingreso' => $idingreso
            ]);

            if (!$okIngreso) {
                $mensaje = 'No se pudo actualizar la cabecera del ingreso';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
