                SET
                    cantidad = :cantidad,
                    observaciones = :observaciones
                WHERE idingresodetalle_accesorios = :idingresodetalle_accesorios
                  AND idingresodetalle = :idingresodetalle
            ");

            $stmtDeleteAccesorio = $conexion->prepare("
                DELETE FROM t_ingresodetalle_accesorios
                WHERE idingresodetalle_accesorios = :idingresodetalle_accesorios
                  AND idingresodetalle = :idingresodetalle
            ");

            $idsDetalleRecibidos = [];
        }

        /*
        |--------------------------------------------------------------------------
        | Insertar / actualizar detalle
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            foreach ($detalle as $itemDetalle) {

                $idingresodetalle = $itemDetalle['idingresodetalle'] ?? 0;

                $fechavencimiento = empty($itemDetalle['fechavencimiento'])
                    ? null
                    : $itemDetalle['fechavencimiento'];

