                    ? null
                    : $itemDetalle['idclasificacion'];

                $idmerma = empty($itemDetalle['idmerma'])
                    ? null
                    : $itemDetalle['idmerma'];

                $iddoc_errada = empty($itemDetalle['iddoc_errada'])
                    ? null
                    : $itemDetalle['iddoc_errada'];

                $fecha_pase_salida = empty($itemDetalle['fecha_pase_salida'])
                    ? null
                    : $itemDetalle['fecha_pase_salida'];

                $dataDetalle = [
                    ':codigo' => $itemDetalle['codigo'] ?? '',
                    ':serie' => $itemDetalle['serie'] ?? '',
                    ':descripcion' => $itemDetalle['descripcion'] ?? '',
                    ':centro_distribucion' => $itemDetalle['centro_distribucion'] ?? '',
                    ':categoria' => $itemDetalle['categoria'] ?? '',
                    ':cantidad' => $itemDetalle['cantidad'] ?? 0,
                    ':idembalaje' => $itemDetalle['idembalaje'] ?? null,
                    ':lote' => $itemDetalle['lote'] ?? '',
                    ':bultos' => $itemDetalle['bultos'] ?? 0,
                    ':costo_un' => $itemDetalle['costo_un'] ?? 0,
                    ':cantidad_no_conf' => $itemDetalle['cantidad_no_conf'] ?? 0,
                    ':idno_conf' => $idno_conf,
                    ':idclasificacion' => $idclasificacion,
                    ':idmerma' => $idmerma,
                    ':fechavencimiento' => $fechavencimiento,
                    ':relacion_caja' => $itemDetalle['relacion_caja'] ?? '',
                    ':volumen' => $itemDetalle['volumen'] ?? 0,
                    ':peso' => $itemDetalle['peso'] ?? 0,
                    ':pallet' => $itemDetalle['pallet'] ?? '',
                    ':temperatura' => $itemDetalle['temperatura'] ?? '',
                    ':iddoc_errada' => $iddoc_errada,
                    ':observaciones' => $itemDetalle['observaciones'] ?? '',
                    ':modelo' => $itemDetalle['modelo'] ?? '',
                    ':marca' => $itemDetalle['marca'] ?? '',
                    ':color' => $itemDetalle['color'] ?? '',
                    ':partida_especifica' => $itemDetalle['partida_especifica'] ?? '',
                    ':invoice' => $itemDetalle['invoice'] ?? '',
                    ':no_dim' => $itemDetalle['no_dim'] ?? '',
                    ':fecha_pase_salida' => $fecha_pase_salida
                ];

                if ((int)$idingresodetalle === 0) {

                    $dataInsert = $dataDetalle;
                    $dataInsert[':idingreso'] = $idingreso;
                    $dataInsert[':created_by'] = $idusuario;

                    $okDetalle = $stmtInsertDetalle->execute($dataInsert);

                    if (!$okDetalle) {
                        $mensaje = 'No se pudo registrar un detalle del ingreso';
                        $continuar = false;
                        break;
                    }

                    $idingresodetalleNuevo = (int)$conexion->lastInsertId();

                    /*
                    Importante:
                    Se agrega el ID nuevo para que no sea eliminado al sincronizar.
                    */
                    $idsDetalleRecibidos[] = $idingresodetalleNuevo;

                    $idDetalleParaRelaciones = $idingresodetalleNuevo;

                } else {

                    $idsDetalleRecibidos[] = (int)$idingresodetalle;

                    $dataUpdate = $dataDetalle;
                    $dataUpdate[':idingresodetalle'] = $idingresodetalle;
                    $dataUpdate[':idingreso'] = $idingreso;
                    $dataUpdate[':edited_by'] = $idusuario;

                    $okDetalle = $stmtUpdateDetalle->execute($dataUpdate);

                    if (!$okDetalle) {
                        $mensaje = 'No se pudo actualizar un detalle del ingreso';
                        $continuar = false;
                        break;
                    }

                    $idDetalleParaRelaciones = (int)$idingresodetalle;
                }

                /*
                |--------------------------------------------------------------------------
                | Ubicación del item
                |--------------------------------------------------------------------------
                */
                if ($continuar) {

                    $idalmacendetalle = $itemDetalle['idalmacendetalle'] ?? 0;

                    if ((int)$idalmacendetalle > 0) {

                        if ((int)$idingresodetalle === 0) {

                            $okUbicacion = $stmtInsertUbicacion->execute([
                                ':idingresodetalle' => $idDetalleParaRelaciones,
                                ':idalmacendetalle' => $idalmacendetalle
                            ]);

                            if (!$okUbicacion) {
                                $mensaje = 'No se pudo registrar la ubicación del detalle';
                                $continuar = false;
                                break;
                            }

                        } else {

                            $stmtUbicacionActual->execute([
                                ':idingresodetalle' => $idDetalleParaRelaciones
                            ]);

                            $rowUbicacion = $stmtUbicacionActual->fetch(PDO::FETCH_ASSOC);

                            $idubicacionitemactual = $rowUbicacion ? (int)$rowUbicacion['idubicacionitem'] : 0;
                            $idalmacendetalleactual = $rowUbicacion ? (int)$rowUbicacion['idalmacendetalle'] : 0;

                            if ((int)$idalmacendetalle !== $idalmacendetalleactual) {

                                if ($idubicacionitemactual > 0) {
                                    $okCerrarUbicacion = $stmtCerrarUbicacion->execute([
                                        ':idubicacionitem' => $idubicacionitemactual
                                    ]);

                                    if (!$okCerrarUbicacion) {
                                        $mensaje = 'No se pudo cerrar la ubicación anterior';
                                        $continuar = false;
                                        break;
                                    }
                                }

                                $okUbicacion = $stmtInsertUbicacion->execute([
                                    ':idingresodetalle' => $idDetalleParaRelaciones,
                                    ':idalmacendetalle' => $idalmacendetalle
                                ]);

                                if (!$okUbicacion) {
                                    $mensaje = 'No se pudo registrar la nueva ubicación';
                                    $continuar = false;
                                    break;
                                }
                            }
                        }
                    }
                }

                /*
                |--------------------------------------------------------------------------
                | Actualizar hijos divididos si corresponde
                |--------------------------------------------------------------------------
                */
                if ($continuar && (int)($itemDetalle['dividido'] ?? 0) > 0 && (int)$idingresodetalle > 0) {
                    $actualizarHijosDivididos([(int)$idingresodetalle]);

                    if (!$continuar) {
                        break;
                    }
                }

                /*
                |--------------------------------------------------------------------------
                | Accesorios del vehículo
                |--------------------------------------------------------------------------
                */
                if ($continuar) {

                    $accesorios = $itemDetalle['accesorios_vehiculos'] ?? [];

                    if (!is_array($accesorios)) {
                        $accesorios = [];
                    }

                    foreach ($accesorios as $accesorio) {

                        $marcado = !empty($accesorio['marcado']);
                        $idingresodetalle_accesorios = $accesorio['idingresodetalle_accesorios'] ?? 0;
                        $idaccesorios_vehiculos = $accesorio['idaccesorios_vehiculos'] ?? null;
                        $cantidadAccesorio = $accesorio['cantidad'] ?? '';
                        $observacionesAccesorio = $accesorio['observaciones'] ?? '';

                        if ($marcado) {

                            if (empty($idaccesorios_vehiculos)) {
                                $mensaje = 'Un accesorio no tiene identificador';
                                $continuar = false;
                                break;
                            }

                            if ((int)$idingresodetalle_accesorios === 0) {

                                $okAccesorio = $stmtInsertAccesorio->execute([
                                    ':idingresodetalle' => $idDetalleParaRelaciones,
                                    ':idaccesorios_vehiculos' => $idaccesorios_vehiculos,
                                    ':cantidad' => $cantidadAccesorio,
                                    ':observaciones' => $observacionesAccesorio
                                ]);

                            } else {

                                $okAccesorio = $stmtUpdateAccesorio->execute([
                                    ':cantidad' => $cantidadAccesorio,
                                    ':observaciones' => $observacionesAccesorio,
                                    ':idingresodetalle_accesorios' => $idingresodetalle_accesorios,
                                    ':idingresodetalle' => $idDetalleParaRelaciones
                                ]);
                            }

                            if (!$okAccesorio) {
                                $mensaje = 'No se pudo guardar un accesorio del vehículo';
                                $continuar = false;
                                break;
                            }

                        } else {

                            if ((int)$idingresodetalle_accesorios > 0) {

                                $okAccesorio = $stmtDeleteAccesorio->execute([
                                    ':idingresodetalle_accesorios' => $idingresodetalle_accesorios,
                                    ':idingresodetalle' => $idDetalleParaRelaciones
                                ]);

                                if (!$okAccesorio) {
                                    $mensaje = 'No se pudo eliminar un accesorio del vehículo';
                                    $continuar = false;
                                    break;
                                }
                            }
                        }
                    }

                    if (!$continuar) {
                        break;
                    }
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Eliminar detalles que ya no llegaron
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $stmtDetallesActualesEliminar = $conexion->prepare("
                SELECT idingresodetalle
                FROM t_ingresodetalle
                WHERE idingreso = :idingreso
                  AND IFNULL(idingresodetallepadre, 0) = 0
            ");

            $stmtDetallesActualesEliminar->execute([
                ':idingreso' => $idingreso
            ]);

            $stmtDeleteAccesoriosDetalle = $conexion->prepare("
                DELETE FROM t_ingresodetalle_accesorios
                WHERE idingresodetalle = :idingresodetalle
            ");

            $stmtDeleteUbicacionDetalle = $conexion->prepare("
                DELETE FROM t_ubicacionitem
                WHERE idingresodetalle = :idingresodetalle
            ");

            $stmtDeleteDetalle = $conexion->prepare("
                DELETE FROM t_ingresodetalle
                WHERE idingresodetalle = :idingresodetalle
                  AND idingreso = :idingreso
                  AND IFNULL(idingresodetallepadre, 0) = 0
            ");

            while ($rowDelete = $stmtDetallesActualesEliminar->fetch(PDO::FETCH_ASSOC)) {

                $idDetalleActual = (int)$rowDelete['idingresodetalle'];

                if (!in_array($idDetalleActual, $idsDetalleRecibidos)) {

                    $okDeleteAccesorios = $stmtDeleteAccesoriosDetalle->execute([
                        ':idingresodetalle' => $idDetalleActual
                    ]);

                    if (!$okDeleteAccesorios) {
                        $mensaje = 'No se pudieron eliminar accesorios del detalle';
                        $continuar = false;
                        break;
                    }

                    $okDeleteUbicacion = $stmtDeleteUbicacionDetalle->execute([
                        ':idingresodetalle' => $idDetalleActual
                    ]);

                    if (!$okDeleteUbicacion) {
                        $mensaje = 'No se pudo eliminar la ubicación del detalle';
                        $continuar = false;
                        break;
                    }

                    $okDeleteDetalle = $stmtDeleteDetalle->execute([
                        ':idingresodetalle' => $idDetalleActual,
                        ':idingreso' => $idingreso
                    ]);

                    if (!$okDeleteDetalle) {
                        $mensaje = 'No se pudo eliminar un detalle del ingreso';
                        $continuar = false;
                        break;
                    }
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar o revertir transacción
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

        } else {

            if ($conexion->inTransaction()) {
                $conexion->rollBack();
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Integración ASGARD posterior al guardado
        |--------------------------------------------------------------------------
        | Se ejecuta después del commit para no dejar la transacción abierta
        | por una llamada externa.
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $stmtInfoIngreso = $conexion->prepare("
                SELECT
                    i.es_vehiculo,
                    c.id_asgard
                FROM t_ingreso i
                LEFT JOIN t_cliente c
                    ON i.idcliente = c.idcliente
                WHERE i.idingreso = :idingreso
            ");

            $stmtInfoIngreso->execute([
                ':idingreso' => $idingreso
            ]);

            $rowInfo = $stmtInfoIngreso->fetch(PDO::FETCH_ASSOC);

            $es_vehiculo = (int)($rowInfo['es_vehiculo'] ?? 0);
            $id_asgard = (int)($rowInfo['id_asgard'] ?? 0);

            if ($es_vehiculo > 0 && $asgard_almacen && $id_asgard > 0 && trim($partida) !== '') {

                $guardar_fecha = true;

                try {
                    $integracionesASAGRD = new IntegracionesASAGRD();
                    $respuesta = $integracionesASAGRD->guardarFechaIngresoVehiculos($id_asgard, $partida, $fecha);
                } catch (Throwable $e) {
                    $respuesta = array(
                        'error' => true,
                        'mensaje' => $e->getMessage()
                    );
                }
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información general';
        }

    } catch (PDOException $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error de base de datos: ' . $e->getMessage();

    } catch (Exception $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error general: ' . $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'detalle' => getDetalleIngreso($idingreso, $conexion),
        'conmovimiento' => $conmovimiento,
        'guardar_fecha' => $guardar_fecha,
        'id_asgard' => $id_asgard,
        'partida' => $partida ?? '',
        'fecha' => $fecha ?? '',
        'respuesta' => $respuesta
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

$app->post('/ingresos', function(Request $request, Response $response, array $args) use ($conexion) {
    $params = json_decode((string) $request->getBody(),true);
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $idingreso=0;
    
    $idcliente=$params["idcliente"];
    $idcliente_destino=$params["idcliente_destino"];
    $es_vehiculo=$params["es_vehiculo"] ? 1 : 0;
    $idtipocamion=$params["es_vehiculo"] ? 17 : "null";
    
    $idclientenum=0;
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=(int)$rowcliente["idcliente"];
    }
    
    $idcliente_destinonum=0;
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente_destino';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idcliente_destinonum=(int)$rowcliente["idcliente"];
    }
    
    
    
    try {
        $conexion->beginTransaction();

        $query = "
            INSERT INTO t_ingreso (
                numero,
                gestion,
                idalmacen,
                idusuario_recibido,
                fecha,
                fechasistema,
                horasistema,
                idtipocontenedor,
                idcliente,
                es_vehiculo,
                idtipocamion,
                idcliente_destino
            )
            SELECT
                (
                    SELECT IFNULL(MAX(numero) + 1, 1)
                    FROM t_ingreso
                    WHERE gestion = YEAR(CURRENT_DATE())
                    AND idalmacen = :idalmacen_numero
                ) AS numero,
                YEAR(CURRENT_DATE()) AS gestion,
                :idalmacen AS idalmacen,
                :idusuario AS idusuario_recibido,
                CURRENT_TIMESTAMP() AS fecha,
                CURRENT_DATE() AS fechasistema,
                CURRENT_TIME() AS horasistema,
                1 AS idtipocontenedor,
                :idcliente AS idcliente,
                :es_vehiculo AS es_vehiculo,
                :idtipocamion AS idtipocamion,
                :idcliente_destino AS idcliente_destino
        ";

        $stmt = $conexion->prepare($query);

        $result = $stmt->execute([
            ':idalmacen_numero' => $decoded_array["idalmacen"],
            ':idalmacen' => $decoded_array["idalmacen"],
            ':idusuario' => $decoded_array["idusuario"],
            ':idcliente' => $idclientenum,
            ':es_vehiculo' => $es_vehiculo,
            ':idtipocamion' => $idtipocamion,
            ':idcliente_destino' => $idcliente_destinonum
        ]);

        if ($result) {
            $idingreso = $conexion->lastInsertId();

            $conexion->commit();

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información correctamente';
        } else {
            $conexion->rollBack();
        }

    } catch (PDOException $e) {
        $conexion->rollBack();

    }
    /*
    $query="insert into t_ingreso (numero,                                                                                                                                      gestion,                idalmacen,                          idusuario_recibido,                 fecha,                  fechasistema,   horasistema,    idtipocontenedor,   idcliente,              es_vehiculo,    idtipocamion,   idcliente_destino) 
                           SELECT (select ifnull(MAX(numero)+1,1) as numero from t_ingreso WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),   ".$decoded_array["idalmacen"].",    ".$decoded_array["idusuario"].",    CURRENT_TIMESTAMP(),    CURRENT_DATE(), current_time(), 1,                  $idclientenum,          $es_vehiculo,   $idtipocamion,  '".$idcliente_destinonum."';
            SELECT LAST_INSERT_ID() INTO @idingreso_nuevo;";
    
    
    $result = $conexion->exec($query);
    if($result){
        
        $result = $conexion->query("SELECT
            @idingreso_nuevo as idingreso;");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $idingreso=$row['idingreso'];
        }
        
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información Correctamente';
    }
    */
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'idingreso'=>$idingreso,
        'query'=>$query
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/ingresos/{idingreso}/cargamasiva', function(Request $request, Response $response, array $args) use ($conexion,$archivosmasivo) {
    $idingreso = $args['idingreso'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
    
    $codigo=400;
    $status='Error';
    $mensaje='El Archivo no se subio, probablemente sea mayor a 10MB';
    $xls_data=[];
    $mensajes_error=[];
    $nuevosdatos=[];
    //$embalaje=[];
    
    if(isset($_FILES['uploads'])){
        $nombredoc=$_FILES['uploads']["name"][0];
        //$random = bin2hex(openssl_random_pseudo_bytes(5));
        //$nombredoc=$random."_".$nombredoc;
        
        $piramideUploader=new PiramideUploader();
        $upload =$piramideUploader->upload($nombredoc, 'uploads', folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/'.$idingreso, $archivosmasivo, true);
        
        $file=$piramideUploader->getInfoFile();
        $file_name=$file['complete_name'];
        
        if(isset($upload) && $upload['uploaded']==false){
            $mensaje=$upload['error'];
        }else{
            $inputFileName = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/'.$idingreso.'/'.$file_name;
            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();
            $highestRow = $sheet->getHighestRow(); 
            $highestColumn = $sheet->getHighestColumn();
            $xls_data = $sheet->rangeToArray(
                'A2:' . $highestColumn . $highestRow,
                '',TRUE,TRUE
            );
            
            $embalajes=[];
            $resultembalaje = $conexion->query("select 
                idembalaje,
                codigoembalaje
                from 
                t_embalaje;");
            while ($rowembalaje =  $resultembalaje ->fetch(PDO::FETCH_ASSOC)){
                $embalajes[]=array(
                    'idembalaje'=>(int)$rowembalaje['idembalaje'],
                    'codigoembalaje'=>$rowembalaje['codigoembalaje']
                );
            }
            
            $baseproductos=[];
            $resultbaseproductos = $conexion->query("select 
                t_baseproductos.codigo,
                t_baseproductos.serie,
                t_baseproductos.descripcion,
                t_baseproductos.idembalaje
                from 
                t_baseproductos
                LEFT JOIN t_ingreso ON t_baseproductos.idcliente=t_ingreso.idcliente
                WHERE
                t_ingreso.idingreso=$idingreso;");
            while ($rowbaseproductos =  $resultbaseproductos ->fetch(PDO::FETCH_ASSOC)){
                $baseproductos[]=array(
                    'codigo'=>$rowbaseproductos['codigo'],
                    'serie'=>$rowbaseproductos['serie'],
                    'descripcion'=>$rowbaseproductos['descripcion'],
                    'idembalaje'=>(int)$rowbaseproductos['idembalaje'],
                    
                );
            }

            
            $datosinsertar='';
            for($ex=0;$ex<count($xls_data);$ex++){
                
                if($xls_data[$ex][8]!==''){
                    $fecha8explode= explode("/", $xls_data[$ex][8]);
                    $xls_data[$ex][8]=$fecha8explode[2]."-".sprintf("%02d", $fecha8explode[0])."-".sprintf("%02d", $fecha8explode[1]);
                }
                if($xls_data[$ex][9]!==''){
                    $fecha9explode= explode("/", $xls_data[$ex][9]);
                    $xls_data[$ex][9]=$fecha9explode[2]."-".sprintf("%02d", $fecha9explode[0])."-".sprintf("%02d", $fecha9explode[1]);
                }
                /*
                if($xls_data[$ex][4]=='' || $xls_data[$ex][4]==0){
                    $mensajes_error[]=array(
                        'fila'=>($ex+2),
                        'mensaje'=>'No tiene cantidad'
                    );
                }
                 * 
                 */
                $key = array_search($xls_data[$ex][5], array_column($embalajes, 'codigoembalaje'));
                if(is_numeric($key)){
                    $xls_data[$ex][5]=$embalajes[$key]['idembalaje'];
                }else{
                    $xls_data[$ex][5]=0;
                }
                
                $keycodigo = array_search($xls_data[$ex][0], array_column($baseproductos, 'codigo'));
                if(is_numeric($keycodigo)){
                    $xls_data[$ex][1]=$baseproductos[$keycodigo]['serie'];
                    $xls_data[$ex][2]=$baseproductos[$keycodigo]['descripcion'];
                    $xls_data[$ex][5]=$baseproductos[$keycodigo]['idembalaje'];
                }
            }

            
            $codigo=200;
            $status='Exito';
            $mensaje='El Archivo se subio correctamente';
        }

    }
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'xls_data'=>$xls_data
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/ingresos/{idingreso}/duplicar', function(Request $request, Response $response, array $args) use ($conexion) {
    $idingreso = $args['idingreso'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $idingreso_nuevo=0;
    
    $query="insert into t_ingreso (numero,
        gestion,
        idalmacen,
        idcliente,
        idcliente_destino,
        fecha,
        placa,
        contenedor,
        idtipoingreso,
        precinto,
        idtipodescarga,
        idtipocamion,
        idtipocontenedor,
        idtipoproducto,
        tipo_camion,
