    $correcto = false;

    // para poder borrar si falla algo
    $imagenes_guardadas = array();

    try {
        $conexion->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $conexion->setAttribute(PDO::ATTR_EMULATE_PREPARES, false);

        $conexion->beginTransaction();

        // =========================
        // 2) NORMALIZAR VARIABLES
        // =========================
        $tiene_daniosg   = !empty($params['tiene_danios']) ? 1 : 0;
        $daniosg         = $tiene_daniosg ? (string)$params['danios'] : '';

        $tiene_faltanteg = !empty($params['tiene_faltante']) ? 1 : 0;
        $faltanteg       = $tiene_faltanteg ? (string)$params['faltante'] : '';

        $kilometraje     = isset($params['kilometraje']) ? (string)$params['kilometraje'] : '';

        // =========================
        // 3) UPDATE t_salidadetalle
        // =========================
        $stmtUpdDetalle = $conexion->prepare("
            UPDATE t_salidadetalle
            SET
                tiene_danios_pendiente = :tiene_danios,
                danios_pendiente       = :danios,
                tiene_faltante_pendiente = :tiene_faltante,
                faltante_pendiente     = :faltante,
                kilometraje_pendiente  = :kilometraje
            WHERE idsalidadetalle = :idsalidadetalle
        ");

        $stmtUpdDetalle->execute(array(
            ':tiene_danios'     => $tiene_daniosg,
            ':danios'           => $daniosg,
            ':tiene_faltante'   => $tiene_faltanteg,
            ':faltante'         => $faltanteg,
            ':kilometraje'      => $kilometraje,
            ':idsalidadetalle'  => (int)$idsalidadetalle,
        ));

        // =========================
        // 4) LEER ACCESORIOS ACTUALES
        // =========================
        $stmtSelAcc = $conexion->prepare("
            SELECT idsalidadetalle_accesorios_pendiente, idaccesorios_vehiculos
            FROM t_salidadetalle_accesorios_pendiente
            WHERE idsalidadetalle = :idsalidadetalle
        ");
        $stmtSelAcc->execute(array(':idsalidadetalle' => (int)$idsalidadetalle));
        $accesorios_actuales = $stmtSelAcc->fetchAll(PDO::FETCH_ASSOC);

        // Para búsquedas rápidas
        $paramsAcc = isset($params["accesorios_vehiculos"]) ? $params["accesorios_vehiculos"] : array();

        // indexar params por idaccesorios_vehiculos
        $paramsAccById = array();
        foreach ($paramsAcc as $a) {
            if (isset($a['idaccesorios_vehiculos'])) {
                $paramsAccById[$a['idaccesorios_vehiculos']] = $a;
            }
        }

        // =========================
        // 5) UPDATE de los que existen (si también están en params)
        // =========================
        $stmtUpdAcc = $conexion->prepare("
            UPDATE t_salidadetalle_accesorios_pendiente
            SET cantidad = :cantidad, texto = :texto
            WHERE idsalidadetalle_accesorios_pendiente = :id_row
        ");

        foreach ($accesorios_actuales as $row) {
            $idAcc = $row['idaccesorios_vehiculos'];

            if (isset($paramsAccById[$idAcc])) {
                $stmtUpdAcc->execute(array(
                    ':cantidad' => $paramsAccById[$idAcc]['cantidad'],
                    ':texto'    => $paramsAccById[$idAcc]['texto'],
                    ':id_row'   => (int)$row['idsalidadetalle_accesorios_pendiente'],
                ));
            }
        }

        // =========================
        // 6) INSERT de los nuevos (están en params, no están en actuales)
        // =========================
        $actualesById = array();
        foreach ($accesorios_actuales as $row) {
            $actualesById[$row['idaccesorios_vehiculos']] = true;
        }

        $stmtInsAcc = $conexion->prepare("
            INSERT INTO t_salidadetalle_accesorios_pendiente
                (idsalidadetalle, idaccesorios_vehiculos, cantidad, texto, created_at)
            VALUES
                (:idsalidadetalle, :idacc, :cantidad, :texto, CURRENT_TIMESTAMP)
        ");

        foreach ($paramsAccById as $idAcc => $a) {
            if (!isset($actualesById[$idAcc])) {
                $stmtInsAcc->execute(array(
                    ':idsalidadetalle' => (int)$idsalidadetalle,
                    ':idacc'           => $idAcc,
                    ':cantidad'        => $a['cantidad'],
                    ':texto'           => $a['texto'],
                ));
            }
        }

