                throw new Exception("No se pudo crear la carpeta: " . $folderPath);
            }
        }

        $stmtImg = $conexion->prepare("
            INSERT INTO t_salidadetalleimagen_pendiente (idsalidadetalle, imagen)
            VALUES (:idsalidadetalle, :imagen)
        ");

        if (!empty($params['imagenes'])) {
            foreach ($params['imagenes'] as $imagen) {

                if (intval($imagen['idsalidadetalleimagen']) !== 0) {
                    continue;
                }

                $base64 = $imagen['itemImageSrc'];

                if (!preg_match('/^data:image\/(\w+);base64,/', $base64, $type)) {
                    continue;
                }

                $base64 = substr($base64, strpos($base64, ',') + 1);
                $extension = strtolower($type[1]);

                if (!in_array($extension, array('jpg', 'jpeg', 'png'))) {
                    continue;
                }

                $base64 = str_replace(' ', '+', $base64);
                $imageData = base64_decode($base64);

                if ($imageData === false) {
                    continue;
                }

                $imageName = uniqid('img_' . date('Ymd_His') . '_') . '.' . $extension;
                $imagePath = $folderPath . '/' . $imageName;

                // 1) Guardar archivo
                if (file_put_contents($imagePath, $imageData) === false) {
                    throw new Exception("No se pudo guardar la imagen: " . $imageName);
                }

                // Guardar para posible rollback de archivos
                $imagenes_guardadas[] = $imagePath;

                // 2) Insert en BD
                $stmtImg->execute(array(
                    ':idsalidadetalle' => (int)$idsalidadetalle,
                    ':imagen'          => $imageName,
                ));
            }
        }

        // Si todo OK
        $conexion->commit();

        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información Correctamente';

    } catch (Exception $e) {

        // rollback BD
        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        // rollback archivos (borrar imágenes guardadas)
        if (!empty($imagenes_guardadas)) {
            foreach ($imagenes_guardadas as $ruta) {
                if (file_exists($ruta)) {
                    @unlink($ruta); // @ para evitar warning si no puede borrar
                }
            }
        }

        

        // Opcional: log del error
        // error_log($e->getMessage());
