$app->post('/ingresos/pendientes/{idsalida}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idsalida = $args['idsalida'];
    $params = json_decode((string) $request->getBody(),true);
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $idingreso=0;
    
    $query="insert into t_ingreso (numero,                                                                                                                                      gestion,                idalmacen,                          idusuario_recibido,                 fecha,                  fechasistema,   horasistema,    idtipocontenedor,   idcliente,  es_vehiculo,    idtipocamion,               idsalida_origen) 
                           SELECT (select ifnull(MAX(numero)+1,1) as numero from t_ingreso WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),   ".$decoded_array["idalmacen"].",    ".$decoded_array["idusuario"].",    CURRENT_TIMESTAMP(),    CURRENT_DATE(), current_time(), 1,                  idcliente,  es_vehiculo,    IF(es_vehiculo=1,17,null),  $idsalida FROM t_salida WHERE idsalida=$idsalida;
            SELECT LAST_INSERT_ID() INTO @idingreso_nuevo;";
    
    $query=$query."INSERT INTO t_ingresodetalle (idingreso, codigo, serie, descripcion, cantidad, idembalaje, modelo, marca, color, created_by, created_at) 
        SELECT 
        @idingreso_nuevo,
        t_ingresodetalle.codigo,
        t_ingresodetalle.serie,
        t_ingresodetalle.descripcion,
        t_salidadetalle.cantidad,
        t_ingresodetalle.idembalaje,
        t_ingresodetalle.modelo,
        t_ingresodetalle.marca,
        t_ingresodetalle.color,
        ".$decoded_array["idusuario"].",
        CURRENT_TIMESTAMP()
        FROM 
        t_salidadetalle 
        LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
        WHERE 
        t_salidadetalle.idsalida=$idsalida;";
    
    $result = $conexion->exec($query);
    if($result){
        
        $result = $conexion->query("SELECT
            @idingreso_nuevo as idingreso;");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $idingreso=$row['idingreso'];
        }
        
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información Correctamente';
    }
    
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'idingreso'=>$idingreso,
        'query'=>$query
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/descarga/reporte/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $filtrocliente="";
    if((int)$idcliente>0){
        $filtrocliente=" AND t_ingreso.idcliente=$idcliente ";
    }
    
    
    $descarga=[];
    
    $result = $conexion->query("SELECT 
        t_ingreso.idingreso,
        t_ingreso.idalmacen,
        t_ingreso.numero,
        t_ingreso.gestion,
        t_ingreso.fecha,
        t_ingreso.idcliente,
        t_cliente.cliente,
        t_ingreso.rubro_producto,
        t_ingreso.no_contrato,
        t_ingreso.piezas_manifestadas,
        t_ingreso.peso_total,
        t_ingreso.proveedor,
        t_ingreso.dui,
        t_ingreso.cantidad_pallet,
        t_ingreso.cantidad_cajas,
        t_ingreso.hora_inicio,
        t_ingreso.hora_fin,
        t_tipocamion.tipocamion,
        t_tipocontenedor.tipocontenedor
        from 
        t_ingreso
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN t_tipocamion ON t_ingreso.idtipocamion=t_tipocamion.idtipocamion
        LEFT JOIN t_tipocontenedor ON t_ingreso.idtipocontenedor=t_tipocontenedor.idtipocontenedor
        WHERE
        t_ingreso.idalmacen=".$decoded_array['idalmacen']."
        AND CAST(t_ingreso.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        $filtrocliente
        ORDER BY
        t_ingreso.fecha DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $descarga[]=array(
            'idingreso'=>(int)$row['idingreso'],
            'idalmacen'=>$row['idalmacen'],
            'numero'=>(int)$row['numero'],
            'gestion'=>$row['gestion'],
            'numeroingreso'=>$row['numero']."/".$row['gestion'],
            'fecha'=>$row['fecha'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'rubro_producto'=>$row['rubro_producto'],
            'no_contrato'=>$row['no_contrato'],
            'piezas_manifestadas'=>$row['piezas_manifestadas'],
            'peso_total'=>$row['peso_total'],
            'proveedor'=>$row['proveedor'],
            'dui'=>$row['dui'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'cantidad_cajas'=>$row['cantidad_cajas'],
