$app->put('/inter_company/{idingreso}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idingreso = $args['idingreso'];
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    
    $curl_login = curl_init();

    curl_setopt_array($curl_login, array(
        CURLOPT_URL => url_intercompany_delosi.'/seguridad/autenticar',
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_ENCODING => '',
        CURLOPT_MAXREDIRS => 10,
        CURLOPT_TIMEOUT => 0,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        CURLOPT_SSL_VERIFYHOST => 0,
        CURLOPT_SSL_VERIFYPEER => 0,
        CURLOPT_CUSTOMREQUEST => 'POST',
        CURLOPT_POSTFIELDS =>'{
            "Usuario": "'.user_intercompany_delosi.'",
            "Clave": "'.clave_intercompany_delosi.'"
        }',
        CURLOPT_HTTPHEADER => array(
          'Content-Type: application/json'
        ),
    ));

    $response_login = curl_exec($curl_login);
    $response_array=[];
    
    if($response_login==false){
        $mensaje="No es posible conectarse con el servidor de DELOSI";
    }else{
        $response_login_array= json_decode($response_login, true);
        $token=$response_login_array["token"];
        
        $result = $conexion->query("select CONCAT(numero,'/',gestion) as numero_ingreso, idcliente, idcliente_destino from t_ingreso WHERE idingreso=$idingreso;");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $numero_ingreso=$row['numero_ingreso'];
            $idcliente=(int)$row['idcliente'];
            $idcliente_destino=(int)$row['idcliente_destino'];
        }

        $result = $conexion->query("select * FROM t_inter_company WHERE (idcliente_1=$idcliente AND idcliente_2=$idcliente_destino) OR (idcliente_1=$idcliente_destino AND idcliente_2=$idcliente);");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $idinter_company=(int)$row['idinter_company'];
            $idcliente_1=(int)$row['idcliente_1'];
            $almacen_1=$row['almacen_1'];
            $idcliente_2=(int)$row['idcliente_2'];
            $almacen_2=$row['almacen_2'];
        }
        
        if($idcliente_1==$idcliente){
            $almacen_origen=$almacen_1;
            $almacen_destino=$almacen_2;
        }else{
            $almacen_origen=$almacen_2;
            $almacen_destino=$almacen_1;
        }
        
        
        $detalle=[];
        $posicion=0;
        $result = $conexion->query("select 
            t_ingresodetalle.codigo,
            t_embalaje.codigoembalaje,
            t_ingresodetalle.cantidad
            from 
            t_ingresodetalle
            LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
            WHERE 
            t_ingresodetalle.idingreso=$idingreso;");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $posicion++;
            $detalle[]=array(
                "Posicion"=>$posicion,
                "CodigoMaterial"=>$row['codigo'],
                "UnidadMedida"=>$row['codigoembalaje'],
                "Cantidad"=>(float)$row['cantidad']
            );
        }
        
        
        
        $data=array(
            "FechaProcesamiento"=>date("Y-m-d"),
            "Fecharegistro"=>date("Y-m-d"),
            "Usuario"=>user_intercompany_delosi,
            "DocumentoMovimiento"=>$numero_ingreso,
            "AlmacenOrigen"=>$almacen_origen,
            "AlmacenDestino"=>$almacen_destino,
            "Detalle"=>$detalle
        );
        
        
        $curl = curl_init();

        curl_setopt_array($curl, array(
          CURLOPT_URL => url_intercompany_delosi.'/almacen/movimientointerno',
          CURLOPT_RETURNTRANSFER => true,
          CURLOPT_ENCODING => '',
          CURLOPT_MAXREDIRS => 10,
          CURLOPT_TIMEOUT => 0,
          CURLOPT_FOLLOWLOCATION => true,
          CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
          CURLOPT_SSL_VERIFYHOST => 0,
          CURLOPT_SSL_VERIFYPEER => 0,
          CURLOPT_CUSTOMREQUEST => 'POST',
          CURLOPT_POSTFIELDS => json_encode($data),
          CURLOPT_HTTPHEADER => array(
            'Token: Bearer '.$token,
            'Content-Type: application/json'
          ),
        ));

        $response = curl_exec($curl);
        $response_array= json_decode($response, TRUE);
        
        $respuesta_api=$response_array["Data"]["Mensaje"];
        $payload_api=json_encode($data);
        $response_api=$response;
        
        if($response_array["Data"]["OK"]){
            $query="UPDATE t_ingreso SET envio_api=CURRENT_TIMESTAMP(), respuesta_api=:respuesta_api, payload_api=:payload_api, response_api=:response_api WHERE idingreso=:idingreso;";
        } else {
            $query="UPDATE t_ingreso SET respuesta_api=:respuesta_api, payload_api=:payload_api, response_api=:response_api  WHERE idingreso=:idingreso;";
        }
        
        $stmt = $conexion->prepare($query);
        $stmt->bindParam(':respuesta_api', $respuesta_api);
        $stmt->bindParam(':payload_api', $payload_api);
        $stmt->bindParam(':response_api', $response_api);
        $stmt->bindParam(':idingreso', $idingreso);
        
        $stmt->execute();

        
        if ($stmt) {
            $codigo=200;
            $status='Exito';
            $mensaje='Se transmitio la informacion correctamente';
        } else {
            //echo "Error al actualizar el registro.";
        }
        //$result = $conexion->exec($query);
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'response_login'=>$response_login,
        'response_login_array'=>$response_login_array,
        'response'=>$response,
        'response_array'=>$response_array,
        'data'=>$data,
        'data_'=>json_encode($data),
        'query'=>$query,
        'respuesta_api'=>$respuesta_api,
        'payload_api'=>$payload_api,
        'respone_api'=>$respone_api,
        'idingreso'=>$idingreso
        
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

