$app->get('/salidas/{idcliente}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $filtrocliente='';
    
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=(int)$rowcliente["idcliente"];
    }
    
    
    if($idclientenum>0){
        $filtrocliente="AND t_salida.idcliente=$idclientenum";
    }
    
    $salidas=[];
    $result = $conexion->query("SELECT 
        md5(t_salida.idsalida) as idsalida,
        t_salida.idalmacen,
        t_salida.numero,
        t_salida.gestion,
        t_salida.fecha,
        t_cliente.cliente,
        t_salida.delivery_note,
        t_salida.rubro_producto,
        t_salida.proyecto_no,
        t_salida.contrato_no,
        IFNULL(t_salida.finalizado,0) as finalizado,
        t_salida.partida
        from 
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        WHERE
        t_salida.idalmacen=".$decoded_array["idalmacen"]." 
        $filtrocliente
        ORDER BY
        t_salida.fecha DESC, t_salida.numero DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $salidas[]=array(
            'idsalida'=>$row['idsalida'],
            //'idalmacen'=>$row['idalmacen'],
            'numero'=>(int)$row['numero'],
            'gestion'=>(int)$row['gestion'],
            'numerosalida'=>$row['numero']."/".$row['gestion'],
            'fecha'=>$row['fecha'],
            'cliente'=>$row['cliente'],
            'delivery_note'=>$row['delivery_note'],
            'rubro_producto'=>$row['rubro_producto'],
            'proyecto_no'=>$row['proyecto_no'],
            'contrato_no'=>$row['contrato_no'],
            'finalizado'=>boolval($row['finalizado']),
            'partida'=>$row['partida'],
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'salidas' => $salidas
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/salidas/reporte/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $filtrocliente="";
    if((int)$idcliente>0){
        $filtrocliente=" AND t_salida.idcliente=$idcliente ";
    }
    
    $salidas=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ultimaubicacion;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_ultimaubicacion (idubicacionitem INT, idingresodetalle INT);");
    $conexion->query("INSERT INTO tmp_ultimaubicacion (idubicacionitem, idingresodetalle)
        SELECT
        MAX(idubicacionitem) as idubicacionitem,
        idingresodetalle
        FROM
        t_ubicacionitem
        GROUP BY
        idingresodetalle;");
    $conexion->query("ALTER TABLE tmp_ultimaubicacion ADD INDEX idubicacionitem (idubicacionitem);");
    $conexion->query("ALTER TABLE tmp_ultimaubicacion ADD INDEX idingresodetalle (idingresodetalle);");
    
    $result = $conexion->query("SELECT
        t_cliente.cliente,
        CONCAT(t_salida.numero,'/',t_salida.gestion) as numerosalida,
        CONCAT(t_salida.fecha) as fechasalida,
        IFNULL(t_salida.es_no_conf,0) as es_no_conf,
        t_salida.solicitado_por,
        t_salida.autorizado_por,
        t_salida.delivery_note,
        t_salida.proyecto_no,
        t_salida.contrato_no,
        t_salida.rubro_producto,
        t_salida.ciudad,
        t_salida.direccion_entrega,
        t_salida.transporte,
        t_salida.placa,
        t_salida.cantidad_pallet,
        t_salida.cantidad_cajas,
        t_salida.autorizacion_compra,
        t_salida.tipo_pedido,
        t_salida.hora_inicio_a,
        t_salida.hora_fin_a,
        t_salida.cantidad_estibadores_a,
        t_salida.nota_adicional,
        t_salida.hora_inicio_b,
        t_salida.hora_fin_b,
        t_salida.cantidad_estibadores_b,
        t_usuario.nombre as nombre_entrega,
        t_usuario.ci as ci_entrega,
        t_salida.nombre_recibido,
        t_salida.ci_recibido,
        t_salida.empresa_recibido,
        CONCAT(t_salida.fecha_recibido,' 12:00:00') as fecha_recibido,
        CASE ifnull(t_salida.entrega_a_tiempo,0)
            WHEN 0 THEN 'NO'
            WHEN 1 THEN 'SI'
        END as entrega_a_tiempo,
        CASE ifnull(t_salida.entrega_completa_conforme,0)
            WHEN 0 THEN 'NO'
            WHEN 1 THEN 'SI'
        END as entrega_completa_conforme,
        t_ingresodetalle.codigo,
        t_ingresodetalle.serie,
        t_ingresodetalle.descripcion,
        t_ingresodetalle.centro_distribucion,
        t_ingresodetalle.categoria,
        t_salidadetalle.cantidad,
        t_embalaje.codigoembalaje,
        t_ingresodetalle.lote,
        t_merma.merma,
        t_ingresodetalle.relacion_caja,
        CONCAT(t_ingresodetalle.fechavencimiento,' 12:00:00') as fechavencimiento,
        t_salidadetalle.bultos,
        t_ingresodetalle.costo_un,
        t_salidadetalle.cantidad_no_conf,
        t_ingresodetalle.idno_conf,
        t_no_conf.no_conf,
        t_clasificacion.clasificacion,
        t_salidadetalle.peso,
        t_ingresodetalle.pallet,
        t_salidadetalle.temperatura,
        t_salidadetalle.observaciones,
        t_tipoingreso.tipoingreso,
        CONCAT(t_ingreso.numero,'/',t_ingreso.gestion) as numeroingreso,
        t_ingreso.fecha as fechaingreso,
        t_almacendetalle.nombre as ubicacionalmacen,
        IFNULL(t_embalaje_salida.codigoembalaje,t_embalaje.codigoembalaje) as codigoembalaje_salida,
        IFNULL(t_baseproductos.factor_conversion,1) as factor_conversion,
        t_ingreso.invoice
        FROM
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario ON t_salida.idusuario_entrega=t_usuario.idusuario
        LEFT JOIN t_salidadetalle ON t_salida.idsalida=t_salidadetalle.idsalida
        LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
        LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
        LEFT JOIN t_no_conf ON t_ingresodetalle.idno_conf=t_no_conf.idno_conf
        LEFT JOIN t_clasificacion ON t_ingresodetalle.idclasificacion=t_clasificacion.idclasificacion
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN t_tipoingreso ON t_ingreso.idtipoingreso=t_tipoingreso.idtipoingreso
        LEFT JOIN tmp_ultimaubicacion ON t_ingresodetalle.idingresodetalle=tmp_ultimaubicacion.idingresodetalle
        LEFT JOIN t_ubicacionitem ON tmp_ultimaubicacion.idubicacionitem=t_ubicacionitem.idubicacionitem
        LEFT JOIN t_almacendetalle ON t_ubicacionitem.idalmacendetalle=t_almacendetalle.idalmacendetalle
        LEFT JOIN t_merma ON t_ingresodetalle.idmerma=t_merma.idmerma
        LEFT JOIN t_baseproductos ON t_ingresodetalle.codigo=t_baseproductos.codigo AND t_ingreso.idcliente=t_baseproductos.idcliente AND t_ingresodetalle.idembalaje=t_baseproductos.idembalaje
        LEFT JOIN t_embalaje as t_embalaje_salida ON t_baseproductos.idembalaje_salida=t_embalaje_salida.idembalaje
        WHERE
        IFNULL(t_salida.finalizado,0)=1
        $filtrocliente
        AND CAST(t_salida.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        AND t_salida.idalmacen=".$decoded_array['idalmacen'].";");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $salidas[]=array(
            'cliente'=>$row['cliente'],
            'numerosalida'=>$row['numerosalida'],
            'fechasalida'=>$row['fechasalida'],
            'es_no_conf'=>$row['es_no_conf'],
            'solicitado_por'=>$row['solicitado_por'],
            'autorizado_por'=>$row['autorizado_por'],
            'delivery_note'=>$row['delivery_note'],
            'proyecto_no'=>$row['proyecto_no'],
            'contrato_no'=>$row['contrato_no'],
            'rubro_producto'=>$row['rubro_producto'],
            'ciudad'=>$row['ciudad'],
            'direccion_entrega'=>$row['direccion_entrega'],
            'transporte'=>$row['transporte'],
            'placa'=>$row['placa'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'cantidad_cajas'=>$row['cantidad_cajas'],
            'autorizacion_compra'=>$row['autorizacion_compra'],
            'tipo_pedido'=>$row['tipo_pedido'],
            'hora_inicio_a'=>$row['hora_inicio_a'],
            'hora_fin_a'=>$row['hora_fin_a'],
            'cantidad_estibadores_a'=>(int)$row['cantidad_estibadores_a'],
            'nota_adicional'=>$row['nota_adicional'],
            'hora_inicio_b'=>$row['hora_inicio_b'],
            'hora_fin_b'=>$row['hora_fin_b'],
            'cantidad_estibadores_b'=>(int)$row['cantidad_estibadores_b'],
            'nombre_entrega'=>$row['nombre_entrega'],
            'ci_entrega'=>$row['ci_entrega'],
            'nombre_recibido'=>$row['nombre_recibido'],
            'ci_recibido'=>$row['ci_recibido'],
            'empresa_recibido'=>$row['empresa_recibido'],
            'fecha_recibido'=>$row['fecha_recibido'],
            'entrega_a_tiempo'=>$row['entrega_a_tiempo'],
