$app->get('/salidas/detalle/{idsalidadetalle}/imagenes', function(Request $request, Response $response, array $args) use ($conexion) {
    $idsalidadetalle = $args['idsalidadetalle'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    
    $imagenes=[];
    $resultimagenes = $conexion->query("SELECT 
        t_salidadetalleimagen.idsalidadetalleimagen,
        t_salidadetalleimagen.imagen,
        t_cliente.idempresa
        FROM 
        t_salidadetalleimagen
        LEFT JOIN t_salidadetalle ON t_salidadetalleimagen.idsalidadetalle=t_salidadetalle.idsalidadetalle
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        WHERE
        t_salidadetalleimagen.idsalidadetalle='$idsalidadetalle';");
    while ($rowimagenes =  $resultimagenes ->fetch(PDO::FETCH_ASSOC)){
        $filePath = folder_files.$rowimagenes["idempresa"].DIRECTORY_SEPARATOR.'almacen/accesorios_salidas/'.$idsalidadetalle.'/'.$rowimagenes["imagen"];
        
        if (file_exists($filePath)) {
            $imageData = file_get_contents($filePath);
            $mimeType = mime_content_type($filePath); // e.g., image/png, image/jpeg
            $base64 = base64_encode($imageData);
            $fileBase64 = "data:$mimeType;base64,$base64";
            $imagenes[]=array(
                'idsalidadetalleimagen'=>(int)$rowimagenes['idsalidadetalleimagen'],
                'itemImageSrc'=>$fileBase64
            );
        }else{
            $fileBase64=null;
        }
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'imagenes' => $imagenes
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);


