    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=$rowcliente['idcliente'];
    }
    
    $idcliente_destinonum='NULL';
    $resultcliente = $conexion->query("SELECT idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente_destino';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idcliente_destinonum=$rowcliente['idcliente'];
    }
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $xls_data=[];
    $salidas=[];
    $mensajes_error=[];
    $query="";
    
    $idsalida=0;
    
    $cargamasiva=$_POST["cargamasiva"];
    if($cargamasiva=='true'){
        if(isset($_FILES['uploads'])){
            $nombredoc=$_FILES['uploads']["name"][0];
            //$random = bin2hex(openssl_random_pseudo_bytes(5));
            //$nombredoc=$random."_".$nombredoc;

            $piramideUploader=new PiramideUploader();
            $upload =$piramideUploader->upload($nombredoc, 'uploads', folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/salidasMasivas', $archivosmasivo, true);

            $file=$piramideUploader->getInfoFile();
            $file_name=$file['complete_name'];

            if(isset($upload) && $upload['uploaded']==false){
                $mensaje=$upload['error'];
            }else{
                $inputFileName = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/salidasMasivas/'.$file_name;
                $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
                $sheet = $spreadsheet->getActiveSheet();
                $highestRow = $sheet->getHighestRow(); 
                $highestColumn = $sheet->getHighestColumn();
                $xls_data = $sheet->rangeToArray(
                    'A2:' . $highestColumn . $highestRow,
                    '',TRUE,TRUE
                );
                
                $indicetotal= count($xls_data[2])-1;
                
                for($dest=3;$dest<count($xls_data[2]);$dest++){
                    $items=[];
                    $salidas[]=array(
                        'index'=>$dest,
                        'tienda'=>$xls_data[2][$dest],
                        'items'=>$items,
                        'query'=>'',
                        'idsalida'=>0
                    );
                }
                
                for($itm=3;$itm<(count($xls_data)-1);$itm++){
                    if($xls_data[$itm][$indicetotal]<>''){+
                        $totaldisponible=0;
                        $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ingreso;");
                        $conexion->query("CREATE TEMPORARY TABLE tmp_ingreso (idingresodetalle INT, cantidadingreso DECIMAL(13,2));");
                        $conexion->query("INSERT INTO tmp_ingreso (idingresodetalle, cantidadingreso)
                            SELECT 
                            t_ingresodetalle.idingresodetalle, 
                            t_ingresodetalle.cantidad as cantidadingreso
                            FROM 
                            t_ingresodetalle 
                            LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
                            WHERE 
                            t_ingresodetalle.codigo='".$xls_data[$itm][0]."' 
                            AND t_ingresodetalle.dividido IS NULL
                            AND t_ingreso.idcliente=$idclientenum
                            AND t_ingreso.idalmacen=".$decoded_array["idalmacen"].";");
                        $conexion->query("ALTER TABLE tmp_ingreso ADD INDEX idingresodetalle (idingresodetalle);");
                        
                        $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salida;");
                        $conexion->query("CREATE TEMPORARY TABLE tmp_salida (idingresodetalle INT, cantidadsalida DECIMAL(13,2));");
                        $conexion->query("INSERT INTO tmp_salida (idingresodetalle, cantidadsalida)
                            SELECT 
                            t_salidadetalle.idingresodetalle,
                            SUM(t_salidadetalle.cantidad) as cantidadsalida
                            FROM 
                            t_salidadetalle
                            LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
                            LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
                            WHERE
                            t_ingresodetalle.codigo='".$xls_data[$itm][0]."' 
                            AND t_ingresodetalle.dividido IS NULL
                            AND t_salida.idcliente=$idclientenum
                            AND t_salida.idalmacen=".$decoded_array["idalmacen"]."
                            AND IFNULL(t_salida.finalizado,0)=1
                            GROUP BY
                            t_salidadetalle.idingresodetalle;");
                        $conexion->query("ALTER TABLE tmp_salida ADD INDEX idingresodetalle (idingresodetalle);");
                        
                        $result = $conexion->query("SELECT
                            SUM(IFNULL(tmp_ingreso.cantidadingreso,0)-IFNULL(tmp_salida.cantidadsalida,0)) as totaldisponible
                            FROM
                            tmp_ingreso
                            LEFT JOIN tmp_salida ON tmp_ingreso.idingresodetalle=tmp_salida.idingresodetalle;");
                        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                            $totaldisponible=$row['totaldisponible'];
                        }
                        
                        if($xls_data[$itm][$indicetotal]>$totaldisponible){
                            $mensajes_error[]=array(
                                'codigo'=>$xls_data[$itm][0],
                                'mensaje'=>"La cantidad solicitada (". number_format($xls_data[$itm][$indicetotal], 2, ".", ",").") es mayor a la disponible (". number_format($totaldisponible, 2, ".", ",").")"
                            );
                        }
                        
                        
                        for($dest=3;$dest<(count($xls_data[$itm])-1);$dest++){
                            if($xls_data[$itm][$dest]<>''){
                                $key = array_search($dest, array_column($salidas, 'index'));
                                if(is_numeric($key)){
                                    $salidas[$key]["items"][]=array(
                                        'codigo'=>$xls_data[$itm][0],
                                        'cantidad'=>$xls_data[$itm][$dest],
                                        'idingresodetalle'=>0,
                                        'query'=>''
                                    );
                                }
                            }
                        }
                    }
                }
                
                if(count($mensajes_error)==0 && count($salidas)>1){
                    $salidasnuevas="";
                    for($s=0;$s<count($salidas)-1;$s++){
                        $conexion->query("INSERT INTO t_salida (numero,                                                                                                                                     gestion,                idalmacen,                          idcliente,      idcliente_destino,      fecha,                  delivery_note,                                              proyecto_no,                    contrato_no,                    rubro_producto,                                             idusuario_entrega,                  fecha_recibido, entrega_a_tiempo,   entrega_completa_conforme) 
                                                        SELECT (SELECT ifnull(MAX(numero)+1,1) as numero from t_salida WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),   ".$decoded_array["idalmacen"].",    $idclientenum,  $idcliente_destinonum,  CURRENT_TIMESTAMP(),    '".preg_replace('/[0-9]+/', '', $salidas[$s]["tienda"])."', '".$salidas[$s]["tienda"]."',   '".$salidas[$s]["tienda"]."',   '".preg_replace('/[0-9]+/', '', $salidas[$s]["tienda"])."', ".$decoded_array["idusuario"].",    CURRENT_DATE(), 1,                  1;");
                        $conexion->query("SELECT LAST_INSERT_ID() INTO @idsalida_nuevo;");
                        $result = $conexion->query("SELECT
                            @idsalida_nuevo as idsalida;");
                        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                            $idsalida=$row['idsalida'];
                            $salidasnuevas=$salidasnuevas.$idsalida.",";
                        }
                        $salidas[$s]['query']="INSERT INTO t_salida (numero,                                                                                                                                     gestion,                idalmacen,                          idcliente,     idcliente_destino,      fecha,                  delivery_note,                                              proyecto_no,                    contrato_no,                    rubro_producto,                                             idusuario_entrega,                  fecha_recibido, entrega_a_tiempo,   entrega_completa_conforme) 
                                                             SELECT (SELECT ifnull(MAX(numero)+1,1) as numero from t_salida WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),   ".$decoded_array["idalmacen"].",    $idclientenum, $idcliente_destinonum,  CURRENT_TIMESTAMP(),    '".preg_replace('/[0-9]+/', '', $salidas[$s]["tienda"])."', '".$salidas[$s]["tienda"]."',   '".$salidas[$s]["tienda"]."',   '".preg_replace('/[0-9]+/', '', $salidas[$s]["tienda"])."', ".$decoded_array["idusuario"].",    CURRENT_DATE(), 1,                  1;
                                SELECT LAST_INSERT_ID() INTO @idsalida_nuevo;";
                        $salidas[$s]['idsalida']=$idsalida;
                        
                        for($i=0;$i<count($salidas[$s]['items']);$i++){
                            $totaldisponible=0;
                            $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ingreso;");
                            $conexion->query("CREATE TEMPORARY TABLE tmp_ingreso (idingresodetalle INT, cantidadingreso DECIMAL(13,2), fechavencimiento DATE, fechaingreso DATE);");
                            $conexion->query("INSERT INTO tmp_ingreso (idingresodetalle, cantidadingreso, fechavencimiento, fechaingreso)
                                SELECT 
                                t_ingresodetalle.idingresodetalle, 
                                t_ingresodetalle.cantidad as cantidadingreso,
                                t_ingresodetalle.fechavencimiento,
                                t_ingreso.fecha
                                FROM 
                                t_ingresodetalle 
                                LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
                                WHERE 
                                t_ingresodetalle.codigo='".$salidas[$s]['items'][$i]["codigo"]."' 
                                AND t_ingresodetalle.dividido IS NULL
                                AND t_ingreso.idcliente=$idclientenum
                                AND t_ingreso.idalmacen=".$decoded_array["idalmacen"].";");
                            $conexion->query("ALTER TABLE tmp_ingreso ADD INDEX idingresodetalle (idingresodetalle);");

                            $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salida;");
                            $conexion->query("CREATE TEMPORARY TABLE tmp_salida (idingresodetalle INT, cantidadsalida DECIMAL(13,2));");
                            $conexion->query("INSERT INTO tmp_salida (idingresodetalle, cantidadsalida)
                                SELECT 
                                t_salidadetalle.idingresodetalle,
                                SUM(t_salidadetalle.cantidad) as cantidadsalida
                                FROM 
                                t_salidadetalle
                                LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
                                LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
                                WHERE
                                t_ingresodetalle.codigo='".$salidas[$s]['items'][$i]["codigo"]."' 
                                AND t_ingresodetalle.dividido IS NULL
                                AND t_salida.idcliente=$idclientenum
                                AND t_salida.idalmacen=".$decoded_array["idalmacen"]."
                                AND (IFNULL(t_salida.finalizado,0)=1 OR t_salida.idsalida IN ($salidasnuevas 0))
                                GROUP BY
                                t_salidadetalle.idingresodetalle;");
                            $conexion->query("ALTER TABLE tmp_salida ADD INDEX idingresodetalle (idingresodetalle);");

                            $result = $conexion->query("SELECT
                                tmp_ingreso.idingresodetalle,
                                tmp_ingreso.fechavencimiento,
                                IFNULL(tmp_ingreso.cantidadingreso,0)-IFNULL(tmp_salida.cantidadsalida,0) as totaldisponible
                                FROM
                                tmp_ingreso
                                LEFT JOIN tmp_salida ON tmp_ingreso.idingresodetalle=tmp_salida.idingresodetalle
                                WHERE
                                (IFNULL(tmp_ingreso.cantidadingreso,0)-IFNULL(tmp_salida.cantidadsalida,0))>='".$salidas[$s]['items'][$i]["cantidad"]."'
                                AND IFNULL(tmp_ingreso.fechavencimiento,CURRENT_DATE())>=CURRENT_DATE()
                                ORDER BY
                                tmp_ingreso.fechavencimiento,
                                tmp_ingreso.fechaingreso
                                LIMIT 0,1;");
                            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                                $salidas[$s]['items'][$i]["idingresodetalle"]=(int)$row['idingresodetalle'];
                            }
                            $conexion->query("INSERT INTO t_salidadetalle (idsalida,    idingresodetalle,                                   cantidad,                                       peso,   bultos, cantidad_no_conf) 
                                                                   VALUES ($idsalida,   ".$salidas[$s]['items'][$i]["idingresodetalle"].",  '".$salidas[$s]['items'][$i]["cantidad"]."',    0,      0,      0);");
                        }
                    }
                    $codigo=200;
                    $status='Exito';
                    $mensaje='Se guardo la información Correctamente';
                }
            }
        }
    }else{
        $query="INSERT INTO t_salida (numero,                                                                                                                                       gestion,                idalmacen,                          idcliente,          es_vehiculo,    movimiento,     es_no_conf,     idcliente_destino,      fecha,                  idusuario_entrega,                  entrega_a_tiempo,   entrega_completa_conforme) 
                              SELECT (SELECT ifnull(MAX(numero)+1,1) as numero from t_salida WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),     YEAR(CURRENT_DATE()),   ".$decoded_array["idalmacen"].",    $idclientenum,      $es_vehiculo,   $movimiento,    $es_no_conf,    $idcliente_destinonum,  CURRENT_TIMESTAMP(),    ".$decoded_array["idusuario"].",    1,                  1;
                SELECT LAST_INSERT_ID() INTO @idsalida_nuevo;";
    }
    if($query<>''){
        $result = $conexion->exec($query);
        if($result){
            if($cargamasiva=='true'){

            }else{
                $result = $conexion->query("SELECT
                    md5(@idsalida_nuevo) as idsalida;");
                while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                    $idsalida=$row['idsalida'];
                }
            }

            $codigo=200;
            $status='Exito';
            $mensaje='Se guardo la información Correctamente';
        }
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'idsalida'=>$idsalida,
        'idcliente'=>$idcliente,
        'idclientenum'=>$idclientenum,
        'xls_data'=>$xls_data,
        'salidas'=>$salidas,
        'mensajes_error'=>$mensajes_error,
        'query'=>$query
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->put('/salidas/{idsalida}', function(Request $request, Response $response, array $args) use ($conexion) {

    $idsalida = $args['idsalida'] ?? null;

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'No se guardó la información';

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros
        |--------------------------------------------------------------------------
        */
        $params = json_decode((string) $request->getBody(), true);

        if (!is_array($params)) {
            $mensaje = 'No se recibieron parámetros válidos';
            $continuar = false;
        }

        if ($continuar) {
            $idcliente = $params['idcliente'] ?? null;
            $idpedido = $params['idpedido'] ?? null;

            $fecha = empty($params['fecha']) ? null : str_replace("T", " ", $params['fecha']);

            $solicitado_por = $params['solicitado_por'] ?? '';
            $autorizado_por = $params['autorizado_por'] ?? '';
            $idmovilizador = $params['idmovilizador'] ?? null;
            $delivery_note = $params['delivery_note'] ?? '';
            $proyecto_no = $params['proyecto_no'] ?? '';
            $contrato_no = $params['contrato_no'] ?? '';
            $rubro_producto = $params['rubro_producto'] ?? '';
            $ciudad = $params['ciudad'] ?? '';
            $direccion_entrega = $params['direccion_entrega'] ?? '';
            $idalmacen_destino = empty($params['idalmacen_destino']) ? null : $params['idalmacen_destino'];
            $transporte = $params['transporte'] ?? '';
            $placa = $params['placa'] ?? '';
            $cantidad_pallet = $params['cantidad_pallet'] ?? '';
            $cantidad_cajas = $params['cantidad_cajas'] ?? '';
            $autorizacion_compra = $params['autorizacion_compra'] ?? '';
            $tipo_pedido = $params['tipo_pedido'] ?? '';
            $almacen_destino = $params['almacen_destino'] ?? '';
            $pedido_consolidado = $params['pedido_consolidado'] ?? '';
            $partida = $params['partida'] ?? '';
            $hora_inicio_a = $params['hora_inicio_a'] ?? '';
            $hora_fin_a = $params['hora_fin_a'] ?? '';
            $cantidad_estibadores_a = $params['cantidad_estibadores_a'] ?? '';
            $hora_inicio_cable = $params['hora_inicio_cable'] ?? '';
            $hora_fin_cable = $params['hora_fin_cable'] ?? '';
            $nota_adicional = $params['nota_adicional'] ?? '';
            $hora_inicio_b = $params['hora_inicio_b'] ?? '';
            $hora_fin_b = $params['hora_fin_b'] ?? '';
            $cantidad_estibadores_b = $params['cantidad_estibadores_b'] ?? '';
            $idusuario_entrega = empty($params['idusuario_entrega']) ? null : $params['idusuario_entrega'];
            $nombre_recibido = $params['nombre_recibido'] ?? '';
            $ci_recibido = $params['ci_recibido'] ?? '';
            $empresa_recibido = $params['empresa_recibido'] ?? '';
            $fecha_recibido = empty($params['fecha_recibido']) ? null : $params['fecha_recibido'];
            $entrega_a_tiempo = $params['entrega_a_tiempo'] ?? '';
            $entrega_completa_conforme = $params['entrega_completa_conforme'] ?? '';

            $detalle = $params["detalle"] ?? [];
        }

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if ($continuar && empty($idsalida)) {
            $mensaje = 'No se recibió la salida';
            $continuar = false;
        }

        if ($continuar && empty($idcliente)) {
            $mensaje = 'No se recibió el cliente';
            $continuar = false;
        }

        if ($continuar && empty($fecha)) {
            $mensaje = 'No se recibió la fecha';
            $continuar = false;
        }

        if ($continuar && !is_array($detalle)) {
            $mensaje = 'El detalle recibido no tiene un formato válido';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Buscar IDs reales por hash
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idsalidanum = 0;

            $stmtSalida = $conexion->prepare("
                SELECT idsalida
                FROM t_salida
                WHERE MD5(idsalida) = :idsalida
                LIMIT 1
            ");

            $stmtSalida->execute([
                ':idsalida' => $idsalida
            ]);

            $rowSalida = $stmtSalida->fetch(PDO::FETCH_ASSOC);

            if ($rowSalida) {
                $idsalidanum = (int)$rowSalida['idsalida'];
            }

            if ($idsalidanum <= 0) {
                $mensaje = 'No se encontró la salida';
                $continuar = false;
            }
        }

        if ($continuar) {

            $idpedidonum = null;

            if (!empty($idpedido)) {
                $stmtPedido = $conexion->prepare("
                    SELECT idpedido
                    FROM t_pedido
                    WHERE MD5(idpedido) = :idpedido
                    LIMIT 1
                ");

                $stmtPedido->execute([
                    ':idpedido' => $idpedido
                ]);

                $rowPedido = $stmtPedido->fetch(PDO::FETCH_ASSOC);

                if ($rowPedido) {
                    $idpedidonum = (int)$rowPedido['idpedido'];
                }
            }

            $idclientenum = 0;

            $stmtCliente = $conexion->prepare("
                SELECT idcliente
                FROM t_cliente
                WHERE MD5(idcliente) = :idcliente
                LIMIT 1
            ");

            $stmtCliente->execute([
                ':idcliente' => $idcliente
            ]);

            $rowCliente = $stmtCliente->fetch(PDO::FETCH_ASSOC);

            if ($rowCliente) {
                $idclientenum = (int)$rowCliente['idcliente'];
            }

            if ($idclientenum <= 0) {
                $mensaje = 'No se encontró el cliente';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Iniciar transacción
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            /*
            |--------------------------------------------------------------------------
            | Actualizar cabecera
            |--------------------------------------------------------------------------
            */
            $stmtUpdateSalida = $conexion->prepare("
                UPDATE t_salida
                SET
                    idcliente = :idcliente,
                    idpedido = :idpedido,
                    fecha = :fecha,
                    solicitado_por = :solicitado_por,
                    autorizado_por = :autorizado_por,
                    idmovilizador = :idmovilizador,
                    delivery_note = :delivery_note,
                    proyecto_no = :proyecto_no,
                    contrato_no = :contrato_no,
                    rubro_producto = :rubro_producto,
                    ciudad = :ciudad,
                    direccion_entrega = :direccion_entrega,
                    idalmacen_destino = :idalmacen_destino,
                    transporte = :transporte,
                    placa = :placa,
                    cantidad_pallet = :cantidad_pallet,
                    cantidad_cajas = :cantidad_cajas,
                    autorizacion_compra = :autorizacion_compra,
                    tipo_pedido = :tipo_pedido,
                    almacen_destino = :almacen_destino,
                    pedido_consolidado = :pedido_consolidado,
                    partida = :partida,
                    hora_inicio_a = :hora_inicio_a,
                    hora_fin_a = :hora_fin_a,
                    cantidad_estibadores_a = :cantidad_estibadores_a,
                    hora_inicio_cable = :hora_inicio_cable,
                    hora_fin_cable = :hora_fin_cable,
                    nota_adicional = :nota_adicional,
                    hora_inicio_b = :hora_inicio_b,
                    hora_fin_b = :hora_fin_b,
                    cantidad_estibadores_b = :cantidad_estibadores_b,
                    idusuario_entrega = :idusuario_entrega,
                    nombre_recibido = :nombre_recibido,
                    ci_recibido = :ci_recibido,
                    empresa_recibido = :empresa_recibido,
                    fecha_recibido = :fecha_recibido,
                    entrega_a_tiempo = :entrega_a_tiempo,
                    entrega_completa_conforme = :entrega_completa_conforme
                WHERE idsalida = :idsalida
            ");

            $okSalida = $stmtUpdateSalida->execute([
                ':idcliente' => $idclientenum,
                ':idpedido' => $idpedidonum,
                ':fecha' => $fecha,
                ':solicitado_por' => $solicitado_por,
                ':autorizado_por' => $autorizado_por,
                ':idmovilizador' => $idmovilizador,
                ':delivery_note' => $delivery_note,
                ':proyecto_no' => $proyecto_no,
                ':contrato_no' => $contrato_no,
                ':rubro_producto' => $rubro_producto,
                ':ciudad' => $ciudad,
                ':direccion_entrega' => $direccion_entrega,
                ':idalmacen_destino' => $idalmacen_destino,
                ':transporte' => $transporte,
                ':placa' => $placa,
                ':cantidad_pallet' => $cantidad_pallet,
                ':cantidad_cajas' => $cantidad_cajas,
                ':autorizacion_compra' => $autorizacion_compra,
                ':tipo_pedido' => $tipo_pedido,
                ':almacen_destino' => $almacen_destino,
                ':pedido_consolidado' => $pedido_consolidado,
                ':partida' => $partida,
                ':hora_inicio_a' => $hora_inicio_a,
                ':hora_fin_a' => $hora_fin_a,
                ':cantidad_estibadores_a' => $cantidad_estibadores_a,
                ':hora_inicio_cable' => $hora_inicio_cable,
                ':hora_fin_cable' => $hora_fin_cable,
                ':nota_adicional' => $nota_adicional,
                ':hora_inicio_b' => $hora_inicio_b,
                ':hora_fin_b' => $hora_fin_b,
                ':cantidad_estibadores_b' => $cantidad_estibadores_b,
                ':idusuario_entrega' => $idusuario_entrega,
                ':nombre_recibido' => $nombre_recibido,
                ':ci_recibido' => $ci_recibido,
                ':empresa_recibido' => $empresa_recibido,
                ':fecha_recibido' => $fecha_recibido,
                ':entrega_a_tiempo' => $entrega_a_tiempo,
                ':entrega_completa_conforme' => $entrega_completa_conforme,
                ':idsalida' => $idsalidanum
            ]);

            if (!$okSalida) {
                $mensaje = 'No se pudo actualizar la salida';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Preparar consultas de detalle y accesorios
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $stmtInsertDetalle = $conexion->prepare("
                INSERT INTO t_salidadetalle (
                    idsalida,
                    idingresodetalle,
                    cantidad,
                    bultos,
                    cantidad_no_conf,
                    peso,
                    temperatura,
                    observaciones,
                    tiene_danios,
                    danios,
                    tiene_faltante,
                    faltante,
                    kilometraje
                ) VALUES (
                    :idsalida,
                    :idingresodetalle,
                    :cantidad,
                    :bultos,
                    :cantidad_no_conf,
                    :peso,
                    :temperatura,
                    :observaciones,
                    :tiene_danios,
                    :danios,
                    :tiene_faltante,
                    :faltante,
                    :kilometraje
                )
            ");

            $stmtUpdateDetalle = $conexion->prepare("
                UPDATE t_salidadetalle
                SET
                    idingresodetalle = :idingresodetalle,
                    cantidad = :cantidad,
                    bultos = :bultos,
                    cantidad_no_conf = :cantidad_no_conf,
                    peso = :peso,
                    temperatura = :temperatura,
                    observaciones = :observaciones,
                    tiene_danios = :tiene_danios,
                    danios = :danios,
                    tiene_faltante = :tiene_faltante,
                    faltante = :faltante,
                    kilometraje = :kilometraje
                WHERE idsalidadetalle = :idsalidadetalle
                  AND idsalida = :idsalida
            ");

            $stmtInsertAccesorio = $conexion->prepare("
                INSERT INTO t_salidadetalle_accesorios (
                    idsalidadetalle,
                    idaccesorios_vehiculos,
                    cantidad,
                    texto,
                    created_at
                ) VALUES (
                    :idsalidadetalle,
                    :idaccesorios_vehiculos,
                    :cantidad,
                    :texto,
                    CURRENT_TIMESTAMP()
                )
            ");

            $stmtUpdateAccesorio = $conexion->prepare("
                UPDATE t_salidadetalle_accesorios
                SET
                    cantidad = :cantidad,
                    texto = :texto,
                    deleted_at = NULL
                WHERE idsalidadetalle_accesorios = :idsalidadetalle_accesorios
                  AND idsalidadetalle = :idsalidadetalle
            ");

            $stmtSoftDeleteAccesorio = $conexion->prepare("
                UPDATE t_salidadetalle_accesorios
                SET deleted_at = CURRENT_TIMESTAMP()
                WHERE idsalidadetalle_accesorios = :idsalidadetalle_accesorios
                  AND idsalidadetalle = :idsalidadetalle
            ");

            $stmtAccesoriosActuales = $conexion->prepare("
                SELECT
                    idsalidadetalle_accesorios,
                    idaccesorios_vehiculos
                FROM t_salidadetalle_accesorios
                WHERE idsalidadetalle = :idsalidadetalle
                  AND deleted_at IS NULL
            ");

            $idsDetalleRecibidos = [];
        }

        /*
        |--------------------------------------------------------------------------
        | Insertar / actualizar detalle
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            foreach ($detalle as $detalleItem) {

                $idsalidadetalle = $detalleItem['idsalidadetalle'] ?? 0;

                $tiene_danios = !empty($detalleItem['tiene_danios']) ? 1 : 0;
                $danios = $tiene_danios ? ($detalleItem['danios'] ?? '') : '';

                $tiene_faltante = !empty($detalleItem['tiene_faltante']) ? 1 : 0;
                $faltante = $tiene_faltante ? ($detalleItem['faltante'] ?? '') : '';

                $dataDetalle = [
                    ':idingresodetalle' => $detalleItem['idingresodetalle'] ?? null,
                    ':cantidad' => $detalleItem['cantidad'] ?? 0,
                    ':bultos' => $detalleItem['bultos'] ?? 0,
                    ':cantidad_no_conf' => $detalleItem['cantidad_no_conf'] ?? 0,
                    ':peso' => $detalleItem['peso'] ?? 0,
                    ':temperatura' => $detalleItem['temperatura'] ?? '',
                    ':observaciones' => $detalleItem['observaciones'] ?? '',
                    ':tiene_danios' => $tiene_danios,
                    ':danios' => $danios,
                    ':tiene_faltante' => $tiene_faltante,
                    ':faltante' => $faltante,
                    ':kilometraje' => $detalleItem['kilometraje'] ?? ''
                ];

                if (empty($dataDetalle[':idingresodetalle'])) {
                    $mensaje = 'Un detalle no tiene item de ingreso asociado';
                    $continuar = false;
                    break;
                }

                if ((int)$idsalidadetalle === 0) {

                    $dataInsert = $dataDetalle;
                    $dataInsert[':idsalida'] = $idsalidanum;

                    $okDetalle = $stmtInsertDetalle->execute($dataInsert);

                    if (!$okDetalle) {
                        $mensaje = 'No se pudo registrar un detalle de salida';
                        $continuar = false;
                        break;
                    }

                    $idsalidadetalleNuevo = (int)$conexion->lastInsertId();

                    /*
                    Importante:
                    Se agrega el ID nuevo para que no sea eliminado al sincronizar.
                    */
                    $idsDetalleRecibidos[] = $idsalidadetalleNuevo;

                    $idDetalleParaAccesorios = $idsalidadetalleNuevo;

                } else {

                    $idsDetalleRecibidos[] = (int)$idsalidadetalle;

                    $dataUpdate = $dataDetalle;
                    $dataUpdate[':idsalidadetalle'] = $idsalidadetalle;
                    $dataUpdate[':idsalida'] = $idsalidanum;

                    $okDetalle = $stmtUpdateDetalle->execute($dataUpdate);

                    if (!$okDetalle) {
                        $mensaje = 'No se pudo actualizar un detalle de salida';
                        $continuar = false;
                        break;
                    }

                    $idDetalleParaAccesorios = (int)$idsalidadetalle;
                }

                /*
                |--------------------------------------------------------------------------
                | Accesorios del detalle
                |--------------------------------------------------------------------------
                */
                if ($continuar) {

                    $accesorios = $detalleItem["accesorios_vehiculos"] ?? [];

                    if (!is_array($accesorios)) {
                        $accesorios = [];
                    }

                    /*
                    Para detalles nuevos, se insertan todos los accesorios recibidos.
                    Para existentes, se sincronizan por idaccesorios_vehiculos.
                    */
                    if ((int)$idsalidadetalle === 0) {

                        foreach ($accesorios as $accesorio) {

                            $idaccesorios_vehiculos = $accesorio["idaccesorios_vehiculos"] ?? null;

                            if (empty($idaccesorios_vehiculos)) {
                                continue;
                            }

                            $okAccesorio = $stmtInsertAccesorio->execute([
                                ':idsalidadetalle' => $idDetalleParaAccesorios,
                                ':idaccesorios_vehiculos' => $idaccesorios_vehiculos,
                                ':cantidad' => $accesorio["cantidad"] ?? 0,
                                ':texto' => $accesorio["texto"] ?? ''
                            ]);

                            if (!$okAccesorio) {
                                $mensaje = 'No se pudo registrar un accesorio de salida';
                                $continuar = false;
                                break;
                            }
                        }

                        if (!$continuar) {
                            break;
                        }

                    } else {

                        $accesoriosActuales = [];

                        $stmtAccesoriosActuales->execute([
                            ':idsalidadetalle' => $idDetalleParaAccesorios
                        ]);

                        while ($rowAccesorio = $stmtAccesoriosActuales->fetch(PDO::FETCH_ASSOC)) {
                            $accesoriosActuales[] = array(
                                'idsalidadetalle_accesorios' => (int)$rowAccesorio['idsalidadetalle_accesorios'],
                                'idaccesorios_vehiculos' => (int)$rowAccesorio['idaccesorios_vehiculos']
                            );
                        }

                        $idsAccesoriosVehiculosRecibidos = [];

                        foreach ($accesorios as $accesorio) {

                            $idaccesorios_vehiculos = $accesorio["idaccesorios_vehiculos"] ?? null;

                            if (empty($idaccesorios_vehiculos)) {
                                continue;
                            }

                            $idaccesorios_vehiculos = (int)$idaccesorios_vehiculos;
                            $idsAccesoriosVehiculosRecibidos[] = $idaccesorios_vehiculos;

                            $indexActual = array_search(
                                $idaccesorios_vehiculos,
                                array_column($accesoriosActuales, 'idaccesorios_vehiculos')
                            );

                            if (is_numeric($indexActual)) {

                                $okAccesorio = $stmtUpdateAccesorio->execute([
                                    ':cantidad' => $accesorio["cantidad"] ?? 0,
                                    ':texto' => $accesorio["texto"] ?? '',
                                    ':idsalidadetalle_accesorios' => $accesoriosActuales[$indexActual]['idsalidadetalle_accesorios'],
                                    ':idsalidadetalle' => $idDetalleParaAccesorios
                                ]);

                            } else {

                                $okAccesorio = $stmtInsertAccesorio->execute([
                                    ':idsalidadetalle' => $idDetalleParaAccesorios,
                                    ':idaccesorios_vehiculos' => $idaccesorios_vehiculos,
                                    ':cantidad' => $accesorio["cantidad"] ?? 0,
                                    ':texto' => $accesorio["texto"] ?? ''
                                ]);
                            }

                            if (!$okAccesorio) {
                                $mensaje = 'No se pudo guardar un accesorio de salida';
                                $continuar = false;
                                break;
                            }
                        }

                        if (!$continuar) {
                            break;
                        }

                        /*
                        Soft delete de accesorios que ya no llegaron.
                        */
                        foreach ($accesoriosActuales as $accesorioActual) {

                            if (!in_array((int)$accesorioActual['idaccesorios_vehiculos'], $idsAccesoriosVehiculosRecibidos)) {

                                $okAccesorio = $stmtSoftDeleteAccesorio->execute([
                                    ':idsalidadetalle_accesorios' => $accesorioActual['idsalidadetalle_accesorios'],
                                    ':idsalidadetalle' => $idDetalleParaAccesorios
                                ]);

                                if (!$okAccesorio) {
                                    $mensaje = 'No se pudo eliminar un accesorio de salida';
                                    $continuar = false;
                                    break;
                                }
                            }
                        }

                        if (!$continuar) {
                            break;
                        }
                    }
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Eliminar detalles que ya no llegaron
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $stmtDetallesActuales = $conexion->prepare("
                SELECT idsalidadetalle
                FROM t_salidadetalle
                WHERE idsalida = :idsalida
            ");

            $stmtDetallesActuales->execute([
                ':idsalida' => $idsalidanum
            ]);

            $stmtDeleteAccesoriosDetalle = $conexion->prepare("
                DELETE FROM t_salidadetalle_accesorios
                WHERE idsalidadetalle = :idsalidadetalle
            ");

            $stmtDeleteDetalle = $conexion->prepare("
                DELETE FROM t_salidadetalle
                WHERE idsalidadetalle = :idsalidadetalle
                  AND idsalida = :idsalida
            ");

            while ($rowDetalleActual = $stmtDetallesActuales->fetch(PDO::FETCH_ASSOC)) {

                $idDetalleActual = (int)$rowDetalleActual['idsalidadetalle'];

                if (!in_array($idDetalleActual, $idsDetalleRecibidos)) {

                    $okDeleteAccesorios = $stmtDeleteAccesoriosDetalle->execute([
                        ':idsalidadetalle' => $idDetalleActual
                    ]);

                    if (!$okDeleteAccesorios) {
                        $mensaje = 'No se pudieron eliminar los accesorios del detalle';
                        $continuar = false;
                        break;
                    }

                    $okDeleteDetalle = $stmtDeleteDetalle->execute([
                        ':idsalidadetalle' => $idDetalleActual,
                        ':idsalida' => $idsalidanum
                    ]);

                    if (!$okDeleteDetalle) {
                        $mensaje = 'No se pudo eliminar un detalle de salida';
                        $continuar = false;
                        break;
                    }
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar / revertir
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información general';

        } else {

            if ($conexion->inTransaction()) {
                $conexion->rollBack();
            }
        }

    } catch (PDOException $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error de base de datos: ' . $e->getMessage();

    } catch (Exception $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error general: ' . $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'detalle' => getDetalleSalida($idsalida, 0, $conexion, false)
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

$app->put('/salidas/accesorios/{idsalidadetalle}/imagenes', function(Request $request, Response $response, array $args) use ($conexion) {
    $idsalidadetalle = $args['idsalidadetalle'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    $idusuario=$decoded_array['idusuario'];
    
    $params = json_decode((string) $request->getBody(),true);
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
        
    $piramideUploader=new PiramideUploader();
    
    //$idInventario = intval($params['idinventariofisicoconteo']);
    $folderPath =   folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/accesorios_salidas/'.$idsalidadetalle;
    if (!file_exists($folderPath)) {
        mkdir($folderPath, 0777, true);
    }

    // Procesar imágenes
    foreach ($params['imagenes'] as $imagen) {
        if (intval($imagen['idsalidadetalleimagen']) !== 0) {
            continue; // Ya insertada
        }

        $base64 = $imagen['itemImageSrc'];

        if (preg_match('/^data:image\/(\w+);base64,/', $base64, $type)) {
            $base64 = substr($base64, strpos($base64, ',') + 1);
            $extension = strtolower($type[1]);
            if (!in_array($extension, ['jpg', 'jpeg', 'png'])) {
                continue; // formato no permitido
            }
        } else {
            continue; // formato inválido
        }

        $base64 = str_replace(' ', '+', $base64);
        $imageData = base64_decode($base64);

        if ($imageData === false) {
            continue; // error al decodificar
        }

        // Generar nombre único
        $imageName = uniqid('img_' . date('Ymd_His') . '_') . '.' . $extension;
        $imagePath = $folderPath . '/' . $imageName;

        // Guardar imagen
        file_put_contents($imagePath, $imageData);

        // Registrar en base de datos
        $stmtImg = $conexion->prepare("INSERT INTO t_salidadetalleimagen (idsalidadetalle, imagen) VALUES (?, ?)");
        $stmtImg->execute([$idsalidadetalle, $imageName]);
    }
        
    
    $codigo=200;
    $status='Exito';
    $mensaje='Se guardo la información General';
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
