$app->put('/salidas/{idsalida}/finalizar', function(Request $request, Response $response, array $args) use ($conexion) {

    $idsalida = $args['idsalida'] ?? null;

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'No se guardó la información';

    $mensajeserror = [];
    $detalleitems = [];

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if (empty($idsalida)) {
            $mensaje = 'No se recibió la salida';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Obtener salida
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $salida = getSalida($idsalida, $conexion);

            if (empty($salida) || !is_array($salida)) {
                $mensaje = 'No se encontró la salida';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Obtener detalle
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $detalleitems = $salida["detalle"] ?? [];

            if (!is_array($detalleitems)) {
                $mensaje = 'El detalle de la salida no tiene un formato válido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar que exista detalle
        |--------------------------------------------------------------------------
        */
        if ($continuar && count($detalleitems) === 0) {
            $mensaje = 'La salida no tiene detalle para finalizar';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Validar rubros
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $centros_rubros = array_unique(array_filter(array_column($detalleitems, 'centro_rubro')));

            if (count($centros_rubros) > 1) {
                $mensajeserror[] = array(
                    'codigo' => implode(",", $centros_rubros),
                    'error' => 'Existen múltiples rubros (' . implode(",", $centros_rubros) . ') en el detalle de items',
                    'disponible' => 0
                );
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar almacén destino si es movimiento
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $esMovimiento = !empty($salida["movimiento"]);

            if (
                (!isset($salida["idalmacen_destino"]) || $salida["idalmacen_destino"] === '') &&
                $esMovimiento
            ) {
                $mensajeserror[] = array(
                    'codigo' => '',
                    'error' => 'No está registrado el dato de almacén destino (Dirección de entrega)',
                    'disponible' => 0
                );
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar stock / saldo disponible
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            for ($i = 0; $i < count($detalleitems); $i++) {

                $idingresodetalle = $detalleitems[$i]['idingresodetalle'] ?? null;
                $codigoItem = $detalleitems[$i]['codigo'] ?? '';

                $cantidadSolicitada = (float)($detalleitems[$i]['cantidad'] ?? 0);
                $pesoSolicitado = (float)($detalleitems[$i]['peso'] ?? 0);

                if (empty($idingresodetalle)) {
                    $mensajeserror[] = array(
                        'codigo' => $codigoItem,
                        'error' => 'El código ' . $codigoItem . ' no tiene ingreso detalle asociado',
                        'disponible' => 0
                    );

                    continue;
                }

                $saldoactual = getDetalleItem($idingresodetalle, $conexion);

                if (empty($saldoactual) || !is_array($saldoactual)) {
                    $mensajeserror[] = array(
                        'codigo' => $codigoItem,
                        'error' => 'No se pudo obtener el saldo actual del código ' . $codigoItem,
                        'disponible' => 0
                    );

                    continue;
                }

                $cantidadActual = (float)($saldoactual['cantidadactual'] ?? 0);
                $pesoActual = (float)($saldoactual['pesoactual'] ?? 0);

                if ($cantidadSolicitada > $cantidadActual) {
                    $mensajeserror[] = array(
                        'codigo' => $codigoItem,
                        'error' => 'El código ' . $codigoItem . ' tiene más cantidad (' . $cantidadSolicitada . ') de lo que se tiene disponible (' . $cantidadActual . ')',
                        'disponible' => $cantidadActual
                    );
                }

                if ($pesoSolicitado > $pesoActual) {
                    $mensajeserror[] = array(
                        'codigo' => $codigoItem,
                        'error' => 'El código ' . $codigoItem . ' tiene más peso (' . $pesoSolicitado . ') de lo que se tiene disponible (' . $pesoActual . ')',
                        'disponible' => $pesoActual
                    );
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Finalizar salida
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if (count($mensajeserror) > 0) {
                $mensaje = 'Existen errores en el detalle de salida';
                $continuar = false;
            }
        }

        if ($continuar) {

            $queryFinalizar = "
                UPDATE t_salida
                SET finalizado = 1
                WHERE MD5(idsalida) = :idsalida
            ";

            $stmtFinalizar = $conexion->prepare($queryFinalizar);

            $resultFinalizar = $stmtFinalizar->execute([
                ':idsalida' => $idsalida
            ]);

            if (!$resultFinalizar) {
                $mensaje = 'No se pudo finalizar la salida';
                $continuar = false;
            } elseif ($stmtFinalizar->rowCount() === 0) {
                $mensaje = 'No se encontró la salida para finalizar';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Respuesta exitosa
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se finalizó la salida correctamente';
        }

    } catch (PDOException $e) {

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error de base de datos: ' . $e->getMessage();

    } catch (Exception $e) {

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error general: ' . $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'mensajeserror' => $mensajeserror
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

