        $idingresodetalleaux=(int)$row['idingresodetalle'];
        $idembalajeaux=(int)$row['idembalaje']; 
        
        $inventariofinal=$inicial+(float)$row['ingreso']-(float)$row['salida'];
        */
        $movimientosinicial[]=array(
            //'idingresodetalle'=>(int)$row['idingresodetalle'],
            'idcliente'=>$row['idcliente'],
            'cliente'=>$row['cliente'],
