            'codigosalida'=>$row['codigosalida'],
            'codigo'=>$row['codigo'],
            //'serie'=>$row['serie'],
            'descripcion'=>$row['descripcion'],
            //'lote'=>$row['lote'],
            //'fechavencimiento'=>$row['fechavencimiento'],
            //'categoria'=>$row['categoria'],
            'idembalaje'=>(int)$row['idembalaje'],
            'codigoembalaje'=>$row['codigoembalaje'],
            'fechamovimiento'=>$row['fechamovimiento'],
            'inicial'=>0,
            'ingreso'=>(float)$row['ingreso'],
            'salida'=>(float)$row['salida'],
            'inventariofinal'=>0,
            'diaspermanencia'=>0,
            'factor'=>(float)$row['factor'],
            'factor_dimensiones'=>(float)$row['factor_dimensiones'],
            'factor_dimensiones_adicional'=>(float)$row['factor_dimensiones_adicional'],
            'tarifa_adicional'=>(float)$row['tarifa_adicional'],
            'inbound_adicional'=>(float)$row['inbound'],
            'outbound_adicional'=>(float)$row['outbound']
        );
    }
    
    $movimientos_orden_1 = array_orderby($movimientosinicial, 'cliente', SORT_ASC, 'codigo', SORT_ASC, 'fechamovimiento');
    
    $codigoauxiliar='';
    $inventariofinal=0;
    for($cc=0;$cc<count($movimientos_orden_1);$cc++){
        if($codigoauxiliar<>$movimientos_orden_1[$cc]["codigo"]){
            $inventariofinal=0;
        }
        
        if($movimientos_orden_1[$cc]["idtipomovimiento"]==0){
            $inicial=(float)$movimientos_orden_1[$cc]["inicial"]+$inventariofinal;
        }else{
            if($codigoauxiliar==$movimientos_orden_1[$cc]["codigo"]){
                $inicial=$inventariofinal;
            }else{
                $inicial=(float)$movimientos_orden_1[$cc]["inicial"];
            }
        }
        
        $inventariofinal=$inicial+(float)$movimientos_orden_1[$cc]['ingreso']-(float)$movimientos_orden_1[$cc]['salida'];
        $codigoauxiliar=$movimientos_orden_1[$cc]["codigo"];
        $movimientos_orden_1[$cc]["inicial"]=$inicial;
        $movimientos_orden_1[$cc]["inventariofinal"]=$inventariofinal;
        
        $movimientos_orden_1[$cc]["fechamovimiento"]=$movimientos_orden_1[$cc]["fechamovimiento"]." 12:00";
        
        $movimientos_orden_1[$cc]["inicialmq"]=$movimientos_orden_1[$cc]["inicial"]*$movimientos_orden_1[$cc]["factor"];
        $movimientos_orden_1[$cc]["ingresomq"]=$movimientos_orden_1[$cc]["ingreso"]*$movimientos_orden_1[$cc]["factor"];
        $movimientos_orden_1[$cc]["salidamq"]=$movimientos_orden_1[$cc]["salida"]*$movimientos_orden_1[$cc]["factor"];
        $movimientos_orden_1[$cc]["inventariofinalmq"]=$movimientos_orden_1[$cc]["inventariofinal"]*$movimientos_orden_1[$cc]["factor"];
        
        
        $fecha2=$fechafinal;
        if(($cc+1)>=count($movimientos_orden_1)){
            $fecha2=$fechafinal;
        }else{
            if($movimientos_orden_1[$cc]["codigo"]==$movimientos_orden_1[$cc+1]["codigo"]){
                $fecha2=$movimientos_orden_1[$cc+1]["fechamovimiento"];
            }else{
                $fecha2=$fechafinal;
            }
        }
        $date1=date_create($movimientos_orden_1[$rr]["fechamovimiento"]);
        $date2=date_create($fecha2);
        $diff=date_diff($date1,$date2);
        $movimientos_orden_1[$cc]["diaspermanencia"]=$diff->format("%a");
        
        
        
        /*
        if($cc==0){
            $acumulado=$movimientos[$cc]["inventariofinalmq"];
        }else{
            $acumulado=$movimientos[$cc-1]["acumulado"]+$movimientos[$cc]["inicialmq"]+$movimientos[$cc]["ingresomq"]-$movimientos[$cc]["salidamq"];
        }
        $movimientos[$cc]["acumulado"]=$acumulado;
        */
        
    }
    
    //$movimientos = $movimientos_orden_1;
    
    $movimientos = array_orderby($movimientos_orden_1, 'cliente', SORT_ASC, 'fechamovimiento');
    
    $idclienteaux=0;
    for($cc=0;$cc<count($movimientos);$cc++){
        $date1 = new DateTime($movimientos[$cc]["fechamovimiento"]);
        if(($cc+1)==count($movimientos)){
            $date2 = new DateTime($fechafinal);
        }else{
            if((int)$movimientos[$cc]["idcliente"]==(int)$movimientos[$cc+1]["idcliente"]){
                $date2 = new DateTime($movimientos[$cc+1]["fechamovimiento"]);
            }else{
                $date2 = new DateTime($fechafinal);
            }
                
        }
        $diff = $date1->diff($date2);
        $dias=$diff->days;
        $movimientos[$cc]["diasliquidacion"]=(int)$dias+1;
        
        if($idclienteaux==(int)$movimientos[$cc]["idcliente"]){
            if($movimientos[$cc]["idtipomovimiento"]==0){
                $acumulado=$acumulado+$movimientos[$cc]["inicialmq"]+$movimientos[$cc]["ingresomq"]-$movimientos[$cc]["salidamq"];
            }else{
                $acumulado=$acumulado+$movimientos[$cc]["ingresomq"]-$movimientos[$cc]["salidamq"];
            }
        }else{
            $acumulado=(float)$movimientos[$cc]["inicialmq"];
        }
        
        $movimientos[$cc]["acumulado"]=$acumulado;
        
        $idclienteaux=(int)$movimientos[$cc]["idcliente"];
        
        
        if($acumulado>$movimientos[$cc]["factor_dimensiones"]){
            $movimientos[$cc]["adicional"]="SI";
            if($movimientos[$cc]["factor_dimensiones_adicional"]>0){
                $movimientos[$cc]["posiciones_adicionales"]= ceil(($acumulado-$movimientos[$cc]["factor_dimensiones"])/$movimientos[$cc]["factor_dimensiones_adicional"]);
            }else{
                $movimientos[$cc]["posiciones_adicionales"]=0;
            }
        } else {
            $movimientos[$cc]["adicional"]="NO";
            $movimientos[$cc]["posiciones_adicionales"]=0;
        }
        
        
        
        
        if($movimientos[$cc]["posiciones_adicionales"]==0){
            $movimientos[$cc]["inbound"]=0;
            $movimientos[$cc]["outbound"]=0;
        }else{
            if($movimientos[$cc]["factor_dimensiones_adicional"]>0){
                $condicion=$movimientos[$cc]["posiciones_adicionales"]/$movimientos[$cc]["factor_dimensiones_adicional"];
                if($condicion<$movimientos[$cc]["ingreso"]){
                    $movimientos[$cc]["inbound"]=$condicion;
                }else{
                    $movimientos[$cc]["inbound"]=$movimientos[$cc]["ingreso"];
                }
                
                if($condicion<$movimientos[$cc]["salida"]){
                    $movimientos[$cc]["outbound"]=$condicion;
                }else{
                    $movimientos[$cc]["outbound"]=$movimientos[$cc]["salida"];
                }
            }else{
                $movimientos[$cc]["inbound"]=0;
                $movimientos[$cc]["outbound"]=0;
            }
        }
        
        
        $movimientos[$cc]["ad_inbound"]=$movimientos[$cc]["inbound"]*$movimientos[$cc]["inbound_adicional"];
        $movimientos[$cc]["ad_outbound"]=$movimientos[$cc]["outbound"]*$movimientos[$cc]["outbound_adicional"];
        
        
        
    }
    
    for($cc=0;$cc<count($movimientos);$cc++){
        $movimientos[$cc]["filtrado_fechamovimiento"]=array();
        for($ccc=0;$ccc<count($movimientos);$ccc++){
            if($movimientos[$ccc]["idcliente"]==$movimientos[$cc]["idcliente"] && $movimientos[$ccc]["fechamovimiento"]==$movimientos[$cc]["fechamovimiento"]){
                array_push($movimientos[$cc]["filtrado_fechamovimiento"],$movimientos[$ccc]["posiciones_adicionales"]);
                /*
                $movimientos[$cc]["filtrado_fechamovimiento"][]=array(
                    'fechamovimiento'=>$movimientos[$cc]["fechamovimiento"],
                    'posiciones_adicionales'=>$movimientos[$ccc]["posiciones_adicionales"]
                );
                 * 
                 */
            }
        }
        
        $movimientos[$cc]["max"]=max($movimientos[$cc]["filtrado_fechamovimiento"]);
        $movimientos[$cc]["max_posiciones"]=0;
        if($movimientos[$cc]["max"]==$movimientos[$cc]["posiciones_adicionales"]){
            $movimientos[$cc]["max_posiciones"]=$movimientos[$cc]["posiciones_adicionales"];
        }
        
        if(($cc+1)==count($movimientos)){
            $fechacomparacion=$fechafinal;
            $max_posicioncomparacion=0;
        }else{
            if($movimientos[$cc+1]["idcliente"]==$movimientos[$cc]["idcliente"]){
                $fechacomparacion=$movimientos[$cc+1]["fechamovimiento"];
                $max_posicioncomparacion=$movimientos[$cc+1]["max_posiciones"];
            }else{
                $fechacomparacion=$fechafinal;
                $max_posicioncomparacion=0;
            }
        }
        
        if($fechacomparacion==$movimientos[$cc]["fechamovimiento"]){
            if($max_posicioncomparacion==$movimientos[$cc]["max_posiciones"]){
                $movimientos[$cc]["posiciones_adicionales_real"]=0;
            }else{
                $movimientos[$cc]["posiciones_adicionales_real"]=$movimientos[$cc]["max_posiciones"];
            }
        }else{
            $movimientos[$cc]["posiciones_adicionales_real"]=$movimientos[$cc]["posiciones_adicionales"];
        }
        
        $movimientos[$cc]["fee_adicional"]=$movimientos[$cc]["posiciones_adicionales_real"]*$movimientos[$cc]["diasliquidacion"]*$movimientos[$cc]["tarifa_adicional"];
        $movimientos[$cc]["total_adicional"]=$movimientos[$cc]["fee_adicional"]+$movimientos[$cc]["ad_inbound"]+$movimientos[$cc]["ad_outbound"];
        
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'movimientos' => $movimientos,
        'timezone' => date_default_timezone_get()
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/reportemovimientosdetalle/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
