        AND CAST(t_ingreso.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        AND IFNULL(t_ingresodetalle.dividido,0)=0
        
        UNION ALL
        
        select 
        t_ingresodetalle.idingresodetalle,
        t_salida.idcliente,
        t_cliente.cliente,
        CAST(t_salida.fecha as DATE) as fechamovimiento,
        CASE IFNULL(t_ingreso.es_vehiculo,0)
            WHEN 1 THEN t_ingresodetalle.serie
            ELSE t_ingresodetalle.codigo
        END as codigo,
        t_ingresodetalle.descripcion,
        t_ingresodetalle.lote,
        2 as idtipomovimiento,
        'Salida' as tipomovimiento,
        t_salida.proyecto_no,
        t_salida.contrato_no as referencia_cliente,
        CONCAT(t_ingreso.numero,'/',t_ingreso.gestion) as correlativo,
        t_salida.delivery_note as orden_pedido,
        t_ingresodetalle.idembalaje,
        t_embalaje.codigoembalaje,
        t_merma.merma,
        t_clasificacion.clasificacion,
        t_no_conf.no_conf,
        t_salidadetalle.cantidad
        from 
        t_ingresodetalle 
        LEFT JOIN t_salidadetalle ON t_ingresodetalle.idingresodetalle=t_salidadetalle.idingresodetalle 
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida 
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN t_merma ON t_ingresodetalle.idmerma=t_merma.idmerma
        LEFT JOIN t_clasificacion ON t_ingresodetalle.idclasificacion=t_clasificacion.idclasificacion
        LEFT JOIN t_no_conf ON t_ingresodetalle.idno_conf=t_no_conf.idno_conf
        WHERE 
        t_salida.idalmacen=$idalmacen
        $filtroclientesalidas
        $filtroingresodetalle
        AND CAST(t_salida.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        AND IFNULL(t_salida.finalizado,0)=1
        ORDER BY
        cliente,
        fechamovimiento,
        idingresodetalle;";
    
    $result = $conexion->query($query_ing_salidas);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $movimientos[]=array(
            'idingresodetalle'=>(int)$row['idingresodetalle'],
            'idcliente'=>$row['idcliente'],
            'cliente'=>$row['cliente'],
            'fechamovimiento'=>$row['fechamovimiento'],
            'codigo'=>$row['codigo'],
            'descripcion'=>$row['descripcion'],
            'lote'=>$row['lote'],
            'idtipomovimiento'=>(int)$row['idtipomovimiento'],
            'tipomovimiento'=>$row['tipomovimiento'],
            'proyecto_no'=>$row['proyecto_no'],
            'referencia_cliente'=>$row['referencia_cliente'],
            'correlativo'=>$row['correlativo'],
            'orden_pedido'=>$row['orden_pedido'],
            'idembalaje'=>(int)$row['idembalaje'],
            'codigoembalaje'=>$row['codigoembalaje'],
            'merma'=>$row['merma'],
            'no_conf'=>$row['no_conf'],
            'clasificacion'=>$row['clasificacion'],
            'cantidad'=>(float)$row['cantidad'],
        );
    }

    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'movimientos' => $movimientos,
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/reportemovimientostienda/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idalmacen=$decoded_array["idalmacen"];
    
    
    $movimientosinicial=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidasinicial;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidasinicial (idingresodetalle INT, salidasinicial DECIMAL(13,2));");
    $conexion->query("INSERT INTO tmp_salidasinicial (idingresodetalle, salidasinicial) 
        select 
        t_ingresodetalle.idingresodetalle, 
        SUM(t_salidadetalle.cantidad) as salidasinicial 
        from 
        t_ingresodetalle 
        LEFT JOIN t_salidadetalle ON t_ingresodetalle.idingresodetalle=t_salidadetalle.idingresodetalle 
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida 
        WHERE 
        t_salida.idalmacen=$idalmacen
        AND t_salida.idcliente=$idcliente
        AND CAST(t_salida.fecha as DATE)<'$fechainicial'
        AND IFNULL(t_salida.finalizado,0)=1 
        GROUP BY 
        t_ingresodetalle.idingresodetalle;");
    $conexion->query("ALTER TABLE tmp_salidasinicial ADD INDEX idingresodetalle (idingresodetalle);");
    
    $result = $conexion->query("SELECT
        t_ingresodetalle.idingresodetalle,
        t_ingresodetalle.codigo,
        t_ingresodetalle.serie,
        t_ingresodetalle.descripcion,
        t_ingresodetalle.categoria,
        t_ingresodetalle.centro_distribucion,
        t_embalaje.codigoembalaje,
        t_ingresodetalle.cantidad-IFNULL(tmp_salidasinicial.salidasinicial,0) as inicial,
        IF(t_ingresodetalle.dividido IS NULL,0,1) as dividido
        FROM
        t_ingresodetalle
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN tmp_salidasinicial ON t_ingresodetalle.idingresodetalle=tmp_salidasinicial.idingresodetalle
        LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
        WHERE
        t_ingreso.idalmacen=$idalmacen
        AND t_ingreso.idcliente=$idcliente
        AND CAST(t_ingreso.fecha as DATE)<'$fechainicial'
        AND t_ingresodetalle.idingresodetallepadre IS NULL;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        
        $valorinicial=(float)$row["inicial"];
        
        if((int)$row["dividido"]==1){
            $idingresodetallepadre=$row["idingresodetalle"];
            do {
                $existedivision=0;
                $idingresodetallehijos='0';
                $resultdiv = $conexion->query("SELECT
                    t_ingresodetalle.idingresodetalle,
                    t_ingresodetalle.cantidad,
                    IFNULL(tmp_salidasinicial.salidasinicial,0) as inicial,
                    IF(t_ingresodetalle.dividido IS NULL,0,1) as dividido
                    FROM
                    t_ingresodetalle
                    LEFT JOIN tmp_salidasinicial ON t_ingresodetalle.idingresodetalle=tmp_salidasinicial.idingresodetalle
                    WHERE
                    t_ingresodetalle.idingresodetallepadre in ($idingresodetallepadre);");
                while ($rowdiv =  $resultdiv ->fetch(PDO::FETCH_ASSOC)){
                    $existedivision=$existedivision+(int)$rowdiv["dividido"];
                    
                    $valorinicial=$valorinicial-(float)$rowdiv["inicial"];
                    
                    if((int)$rowdiv["dividido"]==1){
                        $idingresodetallehijos=$idingresodetallehijos.",".$rowdiv["idingresodetalle"];
                    }
                }
                $idingresodetallepadre=$idingresodetallehijos;

            } while ($existedivision>0);
            
        }
        if((float)$valorinicial>0){
            $key = array_search($row["codigo"]."-".$row["serie"]."-".$row["descripcion"]."-".$row["categoria"]."-".$row["centro_distribucion"]."-".$row["codigoembalaje"], array_column($movimientosinicial, 'id'));
            if(is_numeric($key)){
                $movimientosinicial[$key]["inicial"]=$movimientosinicial[$key]["inicial"]+$valorinicial;
            }else{
                $movimientosinicial[]=array(
                    'id'=>$row["codigo"]."-".$row["serie"]."-".$row["descripcion"]."-".$row["categoria"]."-".$row["centro_distribucion"]."-".$row["codigoembalaje"],
                    'inicial'=>$valorinicial
                );
            }
        }
        
    }
    
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidas;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidas (codigo VARCHAR(250), serie VARCHAR(100), descripcion VARCHAR(250), categoria VARCHAR(150), centro_distribucion VARCHAR(50), proyecto VARCHAR(250), cantidad DECIMAL(13,2), codigoembalaje VARCHAR(10));");
    $conexion->query("INSERT INTO tmp_salidas (codigo, serie, descripcion, categoria, centro_distribucion, proyecto, codigoembalaje, cantidad)
            select
            t_ingresodetalle.codigo,
            t_ingresodetalle.serie,
            t_ingresodetalle.descripcion,
            t_ingresodetalle.categoria,
            t_ingresodetalle.centro_distribucion,
            IFNULL(t_salida.proyecto_no,'') as proyecto,
            t_embalaje.codigoembalaje,
            SUM(t_salidadetalle.cantidad) as cantidad
            FROM
            t_salida
            LEFT JOIN t_salidadetalle ON t_salida.idsalida=t_salidadetalle.idsalida
            LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
            LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
            WHERE
            t_salida.idalmacen=$idalmacen
            AND t_salida.idcliente=$idcliente
            AND t_salida.finalizado=1
            AND CAST(t_salida.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
            GROUP BY
            t_ingresodetalle.codigo,
            t_ingresodetalle.serie,
            t_ingresodetalle.descripcion,
            t_ingresodetalle.categoria,
            t_ingresodetalle.centro_distribucion,
            IFNULL(t_salida.proyecto_no,''),
            t_embalaje.codigoembalaje;");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX codigo (codigo);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX serie (serie);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX descripcion (descripcion);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX categoria (categoria);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX centro_distribucion (centro_distribucion);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX proyecto (proyecto);");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX codigoembalaje (codigoembalaje);");
    
    $columnas=[];
    $result = $conexion->query("select DISTINCT proyecto from tmp_salidas ORDER BY proyecto;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $columnas[]=array(
            'proyecto'=>$row['proyecto'],
            'columna'=>'cantidad_'. str_replace(" ", "_", preg_replace("/[^A-Za-z0-9 ]/", '', $row['proyecto'])),
            'salida'=>''
        );
    }
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ingresos;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_ingresos (codigo VARCHAR(250), serie VARCHAR(100), descripcion VARCHAR(250), categoria VARCHAR(150), centro_distribucion VARCHAR(50), codigoembalaje VARCHAR(10), cantidad DECIMAL(13,2));");
    $conexion->query("INSERT INTO tmp_ingresos (codigo, serie, descripcion, categoria, centro_distribucion, codigoembalaje, cantidad)
            select
            t_ingresodetalle.codigo,
            t_ingresodetalle.serie,
            t_ingresodetalle.descripcion,
            t_ingresodetalle.categoria,
            t_ingresodetalle.centro_distribucion,
            t_embalaje.codigoembalaje,
            SUM(t_ingresodetalle.cantidad) as cantidad
            FROM
            t_ingreso
            LEFT JOIN t_ingresodetalle ON t_ingreso.idingreso=t_ingresodetalle.idingreso
            LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
            WHERE
            t_ingreso.idalmacen=$idalmacen
            AND t_ingreso.idcliente=$idcliente
            AND CAST(t_ingreso.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
            GROUP BY
            t_ingresodetalle.codigo,
            t_ingresodetalle.serie,
            t_ingresodetalle.descripcion,
            t_ingresodetalle.categoria,
            t_ingresodetalle.centro_distribucion,
            t_embalaje.codigoembalaje;");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX codigo (codigo);");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX serie (serie);");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX descripcion (descripcion);");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX categoria (categoria);");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX centro_distribucion (centro_distribucion);");
    $conexion->query("ALTER TABLE tmp_ingresos ADD INDEX codigoembalaje (codigoembalaje);");
    
    
    
    
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_reporte;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_reporte (codigo VARCHAR(250), serie VARCHAR(100), descripcion VARCHAR(250), categoria VARCHAR(150), centro_distribucion VARCHAR(100), codigoembalaje VARCHAR(10));");
    $conexion->query("INSERT INTO tmp_reporte (codigo, serie, descripcion, categoria, centro_distribucion, codigoembalaje) 
        SELECT
        DISTINCT
        t_ingresodetalle.codigo,
        t_ingresodetalle.serie,
        t_ingresodetalle.descripcion,
        t_ingresodetalle.categoria,
        t_ingresodetalle.centro_distribucion,
        t_embalaje.codigoembalaje
        FROM
        t_ingresodetalle
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
        WHERE
        t_ingreso.idalmacen=$idalmacen
        AND t_ingreso.idcliente=$idcliente
        AND t_ingresodetalle.idingresodetallepadre IS NULL;");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX codigo (codigo);");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX serie (serie);");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX descripcion (descripcion);");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX categoria (categoria);");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX centro_distribucion (centro_distribucion);");
    $conexion->query("ALTER TABLE tmp_reporte ADD INDEX codigoembalaje (codigoembalaje);");
    
    $movimientos=[];
    
    $result = $conexion->query("SELECT 
        tmp_reporte.codigo, 
        tmp_reporte.serie, 
        tmp_reporte.descripcion, 
        tmp_reporte.categoria, 
        tmp_reporte.centro_distribucion, 
        tmp_reporte.codigoembalaje,
        tmp_ingresos.cantidad as ingresos
        FROM
        tmp_reporte
        LEFT JOIN tmp_ingresos ON tmp_reporte.codigo=tmp_ingresos.codigo AND tmp_reporte.serie=tmp_ingresos.serie AND tmp_reporte.descripcion=tmp_ingresos.descripcion AND tmp_reporte.categoria=tmp_ingresos.categoria AND tmp_reporte.centro_distribucion=tmp_ingresos.centro_distribucion AND tmp_reporte.codigoembalaje=tmp_ingresos.codigoembalaje
        ORDER BY tmp_reporte.codigo;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $inicial=0;
        $key = array_search($row["codigo"]."-".$row["serie"]."-".$row["descripcion"]."-".$row["categoria"]."-".$row["centro_distribucion"]."-".$row["codigoembalaje"], array_column($movimientosinicial, 'id'));
        if(is_numeric($key)){
            $inicial=(float)$movimientosinicial[$key]["inicial"];
        }
        
        $tiendas=$columnas;
        
        
        $salidas=0;
        for($tt=0;$tt<count($tiendas);$tt++){
            $salida=null;
            $resulttienda = $conexion->query("SELECT 
                cantidad
                FROM
                tmp_salidas
                WHERE
                codigo='".$row["codigo"]."'
                AND serie='".$row["serie"]."'
                AND descripcion='".$row["descripcion"]."'
                AND categoria='".$row["categoria"]."'
                AND centro_distribucion='".$row["centro_distribucion"]."'
                AND codigoembalaje='".$row["codigoembalaje"]."'
                AND proyecto='".$tiendas[$tt]["proyecto"]."';");
            while ($rowtienda =  $resulttienda ->fetch(PDO::FETCH_ASSOC)){
                $salida=(float)$rowtienda["cantidad"];
            }
            $salidas=$salidas+(float)$salida;
            $tiendas[$tt]["salida"]=$salida;
        }
        
        $saldo=0;
        if($inicial>0 || (float)$row['ingresos']>0){
            $saldo=$inicial+(float)$row['ingresos']-$salidas;
            $ingresos=null;
            if((float)$row['ingresos']>0){
                $ingresos=(float)$row['ingresos'];
            }
            $movimientos[]=array(
                'codigo'=>$row['codigo'],
                'serie'=>$row['serie'],
                'descripcion'=>$row['descripcion'],
                'categoria'=>$row['categoria'],
                'centro_distribucion'=>$row['centro_distribucion'],
                'codigoembalaje'=>$row['codigoembalaje'],
                'inicial'=>$inicial,
                'ingresos'=>$ingresos,
                'tiendas'=>$tiendas,
                'salidas'=>$salidas,
                'saldo'=>$saldo
            );
        }
        
            
        
    }
    
    
    
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'movimientos' => $movimientos
    )));
    
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/reporteliquidacion/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idalmacen=$decoded_array["idalmacen"];
    
    $filtroclienteingreso="";
    $filtroclientesalida="";
    $filtroclientepedido="";
    if((int)$idcliente>0){
        $filtroclienteingreso=" AND t_ingreso.idcliente=$idcliente";
        $filtroclientesalida=" AND t_salida.idcliente=$idcliente";
        $filtroclientepedido=" AND t_pedido.idcliente=$idcliente";
    }
    
    $reporte=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_ingresodetalle;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_ingresodetalle (idingreso INT, detalle TEXT, codigos TEXT);");
    $conexion->query("INSERT INTO tmp_ingresodetalle (idingreso, detalle, codigos)
        SELECT
        t_ingresodetalle.idingreso,
        GROUP_CONCAT(CONCAT('\"',t_ingresodetalle.codigo,'\"') SEPARATOR ',') as detalle,
        GROUP_CONCAT(DISTINCT t_ingresodetalle.codigo SEPARATOR ', ') as codigos
        FROM
        t_ingreso
        LEFT JOIN t_ingresodetalle ON t_ingreso.idingreso=t_ingresodetalle.idingreso
        WHERE
        t_ingreso.idalmacen=$idalmacen
        $filtroclienteingreso
        AND CAST(t_ingreso.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        GROUP BY
        t_ingresodetalle.idingreso;");
    $conexion->query("ALTER TABLE tmp_ingresodetalle ADD INDEX idingreso (idingreso);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidadetalle;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidadetalle (idsalida INT, detalle TEXT, peso DECIMAL(13,2), codigos TEXT);");
    $conexion->query("INSERT INTO tmp_salidadetalle (idsalida, detalle, peso, codigos)
        SELECT
        t_salidadetalle.idsalida,
        GROUP_CONCAT(CONCAT('\"',t_ingresodetalle.codigo,'\"') SEPARATOR ',') as detalle,
        SUM(t_salidadetalle.peso) as peso,
        GROUP_CONCAT(DISTINCT t_ingresodetalle.codigo SEPARATOR ', ') as codigos
        FROM
        t_salida
        LEFT JOIN t_salidadetalle ON t_salida.idsalida=t_salidadetalle.idsalida
        LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
        WHERE
        t_salida.idalmacen=$idalmacen
        $filtroclientesalida
        AND CAST(t_salida.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        GROUP BY
        t_salidadetalle.idsalida;");
    $conexion->query("ALTER TABLE tmp_salidadetalle ADD INDEX idsalida (idsalida);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_pedidodetalle;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_pedidodetalle (idpedido INT, descripcion TEXT, detalle TEXT, cantidad DECIMAL(13,2), codigos TEXT);");
    $conexion->query("INSERT INTO tmp_pedidodetalle (idpedido, descripcion, detalle, cantidad, codigos)
        SELECT
        t_pedidodetalle.idpedido,
        GROUP_CONCAT(DISTINCT t_pedidodetalle.descripcion SEPARATOR ',') as descripcion,
        GROUP_CONCAT(CONCAT('\"',t_pedidodetalle.codigo,'\"') SEPARATOR ',') as detalle,
        SUM(t_pediodetalletienda.cantidad) as cantidad,
        GROUP_CONCAT(DISTINCT t_pedidodetalle.codigo SEPARATOR ', ') as codigos
        FROM
        t_pedidodetalle
        LEFT JOIN t_pediodetalletienda ON t_pedidodetalle.idpedidodetalle=t_pediodetalletienda.idpedidodetalle
        LEFT JOIN t_pedido ON t_pedidodetalle.idpedido=t_pedido.idpedido
        WHERE
        t_pedido.idalmacen=$idalmacen
        $filtroclientepedido
        AND IFNULL(t_pedido.tipo_pedido,0)<>2
        AND CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        GROUP BY
        t_pedidodetalle.idpedido;");
    $conexion->query("ALTER TABLE tmp_pedidodetalle ADD INDEX idpedido (idpedido);");
    
    $result = $conexion->query("select
        t_ingreso.fecha,
        t_ingreso.numero,
        t_ingreso.gestion,
        t_cliente.cliente,
        'INGRESOS' as servicio,
        t_ingreso.cantidad_pallet,
        'PX' as embalaje,
        t_ingreso.project as descripcion,
        tmp_ingresodetalle.codigos,
        t_ingreso.peso_total,
        CONCAT('[',IFNULL(tmp_ingresodetalle.detalle,''),']') as detalle
        FROM
        t_ingreso
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_ingresodetalle ON t_ingreso.idingreso=tmp_ingresodetalle.idingreso
        WHERE
        t_ingreso.idalmacen=$idalmacen
        $filtroclienteingreso
        AND CAST(t_ingreso.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        UNION ALL
        SELECT
        t_salida.fecha,
        t_salida.numero,
        t_salida.gestion,
        t_cliente.cliente,
        'SALIDAS' as servicio,
        t_salida.cantidad_pallet,
        'PX' as embalaje,
        t_salida.proyecto_no as descripcion,
        tmp_salidadetalle.codigos,
        tmp_salidadetalle.peso as peso_total,
        CONCAT('[',IFNULL(tmp_salidadetalle.detalle,''),']') as detalle
        FROM
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_salidadetalle ON t_salida.idsalida=tmp_salidadetalle.idsalida
        WHERE
        t_salida.idalmacen=$idalmacen
        $filtroclientesalida
        AND CAST(t_salida.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        UNION ALL
        SELECT
        t_pedido.fecha,
        t_pedido.numero,
        t_pedido.gestion,
        t_cliente.cliente,
        'PEDIDOS' as servicio,
        tmp_pedidodetalle.cantidad as cantidad_pallet,
        'BULTOS' as embalaje,
        tmp_pedidodetalle.descripcion,
        tmp_pedidodetalle.codigos,
        0 as peso_total,
        CONCAT('[',IFNULL(tmp_pedidodetalle.detalle,''),']') as detalle
        FROM
        t_pedido
        LEFT JOIN t_cliente ON t_pedido.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_pedidodetalle ON t_pedido.idpedido=tmp_pedidodetalle.idpedido
        WHERE
        t_pedido.idalmacen=$idalmacen
        $filtroclientepedido
        AND IFNULL(t_pedido.tipo_pedido,0)<>2
        AND CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $reporte[]=array(
            'fecha'=>$row['fecha'],
            'numero'=>$row['numero'],
            'gestion'=>$row['gestion'],
            'cliente'=>$row['cliente'],
            'servicio'=>$row['servicio'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'embalaje'=>$row['embalaje'],
            'descripcion'=>$row['descripcion'],
            'codigos'=>$row['codigos'],
            'peso_total'=>$row['peso_total'],
            'detalle'=>json_decode($row["detalle"], true)
        );
        
        
    }
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'reporte' => $reporte
    )));
    
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/reporteposicionesdia/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idalmacen=$decoded_array["idalmacen"];
    
    $reporte=[];
    $columnas=[];
    $cong=[];
    $inventarios=[];
    
    $start_date = date_create($fechainicial);
    $end_date = date_create($fechafinal);
    $end_date = $end_date->modify( '+1 day' ); 

    $interval = new DateInterval('P1D');

    $date_range = new DatePeriod($start_date, $interval, $end_date);

    foreach ($date_range as $date) {
        $fecha=$date->format('Y-m-d');
        $inventario= getInventario($idcliente, $idalmacen, $fecha, $conexion,false, true, $date->format('Y-m-d'),false);
        //$inventarios[]=$inventario;
        for($ii=0;$ii<count($inventario);$ii++){
            if($inventario[$ii]["cantidad"]>0){
                /*
                if($inventario[$ii]["categoriaalmacendetalle"]=='CON'){
                    $cong[]=array(
                        'ubicacion'=>$inventario[$ii]['ubicacionalmacen'],
                        'codigo'=>$inventario[$ii]['codigo'],
                        'cantidad'=>$inventario[$ii]['cantidad']
                    );
                }
                */
                $key_columna = array_search($inventario[$ii]["idreferenciacolor"], array_column($columnas, 'field'));
                if(!is_numeric($key_columna)){
                    $columnas[]=array(
                        'field'=>$inventario[$ii]["idreferenciacolor"],
                        'header'=>$inventario[$ii]["referenciacolor"]
                    );
                }
                
                $key = array_search($fecha."|".$inventario[$ii]["categoriaalmacendetalle"], array_column($reporte, 'llave'));
                if(is_numeric($key)){
                    if(array_key_exists($inventario[$ii]["idreferenciacolor"], $reporte[$key])){
                        if(!in_array($inventario[$ii]["idalmacendetalle"], $reporte[$key]["posiciones".$inventario[$ii]["idreferenciacolor"]]) || (int)$inventario[$ii]["idalmacendetalle"]==0){
                            $reporte[$key][$inventario[$ii]["idreferenciacolor"]]++;
                            array_push($reporte[$key]['posiciones'.$inventario[$ii]["idreferenciacolor"]],$inventario[$ii]["idalmacendetalle"]);
                        }
                    }else{
                        $reporte[$key][$inventario[$ii]["idreferenciacolor"]]=1;
                        $reporte[$key]['posiciones'.$inventario[$ii]["idreferenciacolor"]]=array($inventario[$ii]["idalmacendetalle"]);
                    }
                }else{
                    $reporte[]=array(
                        'fecha'=>$fecha,
                        'categoriaalmacendetalle'=>$inventario[$ii]["categoriaalmacendetalle"],
                        'llave'=>$fecha."|".$inventario[$ii]["categoriaalmacendetalle"],
                        $inventario[$ii]["idreferenciacolor"]=>1,
                        'posiciones'.$inventario[$ii]["idreferenciacolor"]=>array($inventario[$ii]["idalmacendetalle"])
                        
                    );
                }
            }
        }
        
        /*
        $reporte[]=array(
            'fecha'=>$fecha,
            'inventario'=>$inventario
        );
        */
    }
    
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'reporte' => $reporte,
        'columnas'=>$columnas
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/reporteinventariovencimiento/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idalmacen=$decoded_array["idalmacen"];
    
    $reporte=[];
    
    $inventario = getInventario($idcliente, $idalmacen, $fechafinal, $conexion,false, true, $fechafinal,false);
    
    $fechainicial = new DateTime($fechainicial); 
    for($ii=0;$ii<count($inventario);$ii++){
        $fechaingreso = new DateTime($inventario[$ii]["fechaingreso"]); 
        if($inventario[$ii]["cantidad"]>0 && $fechaingreso>$fechainicial){
            $condicion='';
            if((int)$inventario[$ii]["idmerma"]>0){
                $condicion='MERMA';
            }else{
                if((int)$inventario[$ii]["idno_conf"]>0){
                    $condicion=$inventario[$ii]["no_conf"];
                }else{
                    if($inventario[$ii]["fechavencimiento"]==''){
                        $condicion='NO PERECEDEROS';
                    }else{
                        if((int)$inventario[$ii]["diasavencer"]<0){
                            $condicion='VENCIDO';
                        }else{
                            if((int)$inventario[$ii]["diasavencer"]<60){
                                $condicion='POR VENCER';
                            }else{
                                $condicion='APTO';
                            }
                        }
                    }
                }
            }
            
            $reporte[]=array(
                'centro_distribucion'=>$inventario[$ii]['centro_distribucion'],
                'rubro_producto'=>$inventario[$ii]['rubro_producto'],
                'almacen'=>$inventario[$ii]['tipoalmacendetalle'],
                'codigo'=>$inventario[$ii]['codigo'],
                'descripcion'=>$inventario[$ii]['descripcion'],
                'cantidad'=>$inventario[$ii]['cantidad'],
                'codigoembalaje'=>$inventario[$ii]['codigoembalaje'],
                'fechavencimiento'=>$inventario[$ii]['fechavencimiento'],
                'fechaingreso'=>$inventario[$ii]['fechaingreso'],
                'condicion'=>$condicion,
                'observaciones'=>$inventario[$ii]['observaciones'],
                'procedencia'=>$inventario[$ii]['tipoingreso'],
                'fecha_ultima_salida'=>$inventario[$ii]['fecha_ultima_salida']
            );
            
        }
    }
    
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'reporte' => $reporte
    )));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/inventario/moverdividir', function(Request $request, Response $response, array $args) use ($conexion) {

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'No se guardó la información';

    $continuar = true;
    $datosiguales = false;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'];

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idusuario = $decoded_array["idusuario"] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros
        |--------------------------------------------------------------------------
        */
        $params = json_decode((string) $request->getBody(), true);

        if (!is_array($params)) {
            $mensaje = 'No se recibieron parámetros válidos';
            $continuar = false;
        }

        if ($continuar && count($params) === 0) {
            $mensaje = 'No se recibieron datos para mover o dividir';
            $continuar = false;
        }

        if ($continuar && empty($idusuario)) {
            $mensaje = 'No se recibió el usuario';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Validar primer ítem base
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $itemBase = $params[0];

            $idingresodetalleBase = $itemBase["idingresodetalle"] ?? null;

            if (empty($idingresodetalleBase)) {
                $mensaje = 'No se recibió el item de ingreso a mover o dividir';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Determinar si los datos son iguales
        |--------------------------------------------------------------------------
        | Si solo llega un registro y sus datos coinciden con el detalle actual,
        | solo se moverá la ubicación.
        |--------------------------------------------------------------------------
        */
        if ($continuar && count($params) === 1) {

            $datosactuales = getDetalleItem($idingresodetalleBase, $conexion);

            if (empty($datosactuales) || !is_array($datosactuales)) {
                $mensaje = 'No se pudo obtener el detalle actual del item';
                $continuar = false;
            }
        }

        if ($continuar && count($params) === 1) {

            $fechavencimiento = $itemBase["fechavencimiento"] ?? null;

            if ($fechavencimiento !== null && $fechavencimiento !== '') {
                if (strlen($fechavencimiento) > 10) {
                    $fechavencimiento = substr($fechavencimiento, 0, 10);
                }
            } else {
                $fechavencimiento = null;
            }

            $idno_confcomp = empty($itemBase["idno_conf"]) ? 0 : (int)$itemBase["idno_conf"];
            $idclasificacioncomp = empty($itemBase["idclasificacion"]) ? 0 : (int)$itemBase["idclasificacion"];
            $idmermacomp = empty($itemBase["idmerma"]) ? 0 : (int)$itemBase["idmerma"];

            $queryIguales = "
                SELECT idingresodetalle
                FROM t_ingresodetalle
                WHERE codigo = :codigo
                  AND serie = :serie
                  AND descripcion = :descripcion
                  AND categoria = :categoria
                  AND :cantidadactual = :cantidad
                  AND idembalaje = :idembalaje
                  AND lote = :lote
                  AND :cantidad_no_confactual = :cantidad_no_conf
                  AND IFNULL(idno_conf, 0) = :idno_conf
                  AND IFNULL(idclasificacion, 0) = :idclasificacion
                  AND IFNULL(idmerma, 0) = :idmerma
                  AND (
                        (:fechavencimiento_null IS NULL AND fechavencimiento IS NULL)
                        OR fechavencimiento = :fechavencimiento
                  )
                  AND relacion_caja = :relacion_caja
                  AND :bultosactual = :bultos
                  AND :pesoactual = :peso
                  AND IFNULL(pallet, '') = :pallet
                  AND IFNULL(temperatura, '') = :temperatura
                  AND observaciones = :observaciones
                  AND idingresodetalle = :idingresodetalle
                LIMIT 1
            ";

            $stmtIguales = $conexion->prepare($queryIguales);

            $stmtIguales->execute([
                ':codigo' => $itemBase["codigo"] ?? '',
                ':serie' => $itemBase["serie"] ?? '',
                ':descripcion' => $itemBase["descripcion"] ?? '',
                ':categoria' => $itemBase["categoria"] ?? '',
                ':cantidadactual' => $datosactuales["cantidadactual"] ?? 0,
                ':cantidad' => $itemBase["cantidad"] ?? 0,
                ':idembalaje' => $itemBase["idembalaje"] ?? null,
                ':lote' => $itemBase["lote"] ?? '',
                ':cantidad_no_confactual' => $datosactuales["cantidad_no_confactual"] ?? 0,
                ':cantidad_no_conf' => $itemBase["cantidad_no_conf"] ?? 0,
                ':idno_conf' => $idno_confcomp,
                ':idclasificacion' => $idclasificacioncomp,
                ':idmerma' => $idmermacomp,
                ':fechavencimiento_null' => $fechavencimiento,
                ':fechavencimiento' => $fechavencimiento,
                ':relacion_caja' => $itemBase["relacion_caja"] ?? '',
                ':bultosactual' => $datosactuales["bultosactual"] ?? 0,
                ':bultos' => $itemBase["bultos"] ?? 0,
                ':pesoactual' => $datosactuales["pesoactual"] ?? 0,
                ':peso' => $itemBase["peso"] ?? 0,
                ':pallet' => $itemBase["pallet"] ?? '',
                ':temperatura' => $itemBase["temperatura"] ?? '',
                ':observaciones' => $itemBase["observaciones"] ?? '',
                ':idingresodetalle' => $idingresodetalleBase
            ]);

            $rowIguales = $stmtIguales->fetch(PDO::FETCH_ASSOC);

            if ($rowIguales) {
                $datosiguales = true;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Iniciar transacción
        |--------------------------------------------------------------------------
        */
        if ($continuar) {
            $conexion->beginTransaction();
        }

        /*
        |--------------------------------------------------------------------------
        | Caso 1: datos iguales, solo mover ubicación
        |--------------------------------------------------------------------------
        */
        if ($continuar && $datosiguales) {

            $idalmacendetalleNuevo = $itemBase["idalmacendetalle"] ?? 0;

            if ((int)$idalmacendetalleNuevo > 0) {

                $queryUbicacionActual = "
                    SELECT idubicacionitem, idalmacendetalle
                    FROM t_ubicacionitem
                    WHERE idingresodetalle = :idingresodetalle
                      AND fechasalida IS NULL
                    LIMIT 1
                ";

                $stmtUbicacionActual = $conexion->prepare($queryUbicacionActual);

                $stmtUbicacionActual->execute([
                    ':idingresodetalle' => $idingresodetalleBase
                ]);

                $rowUbicacion = $stmtUbicacionActual->fetch(PDO::FETCH_ASSOC);

                $idubicacionitemactual = $rowUbicacion ? (int)$rowUbicacion["idubicacionitem"] : 0;
                $idalmacendetalleactual = $rowUbicacion ? (int)$rowUbicacion["idalmacendetalle"] : 0;

                if ((int)$idalmacendetalleNuevo !== $idalmacendetalleactual) {

                    if ($idubicacionitemactual > 0) {

                        $queryCerrarUbicacion = "
                            UPDATE t_ubicacionitem
                            SET fechasalida = CURRENT_TIMESTAMP()
                            WHERE idubicacionitem = :idubicacionitem
                        ";

                        $stmtCerrarUbicacion = $conexion->prepare($queryCerrarUbicacion);

                        $ok = $stmtCerrarUbicacion->execute([
                            ':idubicacionitem' => $idubicacionitemactual
                        ]);

                        if (!$ok) {
                            $mensaje = 'No se pudo cerrar la ubicación actual';
                            $continuar = false;
                        }
                    }

                    if ($continuar) {

                        $queryInsertUbicacion = "
                            INSERT INTO t_ubicacionitem (
                                idingresodetalle,
                                idalmacendetalle,
                                fechaingreso
                            ) VALUES (
                                :idingresodetalle,
                                :idalmacendetalle,
                                CURRENT_TIMESTAMP()
                            )
                        ";

                        $stmtInsertUbicacion = $conexion->prepare($queryInsertUbicacion);

                        $ok = $stmtInsertUbicacion->execute([
                            ':idingresodetalle' => $idingresodetalleBase,
                            ':idalmacendetalle' => $idalmacendetalleNuevo
                        ]);

                        if (!$ok) {
                            $mensaje = 'No se pudo registrar la nueva ubicación';
                            $continuar = false;
                        }
                    }

                } else {
                    $mensaje = 'No hay datos para actualizar';
                    $continuar = false;
                }

            } else {
                $mensaje = 'No hay datos para actualizar';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Caso 2: dividir item
        |--------------------------------------------------------------------------
        */
        if ($continuar && !$datosiguales) {

            /*
            Verificar que el item base todavía no esté dividido.
            */
            $queryHabil = "
                SELECT idingresodetalle
                FROM t_ingresodetalle
                WHERE idingresodetalle = :idingresodetalle
                  AND dividido IS NULL
                LIMIT 1
            ";

            $stmtHabil = $conexion->prepare($queryHabil);

            $stmtHabil->execute([
                ':idingresodetalle' => $idingresodetalleBase
            ]);

            $rowHabil = $stmtHabil->fetch(PDO::FETCH_ASSOC);

            if (!$rowHabil) {
                $mensaje = 'El item ya fue dividido';
                $continuar = false;
            }
        }

        if ($continuar && !$datosiguales) {

            $queryInsertDetalle = "
                INSERT INTO t_ingresodetalle (
                    idingreso,
                    idingresodetallepadre,
                    codigo,
                    serie,
                    descripcion,
                    centro_distribucion,
                    categoria,
                    cantidad,
                    idembalaje,
                    lote,
                    costo_un,
                    cantidad_no_conf,
                    idno_conf,
                    idclasificacion,
                    idmerma,
                    fechavencimiento,
                    relacion_caja,
                    volumen,
                    bultos,
                    peso,
                    pallet,
                    temperatura,
                    observaciones,
                    created_by,
                    created_at
                ) VALUES (
                    :idingreso,
                    :idingresodetallepadre,
                    :codigo,
                    :serie,
                    :descripcion,
                    :centro_distribucion,
                    :categoria,
                    :cantidad,
                    :idembalaje,
                    :lote,
                    :costo_un,
                    :cantidad_no_conf,
                    :idno_conf,
                    :idclasificacion,
                    :idmerma,
                    :fechavencimiento,
                    :relacion_caja,
                    :volumen,
                    :bultos,
                    :peso,
                    :pallet,
                    :temperatura,
                    :observaciones,
                    :created_by,
                    CURRENT_TIMESTAMP()
                )
            ";

            $stmtInsertDetalle = $conexion->prepare($queryInsertDetalle);

            $queryInsertUbicacionNueva = "
                INSERT INTO t_ubicacionitem (
                    idingresodetalle,
                    idalmacendetalle,
                    fechaingreso
                ) VALUES (
                    :idingresodetalle,
                    :idalmacendetalle,
                    CURRENT_TIMESTAMP()
                )
            ";

            $stmtInsertUbicacionNueva = $conexion->prepare($queryInsertUbicacionNueva);

            foreach ($params as $item) {

                $fechavencimientoItem = $item["fechavencimiento"] ?? null;

                if ($fechavencimientoItem !== null && $fechavencimientoItem !== '') {
                    if (strlen($fechavencimientoItem) > 10) {
                        $fechavencimientoItem = substr($fechavencimientoItem, 0, 10);
                    }
                } else {
                    $fechavencimientoItem = null;
                }

                $idno_conf = empty($item["idno_conf"]) ? null : $item["idno_conf"];
                $idclasificacion = empty($item["idclasificacion"]) ? null : $item["idclasificacion"];
                $idmerma = empty($item["idmerma"]) ? null : $item["idmerma"];

                $ok = $stmtInsertDetalle->execute([
                    ':idingreso' => $item["idingreso"] ?? null,
                    ':idingresodetallepadre' => $idingresodetalleBase,
                    ':codigo' => $item["codigo"] ?? '',
                    ':serie' => $item["serie"] ?? '',
                    ':descripcion' => $item["descripcion"] ?? '',
                    ':centro_distribucion' => $item["centro_distribucion"] ?? '',
                    ':categoria' => $item["categoria"] ?? '',
                    ':cantidad' => $item["cantidad"] ?? 0,
                    ':idembalaje' => $item["idembalaje"] ?? null,
                    ':lote' => $item["lote"] ?? '',
                    ':costo_un' => $item["costo_un"] ?? 0,
                    ':cantidad_no_conf' => $item["cantidad_no_conf"] ?? 0,
                    ':idno_conf' => $idno_conf,
                    ':idclasificacion' => $idclasificacion,
                    ':idmerma' => $idmerma,
                    ':fechavencimiento' => $fechavencimientoItem,
                    ':relacion_caja' => $item["relacion_caja"] ?? '',
                    ':volumen' => $item["volumen"] ?? 0,
                    ':bultos' => $item["bultos"] ?? 0,
                    ':peso' => $item["peso"] ?? 0,
                    ':pallet' => $item["pallet"] ?? '',
                    ':temperatura' => $item["temperatura"] ?? '',
                    ':observaciones' => $item["observaciones"] ?? '',
                    ':created_by' => $idusuario
                ]);

                if (!$ok) {
                    $mensaje = 'No se pudo registrar el detalle dividido';
                    $continuar = false;
                    break;
                }

                $idingresodetalleNuevo = (int)$conexion->lastInsertId();

                $idalmacendetalleNuevo = $item["idalmacendetalle"] ?? 0;

                if ((int)$idalmacendetalleNuevo > 0) {

                    $ok = $stmtInsertUbicacionNueva->execute([
                        ':idingresodetalle' => $idingresodetalleNuevo,
                        ':idalmacendetalle' => $idalmacendetalleNuevo
                    ]);

                    if (!$ok) {
                        $mensaje = 'No se pudo registrar la ubicación del detalle dividido';
                        $continuar = false;
                        break;
                    }
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Marcar item padre como dividido y cerrar ubicación original
        |--------------------------------------------------------------------------
        */
        if ($continuar && !$datosiguales) {

            $queryFechaDivision = "
                SELECT 
                    IF(
                        MAX(s.fecha) > CURRENT_TIMESTAMP(),
                        MAX(s.fecha),
                        CURRENT_TIMESTAMP()
                    ) AS fecha_division
                FROM t_salidadetalle sd
                LEFT JOIN t_salida s
                    ON sd.idsalida = s.idsalida
                WHERE sd.idingresodetalle = :idingresodetalle
            ";

            $stmtFechaDivision = $conexion->prepare($queryFechaDivision);

            $stmtFechaDivision->execute([
                ':idingresodetalle' => $idingresodetalleBase
            ]);

            $rowFechaDivision = $stmtFechaDivision->fetch(PDO::FETCH_ASSOC);

            $fechaDivision = $rowFechaDivision["fecha_division"] ?? null;

            if (empty($fechaDivision)) {
                $fechaDivision = date('Y-m-d H:i:s');
            }

            $queryMarcarDividido = "
                UPDATE t_ingresodetalle
                SET dividido = :fecha_division
                WHERE idingresodetalle = :idingresodetalle
            ";

            $stmtMarcarDividido = $conexion->prepare($queryMarcarDividido);

            $ok = $stmtMarcarDividido->execute([
                ':fecha_division' => $fechaDivision,
                ':idingresodetalle' => $idingresodetalleBase
            ]);

            if (!$ok) {
                $mensaje = 'No se pudo marcar el item como dividido';
                $continuar = false;
            }
        }

        if ($continuar && !$datosiguales) {

            $queryCerrarUbicacionPadre = "
                UPDATE t_ubicacionitem
                SET fechasalida = :fecha_division
                WHERE idingresodetalle = :idingresodetalle
                  AND fechasalida IS NULL
            ";

            $stmtCerrarUbicacionPadre = $conexion->prepare($queryCerrarUbicacionPadre);

            $ok = $stmtCerrarUbicacionPadre->execute([
                ':fecha_division' => $fechaDivision,
                ':idingresodetalle' => $idingresodetalleBase
            ]);

            if (!$ok) {
                $mensaje = 'No se pudo cerrar la ubicación del item original';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar / revertir transacción
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Datos guardados correctamente';

        } else {

            if ($conexion->inTransaction()) {
                $conexion->rollBack();
            }
        }

    } catch (PDOException $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error de base de datos: ' . $e->getMessage();

    } catch (Exception $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error general: ' . $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

$app->put('/inventario/ubicaralmacen', function(Request $request, Response $response, array $args) use ($conexion) {
    $params = json_decode((string) $request->getBody(),true);
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
