    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $errores=[];
    
    $query="";
    
    for($i=0;$i<count($params);$i++){
        if((int)$params[$i]["idalmacendetalle"]>0){
            $idalmacen_item=0;
            $idalmacen_ubicacion=0;
            $resultalmacenitem = $conexion->query("select 
                t_ingreso.idalmacen 
