                $idalmacen_item=(int)$rowalmacenitem['idalmacen'];
            }
            $resultalmacenitem = $conexion->query("select idalmacen FROM t_almacendetalle WHERE idalmacendetalle=".$params[$i]["idalmacendetalle"].";");
            while ($rowalmacenitem =  $resultalmacenitem ->fetch(PDO::FETCH_ASSOC)){
                $idalmacen_ubicacion=(int)$rowalmacenitem['idalmacen'];
            }
            
            if($idalmacen_item==$idalmacen_ubicacion){
                $idubicacionitemactual=0;
                $idalmacendetalleactual=0;
                $resultubicacion0 = $conexion->query("SELECT idubicacionitem, idalmacendetalle from t_ubicacionitem WHERE idingresodetalle=".$params[$i]["idingresodetalle"]." AND fechasalida IS NULL;");
                while ($rowubicacion0 =  $resultubicacion0 ->fetch(PDO::FETCH_ASSOC)){
                    $idubicacionitemactual=$rowubicacion0["idubicacionitem"];
                    $idalmacendetalleactual=$rowubicacion0["idalmacendetalle"];
                }
                if((int)$params[$i]["idalmacendetalle"]<>(int)$idalmacendetalleactual){
                    $query=$query."UPDATE t_ubicacionitem SET fechasalida=CURRENT_TIMESTAMP() WHERE idubicacionitem=$idubicacionitemactual;";
                    $query=$query."INSERT INTO t_ubicacionitem (idingresodetalle,                      idalmacendetalle,                      fechaingreso) 
                                                        VALUES (".$params[$i]["idingresodetalle"].",   ".$params[$i]["idalmacendetalle"].",    CURRENT_TIMESTAMP());";
                }
            }else{
                $errores[]=array(
                    "idingresodetalle"=>$params[$i]["idingresodetalle"],
                    "idalmacendetalle"=>$params[$i]["idalmacendetalle"],
                    "mensaje"=>"El item no pertenece al almacen de la ubicacion"
                );
            }
            
                
        }
    }
    
    if($query<>''){
        $result = $conexion->exec($query);
        if($result===false){

        }else{
            $codigo=200;
            $status='Exito';
            if(count($errores)>0){
                $mensaje='Datos guardados pero se encontraron errores';
            }else{
                $mensaje='Datos guardados correctamente';
            }
        }
    }else{
        $mensaje="No hay datos para actualizar";
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'errores'=>$errores
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/inventario/actualizacionmasiva', function(Request $request, Response $response, array $args) use ($conexion,$archivosmasivo) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    $idalmacen=$decoded_array["idalmacen"];
    
    $codigo=400;
    $status='Error';
    $mensaje='El Archivo no se subio, probablemente sea mayor a 10MB';
    $xls_data=[];
    $mensajes_error=[];
    $nuevosdatos=[];
    //$embalaje=[];
    
    if(isset($_FILES['uploads'])){
        $nombredoc=date("Y_m_d_H_i_s")."_".$_FILES['uploads']["name"][0];
        //$random = bin2hex(openssl_random_pseudo_bytes(5));
        //$nombredoc=$random."_".$nombredoc;
        $creacion=new Carpetas();
        $respuesta=$creacion->procesarCarpeta($idempresa);
        
        $piramideUploader=new PiramideUploader();
        $upload =$piramideUploader->upload($nombredoc, 'uploads', folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/actualizacion_inventario', $archivosmasivo, true);
        
        $file=$piramideUploader->getInfoFile();
        $file_name=$file['complete_name'];
        
        if(isset($upload) && $upload['uploaded']==false){
            $mensaje=$upload['error'];
        }else{
            $inputFileName = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/actualizacion_inventario/'.$file_name;
            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();
            $highestRow = $sheet->getHighestRow(); 
            $highestColumn = $sheet->getHighestColumn();
            $xls_data = $sheet->rangeToArray(
                'A2:' . $highestColumn . $highestRow,
                '',TRUE,TRUE
            );
            
            $keys = [
                "idingresodetalle",
                "ubicacion",
                "no_conf",
                "observaciones"
            ];

            $no_conf=[];
            $result = $conexion->query("SELECT
                idno_conf,
                no_conf
                FROM
                t_no_conf;");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $no_conf[]=array(
                    'idno_conf'=>(int)$row["idno_conf"],
                    'no_conf'=>$row['no_conf']
                );
            }

            $ubicaciones=[];
            $result = $conexion->query("select 
                idalmacendetalle, 
                nombre 
                FROM
                t_almacendetalle WHERE idalmacen=$idalmacen AND tipo=1 AND activo=1;");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $ubicaciones[]=array(
                    'idalmacendetalle'=>(int)$row["idalmacendetalle"],
                    'nombre'=>$row['nombre']
                );
            }
            
            $datos_excel = array_map(function ($item) use ($keys) {
                return array_combine($keys, $item);
            }, $xls_data);
            
            for($xls=0;$xls<count($datos_excel);$xls++){
                if(empty($datos_excel[$xls]["idingresodetalle"])){
                    $mensajes_error[]=array(
                        'fila'=>($xls+2),
                        'mensaje'=>"ID no puede estar vacio"
                    );
                }else{
                    $sql = "SELECT 
                                t_ingresodetalle.idingresodetalle
                            FROM 
                                t_ingresodetalle
                            LEFT JOIN t_ingreso 
                                ON t_ingresodetalle.idingreso = t_ingreso.idingreso
                            WHERE
                                t_ingresodetalle.idingresodetalle = :id
                                AND t_ingresodetalle.dividido IS NULL
                                AND t_ingreso.idalmacen = :almacen
                            LIMIT 1";

                    $stmt = $conexion->prepare($sql);
                    $stmt->execute([
                        ":id" => $datos_excel[$xls]["idingresodetalle"],
                        ":almacen" => $idalmacen
                    ]);

                    $existe = $stmt->fetch(PDO::FETCH_ASSOC);

                    if ($existe) {
                        // ✅ Sí hay resultado
                    } else {
                        $mensajes_error[]=array(
                            'fila'=>($xls+2),
                            'mensaje'=>"El ID no existe, pertenece a otro almacen o ya fue dividido"
                        );
                    }
                }

                if(!empty($datos_excel[$xls]["ubicacion"])){
                    $key = array_search($datos_excel[$xls]["ubicacion"], array_column($ubicaciones, 'nombre'));
                    if(is_numeric($key)){
                        $datos_excel[$xls]["idalmacendetalle"]=$ubicaciones[$key]['idalmacendetalle'];
                    }else{
                        $mensajes_error[]=array(
                            'fila'=>($xls+2),
                            'mensaje'=>"Ubicación inexistente"
                        );
                    }
                    
                }

                if(!empty($datos_excel[$xls]["no_conf"])){
                    $key = array_search($datos_excel[$xls]["no_conf"], array_column($no_conf, 'no_conf'));
                    if(is_numeric($key)){
                        $datos_excel[$xls]["idno_conf"]=$no_conf[$key]['idno_conf'];
                    }else{
                        $mensajes_error[]=array(
                            'fila'=>($xls+2),
                            'mensaje'=>"No Conf inexistente"
                        );
                    }
                    
                }
            }
            
            if(count($mensajes_error)==0){

                try {

                    $conexion->beginTransaction();

                    // Preparar UNA vez cada query
                    $stmt_no_conf = $conexion->prepare("
                        UPDATE t_ingresodetalle 
                        SET 
                        idno_conf = :idno_conf
                        WHERE idingresodetalle = :idingresodetalle
                    ");

                    $stmt_observaciones = $conexion->prepare("
                        UPDATE t_ingresodetalle 
                        SET 
                        observaciones = :observaciones
                        WHERE idingresodetalle = :idingresodetalle
                    ");

                    $stmt_ubicacion1 = $conexion->prepare("
                        UPDATE t_ubicacionitem 
                        SET 
                        fechasalida = CURRENT_TIMESTAMP() 
                        WHERE 
                        idingresodetalle = :idingresodetalle
                        AND fechasalida IS NULL
                    ");

                    $stmt_ubicacion2 = $conexion->prepare("
                        INSERT INTO t_ubicacionitem (idingresodetalle, idalmacendetalle, fechaingreso) 
                        VALUES (:idingresodetalle, :idalmacendetalle, CURRENT_TIMESTAMP())
                    ");

                    foreach ($datos_excel as $item) {

                        // Ejecutar cada sentencia con los datos actuales
                        if(!empty($item["no_conf"])){
                            $stmt_no_conf->execute([
                                ":idno_conf" => $item['idno_conf'],
                                ":idingresodetalle" => $item['idingresodetalle']
                            ]);
                        }
                        
                        if(!empty($item["observaciones"])){
                            $stmt_observaciones->execute([
                                ":observaciones" => $item['observaciones'],
                                ":idingresodetalle" => $item['idingresodetalle']
                            ]);
                        }

                        if(!empty($item["ubicacion"])){
                            $stmt_ubicacion1->execute([
                                ":idingresodetalle" => $item['idingresodetalle']
                            ]);

                            $stmt_ubicacion2->execute([
                                ":idingresodetalle" => $item['idingresodetalle'],
                                ":idalmacendetalle" => $item['idalmacendetalle']
                            ]);
                        }
                        
                    }

                    $conexion->commit();

                    $codigo=200;
                    $status='Exito';
                    $mensaje='Se guardo la información General';

                } catch (Exception $e) {

                    $conexion->rollBack();

                    //echo "Error: " . $e->getMessage();
                }
            }else{
                $mensaje='Existen errores en el archivo';
            }
        }

    }
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'mensajes_error'=>$mensajes_error,
        'xls_data'=>$xls_data,
        'datos_excel'=>$datos_excel,
        //'finalResult'=>$finalResult,
        //'query'=>$query
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

