$app->get('/pedidos/{idcliente}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array['idalmacen'];
    
    
    $filtrocliente='';
    
    $resultcliente = $conexion->query("select idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($rowcliente =  $resultcliente ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum=(int)$rowcliente["idcliente"];
    }
    
    
    if($idclientenum>0){
        $filtrocliente="AND t_pedido.idcliente=$idclientenum";
    }
    
    $pedidos=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_pedidotienda;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_pedidotienda (idpedido INT, pedidotiendas TEXT);");
    $conexion->query("INSERT INTO tmp_pedidotienda (idpedido, pedidotiendas)
        SELECT
        t_pedidotienda.idpedido,
        GROUP_CONCAT(CONCAT('{\"idpedidotienda\": ',t_pedidotienda.idpedidotienda,', \"tienda\": \"',IFNULL(t_pedidotienda.tienda,''),'\"}') SEPARATOR ',') as pedidotiendas
        from
        t_pedidotienda
        LEFT JOIN t_pedido ON t_pedidotienda.idpedido=t_pedido.idpedido
        WHERE
        t_pedido.idalmacen=$idalmacen
        GROUP BY
        t_pedidotienda.idpedido;");
    $conexion->query("ALTER TABLE tmp_pedidotienda ADD INDEX idpedido (idpedido);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_pedidosalidas;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_pedidosalidas (idpedido INT, salidas TEXT);");
    $conexion->query("INSERT INTO tmp_pedidosalidas (idpedido, salidas)
        SELECT
        idpedido,
        GROUP_CONCAT(CONCAT('{\"idsalida\": ',idsalida,', \"idsalida_cif\": \"',md5(idsalida),'\", \"salida\": \"',numero,'/',gestion,'\", \"finalizado\": ',IFNULL(finalizado,0),'}') SEPARATOR ',') as salidas
        from
        t_salida
        WHERE
        idalmacen=$idalmacen
        AND idpedido IS NOT NULL
        GROUP BY
        idpedido;");
    $conexion->query("ALTER TABLE tmp_pedidosalidas ADD INDEX idpedido (idpedido);");
    
    $result = $conexion->query("SELECT 
        md5(t_pedido.idpedido) as idpedido,
        t_pedido.numero,
        t_pedido.gestion,
        CONCAT(t_pedido.numero,'/',t_pedido.gestion) as numeropedido,
        md5(t_pedido.idcliente) as idcliente,
        t_cliente.cliente,
        t_pedido.fecha,
        t_pedido.no_pedido,
        t_pedido.fecha_entrega,
        t_usuario.nombre,
        t_pedido.nota_adicional,
        IFNULL(t_pedido.tipo_pedido,0) as tipo_pedido,
	CONCAT('[',IFNULL(tmp_pedidotienda.pedidotiendas,''),']') as pedidotiendas,
        CONCAT('[',IFNULL(tmp_pedidosalidas.salidas,''),']') as salidas
        FROM 
        t_pedido
        LEFT JOIN t_cliente ON t_pedido.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario ON t_pedido.idusuario=t_usuario.idusuario
        LEFT JOIN tmp_pedidotienda ON t_pedido.idpedido=tmp_pedidotienda.idpedido
        LEFT JOIN tmp_pedidosalidas ON t_pedido.idpedido=tmp_pedidosalidas.idpedido
        WHERE
        t_pedido.idalmacen=$idalmacen
        $filtrocliente
        ORDER BY
        t_pedido.gestion DESC,
        t_pedido.numero DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $pedidos[]=array(
            'idpedido'=>$row['idpedido'],
            'numero'=>(int)$row['numero'],
            'gestion'=>(int)$row['gestion'],
            'numeropedido'=>$row['numeropedido'],
            'idcliente'=>$row['idcliente'],
            'cliente'=>$row['cliente'],
            'fecha'=>$row['fecha'],
            'no_pedido'=>$row['no_pedido'],
            'fecha_entrega'=>$row['fecha_entrega'],
            'nombre'=>$row['nombre'],
            'nota_adicional'=>$row['nota_adicional'],
            'pedidotiendas'=> json_decode($row["pedidotiendas"], true),
	    'tipo_pedido'=>(int)$row['tipo_pedido'],
            'salidas'=> json_decode($row["salidas"], true),
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'pedidos'=>$pedidos
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

