$app->put('/pedidos/{idpedido}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idpedido = $args['idpedido'];
    $params = json_decode((string) $request->getBody(),true);
    
    $idcliente=$params['idcliente'];
    $rubro = empty($params['rubro'])  ? "NULL" : "'".$params['rubro']."'";
    $idusuario_revisado = empty($params['idusuario_revisado'])  ? "NULL" : $params['idusuario_revisado'];
    $nota_adicional = empty($params['nota_adicional'])  ? "NULL" : "'".$params['nota_adicional']."'";
    $preparacion= $params['preparacion'] ?? [];
    
    $fecha=$params['fecha'];
    
    $idclientenum=0;
    $result = $conexion->query("SELECT idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum= $row["idcliente"];
    }
    
    $idpedidonum=0;
    $result = $conexion->query("SELECT idpedido FROM t_pedido WHERE md5(idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idpedidonum= $row["idpedido"];
    }
    
    
    $query="UPDATE t_pedido  SET
        idcliente=$idclientenum,
        rubro=$rubro,
        idusuario_revisado=$idusuario_revisado,
        nota_adicional=$nota_adicional
        WHERE
        md5(idpedido)='$idpedido';";
    
    for($pp=0;$pp<count($preparacion);$pp++){
        $idpreparador=empty($preparacion[$pp]['idpreparador'])  ? "NULL" : $preparacion[$pp]['idpreparador'];
        $hora_inicio=empty($preparacion[$pp]['hora_inicio'])  ? "NULL" : "'".$preparacion[$pp]['hora_inicio']."'";
        $hora_fin=empty($preparacion[$pp]['hora_fin'])  ? "NULL" : "'".$preparacion[$pp]['hora_fin']."'";
        $demora=empty($preparacion[$pp]['demora'])  ? "0" : $preparacion[$pp]['demora'];
        if((int)$preparacion[$pp]["idpedidopreparacion"]>0){
            
            $sectoresactuales=[];
            $result = $conexion->query("SELECT * FROM t_pedidopreparacionsector WHERE idpedidopreparacion=".$preparacion[$pp]["idpedidopreparacion"].";");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $sectoresactuales[]=array(
                    'idpedidopreparacionsector'=>$row['idpedidopreparacionsector'],
                    'sector'=>$row['sector']
                );
            }
            
            $query=$query."UPDATE t_pedidopreparacion SET
                idpreparador=$idpreparador,
                hora_inicio=$hora_inicio,
                hora_fin=$hora_fin,
                demora=$demora,
                conforme='".$preparacion[$pp]["conforme"]."',
                conforme2='".$preparacion[$pp]["conforme2"]."',
                conforme3='".$preparacion[$pp]["conforme3"]."',
                notas='".$preparacion[$pp]["notas"]."'
                WHERE
                idpedidopreparacion=".$preparacion[$pp]["idpedidopreparacion"].";";
            
            for($ss=0;$ss<count($preparacion[$pp]["sector"]);$ss++){
                $key = array_search($preparacion[$pp]["sector"][$ss]["sector"], array_column($sectoresactuales, 'sector'));
                if(!is_numeric($key)){
                    $query=$query."INSERT INTO t_pedidopreparacionsector (idpedidopreparacion,                          sector) VALUES 
                                                                         (".$preparacion[$pp]["idpedidopreparacion"].", '".$preparacion[$pp]["sector"][$ss]["sector"]."');";
                }
            }
            
            for($sa=0;$sa<count($sectoresactuales);$sa++){
                $key = array_search($sectoresactuales[$sa]["sector"], array_column($preparacion[$pp]["sector"], 'sector'));
                if(!is_numeric($key)){
                    $query=$query."DELETE FROM t_pedidopreparacionsector WHERE idpedidopreparacionsector=".$sectoresactuales[$sa]["idpedidopreparacionsector"].";";
                }
            }
            
        }else{
            $query=$query."INSERT INTO t_pedidopreparacion (idpedido,       idpreparador,   hora_inicio,    hora_fin,   demora,     conforme,                               conforme2,                              conforme3, notas) 
                                                    VALUES ($idpedidonum,   $idpreparador,  $hora_inicio,   $hora_fin,  $demora,    '".$preparacion[$pp]["conforme"]."',    '".$preparacion[$pp]["conforme2"]."',   '".$preparacion[$pp]["conforme3"]."' , '".$preparacion[$pp]["notas"]."');
                    SELECT LAST_INSERT_ID() INTO @idpedidopreparacion_nuevo;";
            for($ss=0;$ss<count($preparacion[$pp]["sector"]);$ss++){
                $query=$query."INSERT INTO t_pedidopreparacionsector (idpedidopreparacion,          sector) VALUES 
                                                                     (@idpedidopreparacion_nuevo,   '".$preparacion[$pp]["sector"][$ss]["sector"]."');";
            }
        }
    }
    
    $data=[];
    $result = $conexion->query("SELECT idpedidopreparacion FROM t_pedidopreparacion WHERE md5(idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $key = array_search($row["idpedidopreparacion"], array_column($preparacion, 'idpedidopreparacion'));
        $data[]=array(
            'idpedidopreparacion'=>$row["idpedidopreparacion"],
            'key'=>$key
        );
        if(!is_numeric($key)){
            $query=$query."DELETE FROM t_pedidopreparacionsector WHERE idpedidopreparacion=".$row["idpedidopreparacion"].";";
            $query=$query."DELETE FROM t_pedidopreparacion WHERE idpedidopreparacion=".$row["idpedidopreparacion"].";";
        }
    }
    
    $result = $conexion->exec($query);
    
    if($result===false){

    }else{
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información Correctamente';
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'query'=>$query,
        'preparacion'=>$preparacion,
        'data'=>$data
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

