                               SELECT  ".$decoded_array["idalmacen"].",     (select ifnull(MAX(numero)+1,1) as numero from t_pedido WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),  $idclientenum,              CURRENT_TIMESTAMP(),   '$no_pedido',    $fecha_entregag,    ".$decoded_array["idusuario"].";
