$app->post('/agruparpedidos', function(Request $request, Response $response, array $args) use ($conexion) {
    $params = json_decode((string) $request->getBody(),true);
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idcliente=$params["idcliente"];
    $pedidos=$params["pedidos"] ?? [];
    $fecha_entrega=$params["fecha_entrega"];
    $pedidos_query= implode("','", $pedidos);
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $idpedido=null;
    
    $result = $conexion->query("SELECT idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum= $row["idcliente"];
    }
    
    
    
    
    
    if((int)$idclientenum==0){
        $mensaje='El cliente no existe';
    }else{
        $query="insert into t_pedido  (idalmacen,                           numero,                                                                                                                                     gestion,                idcliente,                  fecha,                 no_pedido,                                       fecha_entrega,      idusuario,                       tipo_pedido) 
                               SELECT  ".$decoded_array["idalmacen"].",     (select ifnull(MAX(numero)+1,1) as numero from t_pedido WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$decoded_array["idalmacen"]."),   YEAR(CURRENT_DATE()),  $idclientenum,              CURRENT_TIMESTAMP(),   GROUP_CONCAT(DISTINCT no_pedido SEPARATOR ','),  '$fecha_entrega',   ".$decoded_array["idusuario"].", 2              FROM t_pedido WHERE md5(idpedido) IN ('$pedidos_query');
                SELECT LAST_INSERT_ID() INTO @idpedido_nuevo;";
 
        $query=$query."INSERT INTO t_pedidodetalle (idpedido, codigo, serie, descripcion, unidadmedida, idpedidodetalle_aux)
                                            SELECT 
                                            @idpedido_nuevo,  
                                            TRIM(LEADING '0' FROM t_pedidodetalle.codigo) as codigo, 
                                            IFNULL(t_baseproductos.serie,GROUP_CONCAT(DISTINCT IFNULL(t_pedidodetalle.serie,''))) as serie,
                                            IFNULL(t_baseproductos.descripcion,GROUP_CONCAT(DISTINCT IFNULL(t_pedidodetalle.descripcion,''))) as descripcion,
                                            t_pedidodetalle.unidadmedida,
                                            GROUP_CONCAT(t_pedidodetalle.idpedidodetalle SEPARATOR ',') as idpedidodetalle_aux
                                            FROM 
                                            t_pedidodetalle 
                                            LEFT JOIN t_pedido ON t_pedidodetalle.idpedido=t_pedido.idpedido
                                            LEFT JOIN t_baseproductos ON TRIM(LEADING '0' FROM t_pedidodetalle.codigo)=t_baseproductos.codigo AND t_pedido.idcliente=t_baseproductos.idcliente
                                            WHERE 
                                            md5(t_pedidodetalle.idpedido) IN ('$pedidos_query')
                                            GROUP BY
                                            TRIM(LEADING '0' FROM t_pedidodetalle.codigo), 
                                            t_baseproductos.serie,
                                            t_baseproductos.descripcion,
                                            t_pedidodetalle.unidadmedida;";
        
        $query=$query."INSERT INTO t_pedidotienda (idpedido, tienda, idpedidotienda_aux, no_pedido)
                                            SELECT
                                            @idpedido_nuevo,
                                            t_pedidotienda.tienda,
                                            GROUP_CONCAT(t_pedidotienda.idpedidotienda SEPARATOR ',') as idpedidotienda_aux,
                                            t_pedido.no_pedido
                                            FROM
                                            t_pedidotienda
                                            LEFT JOIN t_pedido ON t_pedidotienda.idpedido=t_pedido.idpedido
                                            WHERE 
                                            md5(t_pedidotienda.idpedido) IN ('$pedidos_query')
                                            GROUP BY
                                            t_pedidotienda.tienda,
                                            t_pedido.no_pedido
                                            ORDER BY
                                            t_pedido.fecha;";
        
        $query=$query."INSERT INTO t_pediodetalletienda (idpedidodetalle, idpedidotienda, cantidad)
                                        SELECT
                                        t_pedidodetalle.idpedidodetalle,
                                        t_pedidotienda.idpedidotienda,
                                        SUM(t_pediodetalletienda.cantidad) as cantidad
                                        FROM 
                                        t_pediodetalletienda 
                                        LEFT JOIN t_pedidodetalle ON @idpedido_nuevo=t_pedidodetalle.idpedido AND FIND_IN_SET(t_pediodetalletienda.idpedidodetalle, t_pedidodetalle.idpedidodetalle_aux) > 0
                                        LEFT JOIN t_pedidotienda ON @idpedido_nuevo=t_pedidotienda.idpedido AND FIND_IN_SET(t_pediodetalletienda.idpedidotienda, t_pedidotienda.idpedidotienda_aux) > 0
                                        WHERE 
                                        t_pediodetalletienda.idpedidodetalle IN (select idpedidodetalle FROM t_pedidodetalle WHERE md5(idpedido) IN ('$pedidos_query'))
                                        GROUP BY
                                        t_pedidodetalle.idpedidodetalle,
                                        t_pedidotienda.idpedidotienda;";
        
        $query=$query."UPDATE t_pedido SET tipo_pedido=1, idpedido_padre=@idpedido_nuevo WHERE md5(idpedido) IN ('$pedidos_query');";
        
        $result = $conexion->exec($query);
        if($result){

            $result = $conexion->query("SELECT 
                numero,
                gestion,
                md5(idpedido) as idpedido
                FROM
                t_pedido
                WHERE
                idpedido=@idpedido_nuevo;");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $idpedido=$row['idpedido'];
                $numero=$row['numero'];
                $gestion=$row['gestion'];
            }

            $codigo=200;
            $status='Exito';
            $mensaje='Se guardo la información Correctamente';
        }
    }
    
        

    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'idpedido'=>$idpedido,
        'numero_pedido'=>$numero."/".$gestion
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/pedidos/{idpedido}/carga', function(Request $request, Response $response, array $args) use ($conexion,$archivosmasivo) {
    $idpedido = $args['idpedido'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
    
    $codigo=400;
    $status='Error';
    $mensaje='El Archivo no se subio, probablemente sea mayor a 10MB';
    $xls_data=[];

    $result = $conexion->query("SELECT idpedido FROM t_pedido WHERE md5(idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idpedidonum=$row['idpedido'];
    }
    
    if(isset($_FILES['uploads'])){
        $nombredoc=$_FILES['uploads']["name"][0];
        
        $piramideUploader=new PiramideUploader();
        
        
        
        
        $upload =$piramideUploader->upload($nombredoc, 'uploads', folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/pedidos/'.$idpedidonum, $archivosmasivo, true);
        
        $file=$piramideUploader->getInfoFile();
        $file_name=$file['complete_name'];
        
        if(isset($upload) && $upload['uploaded']==false){
            $mensaje=$upload['error'];
        }else{
            $inputFileName = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/pedidos/'.$idpedidonum.'/'.$file_name;
            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();
            $highestRow = $sheet->getHighestRow(); 
            $highestColumn = $sheet->getHighestColumn();
            
            $xls_data = $sheet->rangeToArray(
                'A4:' . $highestColumn . $highestRow,
                '',TRUE,TRUE
            );
            
            if(count($xls_data)>1){
                $pedidodetalle='';
                for($pp=1;$pp<count($xls_data);$pp++){
                    $pedidodetalle=$pedidodetalle."($idpedidonum, '".$xls_data[$pp][0]."', '".$xls_data[$pp][1]."', '".$xls_data[$pp][2]."', '".$xls_data[$pp][3]."'),";
                }
                $pedidodetalle=substr($pedidodetalle,0,-1);
                $query="";
                $query=$query."DELETE FROM t_pediodetalletienda WHERE idpedidodetalle IN (SELECT idpedidodetalle FROM t_pedidodetalle WHERE md5(idpedido)='$idpedido');";
                $query=$query."DELETE FROM t_pedidodisponibilidad WHERE idpedidodetalle IN (SELECT idpedidodetalle FROM t_pedidodetalle WHERE md5(idpedido)='$idpedido');";
                $query=$query."DELETE FROM t_pedidotienda WHERE md5(idpedido)='$idpedido';";
                $query=$query."DELETE FROM t_pedidodetalle WHERE md5(idpedido)='$idpedido';";
                
                
                
                $query=$query."INSERT INTO t_pedidodetalle (idpedido, codigo, descripcion, lote, unidadmedida)
                                                    VALUES $pedidodetalle;";
                
                
                $pedidotienda='';
                $columnafinal=count($xls_data[0])-1;
                for($tt=4;$tt<$columnafinal;$tt++){
                    $pedidotienda=$pedidotienda."($idpedidonum, '".$xls_data[0][$tt]."'),";
                }
                $pedidotienda=substr($pedidotienda,0,-1);
                
                $query=$query."INSERT INTO t_pedidotienda (idpedido, tienda)
                                                   VALUES $pedidotienda;";
                
                for($pp=1;$pp<count($xls_data);$pp++){
                    for($tt=3;$tt<$columnafinal;$tt++){
                        if(is_numeric($xls_data[$pp][$tt])){
                            $query=$query."INSERT INTO t_pediodetalletienda (idpedidodetalle, idpedidotienda, cantidad)
                                                   VALUES ((SELECT idpedidodetalle FROM t_pedidodetalle WHERE md5(idpedido)='$idpedido' AND codigo='".$xls_data[$pp][0]."' AND lote='".$xls_data[$pp][2]."' LIMIT 0,1), (SELECT idpedidotienda FROM t_pedidotienda WHERE md5(idpedido)='$idpedido' AND tienda='".$xls_data[0][$tt]."' LIMIT 0,1), ".$xls_data[$pp][$tt].");";
                        }
                    }
                }
                
                
                
                
                if($query<>''){
                    $result = $conexion->exec($query);
                    if($result===false){

                    }else{
                        $codigo=200;
                        $status='Exito';
                        $mensaje='Datos guardados correctamente';
                    }
                }else{
                    $mensaje="No hay datos para actualizar";
                }
                
            }
            
        }

    }
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'xls_data'=>$xls_data
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/pedidos/{idpedido}/solicitud', function(Request $request, Response $response, array $args) use ($conexion) {
    $idpedido = $args['idpedido'];
    $codigo=400;
    $status='Error';
    $mensaje='No se pudo cargar los datos, intente mas tarde';
    
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $params = json_decode((string) $request->getBody(),true);
    
    $idpedidonum=0;
    $inventario=[];
    $result = $conexion->query("SELECT idpedido, idcliente, idalmacen FROM t_pedido WHERE md5(idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idpedidonum=$row['idpedido'];
        $idcliente=$row['idcliente'];
        $idalmacen=$row['idalmacen'];
    }
    $error=false;
    if($idpedidonum==0){
        $mensaje="El pedido no existe";
        $error=true;
    }else{
        if(count($params)==0){
            $mensaje="No existen datos o el json es incorrecto";
            $error=true;
        }else{
            
            $inventario= getInventario($idcliente, $idalmacen, date("Y-m-d"), $conexion, true, false,date("Y-m-d"),false);
            $inventarioFiltrado=[];
            for($ii=0;$ii<count($inventario);$ii++){
                //if((int)$inventario[$ii]['vancimientohabilitado']==1 && $inventario[$ii]['cantidad']>0 && !is_numeric(strpos(strtoupper($inventario[$ii]['serie']), 'DEVOLUCION')) && !is_numeric(strpos(strtoupper($inventario[$ii]['no_conf']), 'DAÑADO'))){
                    $inventarioFiltrado[]=array(
                        'idingresodetalle'=>$inventario[$ii]['idingresodetalle'],
                        'codigo'=>$inventario[$ii]['codigo'],
                        'embalaje'=>$inventario[$ii]['codigoembalaje'],
                        'cantidad'=>$inventario[$ii]['cantidad'],
                        'ubicacionalmacen'=>$inventario[$ii]['ubicacionalmacen'],
                        'orden'=>$inventario[$ii]['orden'],
                        'lote'=>$inventario[$ii]['lote'],
                        'fechavencimiento'=>$inventario[$ii]['fechavencimiento'],
                        'diasavencer'=>$inventario[$ii]['diasavencer'],
                        'fechaingreso'=>$inventario[$ii]['fechaingreso'],
                        'serie'=>$inventario[$ii]['serie']
                    );
                //}
            }
            
            
            $mensaje="";
            $observaciones='';
            $codigossolicitados=array();
            for($cc=0;$cc<count($params);$cc++){
                $key = array_search($params[$cc]["codigo"], array_column($inventarioFiltrado, 'codigo'));
                if(!is_numeric($key)){
                    //$error=true;
                    $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." no existe en el almacen, ";
                }else{
                    if($params[$cc]["embalaje"]==$inventarioFiltrado[$key]["embalaje"]){
                        if (in_array($params[$cc]["codigo"], $codigossolicitados)){
                            //$error=true;
                            $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." esta duplicado, ";
                        }
                        array_push($codigossolicitados,$params[$cc]["codigo"]);
                        $total=0;
                        $tiendascodigo=array();
                        for($tt=0;$tt<count($params[$cc]["detalle"]);$tt++){
                            $total=$total+$params[$cc]["detalle"][$tt]["cantidad"];
                            if($params[$cc]["detalle"][$tt]["tienda"]=='' || $params[$cc]["detalle"][$tt]["tienda"]==null){
                                //$error=true;
                                $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." tiene una tienda invalida, ";
                            }

                            if (in_array($params[$cc]["detalle"][$tt]["tienda"], $tiendascodigo)){
                                //$error=true;
                                $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." tiene la tienda ".$params[$cc]["detalle"][$tt]["tienda"]." duplicada, ";
                            }
                            array_push($tiendascodigo,$params[$cc]["detalle"][$tt]["tienda"]);
                        }
                        $totalinventario=0;
                        for($ii=0;$ii<count($inventarioFiltrado);$ii++){
                            if($params[$cc]["codigo"]==$inventarioFiltrado[$ii]["codigo"]){
                                $totalinventario=$totalinventario+$inventarioFiltrado[$ii]["cantidad"];
                            }
                        }
                        if($total==0){
                            //$error=true;
                            $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." debe tener al menos una tienda con valores, ";
                        }
                        if($totalinventario<$total){
                            //$error=true;
                            $observaciones=$observaciones."El codigo ".$params[$cc]["codigo"]." no tiene la cantidad solicitada ($total) en almacen, ";
                        }
