                $query=$query."INSERT INTO t_salida (numero,                                                                                                                               gestion,                idpedido,                delivery_note,                                  idalmacen,                   idcliente,       fecha,                                    fecha_recibido,                 almacen_destino,                               pedido_consolidado,             idpedido_consolidado,   idusuario_entrega,               entrega_a_tiempo,   entrega_completa_conforme) 
                                             SELECT (SELECT ifnull(MAX(numero)+1,1) as numero from t_salida WHERE gestion=YEAR(CURRENT_DATE()) AND idalmacen=".$pedido["idalmacen"]."),    YEAR(CURRENT_DATE()),   '".$idpedido_origen."',  '".$pedido["pedidotienda"][$tt]["no_pedido"]."',".$pedido["idalmacen"].",    $idcliente,      '".$pedido["fecha_entrega"]." 07:00',     '".$pedido["fecha_entrega"]."', '".$pedido["pedidotienda"][$tt]["tienda"]."',  '".$pedido["numeropedido"]."',  $idpedidonum,           ".$decoded_array["idusuario"].", 1,                  1;
                        SELECT LAST_INSERT_ID() INTO @idsalida_nuevo;";
                
                if($contrato_no<>''){
