$app->get('/pedidos/reporte/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    
    $filtrocliente='';
    
    if($idcliente>0){
        $filtrocliente=" AND t_pedido.idcliente=$idcliente ";
    }
    
    $pedidos=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_pedidocantidad;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_pedidocantidad (idpedido INT, total_bultos DECIMAL(13,2), total_items INT, cantidad_tiendas INT);");
    $conexion->query("INSERT INTO tmp_pedidocantidad (idpedido, total_bultos, total_items, cantidad_tiendas)
        SELECT
        t_pedidodetalle.idpedido,
        SUM(t_pediodetalletienda.cantidad) as total_bultos,
        COUNT(DISTINCT t_pedidodetalle.codigo) as total_items,
        COUNT(DISTINCT t_pediodetalletienda.idpedidotienda) as cantidad_tiendas
        FROM
        t_pedidodetalle
        LEFT JOIN t_pediodetalletienda ON t_pedidodetalle.idpedidodetalle=t_pediodetalletienda.idpedidodetalle
        LEFT JOIN t_pedido ON t_pedidodetalle.idpedido=t_pedido.idpedido
        WHERE
        CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        $filtrocliente
        GROUP BY
        t_pedidodetalle.idpedido;");
    $conexion->query("ALTER TABLE tmp_pedidocantidad ADD INDEX idpedido (idpedido);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_disponibilidad;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_disponibilidad (idpedido INT, idpedidodetalle INT, idpedidodisponibilidad INT, sector VARCHAR(50));");
    $conexion->query("INSERT INTO tmp_disponibilidad (idpedido, idpedidodetalle, idpedidodisponibilidad)
        SELECT
        t_pedidodetalle.idpedido,
        t_pedidodisponibilidad.idpedidodetalle,
        MIN(t_pedidodisponibilidad.idpedidodisponibilidad) as idpedidodisponibilidad
        FROM
        t_pedidodisponibilidad
        LEFT JOIN t_pedidodetalle ON t_pedidodisponibilidad.idpedidodetalle=t_pedidodetalle.idpedidodetalle
        LEFT JOIN t_pedidopreparacion ON t_pedidodetalle.idpedido=t_pedidopreparacion.idpedido
        LEFT JOIN t_pedido ON t_pedidodetalle.idpedido=t_pedido.idpedido
        WHERE
        CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        $filtrocliente
        GROUP BY
        t_pedidodetalle.idpedido,
        t_pedidodisponibilidad.idpedidodetalle;");
    $conexion->query("ALTER TABLE tmp_disponibilidad ADD INDEX idpedido (idpedido);");
    $conexion->query("ALTER TABLE tmp_disponibilidad ADD INDEX idpedidodetalle (idpedidodetalle);");
    $conexion->query("ALTER TABLE tmp_disponibilidad ADD INDEX idpedidodisponibilidad (idpedidodisponibilidad);");
    $conexion->query("UPDATE tmp_disponibilidad a
        INNER JOIN t_pedidodisponibilidad b ON a.idpedidodisponibilidad=b.idpedidodisponibilidad
        INNER JOIN t_almacendetalle c ON b.ubicacionalmacen=c.nombre
        SET a.sector=c.sector;");
    $conexion->query("ALTER TABLE tmp_disponibilidad ADD INDEX sector (sector);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_preparacion;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_preparacion (idpedidopreparacion INT, sector VARCHAR(250), cantidad_bultos DECIMAL(13,2));");
    $conexion->query("INSERT INTO tmp_preparacion (idpedidopreparacion, sector, cantidad_bultos)
        SELECT 
        t_pedidopreparacion.idpedidopreparacion,
        GROUP_CONCAT(DISTINCT t_pedidopreparacionsector.sector) as sector,
        SUM(t_pediodetalletienda.cantidad) as cantidad_bultos
        FROM 
        t_pedidopreparacionsector
        LEFT JOIN t_pedidopreparacion ON t_pedidopreparacionsector.idpedidopreparacion=t_pedidopreparacion.idpedidopreparacion
        INNER JOIN tmp_disponibilidad ON t_pedidopreparacionsector.sector=IFNULL(tmp_disponibilidad.sector,'S/U') AND t_pedidopreparacion.idpedido=tmp_disponibilidad.idpedido
        LEFT JOIN t_pediodetalletienda ON tmp_disponibilidad.idpedidodetalle=t_pediodetalletienda.idpedidodetalle
        LEFT JOIN t_pedido ON t_pedidopreparacion.idpedido=t_pedido.idpedido
        WHERE
        CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        $filtrocliente
        GROUP BY
        t_pedidopreparacion.idpedidopreparacion;");
    $conexion->query("ALTER TABLE tmp_preparacion ADD INDEX idpedidopreparacion (idpedidopreparacion);");
    
    $result = $conexion->query("SELECT
        t_cliente.cliente,
        t_pedido.fecha,
        CONCAT(t_pedido.numero,'/',t_pedido.gestion) as numero,
        tmp_pedidocantidad.total_bultos,
        tmp_pedidocantidad.total_items, 
        tmp_preparacion.cantidad_bultos,
        tmp_pedidocantidad.cantidad_tiendas,
        t_pedido.rubro,
        t_usuario_revisado.nombre as usuario_revisado,
        t_preparador.nombre as preparador,
        t_pedidopreparacion.hora_inicio,
        t_pedidopreparacion.hora_fin,
        CASE t_pedidopreparacion.conforme
            WHEN 1 THEN 'SI'
            WHEN 0 THEN 'NO'
            ELSE ''
        END as conforme,
        CASE t_pedidopreparacion.conforme2
            WHEN 1 THEN 'SI'
            WHEN 0 THEN 'NO'
            ELSE ''
        END as conforme2,
        CASE t_pedidopreparacion.conforme3
            WHEN 1 THEN 'SI'
            WHEN 0 THEN 'NO'
            ELSE ''
        END as conforme3,
        t_pedidopreparacion.notas,
        t_pedido.no_pedido,
        t_pedido.fecha_entrega,
        TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio) as hora,
        HOUR(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))+MINUTE(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))/60 as hora_num,
        tmp_preparacion.cantidad_bultos/(HOUR(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))+MINUTE(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))/60) as ct_hr,
        (tmp_preparacion.cantidad_bultos/(HOUR(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))+MINUTE(TIMEDIFF(t_pedidopreparacion.hora_fin, t_pedidopreparacion.hora_inicio))/60))/60 as ct_min,
        tmp_preparacion.sector,
        t_pedido.nota_adicional
        FROM
        t_pedido
        LEFT JOIN t_cliente ON t_pedido.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_pedidocantidad ON t_pedido.idpedido=tmp_pedidocantidad.idpedido
        LEFT JOIN t_pedidopreparacion ON t_pedido.idpedido=t_pedidopreparacion.idpedido
        LEFT JOIN tmp_preparacion ON t_pedidopreparacion.idpedidopreparacion=tmp_preparacion.idpedidopreparacion
        LEFT JOIN t_usuario as t_usuario_revisado ON t_pedido.idusuario_revisado=t_usuario_revisado.idusuario
        LEFT JOIN t_usuario as t_preparador ON t_pedidopreparacion.idpreparador=t_preparador.idusuario
        WHERE
        CAST(t_pedido.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        $filtrocliente;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $pedidos[]=array(
            'cliente'=>$row['cliente'],
            'fecha'=>$row['fecha'],
            'numero'=>$row['numero'],
            'total_bultos'=>$row['total_bultos'],
            'total_items'=>$row['total_items'],
            'cantidad_bultos'=>$row['cantidad_bultos'],
            'cantidad_tiendas'=>$row['cantidad_tiendas'],
            'rubro'=>$row['rubro'],
            'usuario_revisado'=>$row['usuario_revisado'],
            'preparador'=>$row['preparador'],
	    'hora_inicio'=>$row['hora_inicio'],
            'hora_fin'=>$row['hora_fin'],
            'conforme'=>$row['conforme'],
            'conforme2'=>$row['conforme2'],
            'conforme3'=>$row['conforme3'],
            'notas'=>$row['notas'],
            'no_pedido'=>$row['no_pedido'],
            'fecha_entrega'=>$row['fecha_entrega'],
            'hora'=>$row['hora'],
            'hora_num'=>$row['hora_num'],
            'ct_hr'=>$row['ct_hr'],
            'ct_min'=>$row['ct_min'],
            'sector'=>$row['sector'],
            'nota_adicional'=>$row['nota_adicional']
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'pedidos'=>$pedidos
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);


