$app->put('/inventario/mailvencimientoprm/{idalmacen}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idalmacen = $args['idalmacen'];
    $codigo=400;
    $status='Error';
    $mensaje='Ocurrio un problema, intentelo mas tarde';
    
    $unidades=[];
    
    $result = $conexion->query("select 
        DISTINCT
        t_ingreso.idcliente,
        t_cliente.cliente,
        t_ingresodetalle.codigo,
        IF(SUBSTRING_INDEX(t_ingresodetalle.partida_especifica, '-', -1)=t_ingresodetalle.partida_especifica,t_ingresodetalle.partida_especifica,LEFT(t_ingresodetalle.partida_especifica,CHAR_LENGTH(t_ingresodetalle.partida_especifica)-(CHAR_LENGTH(SUBSTRING_INDEX(t_ingresodetalle.partida_especifica, '-', -1))+1))) as partida,
        t_ingresodetalle.serie as chasis,
        t_ingresodetalle.modelo,
        t_ingresodetalle.marca,
        t_ingresodetalle.color,
        t_ingresodetalle.partida_especifica,
        t_ingresodetalle.observaciones,
        t_ingresodetalle.no_dim,
        t_ingresodetalle.fecha_pase_salida,
        t_ingreso.fecha_emision_parte,
        DATE_ADD(CAST(t_ingreso.fecha_emision_parte as DATE),INTERVAL 120 DAY) as fecha_vencimiento,
        IF(DATEDIFF(CURRENT_DATE(),t_ingreso.fecha_emision_parte)>120,'VENCIDO','POR VENCER') as estado
        FROM 
        t_ingresodetalle
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        INNER JOIN t_clientecorreovencimientoprm ON t_ingreso.idcliente=t_clientecorreovencimientoprm.idcliente
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
