        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        WHERE
        DATEDIFF(CURRENT_DATE(),CAST(t_ingreso.fecha_emision_parte as DATE))>=90
        AND t_ingreso.es_vehiculo=1
        AND IFNULL(t_ingresodetalle.no_dim,'')=''
        AND IFNULL(t_salida.finalizado,0)<>1
