    $codigo=200;
    $status='Exito';
    $mensaje='';
    
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'unidades'=>$unidades,
        'idclientes'=>$idclientes,
        'id_clientes'=>$id_clientes,
        'respuesta'=>$respuesta,
        'to'=>$to
            
    );
    
    $response->getBody()->write(json_encode($resultado));
    
        
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/inventariosfisico/listado', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;

    $params = json_decode((string) $request->getBody(),true);

    $fecha_inicial=$params['fecha_inicial'];
    $fecha_final=$params['fecha_final'];
    $idcliente=$params['idcliente'];

    $ciudades= empty($params['ciudades']) ? [] : $params['ciudades'];
    $almacenes= empty($params['almacenes']) ? [] : $params['almacenes'];

    if(count($almacenes)==0){
        $filtroalmacen=$decoded_array['idalmacen'];
    }else{
        $filtroalmacen=implode(",",$almacenes);
    }

    $filtrocliente='';
    if($idcliente<>''){
        $filtrocliente=" AND t_inventariofisico.idcliente=$idcliente";
    }

    $filtrociudad="";
    if(count($ciudades)>0){
        $filtrociudad=" AND t_almacen.idciudad IN (". implode(",", $ciudades).")";
    }

    $filtrofecha='';
    if($fecha_inicial<>'' && $fecha_final<>''){
        $filtrofecha=" AND CAST(IFNULL(t_inventariofisico.created_at,t_inventariofisico.fecha) as DATE) BETWEEN '$fecha_inicial' AND '$fecha_final'";
    }



    $inventariosfisico=[];
    $result = $conexion->query("SELECT
        t_inventariofisico.idinventariofisico,
        t_cliente.cliente,
        IFNULL(t_inventariofisico.es_vehiculo,0) as es_vehiculo,
        t_inventariofisico.fecha,
        CASE
            WHEN COUNT(t_inventariofisicodetalle.idinventariofisicodetalle) = 0 THEN JSON_ARRAY()
            ELSE JSON_ARRAYAGG(
                JSON_OBJECT(
                'idinventariofisicodetalle', t_inventariofisicodetalle.idinventariofisicodetalle,
                'cantidad', t_inventariofisicodetalle.cantidad,
                'cantidad_real', t_inventariofisicodetalle.cantidad_real,
                'codigo', t_inventariofisicodetalle.codigo
                )
            )
        END AS detalle,
        t_status.status,
        t_inventariofisico.categoria,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.fecha_fin_inventario,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        t_ciudad.ciudad
        FROM
        t_inventariofisico
        LEFT JOIN t_cliente ON t_inventariofisico.idcliente=t_cliente.idcliente
        LEFT JOIN t_inventariofisicodetalle ON t_inventariofisico.idinventariofisico=t_inventariofisicodetalle.idinventariofisico
        LEFT JOIN t_status ON t_inventariofisico.idstatus=t_status.idstatus
        LEFT JOIN t_almacen ON t_inventariofisico.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_inventariofisico.idalmacen IN ($filtroalmacen)
        $filtrofecha
        $filtrociudad
        $filtrocliente
        AND t_inventariofisico.deleted_at IS NULL
        GROUP BY
        t_inventariofisico.idinventariofisico,
        t_cliente.cliente,
        IFNULL(t_inventariofisico.es_vehiculo,0),
        t_inventariofisico.fecha,
        t_status.status,
        t_inventariofisico.categoria,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.fecha_fin_inventario,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        t_ciudad.ciudad;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $inventariosfisico[]=array(
            'idinventariofisico'=>(int)$row['idinventariofisico'],
            'cliente'=>$row['cliente'],
            'es_vehiculo'=> boolval($row['es_vehiculo']),
            'fecha'=>$row['fecha'],
            'status'=>$row['status'],
            'categoria'=>$row['categoria'],
            'fecha_inicio_conteo'=>$row['fecha_inicio_conteo'],
            'fecha_fin_conteo'=>$row['fecha_fin_conteo'],
            'fecha_fin_inventario'=>$row['fecha_fin_inventario'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'ciudad'=>$row['ciudad'],
            'detalle'=> json_decode($row["detalle"], true)
        );
    }
    
        
    
    for($if=0;$if<count($inventariosfisico);$if++){
        $diferencia=false;
        $pendientes=0;
        $encontrados=0;
        $sobrantes=0;
        $faltantes=0;
        $estado=false;
        for($dd=0;$dd<count($inventariosfisico[$if]["detalle"]);$dd++){
            if($inventariosfisico[$if]["detalle"][$dd]["cantidad"]<>$inventariosfisico[$if]["detalle"][$dd]["cantidad_real"]){
                $diferencia=true;
            }
            if($inventariosfisico[$if]["fecha_inicio_conteo"]<>''){
                if((float)$inventariosfisico[$if]["detalle"][$dd]["cantidad"]==(float)$inventariosfisico[$if]["detalle"][$dd]["cantidad_real"]){
                    $encontrados++;
                    $estado=true;
                }
                if((float)$inventariosfisico[$if]["detalle"][$dd]["cantidad"]>(float)$inventariosfisico[$if]["detalle"][$dd]["cantidad_real"]){
                    if($inventariosfisico[$if]["fecha_fin_conteo"]<>''){
                        $faltantes++;
                        $estado=true;
                    }else{
                        $pendientes++;
                        $estado=true;
                    }
                }
                if((float)$inventariosfisico[$if]["detalle"][$dd]["cantidad"]<(float)$inventariosfisico[$if]["detalle"][$dd]["cantidad_real"]){
                    $sobrantes++;
                    $estado=true;
                }
                if(!$estado){
                    $pendientes++;
                }
            }else{
                $pendientes++;
            }
                
        }
        $inventariosfisico[$if]["diferencia"]=$diferencia;
        $inventariosfisico[$if]["diferencia_texto"] = $inventariosfisico[$if]["diferencia"] ? "Si" : "Cuadrado";
        $inventariosfisico[$if]["encontrados"]=$encontrados;
        $inventariosfisico[$if]["faltantes"]=$faltantes;
        $inventariosfisico[$if]["sobrantes"]=$sobrantes;
        $inventariosfisico[$if]["pendientes"]=$pendientes;
    }
    
    
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'inventariosfisico'=>$inventariosfisico
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/inventariosfisico/{idcliente}/fechas', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];

    $fechas=array();
    $result = $conexion->query("SELECT
        DISTINCT
        t_inventariofisico.fecha
        FROM
        t_inventariofisico
        LEFT JOIN t_almacen ON t_inventariofisico.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_ciudad.idempresa=$idempresa
        AND t_inventariofisico.idcliente=$idcliente
        AND t_inventariofisico.deleted_at IS NULL
        ORDER BY
        t_inventariofisico.fecha;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        array_push($fechas, $row["fecha"]);
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'fechas'=>$fechas
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

