$app->post('/inventariosfisico/cargamasiva', function(Request $request, Response $response, array $args) use ($conexion, $archivosmasivo) {

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'El archivo no se subió, probablemente sea mayor a 10MB';

    $xls_data = [];
    $datos_excel = [];
    $finalResult = [];
    $mensajes_error = [];

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'];

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idempresa = $decoded_array["idempresa"] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros del formulario
        |--------------------------------------------------------------------------
        */
        $bodyParams = $request->getParsedBody();

        if (!is_array($bodyParams)) {
            $bodyParams = [];
        }

        $idclienteHash = $bodyParams['idcliente'] ?? null;
        $es_vehiculo_set = $bodyParams['es_vehiculo'] ?? null;

        $es_vehiculo = 0;
        $idstatus = null;

        if ($es_vehiculo_set !== null) {
            $es_vehiculo = ($es_vehiculo_set === 'true' || $es_vehiculo_set === true || (int)$es_vehiculo_set === 1) ? 1 : 0;
            $idstatus = ($es_vehiculo === 1) ? 1 : null;
        }

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if (empty($idempresa)) {
            $mensaje = 'No se recibió la empresa';
            $continuar = false;
        }

        if ($continuar && empty($idclienteHash)) {
            $mensaje = 'No se recibió el cliente';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Buscar cliente por hash
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idclientenum = 0;

            $queryCliente = "
                SELECT idcliente
                FROM t_cliente
                WHERE MD5(idcliente) = :idcliente_hash
                LIMIT 1
            ";

            $stmtCliente = $conexion->prepare($queryCliente);

            $stmtCliente->execute([
                ':idcliente_hash' => $idclienteHash
            ]);

            $rowCliente = $stmtCliente->fetch(PDO::FETCH_ASSOC);

            if ($rowCliente) {
                $idclientenum = (int)$rowCliente["idcliente"];
            }

            if ($idclientenum <= 0) {
                $mensaje = 'No se encontró el cliente';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $files = $_FILES['uploads'] ?? null;

            $totalArchivos = (
                isset($files['name']) &&
                is_array($files['name'])
            ) ? count($files['name']) : 0;

            if ($totalArchivos === 0) {
                $mensaje = 'Debe adjuntar un archivo';
                $continuar = false;
            }
        }

        if ($continuar) {

            if (($files['error'][0] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
                $mensaje = 'Ocurrió un problema al subir el archivo';
                $continuar = false;
            }
        }

        if ($continuar) {

            $nombreOriginal = $files["name"][0] ?? '';

            if (trim($nombreOriginal) === '') {
                $mensaje = 'El archivo no tiene nombre válido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Subir archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $nombredoc = $idclientenum . "_" . date("Y_m_d") . "_" . $nombreOriginal;

            $creacion = new Carpetas();
            $respuesta = $creacion->procesarCarpeta($idempresa);

            $piramideUploader = new PiramideUploader();

            $upload = $piramideUploader->upload(
                $nombredoc,
                'uploads',
                folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/inventario_fisico/masivo',
                $archivosmasivo,
                true
            );

            $file = $piramideUploader->getInfoFile();
            $file_name = $file['complete_name'] ?? '';

            if (!isset($upload) || empty($upload['uploaded'])) {
                $mensaje = $upload['error'] ?? 'No se pudo subir el archivo';
                $continuar = false;
            }

            if ($continuar && trim($file_name) === '') {
                $mensaje = 'No se pudo obtener el nombre del archivo subido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Leer Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $inputFileName = folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/inventario_fisico/masivo/' . $file_name;

            if (!file_exists($inputFileName)) {
                $mensaje = 'No se encontró el archivo subido';
                $continuar = false;
            }
        }

        if ($continuar) {

            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();

            $highestRow = $sheet->getHighestRow();
            $highestColumn = $sheet->getHighestColumn();

            if ($highestRow < 2) {
                $mensaje = 'El archivo no tiene datos para procesar';
                $continuar = false;
            }
        }

        if ($continuar) {

            $xls_data = $sheet->rangeToArray(
                'A2:' . $highestColumn . $highestRow,
                '',
                true,
                true
            );

            $keys = [
                "codigo_almacen",
                "codigo",
                "serie",
                "descripcion",
                "categoria",
                "lote"
            ];

            foreach ($xls_data as $index => $item) {

                /*
                Eliminar filas totalmente vacías.
                */
                $filaVacia = true;

                foreach ($item as $valorCelda) {
                    if (trim((string)$valorCelda) !== '') {
                        $filaVacia = false;
                        break;
                    }
                }

                if ($filaVacia) {
                    continue;
                }

                /*
                Normalizar columnas.
                Si vienen menos columnas se rellenan.
                Si vienen más columnas se cortan.
                */
                $item = array_slice($item, 0, count($keys));
                $item = array_pad($item, count($keys), '');

                $datos_excel[] = array_combine($keys, $item);
            }

            if (count($datos_excel) === 0) {
                $mensaje = 'El archivo no contiene filas válidas';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Obtener almacenes permitidos de la empresa
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $almacenes = [];

            $queryAlmacenes = "
                SELECT
                    a.idalmacen,
                    a.codigo_almacen
                FROM t_almacen a
                LEFT JOIN t_ciudad c
                    ON a.idciudad = c.idciudad
                WHERE c.idempresa = :idempresa
            ";

            $stmtAlmacenes = $conexion->prepare($queryAlmacenes);

            $stmtAlmacenes->execute([
                ':idempresa' => $idempresa
            ]);

            while ($row = $stmtAlmacenes->fetch(PDO::FETCH_ASSOC)) {
                $almacenes[] = [
                    'idalmacen' => (int)$row["idalmacen"],
                    'codigo_almacen' => trim((string)$row['codigo_almacen'])
                ];
            }

            if (count($almacenes) === 0) {
                $mensaje = 'No existen almacenes registrados para la empresa';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar filas del Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $codigosAlmacenValidos = array_column($almacenes, 'codigo_almacen');

            foreach ($datos_excel as $xls => $fila) {

                $numeroFilaExcel = $xls + 2;

                $codigoAlmacen = trim((string)($fila["codigo_almacen"] ?? ''));
                $serie = trim((string)($fila["serie"] ?? ''));

                $datos_excel[$xls]["codigo_almacen"] = $codigoAlmacen;
                $datos_excel[$xls]["serie"] = $serie;

                if ($codigoAlmacen === '') {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Centro no puede estar vacío'
                    ];
                } elseif (!in_array($codigoAlmacen, $codigosAlmacenValidos)) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Centro inexistente'
                    ];
                }

                if ($serie === '') {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Números de Chasis no puede estar vacío'
                    ];
                }
            }

            if (count($mensajes_error) > 0) {
                $mensaje = 'El archivo contiene errores';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Agrupar por almacén
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $grouped = [];

            foreach ($datos_excel as $item) {

                $codigoAlmacen = $item['codigo_almacen'];

                $entry = $item;
                unset($entry['codigo_almacen']);

                if (!isset($grouped[$codigoAlmacen])) {
                    $grouped[$codigoAlmacen] = [
                        'codigo_almacen' => $codigoAlmacen,
                        'items' => []
                    ];
                }

                $grouped[$codigoAlmacen]['items'][] = $entry;
            }

            $finalResult = array_values($grouped);

            if (count($finalResult) === 0) {
                $mensaje = 'No existen datos agrupados para procesar';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Insertar inventarios físicos
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            $queryInventario = "
                INSERT INTO t_inventariofisico (
                    idalmacen,
                    idcliente,
                    es_vehiculo,
                    fecha,
                    idstatus,
                    created_at
                ) VALUES (
                    :idalmacen,
                    :idcliente,
                    :es_vehiculo,
                    CURRENT_DATE(),
                    :idstatus,
                    CURRENT_TIMESTAMP()
                )
            ";

            $stmtInventario = $conexion->prepare($queryInventario);

            $queryDetalle = "
                INSERT INTO t_inventariofisicodetalle (
                    idinventariofisico,
                    codigo,
                    serie,
                    descripcion,
                    categoria,
                    cantidad,
                    cantidad_real,
                    embalaje,
                    lote
                ) VALUES (
                    :idinventariofisico,
                    :codigo,
                    :serie,
                    :descripcion,
                    :categoria,
                    1,
                    0,
                    'UND',
                    :lote
                )
            ";

            $stmtDetalle = $conexion->prepare($queryDetalle);

            foreach ($finalResult as $grupo) {

                $key = array_search($grupo["codigo_almacen"], array_column($almacenes, 'codigo_almacen'));

                if (!is_numeric($key)) {
                    $mensaje = 'No se encontró el almacén para registrar el inventario';
                    $continuar = false;
                    break;
                }

                $idalmacenGrupo = $almacenes[$key]["idalmacen"];

                $resultInventario = $stmtInventario->execute([
                    ':idalmacen' => $idalmacenGrupo,
                    ':idcliente' => $idclientenum,
                    ':es_vehiculo' => $es_vehiculo,
                    ':idstatus' => $idstatus
                ]);

                if (!$resultInventario) {
                    $mensaje = 'No se pudo registrar el inventario físico';
                    $continuar = false;
                    break;
                }

                $idinventariofisicoNuevo = (int)$conexion->lastInsertId();

                if ($idinventariofisicoNuevo <= 0) {
                    $mensaje = 'No se pudo obtener el inventario físico generado';
                    $continuar = false;
                    break;
                }

                foreach ($grupo["items"] as $itemDetalle) {

                    $resultDetalle = $stmtDetalle->execute([
                        ':idinventariofisico' => $idinventariofisicoNuevo,
                        ':codigo' => $itemDetalle["codigo"] ?? '',
                        ':serie' => $itemDetalle["serie"] ?? '',
                        ':descripcion' => $itemDetalle["descripcion"] ?? '',
                        ':categoria' => $itemDetalle["categoria"] ?? '',
                        ':lote' => $itemDetalle["lote"] ?? ''
                    ]);

                    if (!$resultDetalle) {
                        $mensaje = 'No se pudo registrar un detalle del inventario físico';
                        $continuar = false;
                        break 2;
                    }
                }
            }

            if (!$continuar) {
                if ($conexion->inTransaction()) {
                    $conexion->rollBack();
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar operación
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información general';
        }

    } catch (Throwable $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'mensajes_error' => $mensajes_error
    );

    /*
    En desarrollo, si quieres depurar, puedes volver a incluir estos campos.
    En producción es mejor no devolverlos:
    'xls_data' => $xls_data,
    'datos_excel' => $datos_excel,
    'finalResult' => $finalResult
    */

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

