$app->post('/inventariosfisico/monitoreo-centros/{idcliente}/{idinvnetariofisico}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $idinvnetariofisico = $args['idinvnetariofisico'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    $params = json_decode((string) $request->getBody(),true);
    
    $ciudades= empty($params['ciudades']) ? [] : $params['ciudades'];
    $almacenes= empty($params['almacenes']) ? [] : $params['almacenes'];
    
    $filtroidinvnetariofisico="";
    if($idinvnetariofisico>0){
        $filtroidinvnetariofisico=" AND t_inventariofisico.idinventariofisico=$idinvnetariofisico";
    }else{
        $filtrociudad="";
        if(count($ciudades)>0){
            $filtrociudad=" AND t_almacen.idciudad IN (". implode(",", $ciudades).")";
        }
        
        $filtroalmacen="";
        if(count($almacenes)>0){
            $filtroalmacen=" AND t_inventariofisico.idalmacen IN (". implode(",", $almacenes).")";
        }
        
        $filtrofecha="";
        if($fechainicial<>0 && $fechafinal<>0){
            $filtrofecha=" AND CAST(IFNULL(t_inventariofisico.created_at,t_inventariofisico.fecha) as DATE) BETWEEN '$fechainicial' AND '$fechafinal'";
        }
    }
    
    $detalle=[];
    $query="WITH tmp_almacenes as (
        SELECT
        t_inventariofisico.idinventariofisico,
        t_inventariofisicoconteo.serie,
        GROUP_CONCAT(t_almacen.codigo_almacen SEPARATOR '/') as codigo_almacen,
        GROUP_CONCAT(t_almacen.almacen SEPARATOR '/') as almacen,
        GROUP_CONCAT(IFNULL(t_usuario.nombre,'') SEPARATOR '/') as usuario_conteo
        FROM
        t_inventariofisico
        LEFT JOIN t_inventariofisico as tmp_inventariofisico_general ON t_inventariofisico.idcliente=tmp_inventariofisico_general.idcliente AND t_inventariofisico.fecha=tmp_inventariofisico_general.fecha AND tmp_inventariofisico_general.deleted_at IS NULL
        LEFT JOIN t_inventariofisicoconteo ON tmp_inventariofisico_general.idinventariofisico=t_inventariofisicoconteo.idinventariofisico
        LEFT JOIN t_almacen ON tmp_inventariofisico_general.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_usuario ON t_inventariofisicoconteo.idusuario=t_usuario.idusuario
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_inventariofisico.idcliente=$idcliente
        AND IFNULL(t_inventariofisicoconteo.serie,'')<>''
        AND t_inventariofisico.deleted_at IS NULL
        $filtroidinvnetariofisico
        GROUP BY
        t_inventariofisico.idinventariofisico,
        t_inventariofisicoconteo.serie)
        select
        t_inventariofisicodetalle.idinventariofisico,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        t_inventariofisicodetalle.idinventariofisicodetalle,
        t_inventariofisicodetalle.codigo,
        t_inventariofisicodetalle.serie,
        t_inventariofisicodetalle.descripcion,
        t_inventariofisicodetalle.categoria,
        t_inventariofisicodetalle.cantidad,
        t_inventariofisicodetalle.cantidad_real,
        IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0) as diferencia,
        t_inventariofisicodetalle.embalaje,
        t_inventariofisicodetalle.lote,
        t_inventariofisicodetalle.observaciones,
        IF(t_inventariofisico.fecha_inicio_conteo IS NULL,'',
          CASE
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))=0 THEN 'ENCONTRADO'
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))>0 THEN 'SOBRANTE'
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))<0 THEN IF(t_inventariofisico.fecha_fin_conteo IS NULL,'PENDIENTE','FALTANTE')
          END
        ) as estado_conteo,
        IF(t_inventariofisico.fecha_inicio_conteo IS NULL,null,
          CASE
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))=0 THEN 1
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))>0 THEN 2
            WHEN (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))<0 THEN IF(t_inventariofisico.fecha_fin_conteo IS NULL,4,3)
          END
        ) as idestado_conteo,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.fecha_fin_inventario,
        t_inventariofisicoconteo.idinventariofisicoconteo,
        t_inventariofisicodetalle.idinventariofisicoetiqueta,
        t_inventariofisicoetiqueta.inventariofisicoetiqueta,
        tmp_almacenes.codigo_almacen as codigo_almacen_conteo,
        tmp_almacenes.almacen as almacen_conteo,
        tmp_almacenes.usuario_conteo,
        tmp_usuario_fin_inventario.nombre as usuario_fin_inventario
        
        FROM
        t_inventariofisicodetalle
        LEFT JOIN t_inventariofisico ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisico.idinventariofisico
        LEFT JOIN t_inventariofisicoconteo ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisicoconteo.idinventariofisico AND t_inventariofisicodetalle.serie=t_inventariofisicoconteo.serie 
        LEFT JOIN t_inventariofisicoetiqueta ON t_inventariofisicodetalle.idinventariofisicoetiqueta=t_inventariofisicoetiqueta.idinventariofisicoetiqueta
        LEFT JOIN tmp_almacenes ON t_inventariofisicodetalle.serie=tmp_almacenes.serie AND t_inventariofisicodetalle.idinventariofisico=tmp_almacenes.idinventariofisico
        LEFT JOIN t_almacen ON t_inventariofisico.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_usuario as tmp_usuario_fin_inventario ON t_inventariofisico.idusuario_fin_inventario=tmp_usuario_fin_inventario.idusuario
        LEFT JOIN t_ciudad ON t_almacen.idciudad=t_ciudad.idciudad
        WHERE
        t_inventariofisico.idcliente=$idcliente
        AND t_inventariofisico.deleted_at IS NULL
        $filtroidinvnetariofisico
        $filtrofecha
        $filtrociudad
        $filtroalmacen
        ORDER BY
        t_inventariofisicodetalle.idinventariofisicodetalle;";
    $result = $conexion->query($query);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $detalle[]=array(
            'idinventariofisico'=>(int)$row['idinventariofisico'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'idinventariofisicodetalle'=>(int)$row['idinventariofisicodetalle'],
            'codigo'=>$row['codigo'],
            'serie'=>$row['serie'],
            'descripcion'=>$row['descripcion'],
            'categoria'=>$row['categoria'],
            'cantidad'=>(float)$row['cantidad'],
            'cantidad_real'=>(float)$row['cantidad_real'],
            'diferencia'=>(float)$row['diferencia'],
            'embalaje'=>$row['embalaje'],
            'lote'=>$row['lote'],
            'observaciones'=>$row['observaciones'],
            'estado_conteo'=>$row['estado_conteo'],
            'idestado_conteo'=>$row['idestado_conteo'],
            'fecha_inicio_conteo'=>$row['fecha_inicio_conteo'],
            'fecha_fin_conteo'=>$row['fecha_fin_conteo'],
            'fecha_fin_inventario'=>$row['fecha_fin_inventario'],
            'idinventariofisicoconteo'=>$row['idinventariofisicoconteo'],
            'idinventariofisicoetiqueta'=>$row['idinventariofisicoetiqueta'],
            'inventariofisicoetiqueta'=>$row['inventariofisicoetiqueta'],
            'codigo_almacen_conteo'=>$row['codigo_almacen_conteo'],
            'almacen_conteo'=>$row['almacen_conteo'],
            'usuario_conteo'=>$row['usuario_conteo'],
            'usuario_fin_inventario'=>$row['usuario_fin_inventario'],
        );
    }
    
    
        
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'detalle'=>$detalle,
        'query'=>$query
    )));
    /*
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'inventariofisico' => getDataInventarioFisico($idinventariosfisico, $conexion)
    )));
    */
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/inventariosfisico/detalle/{idinventariofisicodetalle}/cargararchivo', function(Request $request, Response $response, array $args) use ($conexion,$archivospermitidos) {
    $idinventariofisicodetalle = $args['idinventariofisicodetalle'];
    //$params = json_decode((string) $request->getBody(),true);
    
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $maxFileSize = 15 * 1024 * 1024; // 15 MB
    
    $codigo=400;
    $status='Error';
    $mensaje='No se cargo ningun archivo';
    $errores=[];
    $cargados=[];
    
    $files = $_FILES['demo'] ?? null;

    if (
        $files &&
        isset($files['name']) &&
        is_array($files['name'])
    ) {
        $creacion=new Carpetas();
        $respuesta=$creacion->procesarCarpeta($idempresa);
        
        $uploadDir=folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/inventario_fisico/conteo/archivos/'.$idinventariofisicodetalle.'/';
        if (!file_exists($uploadDir)) {
            mkdir($uploadDir, 0777, true);
        }
            
        for ($i = 0; $i < count($files['name']); $i++) {
            $name = $files['name'][$i];
            $tmpName = $files['tmp_name'][$i];
            $size = $files['size'][$i];
            $error = $files['error'][$i];

            if ($error !== UPLOAD_ERR_OK) {
                $errores[] = "$name: Error al subir el archivo.";
                continue;
            }

            $extension = strtolower(pathinfo($name, PATHINFO_EXTENSION));

            // Validar extensión
            $finfo = finfo_open(FILEINFO_MIME_TYPE);
            $mimeType = finfo_file($finfo, $tmpName);
            finfo_close($finfo);
            
            if (!in_array($mimeType, $archivospermitidos)) {
                $errores[] = "$name: Tipo MIME no permitido ($mimeType).";
                continue;
            }
            
            // Validar tamaño
            if ($size > $maxFileSize) {
                $errores[] = "$name: Tamaño superior al permitido.";
                continue;
            }

            // Validar que sea un archivo realmente subido
            if (!is_uploaded_file($tmpName)) {
                $errores[] = "$name: No es un archivo válido.";
                continue;
            }

            // Guardar archivo
            $safeName = uniqid('upload_', true) . '.' . $extension;
            
            $destination = $uploadDir . $safeName;

            if (move_uploaded_file($tmpName, $destination)) {
                $stmtDetalle = $conexion->prepare("INSERT INTO t_inventariofisicodetallearchivo (idinventariofisicodetalle, inventariofisicodetallearchivo, nombre_fisico) VALUES (?, ?, ?)");
                $stmtDetalle->execute([$idinventariofisicodetalle, $name, $safeName]);
                $idArchivo = $conexion->lastInsertId();
                
                $cargados[] = [
                    'original' => $name,
                    'savedAs' => $safeName,
                    'size' => $size,
                    'id'=>$idArchivo
                ];
                
                $codigo=200;
                $status='Error';
                $mensaje='Archivos Cargados exitosamente';
                
                
            } else {
                $errores[] = "$name: No se pudo guardar el archivo.";
            }
        }
    }
    
    

    //echo json_encode($response);


    /*
    $result = $conexion->exec($query);

    if($result===false){

    }else{
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información General';
    }
     * 
     */
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'errores'=>$errores,
        'cargados'=>$cargados,
        'idinventariofisicodetalle'=>(int)$idinventariofisicodetalle
            
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

