$app->post('/inventariosfisico/{idinventariofisico}/cargamasiva', function(Request $request, Response $response, array $args) use ($conexion,$archivosmasivo) {
    $idinventariofisico = $args['idinventariofisico'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array["idempresa"];
    
    $codigo=400;
    $status='Error';
    $mensaje='El Archivo no se subio, probablemente sea mayor a 10MB';
    $xls_data=[];
    $mensajes_error=[];
    $nuevosdatos=[];
    //$embalaje=[];
    
    if(isset($_FILES['uploads'])){
        $nombredoc=$_FILES['uploads']["name"][0];
        //$random = bin2hex(openssl_random_pseudo_bytes(5));
        //$nombredoc=$random."_".$nombredoc;
        $creacion=new Carpetas();
        $respuesta=$creacion->procesarCarpeta($idempresa);
        
        $piramideUploader=new PiramideUploader();
        $upload =$piramideUploader->upload($nombredoc, 'uploads', folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/inventario_fisico/'.$idinventariofisico, $archivosmasivo, true);
        
        $file=$piramideUploader->getInfoFile();
        $file_name=$file['complete_name'];
        
        if(isset($upload) && $upload['uploaded']==false){
            $mensaje=$upload['error'];
        }else{
            $inputFileName = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/inventario_fisico/'.$idinventariofisico.'/'.$file_name;
            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();
            $highestRow = $sheet->getHighestRow(); 
            $highestColumn = $sheet->getHighestColumn();
            $xls_data = $sheet->rangeToArray(
                'A2:' . $highestColumn . $highestRow,
                '',TRUE,TRUE
            );
            
            $baseproductos=[];
            $resultbaseproductos = $conexion->query("select 
                t_baseproductos.codigo,
                t_baseproductos.serie,
                t_baseproductos.descripcion,
                t_embalaje.codigoembalaje
                from 
                t_baseproductos
                LEFT JOIN t_inventariofisico ON t_baseproductos.idcliente=t_inventariofisico.idcliente
                LEFT JOIN t_embalaje ON t_baseproductos.idembalaje=t_embalaje.idembalaje
                WHERE
                t_inventariofisico.idinventariofisico=$idinventariofisico;");
            while ($rowbaseproductos =  $resultbaseproductos ->fetch(PDO::FETCH_ASSOC)){
                $baseproductos[]=array(
                    'codigo'=>$rowbaseproductos['codigo'],
                    'serie'=>$rowbaseproductos['serie'],
                    'descripcion'=>$rowbaseproductos['descripcion'],
                    'codigoembalaje'=>$rowbaseproductos['codigoembalaje'],
                    
                );
            }

            
            $datosinsertar='';
            for($ex=0;$ex<count($xls_data);$ex++){
                
                if($xls_data[$ex][8]!==''){
                    $fecha8explode= explode("/", $xls_data[$ex][8]);
                    $xls_data[$ex][8]=$fecha8explode[2]."-".sprintf("%02d", $fecha8explode[0])."-".sprintf("%02d", $fecha8explode[1]);
                }
                
                $keycodigo = array_search($xls_data[$ex][0], array_column($baseproductos, 'codigo'));
                if(is_numeric($keycodigo)){
                    $xls_data[$ex][1]=$baseproductos[$keycodigo]['serie'];
                    $xls_data[$ex][2]=$baseproductos[$keycodigo]['descripcion'];
                    $xls_data[$ex][6]=$baseproductos[$keycodigo]['codigoembalaje'];
                }
            }

            
            $codigo=200;
            $status='Exito';
            $mensaje='El Archivo se subio correctamente';
        }

    }
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'xls_data'=>$xls_data
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->put('/inventariosfisico/{idinventariofisico}', function(Request $request, Response $response, array $args) use ($conexion) {

    $idinventariofisico = $args['idinventariofisico'] ?? null;

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'No se guardó la información';

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'];

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idusuario = $decoded_array["idusuario"] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros
        |--------------------------------------------------------------------------
        */
        $params = json_decode((string) $request->getBody(), true);

        if (!is_array($params)) {
            $mensaje = 'No se recibieron parámetros válidos';
            $continuar = false;
        }

        if ($continuar) {
            $idstatus = empty($params['idstatus']) ? null : $params['idstatus'];
            $categoria = $params['categoria'] ?? '';
            $fecha = $params['fecha'] ?? null;
            $idasignado = empty($params['idasignado']) ? null : $params['idasignado'];
            $idapoyo = empty($params['idapoyo']) ? null : $params['idapoyo'];

            $fecha_inicio = empty($params['fecha_inicio'])
                ? null
                : str_replace("T", " ", $params['fecha_inicio']);

            $fecha_fin = empty($params['fecha_fin'])
                ? null
                : str_replace("T", " ", $params['fecha_fin']);

            $detalle = $params["detalle"] ?? [];
        }

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if ($continuar && empty($idinventariofisico)) {
            $mensaje = 'No se recibió el inventario físico';
            $continuar = false;
        }

        if ($continuar && empty($idusuario)) {
            $mensaje = 'No se recibió el usuario';
            $continuar = false;
        }

        if ($continuar && empty($fecha)) {
            $mensaje = 'No se recibió la fecha';
            $continuar = false;
        }

        if ($continuar && !is_array($detalle)) {
            $mensaje = 'El detalle recibido no tiene un formato válido';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Iniciar transacción
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            /*
            |--------------------------------------------------------------------------
            | Actualizar cabecera
            |--------------------------------------------------------------------------
            */
            $queryInventario = "
                UPDATE t_inventariofisico
                SET
                    fecha = :fecha,
                    idstatus = :idstatus,
                    categoria = :categoria,
                    idasignado = :idasignado,
                    idapoyo = :idapoyo,
                    fecha_inicio = :fecha_inicio,
                    fecha_fin = :fecha_fin
                WHERE idinventariofisico = :idinventariofisico
            ";

            $stmtInventario = $conexion->prepare($queryInventario);

            $resultInventario = $stmtInventario->execute([
                ':fecha' => $fecha,
                ':idstatus' => $idstatus,
                ':categoria' => $categoria,
                ':idasignado' => $idasignado,
                ':idapoyo' => $idapoyo,
                ':fecha_inicio' => $fecha_inicio,
                ':fecha_fin' => $fecha_fin,
                ':idinventariofisico' => $idinventariofisico
            ]);

            if (!$resultInventario) {
                $mensaje = 'No se pudo actualizar el inventario físico';
                $continuar = false;

                if ($conexion->inTransaction()) {
                    $conexion->rollBack();
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Detalle: actualizar / insertar
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idsDetalleRecibidos = [];

            $queryUpdateDetalle = "
                UPDATE t_inventariofisicodetalle
                SET
                    codigo = :codigo,
                    serie = :serie,
                    descripcion = :descripcion,
                    categoria = :categoria,
                    ubicacion = :ubicacion,
                    cantidad = :cantidad,
                    cantidad_real = :cantidad_real,
                    embalaje = :embalaje,
                    lote = :lote,
                    fecha_vencimiento = :fecha_vencimiento,
                    observaciones = :observaciones,
                    idinventariofisicoetiqueta = :idinventariofisicoetiqueta
                WHERE idinventariofisicodetalle = :idinventariofisicodetalle
                  AND idinventariofisico = :idinventariofisico
            ";

            $stmtUpdateDetalle = $conexion->prepare($queryUpdateDetalle);

            $queryInsertDetalle = "
                INSERT INTO t_inventariofisicodetalle (
                    idinventariofisico,
                    codigo,
                    serie,
                    descripcion,
                    ubicacion,
                    categoria,
                    cantidad,
                    cantidad_real,
                    embalaje,
                    lote,
                    fecha_vencimiento,
                    observaciones,
                    idinventariofisicoetiqueta
                ) VALUES (
                    :idinventariofisico,
                    :codigo,
                    :serie,
                    :descripcion,
                    :ubicacion,
                    :categoria,
                    :cantidad,
                    :cantidad_real,
                    :embalaje,
                    :lote,
                    :fecha_vencimiento,
                    :observaciones,
                    :idinventariofisicoetiqueta
                )
            ";

            $stmtInsertDetalle = $conexion->prepare($queryInsertDetalle);

            foreach ($detalle as $item) {

                $idinventariofisicodetalle = $item['idinventariofisicodetalle'] ?? 0;

                $fecha_vencimiento = empty($item['fecha_vencimiento'])
                    ? null
                    : $item['fecha_vencimiento'];

                $idinventariofisicoetiqueta = empty($item['idinventariofisicoetiqueta'])
                    ? null
                    : $item['idinventariofisicoetiqueta'];

                $dataDetalle = [
                    ':idinventariofisico' => $idinventariofisico,
                    ':codigo' => $item['codigo'] ?? '',
                    ':serie' => $item['serie'] ?? '',
                    ':descripcion' => $item['descripcion'] ?? '',
                    ':ubicacion' => $item['ubicacion'] ?? '',
                    ':categoria' => $item['categoria'] ?? '',
                    ':cantidad' => $item['cantidad'] ?? 0,
                    ':cantidad_real' => $item['cantidad_real'] ?? 0,
                    ':embalaje' => $item['embalaje'] ?? '',
                    ':lote' => $item['lote'] ?? '',
                    ':fecha_vencimiento' => $fecha_vencimiento,
                    ':observaciones' => $item['observaciones'] ?? '',
                    ':idinventariofisicoetiqueta' => $idinventariofisicoetiqueta
                ];

                if ((int)$idinventariofisicodetalle > 0) {

                    $idsDetalleRecibidos[] = (int)$idinventariofisicodetalle;

                    $dataUpdate = $dataDetalle;
                    $dataUpdate[':idinventariofisicodetalle'] = $idinventariofisicodetalle;

                    $resultDetalle = $stmtUpdateDetalle->execute($dataUpdate);

                } else {

                    $resultDetalle = $stmtInsertDetalle->execute($dataDetalle);

                    /*
                    Importante:
                    Si se inserta un detalle nuevo, agregamos su ID
                    para que no sea eliminado en el bloque siguiente.
                    */
                    if ($resultDetalle) {
                        $idsDetalleRecibidos[] = (int)$conexion->lastInsertId();
                    }
                }

                if (!$resultDetalle) {
                    $mensaje = 'No se pudo guardar un detalle del inventario físico';
                    $continuar = false;
                    break;
                }
            }

            if (!$continuar && $conexion->inTransaction()) {
                $conexion->rollBack();
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Eliminar detalles que ya no llegaron
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $queryDetallesActuales = "
                SELECT idinventariofisicodetalle
                FROM t_inventariofisicodetalle
                WHERE idinventariofisico = :idinventariofisico
            ";

            $stmtDetallesActuales = $conexion->prepare($queryDetallesActuales);

            $stmtDetallesActuales->execute([
                ':idinventariofisico' => $idinventariofisico
            ]);

            $queryDeleteDetalle = "
                DELETE FROM t_inventariofisicodetalle
                WHERE idinventariofisicodetalle = :idinventariofisicodetalle
                  AND idinventariofisico = :idinventariofisico
            ";

            $stmtDeleteDetalle = $conexion->prepare($queryDeleteDetalle);

            while ($rowDelete = $stmtDetallesActuales->fetch(PDO::FETCH_ASSOC)) {

                $idDetalleActual = (int)$rowDelete['idinventariofisicodetalle'];

                if (!in_array($idDetalleActual, $idsDetalleRecibidos)) {

                    $resultDelete = $stmtDeleteDetalle->execute([
                        ':idinventariofisicodetalle' => $idDetalleActual,
                        ':idinventariofisico' => $idinventariofisico
                    ]);

                    if (!$resultDelete) {
                        $mensaje = 'No se pudo eliminar un detalle del inventario físico';
                        $continuar = false;
                        break;
                    }
                }
            }

            if (!$continuar && $conexion->inTransaction()) {
                $conexion->rollBack();
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar operación
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información general';
        }

    } catch (PDOException $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error de base de datos: ' . $e->getMessage();

    } catch (Exception $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = 'Error general: ' . $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'detalle' => getDetalleInventarioFisico($idinventariofisico, false, $conexion)
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

