$app->get('/inventariosfisico/conteo/{idinventariofisico}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idinventariofisico = $args['idinventariofisico'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    
    $inventariofisicoconteo=array();
    
    
    $detalle=[];
    $resultdetalle = $conexion->query("SELECT
        t_inventariofisicoconteo.idinventariofisicoconteo,
        t_inventariofisicoconteo.serie,
        t_inventariofisicoconteo.codigo,
        t_inventariofisicoconteo.categoria,
        t_inventariofisicoconteo.descripcion,
        t_inventariofisicoconteo.lote,
        CONCAT('[',IFNULL(GROUP_CONCAT(CONCAT('{\"idinventariofisicoconteoimagen\": ',t_inventariofisicoconteoimagen.idinventariofisicoconteoimagen,', \"itemImageSrc\": \"\"}') SEPARATOR ','),''),']') as imagenes
        FROM
        t_inventariofisicoconteo
        LEFT JOIN t_inventariofisicoconteoimagen ON t_inventariofisicoconteo.idinventariofisicoconteo=t_inventariofisicoconteoimagen.idinventariofisicoconteo
        WHERE
        t_inventariofisicoconteo.idinventariofisico=$idinventariofisico
        GROUP BY
        t_inventariofisicoconteo.idinventariofisicoconteo,
        t_inventariofisicoconteo.serie,
        t_inventariofisicoconteo.codigo,
        t_inventariofisicoconteo.categoria,
        t_inventariofisicoconteo.descripcion,
        t_inventariofisicoconteo.lote;;");
    while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
        $detalle[]=array(
            'idinventariofisicoconteo'=>(int)$rowdetalle['idinventariofisicoconteo'],
            'serie'=>$rowdetalle['serie'],
            'codigo'=>$rowdetalle['codigo'],
            'categoria'=>$rowdetalle['categoria'],
            'descripcion'=>$rowdetalle['descripcion'],
            'lote'=>$rowdetalle['lote'],
            'imagenes'=> json_decode($rowdetalle['imagenes'], true)
        );
    }

    
    
    
    $result = $conexion->query("SELECT
        t_inventariofisico.idinventariofisico,
        t_inventariofisico.idalmacen,
        t_almacen.almacen,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.idusuario_conteo,
        t_usuario.nombre as usuario_conteo,
        CONCAT('[',GROUP_CONCAT(CONCAT('{\"idinventariofisicodetalle\": ',t_inventariofisicodetalle.idinventariofisicodetalle,', \"cantidad\": ',IFNULL(cantidad,0),', \"cantidad_real\": ',IFNULL(cantidad_real,0),', \"codigo\": \"',IFNULL(codigo,''),'\"}') SEPARATOR ','),']') as detalleitems
        FROM
        t_inventariofisico
        LEFT JOIN t_almacen ON t_inventariofisico.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_usuario ON t_inventariofisico.idusuario_conteo=t_usuario.idusuario
        LEFT JOIN t_inventariofisicodetalle ON t_inventariofisico.idinventariofisico=t_inventariofisicodetalle.idinventariofisico
        WHERE
        t_inventariofisico.idinventariofisico=$idinventariofisico
        GROUP BY
        t_inventariofisico.idinventariofisico,
        t_inventariofisico.idalmacen,
        t_almacen.almacen,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.idusuario_conteo,
        t_usuario.nombre;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        
        $detalleitems= json_decode($row['detalleitems'], true);
        $pendientes=0;
        $encontrados=0;
        $sobrantes=0;
        $faltantes=0;
        $estado=false;
        for($dd=0;$dd<count($detalleitems);$dd++){
            if($row["fecha_inicio_conteo"]<>''){
                if((float)$detalleitems[$dd]["cantidad"]==(float)$detalleitems[$dd]["cantidad_real"]){
                    $encontrados++;
                    $estado=true;
                }
                if((float)$detalleitems[$dd]["cantidad"]>(float)$detalleitems[$dd]["cantidad_real"]){
                    if($row["fecha_fin_conteo"]<>''){
                        $faltantes++;
                        $estado=true;
                    }else{
                        $pendientes++;
                        $estado=true;
                    }
                }
                if((float)$detalleitems[$dd]["cantidad"]<(float)$detalleitems[$dd]["cantidad_real"]){
                    $sobrantes++;
                    $estado=true;
                }
                if(!$estado){
                    $pendientes++;
                }
            }else{
                $pendientes++;
            }
        }
        
        $inventariofisicoconteo=array(
            'idinventariofisico'=>(int)$row['idinventariofisico'],
            'idalmacen'=>(int)$row['idalmacen'],
            'almacen'=>$row['almacen'],
            'fecha_inicio_conteo'=>$row['fecha_inicio_conteo'],
            'fecha_fin_conteo'=>$row['fecha_fin_conteo'],
            'idusuario_conteo'=>(int)$row['idusuario_conteo'],
            'usuario_conteo'=>$row['usuario_conteo'],
            'encontrados'=>$encontrados,
            'faltantes'=>$faltantes,
            'sobrantes'=>$sobrantes,
            'pendientes'=>$pendientes,
            'detalle'=>$detalle
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'inventariofisicoconteo' => $inventariofisicoconteo
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

