$app->post('/inventariosfisico/conteo/{idinventariofisico}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idinventariofisico = $args['idinventariofisico'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    $idusuario=$decoded_array['idusuario'];
    
    $params = json_decode((string) $request->getBody(),true);
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $stmtVerificar = $conexion->prepare("SELECT idinventariofisicoconteo FROM t_inventariofisicoconteo WHERE idinventariofisico = ? AND serie = ?");
    $stmtVerificar->execute([$idinventariofisico, trim($params['serie'])]);
    $existente = $stmtVerificar->fetch(PDO::FETCH_ASSOC);
    if(!$existente){
        // Insertar nuevo registro
        $stmt = $conexion->prepare("INSERT INTO t_inventariofisicoconteo (idinventariofisico, serie, codigo, categoria, descripcion, lote, idusuario) VALUES (?, ?, ?, ?, ?, ?, ?)");
        $stmt->execute([$idinventariofisico, ltrim($params['serie']), $params['codigo'], $params['categoria'], $params['descripcion'], $params['lote'], $idusuario]);
        $idInventario = $conexion->lastInsertId();

        // Verificar si la serie existe en t_inventariofisicodetalle
        $stmtDetalle = $conexion->prepare("SELECT idinventariofisicodetalle FROM t_inventariofisicodetalle WHERE idinventariofisico = ? AND serie = ?");
        $stmtDetalle->execute([$idinventariofisico, ltrim($params['serie'])]);
        $detalle = $stmtDetalle->fetch(PDO::FETCH_ASSOC);

        $id_detalle=0;
        if ($detalle) {
            // Si existe, actualizar cantidad a 1
            $stmtUpdate = $conexion->prepare("UPDATE t_inventariofisicodetalle SET cantidad_real = 1 WHERE idinventariofisicodetalle = ?");
            $stmtUpdate->execute([$detalle['idinventariofisicodetalle']]);
            $id_detalle=$detalle['idinventariofisicodetalle'];
        }else{
            $stmtInsert = $conexion->prepare("INSERT INTO t_inventariofisicodetalle (idinventariofisico, codigo, serie, categoria, descripcion, lote, cantidad, cantidad_real, embalaje) SELECT idinventariofisico, codigo, serie, categoria, descripcion, lote, 0,1,'UND' FROM t_inventariofisicoconteo WHERE idinventariofisicoconteo = ?");
            $stmtInsert->execute([$idInventario]);
        }
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información General';
    }
    
        
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'id'=>(int)$idInventario,
        'id_detalle'=>$id_detalle
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
