$app->put('/inventariosfisico/conteo/{idinventariofisico}/imagenes', function(Request $request, Response $response, array $args) use ($conexion) {
    $idinventariofisico = $args['idinventariofisico'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idempresa=$decoded_array['idempresa'];
    $idusuario=$decoded_array['idusuario'];
    
    $params = json_decode((string) $request->getBody(),true);
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
        
    $piramideUploader=new PiramideUploader();
    
    $idInventario = intval($params['idinventariofisicoconteo']);
    $folderPath =   folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/inventario_fisico/conteo/imagenes/'.$idInventario;
    if (!file_exists($folderPath)) {
        mkdir($folderPath, 0777, true);
    }

    // Procesar imágenes
    foreach ($params['imagenes'] as $imagen) {
        if (intval($imagen['idinventariofisicoconteoimagen']) !== 0) {
            continue; // Ya insertada
        }

        $base64 = $imagen['itemImageSrc'];

        if (preg_match('/^data:image\/(\w+);base64,/', $base64, $type)) {
            $base64 = substr($base64, strpos($base64, ',') + 1);
            $extension = strtolower($type[1]);
            if (!in_array($extension, ['jpg', 'jpeg', 'png'])) {
                continue; // formato no permitido
            }
        } else {
            continue; // formato inválido
        }

        $base64 = str_replace(' ', '+', $base64);
        $imageData = base64_decode($base64);

        if ($imageData === false) {
            continue; // error al decodificar
        }

        // Generar nombre único
        $imageName = uniqid('img_' . date('Ymd_His') . '_') . '.' . $extension;
        $imagePath = $folderPath . '/' . $imageName;

        // Guardar imagen
        file_put_contents($imagePath, $imageData);

        // Registrar en base de datos
        $stmtImg = $conexion->prepare("INSERT INTO t_inventariofisicoconteoimagen (idinventariofisicoconteo, imagen) VALUES (?, ?)");
        $stmtImg->execute([$idInventario, $imageName]);
    }
        
    
    $codigo=200;
    $status='Exito';
    $mensaje='Se guardo la información General';
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);
