$app->put('/inventariosfisico/conteo/{idinventariofisico}/eliminar', function(Request $request, Response $response, array $args) use ($conexion) {
    $idinventariofisico = $args['idinventariofisico'];
    $params = json_decode((string) $request->getBody(),true);
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';

    $query="";
    if(count($params)>0){
        $idinventariofisicoconteo= implode(",", $params);
        
        $result = $conexion->query("SELECT
            t_inventariofisicodetalle.idinventariofisicodetalle,
            t_inventariofisicodetalle.cantidad
            FROM
            t_inventariofisicoconteo
            LEFT JOIN t_inventariofisicodetalle ON t_inventariofisicoconteo.idinventariofisico=t_inventariofisicodetalle.idinventariofisico AND t_inventariofisicoconteo.serie=t_inventariofisicodetalle.serie
            WHERE
            t_inventariofisicoconteo.idinventariofisicoconteo IN ($idinventariofisicoconteo);");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            if((float)$row["cantidad"]>0){
                $query=$query."UPDATE t_inventariofisicodetalle SET cantidad_real=0 WHERE idinventariofisicodetalle=".$row["idinventariofisicodetalle"].";";
            }else{
                $query=$query."DELETE FROM t_inventariofisicodetalle WHERE idinventariofisicodetalle=".$row["idinventariofisicodetalle"].";";
            }
        }
        
        $query=$query."DELETE FROM t_inventariofisicoconteoimagen WHERE idinventariofisicoconteo IN ($idinventariofisicoconteo);";

        $query=$query."DELETE FROM t_inventariofisicoconteo WHERE idinventariofisico=$idinventariofisico AND idinventariofisicoconteo IN ($idinventariofisicoconteo);";

        $result = $conexion->exec($query);

        if($result===false){

        }else{
            $codigo=200;
            $status='Exito';
            $mensaje='Se guardo la información correctamente';
        }
    }else{
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la información correctamente';
    }
        
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

