$app->get('/inventariosfisico/conteo/{idinventariofisico}/series', function(Request $request, Response $response, array $args) use ($conexion) {
    $idinventariofisico = $args['idinventariofisico'];
    $items=[];
    $result = $conexion->query("SELECT
        t_inventariofisicodetalle.codigo,
        t_inventariofisicodetalle.serie,
        t_inventariofisicodetalle.categoria,
        t_inventariofisicodetalle.descripcion,
        t_inventariofisicodetalle.lote
        FROM
        t_inventariofisico
        LEFT JOIN t_inventariofisico as tmp_inventariofisico_general ON t_inventariofisico.idcliente=tmp_inventariofisico_general.idcliente AND t_inventariofisico.fecha=tmp_inventariofisico_general.fecha AND tmp_inventariofisico_general.deleted_at IS NULL
        LEFT JOIN t_inventariofisicodetalle ON tmp_inventariofisico_general.idinventariofisico=t_inventariofisicodetalle.idinventariofisico
        WHERE
        t_inventariofisico.idinventariofisico=$idinventariofisico
        AND IFNULL(t_inventariofisicodetalle.serie,'')<>''
        AND t_inventariofisico.deleted_at IS NULL;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $items[]=array(
            'codigo'=>$row['codigo'],
            'serie'=>$row['serie'],
            'categoria'=>$row['categoria'],
            'descripcion'=>$row['descripcion'],
            'lote'=>$row['lote']
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'items' => $items
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/inventariosfisico/reporte/{idcliente}/{fechainicial}/{fechafinal}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fechainicial = $args['fechainicial'];
    $fechafinal = $args['fechafinal'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    
    $codigo=400;
    $status='Error';
    $mensaje='Ocurrio un problema, intentelo mas tarde';
    
    $filtrocliente='';
    if((int)$idcliente>0){
        $filtrocliente=" AND t_inventariofisico.idcliente=$idcliente";
    }
    
    $inventariosfisico=[];
    
    $result = $conexion->query("SELECT
        t_inventariofisico.idinventariofisico,
        t_cliente.cliente,
        t_inventariofisico.fecha,
        t_status.status,
        t_inventariofisico.categoria,
        CONCAT('[',IFNULL(GROUP_CONCAT(CONCAT('{\"idinventariofisicodetalle\": ',t_inventariofisicodetalle.idinventariofisicodetalle,', \"cantidad\": ',IFNULL(t_inventariofisicodetalle.cantidad,0),', \"cantidad_real\": ',IFNULL(t_inventariofisicodetalle.cantidad_real,0),', \"codigo\": \"',IFNULL(t_inventariofisicodetalle.codigo,''),'\", \"serie\": \"',IFNULL(t_inventariofisicodetalle.serie,''),'\", \"descripcion\": \"',REPLACE(IFNULL(t_inventariofisicodetalle.descripcion,''),'\"',' '),'\", \"ubicacion\": \"',IFNULL(t_inventariofisicodetalle.ubicacion,''),'\", \"embalaje\": \"',IFNULL(t_inventariofisicodetalle.embalaje,''),'\", \"diferencia_cantidad\": ',IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0),', \"diferencia_porcentaje\": ',IF(IFNULL(t_inventariofisicodetalle.cantidad,0)>0,(1-ABS((IFNULL(t_inventariofisicodetalle.cantidad,0)-IFNULL(t_inventariofisicodetalle.cantidad_real,0))/IFNULL(t_inventariofisicodetalle.cantidad,0)))*100,0),'}') SEPARATOR ','),''),']') as detalle,
        t_asignado.nombre as asignado,
        t_apoyo.nombre as apoyo,
        t_inventariofisico.fecha_inicio,
        t_inventariofisico.fecha_fin
        FROM
        t_inventariofisico
        LEFT JOIN t_cliente ON t_inventariofisico.idcliente=t_cliente.idcliente
        LEFT JOIN t_inventariofisicodetalle ON t_inventariofisico.idinventariofisico=t_inventariofisicodetalle.idinventariofisico
        LEFT JOIN t_usuario as t_asignado ON t_inventariofisico.idasignado=t_asignado.idusuario
        LEFT JOIN t_usuario as t_apoyo ON t_inventariofisico.idapoyo=t_apoyo.idusuario
        LEFT JOIN t_status ON t_inventariofisico.idstatus=t_status.idstatus
        WHERE
        t_inventariofisico.idalmacen=".$decoded_array['idalmacen']."
        AND CAST(t_inventariofisico.fecha as DATE) BETWEEN '$fechainicial' AND '$fechafinal'
        AND t_inventariofisico.deleted_at IS NULL
        $filtrocliente
        GROUP BY
        t_inventariofisico.idinventariofisico,
        t_cliente.cliente,
        t_inventariofisico.fecha,
        t_asignado.nombre,
        t_apoyo.nombre,
        t_inventariofisico.fecha_inicio,
        t_inventariofisico.fecha_fin;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $inventariosfisico[]=array(
            'idinventariofisico'=>(int)$row['idinventariofisico'],
            'fecha'=>$row['fecha'],
            'status'=>$row['status'],
            'categoria'=>$row['categoria'],
            'cliente'=>$row['cliente'],
            'detalle'=> json_decode($row["detalle"], true),
            'asignado'=>$row['asignado'],
            'apoyo'=>$row['apoyo'],
            'fecha_inicio'=>$row['fecha_inicio'],
            'fecha_fin'=>$row['fecha_fin']
        );
    }
    
    for($if=0;$if<count($inventariosfisico);$if++){
        $diferencia=false;
        $cantidad_total=0;
        for($dd=0;$dd<count($inventariosfisico[$if]["detalle"]);$dd++){
            $cantidad_total=$cantidad_total+(float)$inventariosfisico[$if]["detalle"][$dd]["cantidad"];
            if($inventariosfisico[$if]["detalle"][$dd]["cantidad"]<>$inventariosfisico[$if]["detalle"][$dd]["cantidad_real"]){
                $diferencia=true;
            }
        }
        $inventariosfisico[$if]["cantidad_total"]=$cantidad_total;
        $inventariosfisico[$if]["diferencia"]=$diferencia;
        $inventariosfisico[$if]["diferencia_texto"] = $inventariosfisico[$if]["diferencia"] ? "Si" : "No";
    }
    
    $resultado=array(
