$app->post('/timbrado', function(Request $request, Response $response, array $args) use ($conexion) {
    $params = json_decode((string) $request->getBody(),true);
    //$token = $app->request->headers->get('Authorization');
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    
    $idcliente=$params["idcliente"];

    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $result = $conexion->query("SELECT idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idclientenum= $row["idcliente"];
    }
    
    if((int)$idclientenum==0){
        $mensaje='El cliente no existe';
    }else{
        $query="insert into t_timbrado (idcliente,                  created_at) 
                                VALUES ($idclientenum,              CURRENT_TIMESTAMP());
                SELECT LAST_INSERT_ID() INTO @idtimbrado_nuevo;";


        $result = $conexion->exec($query);
        if($result){

            $result = $conexion->query("SELECT @idtimbrado_nuevo as idtimbrado;");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $idtimbrado=$row['idtimbrado'];
            }

            $codigo=200;
            $status='Exito';
            $mensaje='Se guardo la información Correctamente';
        }
    }
    
        

    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'idtimbrado'=>$idtimbrado
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

