                        a.mojadas=b.mojadas,
                        a.lote_mojadas=b.lote_mojadas,
                        a.mermadas=b.mermadas,
                        a.lote_mermadas=b.lote_mermadas,
                        a.tapa_extra=b.tapa_extra,
                        a.lote_tapa_extra=b.lote_tapa_extra,
                        a.legales_extra_portugues=b.legales_extra_portugues,
                        a.lote_legales_extra=b.lote_legales_extra,
                        a.caja_extra=b.caja_extra,
                        a.lote_caja_extra=b.lote_caja_extra,
                        a.sarro_leve=b.sarro_leve,
                        a.lote_sarro_leve=b.lote_sarro_leve,
                        a.sarro_severo=b.sarro_severo,
                        a.lote_sarro_severo=b.lote_sarro_severo,
                        a.edited_at=CURRENT_TIMESTAMP()
                        WHERE
                        b.id_temporal=@id_temporal;";
                    
                    
                    $result = $conexion->exec($query);
                    if($result){
                        $codigo=200;
                        $status='Exito';
                        $mensaje='Se guardo la información Correctamente';
                    }
                }
            }
        }

    }
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje,
        'mensajes_error' => $mensajes_error,
        'xls_data'=>$xls_data,
        'values'=>$values,
        'query_crear'=>$query_crear_tmp,
        'query_insert'=>$query_insert_tmp,
        'quert_final'=>$query
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/ate-gas/cargamasiva', function(Request $request, Response $response, array $args) use ($conexion, $archivosmasivo) {

    $codigo = 400;
    $status = 'Error';
    $mensaje = 'El archivo no se subió, intente más tarde';

    $xls_data = [];
    $mensajes_error = [];
    $nuevosdatos = [];

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'];

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idempresa = $decoded_array["idempresa"] ?? null;
        $idalmacen = $decoded_array["idalmacen"] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros del formulario
        |--------------------------------------------------------------------------
        */
        $bodyParams = $request->getParsedBody();

        if (!is_array($bodyParams)) {
            $bodyParams = [];
        }

        $idclienteHash = $bodyParams['idcliente'] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if (empty($idempresa)) {
            $mensaje = 'No se recibió la empresa';
            $continuar = false;
        }

        if ($continuar && empty($idalmacen)) {
            $mensaje = 'No se recibió el almacén';
            $continuar = false;
        }

        if ($continuar && empty($idclienteHash)) {
            $mensaje = 'No se recibió el cliente';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Buscar cliente por hash
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idclientenum = 0;

            $queryCliente = "
                SELECT idcliente
                FROM t_cliente
                WHERE MD5(idcliente) = :idcliente_hash
                LIMIT 1
            ";

            $stmtCliente = $conexion->prepare($queryCliente);

            $stmtCliente->execute([
                ':idcliente_hash' => $idclienteHash
            ]);

            $rowCliente = $stmtCliente->fetch(PDO::FETCH_ASSOC);

            if ($rowCliente) {
                $idclientenum = (int)$rowCliente["idcliente"];
            }

            if ($idclientenum <= 0) {
                $mensaje = 'No se encontró el cliente';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $files = $_FILES['uploads'] ?? null;

            $totalArchivos = (
                isset($files['name']) &&
                is_array($files['name'])
            ) ? count($files['name']) : 0;

            if ($totalArchivos === 0) {
                $mensaje = 'Debe adjuntar un archivo';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Subir archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if (($files['error'][0] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
                $mensaje = 'Ocurrió un problema al subir el archivo';
                $continuar = false;
            }
        }

        if ($continuar) {

            $nombreOriginal = $files["name"][0] ?? '';

            if (trim($nombreOriginal) === '') {
                $mensaje = 'El archivo no tiene nombre válido';
                $continuar = false;
            }
        }

        if ($continuar) {

            $nombredoc = $idclientenum . "_" . date("Y_m_d_H_i_s") . "_" . $nombreOriginal;

            $creacion = new Carpetas();
            $respuesta = $creacion->procesarCarpeta($idempresa);

            $piramideUploader = new PiramideUploader();

            $upload = $piramideUploader->upload(
                $nombredoc,
                'uploads',
                folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/ate_gas/masivo',
                $archivosmasivo,
                true
            );

            $file = $piramideUploader->getInfoFile();
            $file_name = $file['complete_name'] ?? '';

            if (!isset($upload) || empty($upload['uploaded'])) {
                $mensaje = $upload['error'] ?? 'No se pudo subir el archivo';
                $continuar = false;
            }

            if ($continuar && trim($file_name) === '') {
                $mensaje = 'No se pudo obtener el nombre del archivo subido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Leer Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $inputFileName = folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/ate_gas/masivo/' . $file_name;

            if (!file_exists($inputFileName)) {
                $mensaje = 'No se encontró el archivo subido';
                $continuar = false;
            }
        }

        if ($continuar) {

            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();

            $highestRow = $sheet->getHighestRow();
            $highestColumn = $sheet->getHighestColumn();

            if ($highestRow < 2) {
                $mensaje = 'El archivo no tiene datos para procesar';
                $continuar = false;
            }
        }

        if ($continuar) {

            $xls_data = $sheet->rangeToArray(
                'A2:' . $highestColumn . $highestRow,
                '',
                true,
                true
            );

            $keys = [
                "sede",
                "tipo",
                "chasis",
                "marca",
                "modelo",
                "color",
                "cliente",
                "canal",
                "configuracion",
                "tipo_tanque",
                "tipo_ot",
                "valor_neto",
                "pedido_ot",
                "fecha_ot",
                "prog_envio",
            ];

            $datos_excel = [];

            foreach ($xls_data as $index => $item) {

                /*
                Eliminar filas totalmente vacías.
                */
                $filaVacia = true;

                foreach ($item as $valorCelda) {
                    if (trim((string)$valorCelda) !== '') {
                        $filaVacia = false;
                        break;
                    }
                }

                if ($filaVacia) {
                    continue;
                }

                /*
                Normalizar cantidad de columnas.
                Si vienen menos columnas, se rellenan.
                Si vienen más columnas, se cortan.
                */
                $item = array_slice($item, 0, count($keys));
                $item = array_pad($item, count($keys), '');

                $datos_excel[] = array_combine($keys, $item);
            }

            if (count($datos_excel) === 0) {
                $mensaje = 'El archivo no contiene filas válidas';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar datos del Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $queryExisteChasis = "
                SELECT idate_gas
                FROM t_ate_gas
                WHERE chasis = :chasis
                  AND idcliente = :idcliente
                  AND idalmacen = :idalmacen
                  AND deleted_at IS NULL
                  AND fecha_salida IS NULL
                LIMIT 1
            ";

            $stmtExisteChasis = $conexion->prepare($queryExisteChasis);

            $chasisEnArchivo = [];

            foreach ($datos_excel as $xls => $fila) {

                $numeroFilaExcel = $xls + 2;
                $chasis = strtoupper(trim((string)($fila["chasis"] ?? '')));

                $datos_excel[$xls]["chasis"] = $chasis;

                $fechaOtOriginal = $fila["fecha_ot"] ?? '';
                $fechaOt = normalizarFechaExcel($fechaOtOriginal);

                if (
                    $fechaOtOriginal === null ||
                    trim((string)$fechaOtOriginal) === ''
                ) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Fecha OT es obligatoria'
                    ];
                } elseif ($fechaOt === null) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Fecha OT no es una fecha válida'
                    ];
                } else {
                    /*
                    Se reemplaza el valor original por el formato de la base de datos.
                    */
                    $datos_excel[$xls]["fecha_ot"] = $fechaOt;
                }

                /*
                |--------------------------------------------------------------------------
                | Validar prog_envio
                |--------------------------------------------------------------------------
                |
                | No es obligatoria, pero si tiene valor debe ser una fecha válida.
                |
                */
                $progEnvioOriginal = $fila["prog_envio"] ?? '';

                if (
                    $progEnvioOriginal === null ||
                    trim((string)$progEnvioOriginal) === ''
                ) {
                    /*
                    Para que PDO inserte NULL y no una cadena vacía.
                    */
                    $datos_excel[$xls]["prog_envio"] = null;
                } else {

                    $progEnvio = normalizarFechaExcel($progEnvioOriginal);

                    if ($progEnvio === null) {
                        $mensajes_error[] = [
                            'fila' => $numeroFilaExcel,
                            'mensaje' => 'Programación de envío no es una fecha válida'
                        ];
                    } else {
                        $datos_excel[$xls]["prog_envio"] = $progEnvio;
                    }
                }

                if ($chasis === '') {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Chasis es obligatorio'
                    ];
                    continue;
                }

                if (strlen($chasis) !== 17) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Chasis debe tener 17 caracteres'
                    ];
                    continue;
                }

                if (preg_match('/[IOQ]/', $chasis)) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis no puede contener I, O o Q'
                    ];
                    continue;
                }

                if (in_array($chasis, $chasisEnArchivo)) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis está duplicado en el archivo'
                    ];
                    continue;
                }

                $chasisEnArchivo[] = $chasis;

                $stmtExisteChasis->execute([
                    ':chasis' => $chasis,
                    ':idcliente' => $idclientenum,
                    ':idalmacen' => $idalmacen
                ]);

                $rowExiste = $stmtExisteChasis->fetch(PDO::FETCH_ASSOC);

                if ($rowExiste) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis ya existe en la base de datos'
                    ];
                }
            }

            if (count($mensajes_error) > 0) {
                $mensaje = 'El archivo contiene errores';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Insertar datos
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            $queryInsert = "
                INSERT INTO t_ate_gas (
                    idalmacen,
                    idcliente,
                    sede,
                    tipo,
                    chasis,
                    marca,
                    modelo,
                    color,
                    cliente,
                    canal,
                    configuracion,
                    tipo_tanque,
                    tipo_ot,
                    valor_neto,
                    pedido_ot,
                    fecha_ot,
                    prog_envio,
                    created_at
                ) VALUES (
                    :idalmacen,
                    :idcliente,
                    :sede,
                    :tipo,
                    :chasis,
                    :marca,
                    :modelo,
                    :color,
                    :cliente,
                    :canal,
                    :configuracion,
                    :tipo_tanque,
                    :tipo_ot,
                    :valor_neto,
                    :pedido_ot,
                    :fecha_ot,
                    :prog_envio,
                    CURRENT_TIMESTAMP()
                )
            ";

            $stmtInsert = $conexion->prepare($queryInsert);

            foreach ($datos_excel as $fila) {

                $resultInsert = $stmtInsert->execute([
                    ':idalmacen' => $idalmacen,
                    ':idcliente' => $idclientenum,
                    ':sede' => $fila["sede"] ?? '',
                    ':tipo' => $fila["tipo"] ?? '',
                    ':chasis' => $fila["chasis"] ?? '',
                    ':marca' => $fila["marca"] ?? '',
                    ':modelo' => $fila["modelo"] ?? '',
                    ':color' => $fila["color"] ?? '',
                    ':cliente' => $fila["cliente"] ?? '',
                    ':canal' => $fila["canal"] ?? '',
                    ':configuracion' => $fila["configuracion"] ?? '',
                    ':tipo_tanque' => $fila["tipo_tanque"] ?? '',
                    ':tipo_ot' => $fila["tipo_ot"] ?? '',
                    ':valor_neto' => $fila["valor_neto"] ?? '',
                    ':pedido_ot' => $fila["pedido_ot"] ?? '',
                    ':fecha_ot' => $fila["fecha_ot"] ?? '',
                    ':prog_envio' => $fila["prog_envio"] ?? ''
                ]);

                if (!$resultInsert) {
                    $mensaje = 'No se pudo insertar una fila del archivo';
                    $continuar = false;
                    break;
                }
            }

            if (!$continuar) {
                if ($conexion->inTransaction()) {
                    $conexion->rollBack();
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar operación
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información correctamente';
        }

    } catch (Throwable $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'mensajes_error' => $mensajes_error
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

$app->get('/ate-gas', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $ategas=[];
    $result = $conexion->query("SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idalmacen,
        t_ate_gas.idcliente,
        t_cliente.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.created_at,
        t_ate_gas.fecha_recepcion,
        IF(t_ate_gas.fecha_recepcion IS NULL, 'Pendiente', 'Recepción') as estado_recepcion,
        IF(t_ate_gas.fecha_recepcion IS NULL, 'Pendiente', 'Completo') as estado_inventario,
        t_ate_gas_ubicacion.idalmacendetalle,
        t_almacendetalle.nombre as ubicacion
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        AND t_ate_gas.fecha_salida IS NULL
        ORDER BY
        t_ate_gas.created_at DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $ategas[]=array(
            'idate_gas'=>(int)$row['idate_gas'],
            'idalmacen'=>(int)$row['idalmacen'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'created_at'=>$row['created_at'],
            'fecha_recepcion'=>$row['fecha_recepcion'],
            'estado_recepcion'=>$row['estado_recepcion'],
            'estado_inventario'=>$row['estado_inventario'],
            'idalmacendetalle'=>$row['idalmacendetalle'],
            'ubicacion'=>$row['ubicacion'],
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'ategas'=>$ategas
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->put('/ate-gas/recepcionar/{idate_gas}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas = $args['idate_gas'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $params = json_decode((string) $request->getBody(),true);
    
    $query="UPDATE t_ate_gas SET estado_vehiculo=:estado_vehiculo, observaciones=:observaciones, fecha_recepcion=CURRENT_TIMESTAMP(), edited_at=CURRENT_TIMESTAMP() WHERE idate_gas=:idate_gas;";
    $stmt = $conexion->prepare($query);
    $stmt->bindParam(':estado_vehiculo', $params['estado_vehiculo']);
    $stmt->bindParam(':observaciones', $params['observaciones']);
    $stmt->bindParam(':idate_gas', $idate_gas);

    $stmt->execute();

    if ($stmt) {
        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la informacion correctamente';
    } else {
        //echo "Error al actualizar el registro.";
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->put('/ate-gas/ubicar/{idate_gas}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas = $args['idate_gas'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $params = json_decode((string) $request->getBody(),true);
    
    try {
        $conexion->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $conexion->beginTransaction();

        // Query 1
        $sql1 = "UPDATE t_ate_gas_ubicacion SET fecha_salida = CURRENT_TIMESTAMP() WHERE idate_gas = :idate_gas AND fecha_salida IS NULL";
        $st1  = $conexion->prepare($sql1);
        $st1->execute(array(
            ':idate_gas' => $idate_gas,
        ));

        // Query 2
        $sql2 = "INSERT INTO t_ate_gas_ubicacion (idate_gas, idalmacendetalle, fecha_ingreso) VALUES (:idate_gas, :idalmacendetalle, CURRENT_TIMESTAMP())";
        $st2  = $conexion->prepare($sql2);
        $st2->execute(array(
            ':idate_gas' => $idate_gas,
            ':idalmacendetalle'   => $params['idalmacendetalle']
        ));

        $conexion->commit();

        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la informacion correctamente';

    } catch (Exception $e) {
        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }
        //throw $e; // o maneja el error como prefieras
    }


    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
