$app->get('/ate-gas/asignacion-trabajo', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $asignaciontrabajo=[];
    $result = $conexion->query("WITH tmp_ate_gas_etapa_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL AND t_ate_gas.fecha_salida IS NULL
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa_anterior_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL AND t_ate_gas.fecha_salida IS NULL
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        AND t_ate_gas_etapa.idetapa IS NOT NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa as (
        SELECT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.idestado_etapa
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        WHERE
        t_ate_gas_etapa.idestado_etapa<>4
        ), tmp_ate_gas_etapa_anterior as (
        SELECT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.idestado_etapa
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_anterior_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_anterior_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_anterior_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        ), tmp_ate_gas_etapa_tecnico as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico', t_ate_gas_etapa_tecnico.idate_gas_etapa_tecnico,
                'idusuario', t_ate_gas_etapa_tecnico.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos
        FROM 
        t_ate_gas_etapa_tecnico
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        ), tmp_ate_gas_etapa_tecnico_qa as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico_qa', t_ate_gas_etapa_tecnico_qa.idate_gas_etapa_tecnico_qa,
                'idusuario', t_ate_gas_etapa_tecnico_qa.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos_qa
        FROM 
        t_ate_gas_etapa_tecnico_qa
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico_qa.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico_qa.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico_qa.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        )
        SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idcliente,
        t_cliente.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.created_at,
        IFNULL(tmp_ate_gas_etapa.etapa,tmp_ate_gas_etapa_anterior.etapa) as etapa,
        IFNULL(tmp_ate_gas_etapa.severity,tmp_ate_gas_etapa_anterior.severity) as severity,
        t_almacendetalle.nombre as ubicacion,
        tmp_ate_gas_etapa.idestado_etapa,
        IFNULL(tmp_ate_gas_etapa_tecnico.tecnicos,'[]') as tecnicos,
        IFNULL(tmp_ate_gas_etapa_tecnico_qa.tecnicos_qa,'[]') as tecnicos_qa
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_ate_gas_etapa ON t_ate_gas.idate_gas=tmp_ate_gas_etapa.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_anterior ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_anterior.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_tecnico ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico.idate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tecnico_qa ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico_qa.idate_gas_etapa
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        AND t_ate_gas.fecha_recepcion IS NOT NULL
        AND t_ate_gas.fecha_salida IS NULL
        ORDER BY
        t_ate_gas.created_at DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $asignaciontrabajo[]=array(
            'idate_gas'=>(int)$row['idate_gas'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'etapa'=>$row['etapa'],
            'severity'=>$row['severity'],
            'ubicacion'=>$row['ubicacion'],
            'idestado_etapa'=>(int)$row['idestado_etapa'],
            'tecnicos'=> json_decode($row['tecnicos'],true),
            'tecnicos_qa'=> json_decode($row['tecnicos_qa'],true),
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'asignaciontrabajo'=>$asignaciontrabajo
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

