                          VALUES (:idate_gas, :paso, 1, CURRENT_TIMESTAMP())";
                $stmt = $conexion->prepare($query);
                $stmt->bindParam(':idate_gas', $idate_gas[$ag]);
                $stmt->bindParam(':paso', $paso_insert);
                $stmt->execute();

                // Obtener ID generado
                $idate_gas_etapa = (int) $conexion->lastInsertId();

            }

            $tecnicos_actuales=array();
            $result = $conexion->query("select idusuario FROM t_ate_gas_etapa_tecnico_qa WHERE idate_gas_etapa=$idate_gas_etapa AND deleted_at IS NULL;");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                array_push($tecnicos_actuales, (int)$row["idusuario"]);
            }

            $tecnicos_insert=array();
            for($tt=0;$tt<count($params['idusuario']);$tt++){
                $indice=array_search($params['idusuario'][$tt],$tecnicos_actuales);
                if(!is_numeric($indice)){
                    array_push($tecnicos_insert, $params['idusuario'][$tt]);
                }
            }

            $tecnicos_delete=array();
            for($ta=0;$ta<count($tecnicos_actuales);$ta++){
                $indice=array_search($tecnicos_actuales[$ta],$params['idusuario']);
                if(!is_numeric($indice)){
                    array_push($tecnicos_delete, $tecnicos_actuales[$ta]);
                }
            }

            if(count($tecnicos_insert)>0){
                $queryDetalle = "INSERT INTO t_ate_gas_etapa_tecnico_qa (idate_gas_etapa,  idusuario,  created_at)
                                                                 VALUES (:idate_gas_etapa, :idusuario, CURRENT_TIMESTAMP())";
                $stmtDetalle = $conexion->prepare($queryDetalle);

                foreach ($tecnicos_insert as $detalle) {
                    $stmtDetalle->bindParam(':idate_gas_etapa', $idate_gas_etapa, PDO::PARAM_INT);
                    $stmtDetalle->bindParam(':idusuario', $detalle);
                    $stmtDetalle->execute();
                }
            }

            if(count($tecnicos_delete)>0){
                $queryDetalle2 = "UPDATE t_ate_gas_etapa_tecnico_qa
                    SET deleted_at = CURRENT_TIMESTAMP()
                    WHERE idate_gas_etapa = :idate_gas_etapa AND idusuario=:idusuario";

                $stmtDetalle2 = $conexion->prepare($queryDetalle2);

                foreach ($tecnicos_delete as $idDetalle) {
                    $stmtDetalle2->bindParam(':idate_gas_etapa', $idate_gas_etapa, PDO::PARAM_INT);
                    $stmtDetalle2->bindParam(':idusuario', $idDetalle);
                    $stmtDetalle2->execute();
                }
            }
        }
        // Obtener tablaid enviado


        // Confirmar transacción
        $conexion->commit();

        $codigo  = 200;
        $status  = 'Éxito';
        $mensaje = 'La información se guardó correctamente';

    } catch (Exception $e) {

        // Rollback seguro
        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        //$codigo  = 500;
        //$status  = 'Error';
        $mensaje = 'Ocurrió un error: ' . $e->getMessage();
    }
    

    $response->getBody()->write(json_encode(array(
        'estado' => $status,
        'codigo' => $codigo,
        'mensaje' => $mensaje,
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

