$app->get('/ate-gas/gestion-movimiento', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];
    $idusuario=$decoded_array["idusuario"];
    $idtipousuario=$decoded_array["idtipousuario"];
    
    $condicion="=$idusuario";
    if((int)$idtipousuario==1){
        $condicion=" IS NOT NULL";
    }

    $gestionmovimientos=[];
    $result = $conexion->query("WITH tmp_ate_gas_etapa_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL AND t_ate_gas.fecha_salida IS NULL
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa as (
        SELECT
        DISTINCT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_ate_gas_etapa.idetapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.observaciones_inventario,
        t_ate_gas_etapa.fecha_inventario,
        t_ate_gas_etapa.idestado_etapa,
        t_estado_etapa.estado_etapa
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        LEFT JOIN t_estado_etapa ON t_ate_gas_etapa.idestado_etapa=t_estado_etapa.idestado_etapa
        INNER JOIN t_ate_gas_etapa_tecnico ON t_ate_gas_etapa.idate_gas_etapa=t_ate_gas_etapa_tecnico.idate_gas_etapa AND t_ate_gas_etapa_tecnico.idusuario$condicion AND t_ate_gas_etapa_tecnico.deleted_at IS NULL
        WHERE
        t_ate_gas_etapa.idestado_etapa<>4
        ), tmp_ate_gas_etapa_tecnico as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico', t_ate_gas_etapa_tecnico.idate_gas_etapa_tecnico,
                'idusuario', t_ate_gas_etapa_tecnico.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos
        FROM 
        t_ate_gas_etapa_tecnico
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico.deleted_at IS NULL
        
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        ), tmp_ate_gas_etapa_tecnico_qa as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico_qa', t_ate_gas_etapa_tecnico_qa.idate_gas_etapa_tecnico_qa,
                'idusuario', t_ate_gas_etapa_tecnico_qa.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos_qa
        FROM 
        t_ate_gas_etapa_tecnico_qa
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico_qa.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico_qa.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico_qa.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        ), tmp_ate_gas_etapa_tiempos as (
        SELECT 
        t_ate_gas_etapa_tiempos.idate_gas_etapa,
        MIN(t_ate_gas_etapa_tiempos.inicio) as inicio,
        SUM(TIMESTAMPDIFF(SECOND, t_ate_gas_etapa_tiempos.inicio, IFNULL(t_ate_gas_etapa_tiempos.fin,CURRENT_TIMESTAMP()))) as tiempo
        FROM 
        t_ate_gas_etapa_tiempos
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tiempos.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        WHERE
        t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_tiempos.idate_gas_etapa
        )
        SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idalmacen,
        t_ate_gas.idcliente,
        t_cliente.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.created_at,
        tmp_ate_gas_etapa.idate_gas_etapa,
        tmp_ate_gas_etapa.idetapa,
        tmp_ate_gas_etapa.etapa,
        tmp_ate_gas_etapa.severity,
        t_ate_gas_ubicacion.idalmacendetalle,
        t_almacendetalle.nombre as ubicacion,
        tmp_ate_gas_etapa.observaciones_inventario,
        tmp_ate_gas_etapa.fecha_inventario,
        tmp_ate_gas_etapa.idestado_etapa,
        tmp_ate_gas_etapa.estado_etapa,
        tmp_ate_gas_etapa_tiempos.inicio,
        tmp_ate_gas_etapa_tiempos.tiempo,
        IFNULL(tmp_ate_gas_etapa_tecnico.tecnicos,'[]') as tecnicos,
        IFNULL(tmp_ate_gas_etapa_tecnico_qa.tecnicos_qa,'[]') as tecnicos_qa
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas.idate_gas=tmp_ate_gas_etapa.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_tecnico ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico.idate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tecnico_qa ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico_qa.idate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tiempos.idate_gas_etapa
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        AND t_ate_gas.fecha_recepcion IS NOT NULL
        AND t_ate_gas.fecha_salida IS NULL
        ORDER BY
        t_ate_gas.created_at DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $gestionmovimientos[]=array(
            'idate_gas'=>(int)$row['idate_gas'],
            'idalmacen'=>(int)$row['idalmacen'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'idate_gas_etapa'=>(int)$row['idate_gas_etapa'],
            'idetapa'=>$row['idetapa'],
            'etapa'=>$row['etapa'],
            'severity'=>$row['severity'],
            'idalmacendetalle'=>$row['idalmacendetalle'],
            'ubicacion'=>$row['ubicacion'],
            'observaciones_inventario'=>$row['observaciones_inventario'],
            'fecha_inventario'=>$row['fecha_inventario'],
            'idestado_etapa'=>$row['idestado_etapa'],
            'estado_etapa'=>$row['estado_etapa'],
            'inicio'=>$row['inicio'],
            'tiempo'=>$row['tiempo'],
            'tecnicos'=> json_decode($row['tecnicos'],true),
            'tecnicos_qa'=> json_decode($row['tecnicos_qa'],true),
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'gestionmovimientos'=>$gestionmovimientos
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->put('/ate-gas/gestion-movimiento/vista/{idate_gas_etapa}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas_etapa = $args['idate_gas_etapa'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];
    $idusuario=$decoded_array["idusuario"];
    $idtipousuario=$decoded_array["idtipousuario"];
    
    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    
    $params = json_decode((string) $request->getBody(),true);
    
    $idalmacendetalle=$params['idalmacendetalle'];
    $idetapa=$params['idetapa'];

    try {
        $conexion->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        $conexion->beginTransaction();

        // Query 1
        $sql1 = "UPDATE t_ate_gas_ubicacion a
            INNER JOIN t_ate_gas_etapa b ON a.idate_gas=b.idate_gas
            SET a.fecha_salida = CURRENT_TIMESTAMP() 
            WHERE 
            b.idate_gas_etapa = :idate_gas_etapa 
            AND a.fecha_salida IS NULL";
        $st1  = $conexion->prepare($sql1);
        $st1->execute(array(
            ':idate_gas_etapa' => $idate_gas_etapa,
        ));

        // Query 2
        $sql2 = "INSERT INTO t_ate_gas_ubicacion (idate_gas, idate_gas_etapa, idalmacendetalle, fecha_ingreso) SELECT idate_gas, idate_gas_etapa, :idalmacendetalle, CURRENT_TIMESTAMP() FROM t_ate_gas_etapa WHERE idate_gas_etapa=:idate_gas_etapa";
        $st2  = $conexion->prepare($sql2);
        $st2->execute(array(
            ':idalmacendetalle'   => $params['idalmacendetalle'],
            ':idate_gas_etapa'   => $idate_gas_etapa,
        ));

        // Query 3
        $sql3 = "UPDATE t_ate_gas_etapa SET 
            idetapa=:idetapa, 
            edited_at=CURRENT_TIMESTAMP() 
            WHERE idate_gas_etapa=:idate_gas_etapa;";
        $st3  = $conexion->prepare($sql3);
        $st3->execute(array(
            ':idetapa'   => $params['idetapa'],
            ':idate_gas_etapa'   => $idate_gas_etapa,
        ));

        $conexion->commit();

        $codigo=200;
        $status='Exito';
        $mensaje='Se guardo la informacion correctamente';

    } catch (Exception $e) {
        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }
        //throw $e; // o maneja el error como prefieras
    }

    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
    $response->getBody()->write(json_encode($resultado));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/ate-gas/gestion-movimiento/inventario/{idate_gas_etapa}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas_etapa = $args['idate_gas_etapa'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;

    
    $inventario=[];
    $azureBlobInventario = (defined('azure_blob_enabled') && azure_blob_enabled) ? new BlobStorageService() : null;
    $result = $conexion->query("SELECT
        t_danios_vehiculos.iddanios_vehiculos,
        t_danios_vehiculos.danios_vehiculos,
        IF(t_ate_gas_etapa_inventario.idate_gas_etapa_inventario IS NULL,0,1) as marcado,
        t_ate_gas_etapa_inventario.descripcion
        FROM
        t_danios_vehiculos
        LEFT JOIN t_ate_gas_etapa_inventario ON t_danios_vehiculos.iddanios_vehiculos=t_ate_gas_etapa_inventario.iddanios_vehiculos AND $idate_gas_etapa=t_ate_gas_etapa_inventario.idate_gas_etapa AND t_ate_gas_etapa_inventario.deleted_at IS NULL;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $imagenes=[];
        $resultimagenes = $conexion->query("SELECT
            ubicacion_thumb
            FROM
            t_ate_gas_etapa_inventario_imagen
            WHERE
            idate_gas_etapa=$idate_gas_etapa
            AND deleted_at IS NULL
            AND iddanios_vehiculos='".$row['iddanios_vehiculos']."';");
        while ($rowimagenes =  $resultimagenes ->fetch(PDO::FETCH_ASSOC)){
            $fileBase64 = null;
            $thumbKey   = str_replace('\\', '/', $rowimagenes['ubicacion_thumb']);
            if ($azureBlobInventario !== null) {
                try {
                    $blob = $azureBlobInventario->getBlob($thumbKey);
                    if ($blob !== null) {
                        $fileBase64 = 'data:' . $blob['contentType'] . ';base64,' . base64_encode($blob['content']);
                    }
                } catch (Throwable $e) {
                    error_log('[AzureBlob] getBlob inventario blob=' . $thumbKey . ' err=' . $e->getMessage());
                }
            }
            // Fallback a disco local para imágenes anteriores a la migración
            if ($fileBase64 === null) {
                $filePath = folder_files . $rowimagenes['ubicacion_thumb'];
                if (file_exists($filePath)) {
                    $imageData  = file_get_contents($filePath);
                    $mimeType   = mime_content_type($filePath);
                    $fileBase64 = "data:$mimeType;base64," . base64_encode($imageData);
                }
            }
            if ($fileBase64 !== null) {
                $imagenes[] = array(
                    //'idinventariofisicoconteoimagen'=>(int)$rowimagenes['idinventariofisicoconteoimagen'],
                    'itemImageSrc' => $fileBase64
                );
            }
        }
        $inventario[]=array(
            'iddanios_vehiculos'=>(int)$row['iddanios_vehiculos'],
            'danios_vehiculos'=>$row['danios_vehiculos'],
            'marcado'=>boolval($row['marcado']),
            'descripcion'=>$row['descripcion'],
            'imagenes'=>$imagenes
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'inventario'=>$inventario
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

