    $observaciones_inventario = $_POST['observaciones_inventario'];
    $inventario = json_decode($inventarioJson, true);
    if (!is_array($inventario)) $inventario = [];

    // 2) Archivos agrupados
    $files = $_FILES['files'];
    $filesMain = $_FILES['filesMain'];

    $common=new Common();
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);

    $azureEnabled = defined('azure_blob_enabled') && azure_blob_enabled;
    $blobStorage  = $azureEnabled ? new BlobStorageService() : null;

    $baseDir        = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/ate_gas/gestion-movimiento/'.$idate_gas_etapa;
    $baseDirDB      = $idempresa.DIRECTORY_SEPARATOR.'almacen/ate_gas/gestion-movimiento/'.$idate_gas_etapa;
    $baseDirMain    = folder_files.$idempresa.DIRECTORY_SEPARATOR.'almacen/ate_gas/gestion-movimiento-main';
    $baseDirParcial = $idempresa.DIRECTORY_SEPARATOR.'almacen/ate_gas/gestion-movimiento-main';

    // Blob name prefixes (forward-slash, no folder_files)
    $blobPrefixMain = $idempresa . '/almacen/ate_gas/gestion-movimiento-main/' . $idate_gas_etapa;
    $blobPrefixDir  = $idempresa . '/almacen/ate_gas/gestion-movimiento/' . $idate_gas_etapa;

    $mimeMapUpload  = ['jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp'];
    $tempFiles      = []; // rutas temporales a limpiar en finally

    $conexion->beginTransaction();
    try {
        $queryMain = "UPDATE t_ate_gas_etapa SET observaciones_inventario=:observaciones_inventario, fecha_inventario=CURRENT_TIMESTAMP() WHERE idate_gas_etapa=:idate_gas_etapa";
        $stmtMain = $conexion->prepare($queryMain);
        $stmtMain->bindParam(':observaciones_inventario', $observaciones_inventario);
        $stmtMain->bindParam(':idate_gas_etapa', $idate_gas_etapa);
        $stmtMain->execute();
        
        
        for($ii=0;$ii<count($inventario);$ii++){
            $idate_gas_etapa_inventario=0;
            $result = $conexion->query("SELECT idate_gas_etapa_inventario FROM t_ate_gas_etapa_inventario WHERE idate_gas_etapa=$idate_gas_etapa AND iddanios_vehiculos=".$inventario[$ii]["iddanios_vehiculos"].";");
            while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
                $idate_gas_etapa_inventario=(int)$row['idate_gas_etapa_inventario'];
            }
            
            if($idate_gas_etapa_inventario==0){
                $query = "INSERT INTO t_ate_gas_etapa_inventario (idate_gas_etapa, iddanios_vehiculos, descripcion, created_at)
                                                          VALUES (:idate_gas_etapa, :iddanios_vehiculos, :descripcion, CURRENT_TIMESTAMP())";
                $stmt = $conexion->prepare($query);
                $stmt->bindParam(':idate_gas_etapa', $idate_gas_etapa);
                $stmt->bindParam(':iddanios_vehiculos', $inventario[$ii]["iddanios_vehiculos"]);
                $stmt->bindParam(':descripcion', $inventario[$ii]["descripcion"]);
                $stmt->execute();
                // Obtener ID generado
                //$idate_gas_etapa_inventario = (int) $conexion->lastInsertId();
            }else{
                $query = "UPDATE t_ate_gas_etapa_inventario SET descripcion=:descripcion, edited_at=CURRENT_TIMESTAMP() WHERE idate_gas_etapa_inventario=:idate_gas_etapa_inventario";
                $stmt = $conexion->prepare($query);
                $stmt->bindParam(':descripcion', $inventario[$ii]["descripcion"]);
                $stmt->bindParam(':idate_gas_etapa_inventario', $idate_gas_etapa_inventario);
                $stmt->execute();
            }
        }
        
        $inventario_delete=[];
        $result = $conexion->query("SELECT idate_gas_etapa_inventario, iddanios_vehiculos FROM t_ate_gas_etapa_inventario WHERE idate_gas_etapa=$idate_gas_etapa;");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $indice = array_search((int)$row['iddanios_vehiculos'], array_column($inventario, 'iddanios_vehiculos'));
            if(!is_numeric($indice)){
                $inventario_delete[]=array(
                    'idate_gas_etapa_inventario'=>$row['idate_gas_etapa_inventario'],
                    'iddanios_vehiculos'=>$row['iddanios_vehiculos'],
                );
            }
        }
        
        if(count($inventario_delete)>0){
            $queryDeleteImagenes = "UPDATE t_ate_gas_etapa_inventario_imagen
                SET deleted_at = CURRENT_TIMESTAMP()
                WHERE idate_gas_etapa = :idate_gas_etapa AND iddanios_vehiculos=:iddanios_vehiculos";

            $stmtDeleteImagenes = $conexion->prepare($queryDeleteImagenes);

            foreach ($inventario_delete as $Detalle) {
                $stmtDeleteImagenes->bindParam(':idate_gas_etapa', $idate_gas_etapa);
                $stmtDeleteImagenes->bindParam(':iddanios_vehiculos', $Detalle['iddanios_vehiculos']);
                $stmtDeleteImagenes->execute();
            }
            
            
            $queryDelete = "UPDATE t_ate_gas_etapa_inventario
                SET deleted_at = CURRENT_TIMESTAMP()
                WHERE idate_gas_etapa_inventario = :idate_gas_etapa_inventario";

            $stmtDelete = $conexion->prepare($queryDelete);

            foreach ($inventario_delete as $Detalle) {
                $stmtDelete->bindParam(':idate_gas_etapa_inventario', $Detalle['idate_gas_etapa_inventario']);
                $stmtDelete->execute();
            }
        }

        if ($filesMain && isset($filesMain['name']) && is_array($filesMain['name'])) {
            $stmtInsertMain = $conexion->prepare("INSERT INTO t_ate_gas_etapa_imagen (idate_gas_etapa,   nombre_original,    nombre_guardado,    ubicacion_fisica,   ubicacion_thumb,    created_at)
                                                                              VALUES (:idate_gas_etapa,  :nombre_original,   :nombre_guardado,   :ubicacion_fisica,  :ubicacion_thumb,   CURRENT_TIMESTAMP())");

            $names    = $filesMain['name'];
            $tmpNames = $filesMain['tmp_name'];
            $errs     = $filesMain['error'];

            for ($i = 0; $i < count($names); $i++) {
                if ($names[$i] === '') continue;
                if ($errs[$i] !== UPLOAD_ERR_OK) {
                    $errors[] = array("file" => $names[$i], "error" => $errs[$i]);
                    continue;
                }

                $finfo = finfo_open(FILEINFO_MIME_TYPE);
                $mime  = finfo_file($finfo, $tmpNames[$i]);
                finfo_close($finfo);

                $originalName = $names[$i];
                $ext          = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
                $allowed      = ['jpg','jpeg','png','webp'];
                if (!in_array($ext, $allowed, true)) continue;

                $saved     = bin2hex(random_bytes(16)) . '.' . $ext;
                $thumbName = pathinfo($saved, PATHINFO_FILENAME) . '.jpg';

                if ($azureEnabled && $blobStorage !== null) {
                    // ── Azure path ────────────────────────────────────────────
                    $tempOrig  = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $saved;
                    // Prefijo 'thumb_' evita colisión con $tempOrig cuando el original es JPG
                    $tempThumb = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'thumb_' . $thumbName;
                    $tempFiles[] = $tempOrig;
                    $tempFiles[] = $tempThumb;

                    if (!move_uploaded_file($tmpNames[$i], $tempOrig)) continue;

                    $thumbOk       = $common->crearThumbGD($tempOrig, $tempThumb, 320, 320);
                    $blobOrig      = $blobPrefixMain . '/' . $saved;
                    $blobThumb     = $thumbOk ? ($blobPrefixMain . '/thumb/' . $thumbName) : null;
                    $blobMimeType  = isset($mimeMapUpload[$ext]) ? $mimeMapUpload[$ext] : $mime;

                    if (!$blobStorage->uploadBlobFromFile($blobOrig, $tempOrig, $blobMimeType)) {
                        error_log('[AzureBlob] upload failed main image blob=' . $blobOrig);
                        continue;
                    }
                    $dbThumbPath = null;
                    if ($blobThumb !== null && $blobStorage->uploadBlobFromFile($blobThumb, $tempThumb, 'image/jpeg')) {
                        $dbThumbPath = $blobThumb;
                    }
                    $dbPath = $blobOrig;

                } else {
                    // ── Disco local (comportamiento original) ─────────────────
                    $dirMain = $baseDirMain . '/' . $idate_gas_etapa;
                    if (!is_dir($dirMain)) mkdir($dirMain, 0777, true);

                    $dest = $dirMain . '/' . $saved;
                    if (!move_uploaded_file($tmpNames[$i], $dest)) continue;

                    $thumbDir  = $dirMain . '/thumb';
                    $thumbPath = $thumbDir . '/' . $thumbName;
                    $thumbOk   = $common->crearThumbGD($dest, $thumbPath, 320, 320);

                    $dbThumbPath = $thumbOk ? ($baseDirParcial . '/' . $idate_gas_etapa . '/thumb/' . $thumbName) : null;
                    $dbPath      = $baseDirParcial . '/' . $idate_gas_etapa . '/' . $saved;
                }

                $stmtInsertMain->execute([
                    ':idate_gas_etapa'  => $idate_gas_etapa,
                    ':nombre_original'  => $originalName,
                    ':nombre_guardado'  => $saved,
                    ':ubicacion_fisica' => $dbPath,
                    ':ubicacion_thumb'  => $dbThumbPath,
                ]);
            }
        }

        if ($files && isset($files['name']) && is_array($files['name'])) {

            $stmtInsertImg = $conexion->prepare("INSERT INTO t_ate_gas_etapa_inventario_imagen (idate_gas_etapa,   iddanios_vehiculos,   nombre_original,    nombre_guardado,    ubicacion_fisica,   ubicacion_thumb,    created_at)
                                                                                        VALUES (:idate_gas_etapa,  :iddanios_vehiculos,  :nombre_original,   :nombre_guardado,   :ubicacion_fisica,  :ubicacion_thumb,   CURRENT_TIMESTAMP())");

            // Estructura: $files['name'][<invId>][<idx>]
            foreach ($files['name'] as $invId => $namesByIndex) {

                $invId = (int)$invId;
                if ($invId <= 0) continue;

                foreach ($namesByIndex as $idx => $originalName) {

                    $error = $files['error'][$invId][$idx];
                    if ($error !== UPLOAD_ERR_OK) continue;

                    $tmp = $files['tmp_name'][$invId][$idx];
                    if (!$tmp || !is_uploaded_file($tmp)) continue;

                    $ext     = strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
                    $allowed = ['jpg','jpeg','png','webp'];
                    if (!in_array($ext, $allowed, true)) continue;

                    $saved     = bin2hex(random_bytes(16)) . '.' . $ext;
                    $thumbName = pathinfo($saved, PATHINFO_FILENAME) . '.jpg';

                    if ($azureEnabled && $blobStorage !== null) {
                        // ── Azure path ─────────────────────────────────────────
                        $finfo = finfo_open(FILEINFO_MIME_TYPE);
                        $mime  = finfo_file($finfo, $tmp);
                        finfo_close($finfo);

                        $tempOrig  = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $saved;
                        // Prefijo 'thumb_' evita colisión con $tempOrig cuando el original es JPG
                        $tempThumb = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'thumb_' . $thumbName;
                        $tempFiles[] = $tempOrig;
                        $tempFiles[] = $tempThumb;

                        if (!move_uploaded_file($tmp, $tempOrig)) continue;

                        $thumbOk      = $common->crearThumbGD($tempOrig, $tempThumb, 320, 320);
                        $blobOrig     = $blobPrefixDir . '/' . $invId . '/' . $saved;
                        $blobThumb    = $thumbOk ? ($blobPrefixDir . '/' . $invId . '/thumb/' . $thumbName) : null;
                        $blobMimeType = isset($mimeMapUpload[$ext]) ? $mimeMapUpload[$ext] : $mime;

                        if (!$blobStorage->uploadBlobFromFile($blobOrig, $tempOrig, $blobMimeType)) {
                            error_log('[AzureBlob] upload failed damage image blob=' . $blobOrig);
                            continue;
                        }
                        $dbThumbPath = null;
                        if ($blobThumb !== null && $blobStorage->uploadBlobFromFile($blobThumb, $tempThumb, 'image/jpeg')) {
                            $dbThumbPath = $blobThumb;
                        }
                        $dbPath = $blobOrig;

                    } else {
                        // ── Disco local (comportamiento original) ───────────────
                        $dir = $baseDir . '/' . $invId;
                        if (!is_dir($dir)) mkdir($dir, 0777, true);

                        $dest = $dir . '/' . $saved;
                        if (!move_uploaded_file($tmp, $dest)) continue;

                        $thumbDir  = $dir . '/thumb';
                        $thumbPath = $thumbDir . '/' . $thumbName;
                        $thumbOk   = $common->crearThumbGD($dest, $thumbPath, 320, 320);

                        $dbThumbPath = $thumbOk ? ($baseDirDB . '/' . $invId . '/thumb/' . $thumbName) : null;
                        $dbPath      = $baseDirDB . '/' . $invId . '/' . $saved;
                    }

                    $stmtInsertImg->execute([
                        ':idate_gas_etapa'    => $idate_gas_etapa,
                        ':iddanios_vehiculos' => $invId,
                        ':nombre_original'    => $originalName,
                        ':nombre_guardado'    => $saved,
                        ':ubicacion_fisica'   => $dbPath,
                        ':ubicacion_thumb'    => $dbThumbPath,
                    ]);
                }
            }
        }

        $conexion->commit();
        $codigo=200;
        $status="Exito";
        $mensaje="Se guardo la informacion correctamente";

    } catch (Throwable $e) {
        $conexion->rollBack();
        $mensaje=$e->getMessage();
    } finally {
        foreach ($tempFiles as $tf) {
            if (file_exists($tf)) @unlink($tf);
        }
    }
    
    $resultado=array(
        'codigo'=> $codigo,
        'estado'=> $status,
        'mensaje'=> $mensaje
    );
    
    $response->getBody()->write(json_encode($resultado));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

