$app->post('/ate-gas/estado-pedidos', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];
    $idusuario=$decoded_array["idusuario"];
    $idtipousuario=$decoded_array["idtipousuario"];

    $params = json_decode((string) $request->getBody(),true);
    $filtro_chasis_etapa="";
    $filtro_chasis="";
    if(isset($params['chasis'])){
        $filtro_chasis_etapa=" AND t_ate_gas.chasis LIKE '%".$params['chasis']."%' ";
        $filtro_chasis=" AND t_ate_gas.chasis  LIKE '%".$params['chasis']."%' ";
    }

    $filtro_tecnico="";
    $join_tecnico="LEFT";
    if(isset($params['idtecnico']) && (int)$params['idtecnico']>0){
        $filtro_tecnico=" AND t_ate_gas_etapa_tecnico.idusuario=".$params['idtecnico'];
        $join_tecnico="INNER";
    }

    $filtro_etapa="";
    $join_etapa="LEFT";
    if(isset($params['idetapa']) && (int)$params['idetapa']>0){
        $filtro_etapa=" AND t_ate_gas_etapa.idetapa=".$params['idetapa'];
        $join_etapa="INNER";
    }

    $filtro_marca_etapa="";
    $filtro_marca="";
    if(isset($params['marca'])){
        $filtro_marca_etapa=" AND t_ate_gas.marca LIKE '%".$params['marca']."%' ";
        $filtro_marca=" AND t_ate_gas.marca  LIKE '%".$params['marca']."%' ";
    }
    
    $estadopedidos=[];

    $query="WITH tmp_ate_gas_etapa_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL $filtro_chasis_etapa $filtro_marca_etapa
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa as (
        SELECT
        DISTINCT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_ate_gas_etapa.idetapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.observaciones_inventario,
        t_ate_gas_etapa.fecha_inventario,
        t_ate_gas_etapa.idestado_etapa,
        t_estado_etapa.estado_etapa
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        LEFT JOIN t_estado_etapa ON t_ate_gas_etapa.idestado_etapa=t_estado_etapa.idestado_etapa
        WHERE
        1=1
        $filtro_etapa
        ), tmp_ate_gas_etapa_tecnico as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico', t_ate_gas_etapa_tecnico.idate_gas_etapa_tecnico,
                'idusuario', t_ate_gas_etapa_tecnico.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos
        FROM 
        t_ate_gas_etapa_tecnico
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico.deleted_at IS NULL
        $filtro_tecnico
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        ), tmp_ate_gas_etapa_tecnico_qa as (
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idate_gas_etapa_tecnico_qa', t_ate_gas_etapa_tecnico_qa.idate_gas_etapa_tecnico_qa,
                'idusuario', t_ate_gas_etapa_tecnico_qa.idusuario,
                'nombre', t_usuario.nombre
            )
        ) AS tecnicos_qa
        FROM 
        t_ate_gas_etapa_tecnico_qa
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tecnico_qa.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico_qa.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico_qa.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa.idate_gas_etapa
        ), tmp_ate_gas_etapa_tiempos as (
        SELECT 
        t_ate_gas_etapa_tiempos.idate_gas_etapa,
        MIN(t_ate_gas_etapa_tiempos.inicio) as inicio,
        MAX(t_ate_gas_etapa_tiempos.fin) as fin,
        SUM(TIMESTAMPDIFF(SECOND, t_ate_gas_etapa_tiempos.inicio, IFNULL(t_ate_gas_etapa_tiempos.fin,CURRENT_TIMESTAMP()))) as tiempo
        FROM 
        t_ate_gas_etapa_tiempos
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tiempos.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        WHERE
        t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_tiempos.idate_gas_etapa
        )
        SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idalmacen,
        t_ate_gas.idcliente,
        t_cliente.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.created_at,
        tmp_ate_gas_etapa.idate_gas_etapa,
        tmp_ate_gas_etapa.idetapa,
        tmp_ate_gas_etapa.etapa,
        tmp_ate_gas_etapa.severity,

        t_ate_gas_ubicacion.idalmacendetalle,
        t_almacendetalle.nombre as ubicacion,
        
        tmp_ate_gas_etapa.observaciones_inventario,
        tmp_ate_gas_etapa.fecha_inventario,
        tmp_ate_gas_etapa.idestado_etapa,
        tmp_ate_gas_etapa.estado_etapa,
        tmp_ate_gas_etapa_tiempos.inicio,
        tmp_ate_gas_etapa_tiempos.fin,
        tmp_ate_gas_etapa_tiempos.tiempo,
        sp_workdaydiff(IFNULL(CAST(tmp_ate_gas_etapa_tiempos.fin as DATE),CURRENT_DATE()), CAST(t_ate_gas.created_at as DATE)) as tiempo_total,
        IFNULL(tmp_ate_gas_etapa_tecnico.tecnicos,'[]') as tecnicos,
        IFNULL(tmp_ate_gas_etapa_tecnico_qa.tecnicos_qa,'[]') as tecnicos_qa
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        $join_etapa JOIN tmp_ate_gas_etapa ON t_ate_gas.idate_gas=tmp_ate_gas_etapa.idate_gas
        $join_tecnico JOIN tmp_ate_gas_etapa_tecnico ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico.idate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tecnico_qa ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tecnico_qa.idate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tiempos.idate_gas_etapa
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        $filtro_chasis
        $filtro_marca
        ORDER BY
        t_ate_gas.created_at DESC;";

    $result = $conexion->query($query);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $estadopedidos[]=array(
            'idate_gas'=>(int)$row['idate_gas'],
            'idalmacen'=>(int)$row['idalmacen'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'created_at'=>$row['created_at'],
            'idate_gas_etapa'=>(int)$row['idate_gas_etapa'],
            'idetapa'=>$row['idetapa'],
            'etapa'=>$row['etapa'],
            'severity'=>$row['severity'],
            'idalmacendetalle'=>$row['idalmacendetalle'],
            'ubicacion'=>$row['ubicacion'],
            'observaciones_inventario'=>$row['observaciones_inventario'],
            'fecha_inventario'=>$row['fecha_inventario'],
            'idestado_etapa'=>$row['idestado_etapa'],
            'estado_etapa'=>$row['estado_etapa'],
            'inicio'=>$row['inicio'],
            'fin'=>$row['fin'],
            'tiempo'=>$row['tiempo'],
            'tiempo_total'=>$row['tiempo_total'],
            'tecnicos'=> json_decode($row['tecnicos'],true),
            'tecnicos_qa'=> json_decode($row['tecnicos_qa'],true),
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'estadopedidos'=>$estadopedidos,
        'query'=>$query
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

