    $codigo = 400;
    $status = 'Error';
    $mensaje = 'El archivo no se subió, intente más tarde';

    $xls_data = [];
    $mensajes_error = [];
    $nuevosdatos = [];

    $continuar = true;

    try {

        /*
        |--------------------------------------------------------------------------
        | Token ya validado por middleware
        |--------------------------------------------------------------------------
        */
        $headers = apache_request_headers();
        $token = $headers['Authorization'];

        $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
        $decoded_array = (array) $decoded;

        $idempresa = $decoded_array["idempresa"] ?? null;
        $idalmacen = $decoded_array["idalmacen"] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Leer parámetros del formulario
        |--------------------------------------------------------------------------
        */
        $bodyParams = $request->getParsedBody();

        if (!is_array($bodyParams)) {
            $bodyParams = [];
        }

        $idclienteHash = $bodyParams['idcliente'] ?? null;

        /*
        |--------------------------------------------------------------------------
        | Validaciones básicas
        |--------------------------------------------------------------------------
        */
        if (empty($idempresa)) {
            $mensaje = 'No se recibió la empresa';
            $continuar = false;
        }

        if ($continuar && empty($idalmacen)) {
            $mensaje = 'No se recibió el almacén';
            $continuar = false;
        }

        if ($continuar && empty($idclienteHash)) {
            $mensaje = 'No se recibió el cliente';
            $continuar = false;
        }

        /*
        |--------------------------------------------------------------------------
        | Buscar cliente por hash
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $idclientenum = 0;

            $queryCliente = "
                SELECT idcliente
                FROM t_cliente
                WHERE MD5(idcliente) = :idcliente_hash
                LIMIT 1
            ";

            $stmtCliente = $conexion->prepare($queryCliente);

            $stmtCliente->execute([
                ':idcliente_hash' => $idclienteHash
            ]);

            $rowCliente = $stmtCliente->fetch(PDO::FETCH_ASSOC);

            if ($rowCliente) {
                $idclientenum = (int)$rowCliente["idcliente"];
            }

            if ($idclientenum <= 0) {
                $mensaje = 'No se encontró el cliente';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $files = $_FILES['uploads'] ?? null;

            $totalArchivos = (
                isset($files['name']) &&
                is_array($files['name'])
            ) ? count($files['name']) : 0;

            if ($totalArchivos === 0) {
                $mensaje = 'Debe adjuntar un archivo';
                $continuar = false;
            }
        }

        if ($continuar) {

            if (($files['error'][0] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
                $mensaje = 'Ocurrió un problema al subir el archivo';
                $continuar = false;
            }
        }

        if ($continuar) {

            $nombreOriginal = $files["name"][0] ?? '';

            if (trim($nombreOriginal) === '') {
                $mensaje = 'El archivo no tiene nombre válido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Subir archivo
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $nombredoc = $idclientenum . "_" . date("Y_m_d") . "_" . $nombreOriginal;

            $creacion = new Carpetas();
            $respuesta = $creacion->procesarCarpeta($idempresa);

            $piramideUploader = new PiramideUploader();

            $upload = $piramideUploader->upload(
                $nombredoc,
                'uploads',
                folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/ate_gas/masivo_salidas',
                $archivosmasivo,
                true
            );

            $file = $piramideUploader->getInfoFile();
            $file_name = $file['complete_name'] ?? '';

            if (!isset($upload) || empty($upload['uploaded'])) {
                $mensaje = $upload['error'] ?? 'No se pudo subir el archivo';
                $continuar = false;
            }

            if ($continuar && trim($file_name) === '') {
                $mensaje = 'No se pudo obtener el nombre del archivo subido';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Leer Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $inputFileName = folder_files . $idempresa . DIRECTORY_SEPARATOR . 'almacen/ate_gas/masivo_salidas/' . $file_name;

            if (!file_exists($inputFileName)) {
                $mensaje = 'No se encontró el archivo subido';
                $continuar = false;
            }
        }

        if ($continuar) {

            $spreadsheet = \PhpOffice\PhpSpreadsheet\IOFactory::load($inputFileName);
            $sheet = $spreadsheet->getActiveSheet();

            $highestRow = $sheet->getHighestRow();

            if ($highestRow < 2) {
                $mensaje = 'El archivo no tiene datos para procesar';
                $continuar = false;
            }
        }

        if ($continuar) {

            /*
            Solo se lee la columna A, desde la fila 2.
            */
            $xls_data = $sheet->rangeToArray(
                'A2:A' . $highestRow,
                '',
                true,
                true
            );

            $datos_excel = [];

            foreach ($xls_data as $index => $item) {

                $chasis = $item[0] ?? '';

                if (trim((string)$chasis) === '') {
                    continue;
                }

                $datos_excel[] = [
                    'chasis' => strtoupper(trim((string)$chasis))
                ];
            }

            if (count($datos_excel) === 0) {
                $mensaje = 'El archivo no contiene chasis válidos';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Validar datos del Excel
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $queryExisteChasis = "
                SELECT idate_gas
                FROM t_ate_gas
                WHERE chasis = :chasis
                  AND fecha_recepcion IS NOT NULL
                  AND fecha_programacion_salida IS NULL
                  AND deleted_at IS NULL
                  AND fecha_salida IS NULL
                  AND idcliente = :idcliente
                  AND idalmacen = :idalmacen
                LIMIT 1
            ";

            $stmtExisteChasis = $conexion->prepare($queryExisteChasis);

            $chasisEnArchivo = [];

            foreach ($datos_excel as $xls => $fila) {

                $numeroFilaExcel = $xls + 2;
                $chasis = strtoupper(trim((string)($fila["chasis"] ?? '')));

                $datos_excel[$xls]["chasis"] = $chasis;

                if ($chasis === '') {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Chasis es obligatorio'
                    ];
                    continue;
                }

                if (strlen($chasis) !== 17) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'Chasis debe tener 17 caracteres'
                    ];
                    continue;
                }

                if (preg_match('/[IOQ]/', $chasis)) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis no puede contener I, O o Q'
                    ];
                    continue;
                }

                if (in_array($chasis, $chasisEnArchivo)) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis está duplicado en el archivo'
                    ];
                    continue;
                }

                $chasisEnArchivo[] = $chasis;

                $stmtExisteChasis->execute([
                    ':chasis' => $chasis,
                    ':idcliente' => $idclientenum,
                    ':idalmacen' => $idalmacen
                ]);

                $rowExiste = $stmtExisteChasis->fetch(PDO::FETCH_ASSOC);

                if (!$rowExiste) {
                    $mensajes_error[] = [
                        'fila' => $numeroFilaExcel,
                        'mensaje' => 'El chasis no existe en la base de datos o no está disponible para programar salida'
                    ];
                }
            }

            if (count($mensajes_error) > 0) {
                $mensaje = 'El archivo contiene errores';
                $continuar = false;
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Actualizar datos
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            $conexion->beginTransaction();

            $queryUpdate = "
                UPDATE t_ate_gas
                SET fecha_programacion_salida = CURRENT_TIMESTAMP()
                WHERE chasis = :chasis
                  AND idcliente = :idcliente
                  AND idalmacen = :idalmacen
                  AND fecha_recepcion IS NOT NULL
                  AND fecha_programacion_salida IS NULL
                  AND deleted_at IS NULL
                  AND fecha_salida IS NULL
            ";

            $stmtUpdate = $conexion->prepare($queryUpdate);

            foreach ($datos_excel as $fila) {

                $resultUpdate = $stmtUpdate->execute([
                    ':chasis' => $fila["chasis"],
                    ':idcliente' => $idclientenum,
                    ':idalmacen' => $idalmacen
                ]);

                if (!$resultUpdate) {
                    $mensaje = 'No se pudo programar la salida de un chasis';
                    $continuar = false;
                    break;
                }

                /*
                Si no actualizó ninguna fila, también lo tratamos como error.
                Esto cubre casos donde otro proceso cambió el estado entre la validación y el UPDATE.
                */
                if ($stmtUpdate->rowCount() === 0) {
                    $mensaje = 'Uno de los chasis ya no está disponible para programar salida';
                    $continuar = false;
                    break;
                }
            }

            if (!$continuar) {
                if ($conexion->inTransaction()) {
                    $conexion->rollBack();
                }
            }
        }

        /*
        |--------------------------------------------------------------------------
        | Confirmar operación
        |--------------------------------------------------------------------------
        */
        if ($continuar) {

            if ($conexion->inTransaction()) {
                $conexion->commit();
            }

            $codigo = 200;
            $status = 'Exito';
            $mensaje = 'Se guardó la información correctamente';
        }

    } catch (Throwable $e) {

        if ($conexion->inTransaction()) {
            $conexion->rollBack();
        }

        $codigo = 400;
        $status = 'Error';
        $mensaje = $e->getMessage();
    }

    $resultado = array(
        'codigo' => $codigo,
        'estado' => $status,
        'mensaje' => $mensaje,
        'mensajes_error' => $mensajes_error
    );

    $response->getBody()->write(json_encode($resultado));

    return $response->withHeader('Content-Type', 'application/json');

})->add($verifyToken);

$app->get('/ate-gas/salidas', function(Request $request, Response $response, array $args) use ($conexion) {
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $ategas=[];
    $result = $conexion->query("SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idalmacen,
        t_ate_gas.idcliente,
        t_cliente.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.fecha_programacion_salida,
        t_ate_gas.fecha_salida,
        t_ate_gas.destino_salida,
        t_ate_gas.transportista_salida,
        t_ate_gas.nombre_original_salida,
        t_ate_gas.nombre_guardado_salida,
        t_ate_gas.ubicacion_fisica_salida,
        IF(t_ate_gas.fecha_salida IS NULL,'Programado','Despachado') as estado_salida
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        AND t_ate_gas.fecha_programacion_salida IS NOT NULL
        ORDER BY
        t_ate_gas.fecha_programacion_salida DESC;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $ategas[]=array(
            'idate_gas'=>(int)$row['idate_gas'],
            'idalmacen'=>(int)$row['idalmacen'],
            'idcliente'=>(int)$row['idcliente'],
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'fecha_programacion_salida'=>$row['fecha_programacion_salida'],
            'fecha_salida'=>$row['fecha_salida'],
            'destino_salida'=>$row['destino_salida'],
            'transportista_salida'=>$row['transportista_salida'],
            'nombre_original_salida'=>$row['nombre_original_salida'],
            'nombre_guardado_salida'=>$row['nombre_guardado_salida'],
            'ubicacion_fisica_salida'=>$row['ubicacion_fisica_salida'],
            'estado_salida'=>$row['estado_salida'],
        );
    }
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'ategas'=>$ategas
    )));
    
    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->post('/ate-gas/salidas/{idate_gas}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas=(int)$args['idate_gas'];
    $headers=apache_request_headers();
    $token=$headers['Authorization'];
    $decoded=JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array=(array)$decoded;
    $idempresa=(int)$decoded_array['idempresa'];
    $idalmacen=(int)$decoded_array['idalmacen'];

    $codigo=400;
    $status='Error';
    $mensaje='No se guardo la información';
    $blobName=null;
    $blobUploaded=false;
    $tempFile=null;
    $blobStorage=null;

    try {
        if($idate_gas<=0 || $idempresa<=0 || $idalmacen<=0){
            throw new InvalidArgumentException('La unidad solicitada no es válida');
        }

        $params=$request->getParsedBody();
        if(!is_array($params)) $params=[];
        $destino_salida=isset($params['destino_salida']) ? trim((string)$params['destino_salida']) : '';
        $transportista_salida=isset($params['transportista_salida']) ? trim((string)$params['transportista_salida']) : '';
        if($destino_salida==='') throw new InvalidArgumentException('El destino es obligatorio');
        if($transportista_salida==='') throw new InvalidArgumentException('El transportista es obligatorio');
        if(mb_strlen($destino_salida, 'UTF-8')>255) throw new InvalidArgumentException('El destino no puede superar 255 caracteres');
        if(mb_strlen($transportista_salida, 'UTF-8')>255) throw new InvalidArgumentException('El transportista no puede superar 255 caracteres');

        $stmtUnidad=$conexion->prepare("SELECT idate_gas, fecha_salida
            FROM t_ate_gas
            WHERE idate_gas=:idate_gas
              AND idalmacen=:idalmacen
              AND deleted_at IS NULL
            LIMIT 1");
        $stmtUnidad->execute(array(':idate_gas'=>$idate_gas, ':idalmacen'=>$idalmacen));
        $unidad=$stmtUnidad->fetch(PDO::FETCH_ASSOC);
        if(!$unidad) throw new RuntimeException('La unidad no existe o no pertenece al almacén seleccionado');
        if($unidad['fecha_salida']!==null) throw new RuntimeException('La unidad ya fue despachada');

        $stmtEtapa=$conexion->prepare("SELECT idestado_etapa
            FROM t_ate_gas_etapa
            WHERE idate_gas=:idate_gas
              AND deteled_at IS NULL
            ORDER BY paso DESC
            LIMIT 1");
        $stmtEtapa->execute(array(':idate_gas'=>$idate_gas));
        $idestado_etapa=(int)$stmtEtapa->fetchColumn();
        if($idestado_etapa===2) throw new RuntimeException('La unidad está en proceso y no puede ser despachada');

        $uploadedFiles=$request->getUploadedFiles();
        $files=[];
        $collectFiles=function($entry) use (&$collectFiles, &$files) {
            if(is_array($entry)){
                foreach($entry as $child) $collectFiles($child);
            }elseif($entry!==null){
                $files[]=$entry;
            }
        };
        $collectFiles($uploadedFiles);
        if(!isset($uploadedFiles['file']) || count($files)===0) throw new InvalidArgumentException('La guía de remisión es obligatoria');
        if(count($files)!==1) throw new InvalidArgumentException('Solo se permite una guía de remisión');

        $uploadedFile=$files[0];
        if($uploadedFile->getError()!==UPLOAD_ERR_OK) throw new InvalidArgumentException('No se pudo recibir la guía de remisión');
        $fileSize=$uploadedFile->getSize();
        if($fileSize===null || $fileSize<=0) throw new InvalidArgumentException('La guía de remisión está vacía');
        if($fileSize>(10*1024*1024)) throw new InvalidArgumentException('La guía de remisión no puede superar 10 MB');

        $clientName=str_replace('\\', '/', (string)$uploadedFile->getClientFilename());
        $originalName=trim(preg_replace('/[\x00-\x1F\x7F]/u', '', basename($clientName)));
        if($originalName==='') throw new InvalidArgumentException('El nombre del archivo no es válido');
        $extension=strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
        $allowedExtensions=['jpg','jpeg','png','webp','heic','heif','pdf','xls','xlsx','doc','docx'];
        if(!in_array($extension, $allowedExtensions, true)) throw new InvalidArgumentException('El formato de la guía de remisión no está permitido');
        if(mb_strlen($originalName, 'UTF-8')>255){
            $baseName=pathinfo($originalName, PATHINFO_FILENAME);
            $maxBaseLength=250-mb_strlen($extension, 'UTF-8');
            $originalName=mb_substr($baseName, 0, $maxBaseLength, 'UTF-8').'.'.$extension;
        }

        $tempFile=tempnam(sys_get_temp_dir(), 'ategas_salida_');
        if($tempFile===false) throw new RuntimeException('No se pudo preparar temporalmente la guía de remisión');
        $uploadedFile->moveTo($tempFile);

        $finfo=finfo_open(FILEINFO_MIME_TYPE);
        $detectedMime=$finfo ? finfo_file($finfo, $tempFile) : false;
        if($finfo) finfo_close($finfo);
        if(!$detectedMime) throw new InvalidArgumentException('No se pudo identificar el tipo real del archivo');
        $detectedMimeLower=strtolower($detectedMime);
        $mimeMap=[
            'jpg'=>['image/jpeg','image/pjpeg'],
            'jpeg'=>['image/jpeg','image/pjpeg'],
            'png'=>['image/png'],
            'webp'=>['image/webp'],
            'heic'=>['image/heic','image/heic-sequence','image/x-heic','application/heic'],
            'heif'=>['image/heif','image/heif-sequence','image/x-heif','application/heif'],
            'pdf'=>['application/pdf'],
            'xls'=>['application/vnd.ms-excel','application/x-msexcel','application/xls','application/x-ole-storage','application/cdfv2'],
            'xlsx'=>['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'],
            'doc'=>['application/msword','application/x-ole-storage','application/cdfv2'],
            'docx'=>['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
        ];
        $validMime=in_array($detectedMimeLower, $mimeMap[$extension], true);

        if(!$validMime && in_array($extension, ['xlsx','docx'], true)
            && in_array($detectedMimeLower, ['application/zip','application/x-zip','application/x-zip-compressed'], true)
            && class_exists('ZipArchive')){
            $zip=new ZipArchive();
            if($zip->open($tempFile)===true){
                $requiredEntry=$extension==='xlsx' ? 'xl/workbook.xml' : 'word/document.xml';
                $validMime=$zip->locateName('[Content_Types].xml')!==false && $zip->locateName($requiredEntry)!==false;
                $zip->close();
            }
        }
        if(!$validMime && in_array($extension, ['heic','heif'], true) && $detectedMimeLower==='application/octet-stream'){
            $signature=file_get_contents($tempFile, false, null, 0, 32);
            $validMime=is_string($signature) && preg_match('/ftyp(heic|heix|hevc|hevx|mif1|msf1)/', $signature)===1;
        }
        if(!$validMime) throw new InvalidArgumentException('El contenido del archivo no coincide con su extensión');

        $storageMimeMap=[
            'jpg'=>'image/jpeg', 'jpeg'=>'image/jpeg', 'png'=>'image/png', 'webp'=>'image/webp',
            'heic'=>'image/heic', 'heif'=>'image/heif', 'pdf'=>'application/pdf',
            'xls'=>'application/vnd.ms-excel',
            'xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'doc'=>'application/msword',
            'docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        ];

        $azureEnabled=defined('azure_blob_enabled') && azure_blob_enabled;
        $blobStorage=$azureEnabled ? new BlobStorageService() : null;
        if(!$azureEnabled || $blobStorage===null || !$blobStorage->isConfigured()){
            throw new RuntimeException('El almacenamiento de archivos no está disponible');
        }

        $savedName=bin2hex(random_bytes(16)).'.'.$extension;
        $blobName=$idempresa.'/almacen/ate_gas/salidas/'.$idate_gas.'/'.$savedName;
        error_log('[AteGasSalida] upload start idate_gas='.$idate_gas.' idempresa='.$idempresa.' idalmacen='.$idalmacen.' method=POST blob='.$blobName);
        if(!$blobStorage->uploadBlobFromFile($blobName, $tempFile, $storageMimeMap[$extension])){
            error_log('[AteGasSalida] upload failed idate_gas='.$idate_gas.' blob='.$blobName);
            throw new RuntimeException('No se pudo almacenar la guía de remisión');
        }
        $blobUploaded=true;

        $conexion->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $conexion->beginTransaction();
        $stmtUpdate=$conexion->prepare("UPDATE t_ate_gas
            SET fecha_salida=CURRENT_TIMESTAMP(),
                destino_salida=:destino_salida,
                transportista_salida=:transportista_salida,
                nombre_original_salida=:nombre_original_salida,
                nombre_guardado_salida=:nombre_guardado_salida,
                ubicacion_fisica_salida=:ubicacion_fisica_salida
            WHERE idate_gas=:idate_gas
              AND idalmacen=:idalmacen
              AND fecha_salida IS NULL
              AND deleted_at IS NULL");
        $stmtUpdate->execute(array(
            ':destino_salida'=>$destino_salida,
            ':transportista_salida'=>$transportista_salida,
            ':nombre_original_salida'=>$originalName,
            ':nombre_guardado_salida'=>$savedName,
            ':ubicacion_fisica_salida'=>$blobName,
            ':idate_gas'=>$idate_gas,
            ':idalmacen'=>$idalmacen,
        ));
        if($stmtUpdate->rowCount()!==1) throw new RuntimeException('La unidad ya fue despachada o cambió de estado');
        $conexion->commit();

        $codigo=200;
        $status='Exito';
        $mensaje='Se guardó la información correctamente';
        error_log('[AteGasSalida] dispatch committed idate_gas='.$idate_gas.' blob='.$blobName);
    }catch(Throwable $e){
        if($conexion->inTransaction()) $conexion->rollBack();
        if($blobUploaded && $blobName!==null && $blobStorage!==null){
            $deleted=$blobStorage->deleteBlob($blobName);
            error_log('[AteGasSalida] compensation idate_gas='.$idate_gas.' blob='.$blobName.' deleted='.($deleted ? '1' : '0'));
        }
        $mensaje=$e instanceof PDOException ? 'No se pudo guardar la información del despacho' : $e->getMessage();
        error_log('[AteGasSalida] dispatch failed idate_gas='.$idate_gas.' idempresa='.$idempresa.' idalmacen='.$idalmacen.' reason='.get_class($e));
    }finally{
        if($tempFile!==null && is_file($tempFile)) @unlink($tempFile);
    }

    $response->getBody()->write(json_encode(array('codigo'=>$codigo, 'estado'=>$status, 'mensaje'=>$mensaje)));
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/ate-gas/salidas/{idate_gas}/guia-remision', function(Request $request, Response $response, array $args) use ($conexion) {
    $idate_gas=(int)$args['idate_gas'];
    $headers=apache_request_headers();
    $token=$headers['Authorization'];
    $decoded=JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array=(array)$decoded;
    $idalmacen=(int)$decoded_array['idalmacen'];

    try{
        $stmt=$conexion->prepare("SELECT nombre_original_salida, nombre_guardado_salida, ubicacion_fisica_salida
            FROM t_ate_gas
            WHERE idate_gas=:idate_gas
              AND idalmacen=:idalmacen
              AND deleted_at IS NULL
            LIMIT 1");
        $stmt->execute(array(':idate_gas'=>$idate_gas, ':idalmacen'=>$idalmacen));
        $archivo=$stmt->fetch(PDO::FETCH_ASSOC);
    }catch(Throwable $e){
        error_log('[AteGasSalida] download query failed idate_gas='.$idate_gas.' reason='.get_class($e));
        $response->getBody()->write(json_encode(array('codigo'=>500, 'estado'=>'Error', 'mensaje'=>'No se pudo obtener la guía de remisión')));
        return $response->withStatus(500)->withHeader('Content-Type', 'application/json');
    }
    if(!$archivo || empty($archivo['nombre_original_salida']) || empty($archivo['ubicacion_fisica_salida'])){
        $response->getBody()->write(json_encode(array('codigo'=>404, 'estado'=>'Error', 'mensaje'=>'La guía de remisión no fue encontrada')));
        return $response->withStatus(404)->withHeader('Content-Type', 'application/json');
    }

    $blobStorage=(defined('azure_blob_enabled') && azure_blob_enabled) ? new BlobStorageService() : null;
    if($blobStorage===null || !$blobStorage->isConfigured()){
        $response->getBody()->write(json_encode(array('codigo'=>503, 'estado'=>'Error', 'mensaje'=>'El almacenamiento de archivos no está disponible')));
        return $response->withStatus(503)->withHeader('Content-Type', 'application/json');
    }

    try{
        $blob=$blobStorage->getBlob($archivo['ubicacion_fisica_salida']);
    }catch(Throwable $e){
        $blob=null;
        error_log('[AteGasSalida] download error idate_gas='.$idate_gas.' reason='.get_class($e));
    }
    if($blob===null){
        error_log('[AteGasSalida] blob missing idate_gas='.$idate_gas);
        $response->getBody()->write(json_encode(array('codigo'=>404, 'estado'=>'Error', 'mensaje'=>'La guía de remisión no fue encontrada')));
        return $response->withStatus(404)->withHeader('Content-Type', 'application/json');
    }

    $originalName=trim(preg_replace('/[\x00-\x1F\x7F]/u', '', basename(str_replace('\\', '/', $archivo['nombre_original_salida']))));
    $extension=strtolower(pathinfo($originalName, PATHINFO_EXTENSION));
    $disposition=in_array($extension, ['jpg','jpeg','png','webp','heic','heif','pdf'], true) ? 'inline' : 'attachment';
    $asciiName=preg_replace('/[^A-Za-z0-9._-]/', '_', $originalName);
    if($asciiName==='') $asciiName='guia-remision.'.$extension;
    $contentDisposition=$disposition.'; filename="'.$asciiName.'"; filename*=UTF-8\'\''.rawurlencode($originalName);

    $response->getBody()->write($blob['content']);
    return $response
        ->withHeader('Content-Type', $blob['contentType'])
        ->withHeader('Content-Length', (string)strlen($blob['content']))
        ->withHeader('Content-Disposition', $contentDisposition)
        ->withHeader('X-Content-Type-Options', 'nosniff');
})->add($verifyToken);

$app->get('/ate-gas/reporte-tiempos-proceso/{idcliente}/{tipo_filtro}/{fecha_inicial}/{fecha_final}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $tipo_filtro = $args['tipo_filtro'];
    $fecha_inicial = $args['fecha_inicial'];
    $fecha_final = $args['fecha_final'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    if((int)$tipo_filtro==1){
        $filtro_fecha=" AND (CAST(t_ate_gas.created_at as DATE) BETWEEN '$fecha_inicial' AND '$fecha_final' OR CAST(t_ate_gas.fecha_recepcion as DATE) BETWEEN '$fecha_inicial' AND '$fecha_final') ";
    }
    if((int)$tipo_filtro==2){
        $filtro_fecha=" AND CAST(tmp_ate_gas_etapa_tiempos.fin as DATE) BETWEEN '$fecha_inicial' AND '$fecha_final' ";
    }

    $reporte_tiempos_proceso=[];
    $query="WITH tmp_ate_gas_etapa_tiempos as (
        SELECT 
        t_ate_gas_etapa_tiempos.idate_gas_etapa,
        MIN(t_ate_gas_etapa_tiempos.inicio) as inicio,
        MAX(t_ate_gas_etapa_tiempos.fin) as fin,
        SUM(TIMESTAMPDIFF(SECOND, t_ate_gas_etapa_tiempos.inicio, t_ate_gas_etapa_tiempos.fin)) as tiempo
        FROM 
        t_ate_gas_etapa_tiempos
        WHERE
        t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_tiempos.idate_gas_etapa
        ),
        tmp_tecnicos as (
        select 
        t_ate_gas_etapa_tecnico.idate_gas_etapa,
        GROUP_CONCAT(t_usuario.nombre) as tecnico,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'idtecnico', t_ate_gas_etapa_tecnico.idusuario
            )
        ) as idtecnico
        from 
        t_ate_gas_etapa_tecnico
        LEFT JOIN t_usuario ON t_ate_gas_etapa_tecnico.idusuario=t_usuario.idusuario
        WHERE
        t_ate_gas_etapa_tecnico.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_tecnico.idate_gas_etapa
        ), tmp_ubicacion_max as (
        select 
        idate_gas_etapa,
        MAX(idate_gas_ubicacion) as idate_gas_ubicacion
        from 
        t_ate_gas_ubicacion
        GROUP BY
        idate_gas_etapa), tmp_ubicacion as (
        SELECT
        t_ate_gas_ubicacion.idate_gas_etapa,
        t_ate_gas_ubicacion.idalmacendetalle,
        t_almacendetalle.nombre as ubicacion
        FROM
        t_ate_gas_ubicacion
        INNER JOIN tmp_ubicacion_max ON t_ate_gas_ubicacion.idate_gas_etapa=tmp_ubicacion_max.idate_gas_etapa AND t_ate_gas_ubicacion.idate_gas_ubicacion=tmp_ubicacion_max.idate_gas_ubicacion
        INNER JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        )
        SELECT
        t_ate_gas.created_at,
        t_ate_gas.fecha_recepcion,
        t_ate_gas.sede,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        tmp_tecnicos.tecnico,
        tmp_tecnicos.idtecnico,
        t_ate_gas_etapa.idetapa,
        t_etapa.etapa,
        tmp_ubicacion.ubicacion,
        tmp_ate_gas_etapa_tiempos.inicio,
        tmp_ate_gas_etapa_tiempos.fin,
        tmp_ate_gas_etapa_tiempos.tiempo,
        TIMESTAMPDIFF(SECOND, tmp_ate_gas_etapa_tiempos.inicio, tmp_ate_gas_etapa_tiempos.fin) as tiempo_total,
        sec_to_time(timestampdiff(SECOND, tmp_ate_gas_etapa_tiempos.inicio, tmp_ate_gas_etapa_tiempos.fin)) AS tiempo_total_formato,
        TIMESTAMPDIFF(SECOND, tmp_ate_gas_etapa_tiempos.inicio, tmp_ate_gas_etapa_tiempos.fin)-tmp_ate_gas_etapa_tiempos.tiempo as tiempo_en_pausa,
        sec_to_time(TIMESTAMPDIFF(SECOND, tmp_ate_gas_etapa_tiempos.inicio, tmp_ate_gas_etapa_tiempos.fin)-tmp_ate_gas_etapa_tiempos.tiempo) AS tiempo_en_pausa_formato
        FROM
        t_ate_gas
        LEFT JOIN t_ate_gas_etapa ON t_ate_gas.idate_gas=t_ate_gas_etapa.idate_gas AND t_ate_gas_etapa.deteled_at IS NULL
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        LEFT JOIN tmp_ate_gas_etapa_tiempos ON t_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tiempos.idate_gas_etapa
        LEFT JOIN tmp_tecnicos ON t_ate_gas_etapa.idate_gas_etapa=tmp_tecnicos.idate_gas_etapa
        LEFT JOIN tmp_ubicacion ON t_ate_gas_etapa.idate_gas_etapa=tmp_ubicacion.idate_gas_etapa
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.idcliente=$idcliente
        $filtro_fecha
        AND t_ate_gas.deleted_at IS NULL;";
        
    $result = $conexion->query($query);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $reporte_tiempos_proceso[]=array(
            'created_at'=>$row['created_at'],
            'fecha_recepcion'=>$row['fecha_recepcion'],
            'sede'=>$row['sede'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'color'=>$row['color'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'tecnico'=>$row['tecnico'],
            'idtecnico'=>json_decode($row['idtecnico'],true),
            'idetapa'=>$row['idetapa'],
            'etapa'=>$row['etapa'],
            'ubicacion'=>$row['ubicacion'],
            'inicio'=>$row['inicio'],
            'fin'=>$row['fin'],
            'tiempo'=>$row['tiempo'],
            'tiempo_total'=>$row['tiempo_total'],
            'tiempo_total_formato'=>$row['tiempo_total_formato'],
            'tiempo_en_pausa'=>$row['tiempo_en_pausa'],
            'tiempo_en_pausa_formato'=>$row['tiempo_en_pausa_formato']
        );
    }
        
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'query'=>$query,
        'reporte_tiempos_proceso'=>$reporte_tiempos_proceso
    )));

    

    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

$app->get('/ate-gas/reporte-status/{idcliente}/{fecha_inicial}/{fecha_final}', function(Request $request, Response $response, array $args) use ($conexion) {
    $idcliente = $args['idcliente'];
    $fecha_inicial = $args['fecha_inicial'];
    $fecha_final = $args['fecha_final'];
    $headers = apache_request_headers();
    $token=$headers['Authorization'];
    $decoded = JWT::decode($token, new Key(jwt_key, 'HS256'));
    $decoded_array = (array) $decoded;
    $idalmacen=$decoded_array["idalmacen"];

    $reporte_status=[];
    $query="WITH tmp_ate_gas_etapa_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL AND t_ate_gas.fecha_salida IS NULL
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa_anterior_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL AND t_ate_gas.fecha_salida IS NULL
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        AND t_ate_gas_etapa.idetapa IS NOT NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ), tmp_ate_gas_etapa as (
        SELECT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.idestado_etapa,
        t_ate_gas_etapa.created_at
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        WHERE
        t_ate_gas_etapa.idestado_etapa<>4
        ), tmp_ate_gas_etapa_anterior as (
        SELECT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.idestado_etapa,
        t_ate_gas_etapa.created_at
        FROM
        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_anterior_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_anterior_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_anterior_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        ),
        tmp_ate_gas_etapa_tiempos as (
        SELECT
        tmp_ate_gas_etapa.idate_gas,
        tmp_ate_gas_etapa.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'inicio', t_ate_gas_etapa_tiempos.inicio,
                'fin', t_ate_gas_etapa_tiempos.fin
            )
        ) as tiempos
        FROM
        tmp_ate_gas_etapa
        LEFT JOIN t_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa.idate_gas_etapa=t_ate_gas_etapa_tiempos.idate_gas_etapa AND t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa.idate_gas,
        tmp_ate_gas_etapa.idate_gas_etapa
        ),
        tmp_ate_gas_etapa_anterior_tiempos as (
        SELECT
        tmp_ate_gas_etapa_anterior.idate_gas,
        tmp_ate_gas_etapa_anterior.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'inicio', t_ate_gas_etapa_tiempos.inicio,
                'fin', t_ate_gas_etapa_tiempos.fin
            )
        ) as tiempos
        FROM
        tmp_ate_gas_etapa_anterior
        LEFT JOIN t_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa_anterior.idate_gas_etapa=t_ate_gas_etapa_tiempos.idate_gas_etapa AND t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa_anterior.idate_gas,
        tmp_ate_gas_etapa_anterior.idate_gas_etapa
        )
        SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idcliente,
        t_ate_gas.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.sede,
        IF(t_ate_gas.fecha_salida IS NOT NULL,'Despachado',IFNULL(IFNULL(tmp_ate_gas_etapa.etapa,tmp_ate_gas_etapa_anterior.etapa),'Pendiente de Envio')) as etapa,
        IFNULL(tmp_ate_gas_etapa.created_at,tmp_ate_gas_etapa_anterior.created_at) as fecha_asignacion_etapa,
        IFNULL(tmp_ate_gas_etapa.idestado_etapa,tmp_ate_gas_etapa_anterior.idestado_etapa) as idestado_etapa,
        IFNULL(tmp_ate_gas_etapa_tiempos.tiempos,tmp_ate_gas_etapa_anterior_tiempos.tiempos) as tiempos,
        t_ate_gas.fecha_recepcion,
        t_ate_gas.fecha_salida,
        t_ate_gas.created_at
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_ate_gas_etapa ON t_ate_gas.idate_gas=tmp_ate_gas_etapa.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_anterior ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_anterior.idate_gas
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        LEFT JOIN tmp_ate_gas_etapa_tiempos ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_tiempos.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_anterior_tiempos ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_anterior_tiempos.idate_gas
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        AND CAST(t_ate_gas.created_at as DATE) BETWEEN '$fecha_inicial' AND '$fecha_final'
        AND t_ate_gas.idcliente=$idcliente
        ORDER BY
        t_ate_gas.created_at DESC;";
    $result = $conexion->query($query);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $inicio=null;
        $fin=null;
        if($row["tiempos"]!=''){
            $tiempos=json_decode($row["tiempos"], true);
            usort($tiempos, function($a, $b) {
                return strcmp($a['inicio'], $b['inicio']);
            });
            $inicio=$tiempos[0]['inicio'];
            if((int)$row['idestado_etapa']==4){
                $fin=$tiempos[count($tiempos)-1]['fin'];
            }
        }

        $reporte_status[]=array(
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'sede'=>$row['sede'],
            'etapa'=>$row['etapa'],
            'fecha_asignacion_etapa'=>$row['fecha_asignacion_etapa'],
            'inicio'=>$inicio,
            'fin'=>$fin,
            'fecha_recepcion'=>$row['fecha_recepcion'],
            'fecha_salida'=>$row['fecha_salida'],
            'created_at'=>$row['created_at'],
            
            
            
        );
    }
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'reporte_status'=>$reporte_status
    )));

    

    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);

