        -- t_cliente.cliente,
        t_ate_gas.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        -- t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.sede,
        t_ate_gas.fecha_ot,
        t_almacendetalle.nombre as ubicacion,
