        t_ate_gas_etapa 
        INNER JOIN tmp_ate_gas_etapa_anterior_max ON t_ate_gas_etapa.idate_gas=tmp_ate_gas_etapa_anterior_max.idate_gas AND t_ate_gas_etapa.paso=tmp_ate_gas_etapa_anterior_max.paso
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        ),
        
    -- SECCION PRODUCCION        
    tmp_ate_gas_etapa_produccion_max as (
        select 
        t_ate_gas_etapa.idate_gas,
        MAX(t_ate_gas_etapa.paso)  as paso
        FROM 
        t_ate_gas_etapa
        INNER JOIN t_ate_gas ON t_ate_gas_etapa.idate_gas=t_ate_gas.idate_gas AND $idalmacen=t_ate_gas.idalmacen AND t_ate_gas.deleted_at IS NULL
        WHERE
        t_ate_gas_etapa.idetapa=4
        AND t_ate_gas_etapa.deteled_at IS NULL
        GROUP BY
        t_ate_gas_etapa.idate_gas
        ),
    tmp_ate_gas_etapa_produccion as (
        SELECT
        t_ate_gas_etapa.idate_gas,
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_etapa.severity,
        t_ate_gas_etapa.idestado_etapa,
