        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        ), 
    tmp_ate_gas_etapa_produccion_tiempos as (
        SELECT
        tmp_ate_gas_etapa_produccion.idate_gas,
        tmp_ate_gas_etapa_produccion.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'inicio', t_ate_gas_etapa_tiempos.inicio,
                'fin', t_ate_gas_etapa_tiempos.fin,
                'usuario', t_usuario.nombre
            )
        ) as tiempos
        FROM
        tmp_ate_gas_etapa_produccion
        LEFT JOIN t_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa_produccion.idate_gas_etapa=t_ate_gas_etapa_tiempos.idate_gas_etapa AND t_ate_gas_etapa_tiempos.deleted_at IS NULL
