        t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        tmp_ate_gas_etapa_control_calidad.idate_gas,
        tmp_ate_gas_etapa_control_calidad.idate_gas_etapa
        )
        
        SELECT 
        t_ate_gas.idate_gas,
        t_ate_gas.idcliente,
        -- t_cliente.cliente,
        t_ate_gas.cliente,
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_ate_gas.sede,
        t_ate_gas.fecha_recepcion,
        tmp_ate_gas_etapa_produccion.idestado_etapa as idestado_etapa_produccion,
        tmp_ate_gas_etapa_produccion_tiempos.tiempos as tiempos_produccion,
        tmp_ate_gas_etapa_control_calidad_tiempos.tiempos as tiempos_control_calidad,
        IF(t_ate_gas.fecha_salida IS NOT NULL,'Despachado',IFNULL(IFNULL(tmp_ate_gas_etapa.etapa,tmp_ate_gas_etapa_anterior.etapa),'Pendiente de Envio')) as etapa,
        tmp_almacendetalle_produccion.nombre as ubicacion_produccion,
        t_almacendetalle.nombre as ubicacion,
        tmp_ate_gas_etapa_produccion_tecnicos.tecnico_asignado as tecnico_asignado_produccion,
        t_ate_gas.fecha_programacion_salida,
        t_ate_gas.fecha_salida,
        t_ate_gas.destino_salida,
        t_ate_gas.transportista_salida,
        
        t_ate_gas.created_at,
        IFNULL(tmp_ate_gas_etapa.created_at,tmp_ate_gas_etapa_anterior.created_at) as fecha_creacion_etapa
        
        
        FROM 
        t_ate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        LEFT JOIN tmp_ate_gas_etapa ON t_ate_gas.idate_gas=tmp_ate_gas_etapa.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_anterior ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_anterior.idate_gas
        LEFT JOIN t_ate_gas_ubicacion ON t_ate_gas.idate_gas=t_ate_gas_ubicacion.idate_gas AND t_ate_gas_ubicacion.fecha_salida IS NULL
        LEFT JOIN t_almacendetalle ON t_ate_gas_ubicacion.idalmacendetalle=t_almacendetalle.idalmacendetalle
        LEFT JOIN tmp_ate_gas_etapa_produccion ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_produccion.idate_gas
        INNER JOIN tmp_ate_gas_etapa_produccion_tiempos ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_produccion_tiempos.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_produccion_tecnicos ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_produccion_tecnicos.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_control_calidad_tiempos ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_control_calidad_tiempos.idate_gas
        LEFT JOIN tmp_ate_gas_etapa_produccion_ubicacion_max ON t_ate_gas.idate_gas=tmp_ate_gas_etapa_produccion_ubicacion_max.idate_gas
        LEFT JOIN t_ate_gas_ubicacion as tmp_ate_gas_ubicacion_produccion ON tmp_ate_gas_etapa_produccion_ubicacion_max.idate_gas_ubicacion=tmp_ate_gas_ubicacion_produccion.idate_gas_ubicacion
        LEFT JOIN t_almacendetalle as tmp_almacendetalle_produccion ON tmp_ate_gas_ubicacion_produccion.idalmacendetalle=tmp_almacendetalle_produccion.idalmacendetalle
        WHERE
        t_ate_gas.idalmacen=$idalmacen
        AND t_ate_gas.deleted_at IS NULL
        -- AND CAST(t_ate_gas.fecha_recepcion as DATE) BETWEEN @fecha_inicial AND @fecha_final
        AND t_ate_gas.idcliente=$idcliente
        ORDER BY
        t_ate_gas.created_at DESC;";
        
    $result = $conexion->query($query);
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $inicio_produccion=null;
        $fin_produccion=null;
        $tecnico_produccion=$row['tecnico_asignado_produccion'];
        if($row["tiempos_produccion"]!=''){
            $tiempos_produccion=json_decode($row["tiempos_produccion"], true);
            usort($tiempos_produccion, function($a, $b) {
                return strcmp($a['inicio'], $b['inicio']);
            });
            $inicio_produccion=$tiempos_produccion[0]['inicio'];
            if((int)$row['idestado_etapa_produccion']==4){
                $fin_produccion=$tiempos_produccion[count($tiempos_produccion)-1]['fin'];
            }
            $tecnico_produccion=$tiempos_produccion[count($tiempos_produccion)-1]['usuario'];
        }

        $inicio_control_calidad=null;
        $fin_control_calidad=null;
        if($row["tiempos_control_calidad"]!=''){
            $tiempos_control_calidad=json_decode($row["tiempos_control_calidad"], true);
            usort($tiempos_control_calidad, function($a, $b) {
                return strcmp($a['inicio'], $b['inicio']);
            });
            $inicio_control_calidad=$tiempos_control_calidad[0]['inicio'];
            if((int)$row['idestado_etapa_produccion']==4){
                $fin_control_calidad=$tiempos_control_calidad[count($tiempos_control_calidad)-1]['fin'];
            }
        }

        $reporte_produccion[]=array(
            'cliente'=>$row['cliente'],
            'chasis'=>$row['chasis'],
            'marca'=>$row['marca'],
            'modelo'=>$row['modelo'],
            'configuracion'=>$row['configuracion'],
            'tipo_tanque'=>$row['tipo_tanque'],
            'sede'=>$row['sede'],
            'fecha_recepcion'=>$row['fecha_recepcion'],
            'fecha_inicio_produccion'=>$inicio_produccion,
            'fecha_fin_produccion'=>$fin_produccion,
            'fecha_fin_control_calidad'=>$fin_control_calidad,
            'etapa'=>$row['etapa'],
            'ubicacion_produccion'=>$row['ubicacion_produccion'],
            'ubicacion'=>$row['ubicacion'],
            'tecnico_produccion'=>$tecnico_produccion,
            'fecha_programacion_salida'=>$row['fecha_programacion_salida'],
            'fecha_salida'=>$row['fecha_salida'],
            'destino_salida'=>$row['destino_salida'],
            'transportista_salida'=>$row['transportista_salida'],
        );
    }
        
    
        
    
    $response->getBody()->write(json_encode(array(
        'estado' => 'Exito',
        'codigo' => 200,
        'mensaje' => 'Todo correcto',
        'reporte_produccion'=>$reporte_produccion
    )));

    

    
    return $response->withHeader('Content-Type', 'application/json');
})->add($verifyToken);



function dataForDataBase($dato,$tipo,$obligar_cero=false){
    $respuesta="NULL";
    switch($tipo){
        case 1: // TEXTO
            $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
            break;
        case 2: // FECHA
            $respuesta="NULL";
            $datosplit=explode("/", $dato);
            if(count($datosplit)==3){
                $respuesta="'".$datosplit[2]."-".$datosplit[0]."-".$datosplit[1]."'";
            }
            //$respuesta= count(explode("/", $dato))==3 ? "'".date('Y-m-d', strtotime(str_replace('/', '-', $dato)))."'" : "NULL";
            break;
        case 3: //NUMERO
            $respuesta=$dato<>'' ? (float)$dato : ($obligar_cero ? 0 : "NULL");
            break;
        case 4: // HORA
            $respuesta="NULL";
            $datosplit=explode(" ", $dato);
            if(count($datosplit)==2){
                if($datosplit[1]=="PM"){
                    $horaplit=explode(":", $datosplit[0]);
                    if(count($horaplit)==3){
                        if((int)$horaplit[0]<12){
                            $respuesta="'".($horaplit[0]+12).":".$horaplit[1].":".$horaplit[2]."'";
                        }else{
                            $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
                        }
                    }else{
                        $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
                    }
                }else{
                    $horaplit=explode(":", $datosplit[0]);
                    if(count($horaplit)==3){
                        if((int)$horaplit[0]==12){
                            $respuesta="'00:".$horaplit[1].":".$horaplit[2]."'";
                        }else{
                            $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
                        }
                    }else{
                        $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
                    }
                }
            }else{
                $respuesta=$dato<>'' ? "'".$dato."'" : "NULL";
            }
                
            break;
    }
    return $respuesta;
}

