function getSaldo($idingresodetalle,$conexion){
    $saldo=array('cantidad_saldo'=>0,'peso_saldo'=>0);
    
    $dividido=0;
    $resultdiv = $conexion->query("SELECT 
        t_ingresodetalle.idingresodetalle, 
        t_ingresodetalle.cantidad-IFNULL(SUM(t_salidadetalle.cantidad),0) as cantidad_saldo, 
        t_ingresodetalle.peso-IFNULL(SUM(t_salidadetalle.peso),0) as peso_saldo, 
        IF(t_ingresodetalle.dividido IS NULL,0,1) as dividido
        FROM 
        t_ingresodetalle 
        LEFT JOIN t_salidadetalle ON t_ingresodetalle.idingresodetalle=t_salidadetalle.idingresodetalle
        WHERE 
        t_ingresodetalle.idingresodetalle=$idingresodetalle
        GROUP BY
        t_ingresodetalle.idingresodetalle, 
        t_ingresodetalle.cantidad, 
        t_ingresodetalle.peso, 
        t_ingresodetalle.dividido;");
    while ($rowdiv =  $resultdiv ->fetch(PDO::FETCH_ASSOC)){
        $dividido=(int)$rowdiv["dividido"];
        if((int)$rowdiv["dividido"]==0){
            $saldo['cantidad_saldo']=$saldo['cantidad_saldo']+(float)$rowdiv["cantidad_saldo"];
            $saldo['peso_saldo']=$saldo['peso_saldo']+(float)$rowdiv["peso_saldo"];
        }
    }
    
    if($dividido==1){
        $idingresodetallepadre=$idingresodetalle;
        do {
            $existedivision=0;
            $idingresodetallehijos='0';
            $resultdiv = $conexion->query("SELECT 
                t_ingresodetalle.idingresodetalle, 
                t_ingresodetalle.cantidad-IFNULL(SUM(t_salidadetalle.cantidad),0) as cantidad_saldo, 
                t_ingresodetalle.peso-IFNULL(SUM(t_salidadetalle.peso),0) as peso_saldo, 
                IF(t_ingresodetalle.dividido IS NULL,0,1) as dividido
                FROM 
                t_ingresodetalle 
                LEFT JOIN t_salidadetalle ON t_ingresodetalle.idingresodetalle=t_salidadetalle.idingresodetalle
                WHERE 
                t_ingresodetalle.idingresodetallepadre IN ($idingresodetallepadre)
                GROUP BY
                t_ingresodetalle.idingresodetalle, 
                t_ingresodetalle.cantidad, 
                t_ingresodetalle.peso, 
                t_ingresodetalle.dividido;");
            while ($rowdiv =  $resultdiv ->fetch(PDO::FETCH_ASSOC)){
                $existedivision=$existedivision+(int)$rowdiv["dividido"];
                if((int)$rowdiv["dividido"]==1){
                    $idingresodetallehijos=$idingresodetallehijos.",".$rowdiv["idingresodetalle"];
                }else{
                    $saldo['cantidad_saldo']=$saldo['cantidad_saldo']+(float)$rowdiv["cantidad_saldo"];
                    $saldo['peso_saldo']=$saldo['peso_saldo']+(float)$rowdiv["peso_saldo"];
                }
            }
            $idingresodetallepadre=$idingresodetallehijos;

        } while ($existedivision>0);
    }
        
    return $saldo;
    
}

function getSalida($idsalida,$conexion,$resumen=false){
    $salida=array();
    $result = $conexion->query("SELECT
        t_cliente.idempresa,
        md5(t_salida.idsalida) as idsalida,
        t_salida.numero,
        t_salida.gestion,
        t_salida.idalmacen,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        md5(t_salida.idcliente) as idcliente,
        IFNULL(t_salida.es_vehiculo,0) as es_vehiculo,
        IFNULL(t_salida.movimiento,0) as movimiento,
        IFNULL(t_salida.es_no_conf,0) as es_no_conf,
        t_cliente.cliente,
        md5(t_salida.idpedido) as idpedido,
        t_salida.fecha,
        t_salida.solicitado_por,
        t_salida.autorizado_por,
        t_salida.idmovilizador,
        t_movilizador.movilizador,
        t_salida.delivery_note,
        t_salida.proyecto_no,
        IFNULL(t_salida.contrato_no,'') as contrato_no,
        t_salida.rubro_producto,
        t_salida.ciudad,
        t_salida.direccion_entrega,
        t_salida.idalmacen_destino,
        tmp_almacen_destino.codigo_almacen as codigo_almacen_destino,
        t_salida.transporte,
        t_salida.placa,
        t_salida.cantidad_pallet,
        t_salida.cantidad_cajas,
        t_salida.autorizacion_compra,
        t_salida.tipo_pedido,
        IFNULL(tmp_almacen_destino.almacen,t_salida.almacen_destino) as almacen_destino,
        t_salida.pedido_consolidado,
        IFNULL(t_salida.partida,'') as partida,
        t_salida.hora_inicio_a,
        t_salida.hora_fin_a,
        t_salida.cantidad_estibadores_a,
        t_salida.hora_inicio_cable,
        t_salida.hora_fin_cable,
        t_salida.nota_adicional,
        t_salida.hora_inicio_b,
        t_salida.hora_fin_b,
        t_salida.cantidad_estibadores_b,
        t_salida.idusuario_entrega,
        t_usuario.nombre,
        t_usuario.ci,
        t_salida.nombre_recibido,
        t_salida.ci_recibido,
        t_salida.empresa_recibido,
        t_salida.fecha_recibido,
        IFNULL(t_salida.entrega_a_tiempo,0) as entrega_a_tiempo,
        IFNULL(t_salida.entrega_completa_conforme,0) as entrega_completa_conforme,
        IFNULL(t_salida.finalizado,0) as finalizado,
        t_ingreso.idingreso
        FROM
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario ON t_salida.idusuario_entrega=t_usuario.idusuario
        LEFT JOIN t_almacen ON t_salida.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_almacen as tmp_almacen_destino ON t_salida.idalmacen_destino=tmp_almacen_destino.idalmacen
        LEFT JOIN t_movilizador ON t_salida.idmovilizador=t_movilizador.idmovilizador
        LEFT JOIN t_ingreso ON t_salida.idsalida=t_ingreso.idsalida_origen
        WHERE
        md5(t_salida.idsalida)='$idsalida';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idempresa=$row['idempresa'];
        
        $adjuntos=[];
        $ruta = folder_files.$idempresa.DIRECTORY_SEPARATOR."almacen/adjuntos_salidas/$idsalida/";
        if(file_exists($ruta)){
            $directorio = opendir($ruta);
            $iddocumento=0;
            while ($documento = readdir($directorio)){
                if (!is_dir($documento)){
                    $iddocumento++;
                    $adjuntos[] = array(
                        'iddocumento' => $iddocumento,
                        'documento' => $documento
                    );
                }
            }
        }
        
        $salida=array(
            'idsalida'=>$row['idsalida'],
            'numero'=>(int)$row['numero'],
            'gestion'=>(int)$row['gestion'],
            'numerosalida'=>$row['numero']."/".$row['gestion'],
            //'idalmacen'=>(int)$row['idalmacen'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'idcliente'=>$row['idcliente'],
            'cliente'=>$row['cliente'],
            'es_vehiculo'=> boolval($row['es_vehiculo']),
            'movimiento'=> boolval($row['movimiento']),
            'es_no_conf'=> boolval($row['es_no_conf']),
            'idpedido'=>$row['idpedido'],
            'fecha'=>$row['fecha'],
            'solicitado_por'=>$row['solicitado_por'],
            'autorizado_por'=>$row['autorizado_por'],
            'idmovilizador'=>$row['idmovilizador'],
            'movilizador'=>$row['movilizador'],
            'delivery_note'=>$row['delivery_note'],
            'proyecto_no'=>$row['proyecto_no'],
            'contrato_no'=>$row['contrato_no'],
            'rubro_producto'=>$row['rubro_producto'],
            'ciudad'=>$row['ciudad'],
            'direccion_entrega'=>$row['direccion_entrega'],
            'idalmacen_destino'=>$row['idalmacen_destino'],
            'codigo_almacen_destino'=>$row['codigo_almacen_destino'],
            'transporte'=>$row['transporte'],
            'placa'=>$row['placa'],
            'cantidad_pallet'=>$row['cantidad_pallet'],
            'cantidad_cajas'=>$row['cantidad_cajas'],
            'autorizacion_compra'=>$row['autorizacion_compra'],
            'tipo_pedido'=>$row['tipo_pedido'],
            'almacen_destino'=>$row['almacen_destino'],
            'pedido_consolidado'=>$row['pedido_consolidado'],
            'partida'=>$row['partida'],
            'hora_inicio_a'=>$row['hora_inicio_a'],
            'hora_fin_a'=>$row['hora_fin_a'],
            'cantidad_estibadores_a'=>(int)$row['cantidad_estibadores_a'],
            'hora_inicio_cable'=>$row['hora_inicio_cable'],
            'hora_fin_cable'=>$row['hora_fin_cable'],
            'nota_adicional'=>$row['nota_adicional'],
            'hora_inicio_b'=>$row['hora_inicio_b'],
            'hora_fin_b'=>$row['hora_fin_b'],
            'cantidad_estibadores_b'=>(int)$row['cantidad_estibadores_b'],
            'idusuario_entrega'=>(int)$row['idusuario_entrega'],
            'nombre_entrega'=>$row['nombre'],
            'ci_entrega'=>$row['ci'],
            'nombre_recibido'=>$row['nombre_recibido'],
            'ci_recibido'=>$row['ci_recibido'],
            'empresa_recibido'=>$row['empresa_recibido'],
            'fecha_recibido'=>$row['fecha_recibido'],
            'entrega_a_tiempo'=>boolval($row['entrega_a_tiempo']),
            'entrega_completa_conforme'=>boolval($row['entrega_completa_conforme']),
            'finalizado'=>boolval($row['finalizado']),
            'idingreso'=>(int)$row['idingreso'],
            'detalle'=> getDetalleSalida($idsalida, 0, $conexion, $resumen),
            'adjuntos'=>$adjuntos
        );
    }
    
    return $salida;
}

function getDetalleSalida($idsalida, $unidad_salida, $conexion, $resumen=false){
    $detalle=[];
    
    if($resumen){
        $resultdetalle = $conexion->query("SELECT
            t_ingresodetalle.codigo,
            t_ingresodetalle.descripcion,
            SUM(t_salidadetalle.cantidad) as cantidad,
            t_embalaje.embalaje,
            t_embalaje.codigoembalaje,
            t_ingresodetalle.centro_distribucion
            FROM
            t_salidadetalle
            LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
            LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
            WHERE
            md5(t_salidadetalle.idsalida)='$idsalida' 
            GROUP BY
            t_ingresodetalle.codigo,
            t_ingresodetalle.descripcion,
            t_embalaje.embalaje,
            t_embalaje.codigoembalaje,
            t_ingresodetalle.centro_distribucion;");
        while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
            $detalle[]=array(
                'codigo'=>$rowdetalle['codigo'],
                //'serie'=>$rowdetalle['serie'],
                'descripcion'=>$rowdetalle['descripcion'],
                'cantidad'=>(float)$rowdetalle['cantidad'],
                'embalaje'=>$rowdetalle['embalaje'],
                'codigoembalaje'=>$rowdetalle['codigoembalaje'],
                'centro_distribucion'=>$rowdetalle['centro_distribucion']
            );
        }
    }else{
        $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidadetalle;");
        $conexion->query("CREATE TEMPORARY TABLE tmp_salidadetalle (idingresodetalle INT, cantidad DECIMAL(13,2), bultos INT, cantidad_no_conf DECIMAL(13,2), peso DECIMAL(13,2));");
        $conexion->query("INSERT INTO tmp_salidadetalle (idingresodetalle, cantidad, bultos, cantidad_no_conf, peso)
            SELECT
            t_salidadetalle.idingresodetalle,
            SUM(t_salidadetalle.cantidad) as cantidad,
            SUM(t_salidadetalle.bultos) as bultos,
            SUM(t_salidadetalle.cantidad_no_conf) as cantidad_no_conf,
            SUM(t_salidadetalle.peso) as peso
            FROM
            t_salidadetalle
            LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
            LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle

            GROUP BY
            t_salidadetalle.idingresodetalle;");
        $conexion->query("ALTER TABLE tmp_salidadetalle ADD INDEX idingresodetalle (idingresodetalle);");
        
        $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_accesorios_vehiculos;");
        $conexion->query("CREATE TEMPORARY TABLE tmp_accesorios_vehiculos (idsalidadetalle INT, accesorios_vehiculos TEXT);");
        $conexion->query("INSERT INTO tmp_accesorios_vehiculos (idsalidadetalle, accesorios_vehiculos)
            SELECT
            t_salidadetalle_accesorios.idsalidadetalle,
            JSON_ARRAYAGG(
              JSON_OBJECT(
                  'idaccesorios_vehiculos', t_salidadetalle_accesorios.idaccesorios_vehiculos,
                  'accesorios_vehiculos', t_accesorios_vehiculos.accesorios_vehiculos,
                  'cantidad', t_salidadetalle_accesorios.cantidad,
                  'texto', t_salidadetalle_accesorios.texto
              )
            ) AS accesorios_vehiculos
            FROM
            t_salidadetalle_accesorios
            LEFT JOIN t_salidadetalle ON t_salidadetalle_accesorios.idsalidadetalle=t_salidadetalle.idsalidadetalle
            LEFT JOIN t_accesorios_vehiculos ON t_salidadetalle_accesorios.idaccesorios_vehiculos=t_accesorios_vehiculos.idaccesorios_vehiculos
            WHERE
            md5(t_salidadetalle.idsalida)='$idsalida'
            AND t_salidadetalle_accesorios.deleted_at IS NULL
            GROUP BY
            t_salidadetalle_accesorios.idsalidadetalle;");
        $conexion->query("ALTER TABLE tmp_accesorios_vehiculos ADD INDEX idsalidadetalle (idsalidadetalle);");

        $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidadetalleimagen;");
        $conexion->query("CREATE TEMPORARY TABLE tmp_salidadetalleimagen (idsalidadetalle INT, imagenes INT);");
        $conexion->query("INSERT INTO tmp_salidadetalleimagen (idsalidadetalle, imagenes)
            SELECT
            t_salidadetalleimagen.idsalidadetalle,
            COUNT(t_salidadetalleimagen.idsalidadetalleimagen) AS imagenes
            FROM
            t_salidadetalleimagen
            LEFT JOIN t_salidadetalle ON t_salidadetalleimagen.idsalidadetalle=t_salidadetalle.idsalidadetalle
            WHERE
            md5(t_salidadetalle.idsalida)='$idsalida'
            GROUP BY
            t_salidadetalleimagen.idsalidadetalle;");
        $conexion->query("ALTER TABLE tmp_salidadetalleimagen ADD INDEX idsalidadetalle (idsalidadetalle);");


        $conexion->query("SET @codigo_salida=$unidad_salida;");
        $resultdetalle = $conexion->query("SELECT
            t_salidadetalle.idsalidadetalle,
            t_salidadetalle.idsalida,
            t_salidadetalle.idingresodetalle,
            t_ingresodetalle.codigo,
            t_ingresodetalle.serie,
            t_ingresodetalle.categoria,
            t_ingresodetalle.descripcion,
            t_ingresodetalle.centro_distribucion,
            t_ingresodetalle.costo_un,
            t_salidadetalle.cantidad_no_conf,
            t_ingresodetalle.cantidad_no_conf-IFNULL(tmp_salidadetalle.cantidad_no_conf,0) as cantidad_no_confactual,
            t_no_conf.no_conf,
            t_merma.merma,
            t_ingresodetalle.relacion_caja,
            t_ingresodetalle.fechavencimiento,
            DATEDIFF(t_ingresodetalle.fechavencimiento,CURRENT_DATE()) as diasavencer,
            t_ingresodetalle.lote,
            t_salidadetalle.cantidad,
            t_salidadetalle.cantidad/IFNULL(t_baseproductos.factor_conversion,1) as cantidad_salida,
            IFNULL(t_baseproductos.factor_conversion,1) as factor_conversion,
            t_ingresodetalle.cantidad-IFNULL(tmp_salidadetalle.cantidad,0) as cantidadactual,
            t_ingresodetalle.idembalaje,
            t_embalaje.embalaje,
            t_embalaje.codigoembalaje,
            t_embalaje_salida.embalaje as embalaje_salida,
            t_embalaje_salida.codigoembalaje as codigoembalaje_salida,
            t_salidadetalle.peso,
            t_ingresodetalle.peso-IFNULL(tmp_salidadetalle.peso,0) as pesoactual,
            t_salidadetalle.bultos,
            t_ingresodetalle.bultos-IFNULL(tmp_salidadetalle.bultos,0) as bultosactual,
            t_salidadetalle.temperatura,
            t_ingresodetalle.modelo,
            t_ingresodetalle.marca,
            t_ingresodetalle.color as color_vehiculo,
            t_salidadetalle.observaciones,
            t_almacendetalle.nombre as ubicacionalmacen,
            CONCAT(t_ingreso.numero,'/',t_ingreso.gestion) as numeroingreso,
            IFNULL(t_centro_rubro.rubro,'') as centro_rubro,
            t_salidadetalle.kilometraje,
            IFNULL(t_salidadetalle.tiene_danios,0) as tiene_danios,
            t_salidadetalle.danios,
            IFNULL(t_salidadetalle.tiene_faltante,0) as tiene_faltante,
            t_salidadetalle.faltante,
            IFNULL(tmp_accesorios_vehiculos.accesorios_vehiculos, '[]') as accesorios_vehiculos,
            tmp_salidadetalleimagen.imagenes,
            IF(IFNULL(t_salidadetalle.kilometraje,'')<>'' OR IFNULL(t_salidadetalle.tiene_danios,0)=1 OR IFNULL(t_salidadetalle.tiene_faltante,0)=1,1,0) as con_accesorios
            FROM
            t_salidadetalle
            LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
            LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
            LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
            LEFT JOIN t_no_conf ON t_ingresodetalle.idno_conf=t_no_conf.idno_conf
            LEFT JOIN t_merma ON t_ingresodetalle.idmerma=t_merma.idmerma
            LEFT JOIN tmp_salidadetalle ON t_salidadetalle.idingresodetalle=tmp_salidadetalle.idingresodetalle
            LEFT JOIN t_ubicacionitem ON t_ingresodetalle.idingresodetalle=t_ubicacionitem.idingresodetalle AND t_ubicacionitem.fechasalida IS NULL
            LEFT JOIN t_almacendetalle ON t_ubicacionitem.idalmacendetalle=t_almacendetalle.idalmacendetalle
            LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
            LEFT JOIN t_centro_rubro ON t_salida.idcliente=t_centro_rubro.idcliente AND t_ingresodetalle.centro_distribucion=t_centro_rubro.centro_distribucion
            LEFT JOIN t_baseproductos ON t_ingresodetalle.codigo=t_baseproductos.codigo AND t_ingresodetalle.idembalaje=t_baseproductos.idembalaje AND t_ingreso.idcliente=t_baseproductos.idcliente
            LEFT JOIN t_embalaje as t_embalaje_salida ON t_baseproductos.idembalaje_salida=t_embalaje_salida.idembalaje
            LEFT JOIN tmp_accesorios_vehiculos ON t_salidadetalle.idsalidadetalle=tmp_accesorios_vehiculos.idsalidadetalle
            LEFT JOIN tmp_salidadetalleimagen ON t_salidadetalle.idsalidadetalle=tmp_salidadetalleimagen.idsalidadetalle
            WHERE
            md5(t_salidadetalle.idsalida)='$idsalida'
       	    ORDER BY
            t_salidadetalle.idsalidadetalle;");
        while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
            /*
            $embalaje=$rowdetalle['embalaje'];
            $codigoembalaje=$rowdetalle['codigoembalaje'];
