function generarConstanciaIngreso($idingreso, $conexion){
    $result = $conexion->query("SELECT 
        t_cliente.idempresa,
        t_ingreso.numero,
        t_ingreso.gestion,
        t_ingreso.fecha,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        tmp_almacen_origen.codigo_almacen as codigo_almacen_origen,
        tmp_almacen_origen.almacen as almacen_origen,
        t_movilizador.movilizador,
        md5(t_ingreso.idsalida_origen) as idsalida_origen
        FROM 
        t_ingreso 
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN t_almacen ON t_ingreso.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_salida ON t_ingreso.idsalida_origen=t_salida.idsalida
        LEFT JOIN t_almacen as tmp_almacen_origen ON t_salida.idalmacen=tmp_almacen_origen.idalmacen
        LEFT JOIN t_movilizador ON t_salida.idmovilizador=t_movilizador.idmovilizador
        WHERE 
        t_ingreso.idingreso=$idingreso;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idempresa=$row['idempresa'];
        $numero=$row['numero'];
        $gestion=$row['gestion'];
        $fecha=$row['fecha'];
        $codigo_almacen=$row['codigo_almacen'];
        $almacen=$row['almacen'];
        $codigo_almacen_origen=$row['codigo_almacen_origen'];
        $almacen_origen=$row['almacen_origen'];
        $movilizador=$row['movilizador'];
        $idsalida_origen=$row['idsalida_origen'];
    }
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
    
    $cabecera='<table border="0" cellspacing="0" cellpadding="3" width="100%">
            <tr>
                <td width="100%" align="center">
                    <b>
                        <font style="font-family: Helvetica; font-size: 14pt">CONSTANCIA DE INGRESO</font>
                    </b><br />
                    <font style="font-family: Helvetica; font-size: 10pt">ID: '.$numero.'/'.$gestion.'</font><br />
                    <font style="font-family: Helvetica; font-size: 10pt">Fecha: '.date("d/m/Y H:i:s", strtotime($fecha)).'</font>
                </td>
            </tr>
        </table>
        ';
    $html='<hr /><table border="0" cellspacing="3" cellpadding="4" width="100%">
                <tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">INFORMACIÓN DE LA TRANSFERENCIA</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">SALÓN ORIGEN<br />'.$codigo_almacen_origen.' '.$almacen_origen.'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">SALÓN DESTINO<br />'.$codigo_almacen.' '.$almacen.'</font>
                    </td>
                </tr>
                
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MOVILIZADOR<br />'.$movilizador.'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">ESTADO<br />Recepcionado</font>
                    </td>
                </tr>';
    
    $detalle=getDetalleSalida($idsalida_origen, 0, $conexion, false);
    
    for($it=0;$it<count($detalle);$it++){
        $html=$html.'<tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">'.($it+1).'. DETALLES DEL VEHÍCULO</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">CHASIS (VIN)<br />'.$detalle[$it]["serie"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MARCA<br />'.$detalle[$it]["marca"].'</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MODELO<br />'.$detalle[$it]["modelo"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">COLOR<br />'.$detalle[$it]["color_vehiculo"].'</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MOTOR<br />'.$detalle[$it]["modelo"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">KILOMETRAJE<br />'.$detalle[$it]["kilometraje"].'</font>
                    </td>
                </tr>
                <tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">INVENTARIO DEL VEHÍCULO</font>
                    </td>
                </tr>
                <tr>
                    <td colspan="2">
                        <table border="0" cellspacing="0" cellpadding="3" width="100%">
                ';
                $columnas=1;
                $resultaccesorio = $conexion->query("select 
                    * 
                    from 
                    t_accesorios_vehiculos;");
                while ($rowaccesorio =  $resultaccesorio ->fetch(PDO::FETCH_ASSOC)){
                    if($columnas==1){
                        $html=$html.'<tr>';
                    }
                    $index = array_search((int)$rowaccesorio["idaccesorios_vehiculos"], array_column($detalle[$it]["accesorios_vehiculos"], 'idaccesorios_vehiculos'));
                    $marcado="";
                    $cantidad="";
                    if(is_numeric($index)){
                        $marcado='checked="checked"';
                        if((int)$rowaccesorio["requiere_cantidad"]==1){
                            $cantidad=" (".$detalle[$it]["accesorios_vehiculos"][$index]["cantidad"].")";
                        }
                    }
                    $html=$html.'<td width="33%"><input type="checkbox" '.$marcado.' /><font style="font-family: Helvetica; font-size: 10pt;">'.$rowaccesorio["accesorios_vehiculos"].$cantidad.'</font></td>';
                    if($columnas==3){
                        $html=$html.'</tr>';
                    }
                    $columnas=($columnas==3) ? 1 : $columnas+1;

                }
                $html=$html.'</table>';
                $html=$html.'</td></tr>';
        
    }
    
    
    $html=$html.'</table>';
    
    
    $piedepagina='<div align="right"><font style="font-family: Helvetica; font-size: 7pt">{PAGENO}/{nbpg}</font></div>';
        
    $firma='<br />
    <table border="0" cellspacing="0" cellpadding="0" width="100%">
        <tr>
            <td width="45%" align="center">
                <table border="0">
                    <tr>
                        <td colspan="3">&nbsp;<br />&nbsp;</td>
                    </tr>
                    <tr>
                        <td width="50">&nbsp;</td>
                        <td width="200" style="border-top-style: solid; border-top-width: 1pt;"><font style="font-family: Helvetica; font-size: 7pt">Nombre y Firma<br />Entregue Conforme<br />'.$almacen_origen.'</font></td>
                        <td width="50">&nbsp;</td>
                    </tr>
                </table>
            </td>
            <td width="10%">&nbsp;</td>
            <td width="45%" align="center">
                <table border="0" width="300">
                    <tr>
                        <td colspan="3">&nbsp;<br />&nbsp;</td>
                    </tr>
                    <tr>
                        <td width="50">&nbsp;</td>
                        <td width="200" style="border-top-style: solid; border-top-width: 1pt;"><font style="font-family: Helvetica; font-size: 7pt">Nombre y Firma<br />Recibi Conforme<br />Movilizador: '.$movilizador.'</font></td>
                        <td width="50">&nbsp;</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>';
    
    
    $mpdf = new \Mpdf\Mpdf([
        'mode' => 'utf-8',
        'format' => 'Letter',
        'orientation' => 'P',
        'margin_left' => 15,
        'margin_right'=> 15,
        'margin_top'=> 25,
        'margin_bottom'=> 16,
        'margin_header'=> 9,
        'margin_footer'=> 12
    ]);
    $mpdf->SetHTMLHeader($cabecera);
    $mpdf->WriteHTML($html);
    $mpdf->SetHTMLFooter($firma.$piedepagina);
    
    $mpdf->Output(folder_files.$idempresa.DIRECTORY_SEPARATOR."documentos/constanciaingreso/constanciaingreso$idingreso.pdf");
}

function generarActaSalida($idsalida, $unidad_salida, $conexion, $membretado = false){
    $idsalidanum=0;
    $resultsalida = $conexion->query("SELECT idsalida FROM t_salida WHERE md5(idsalida)='$idsalida';");
    while ($rowsalida =  $resultsalida ->fetch(PDO::FETCH_ASSOC)){
        $idsalidanum=$rowsalida['idsalida'];
    }
    
    
    $result = $conexion->query("SELECT
        t_cliente.idempresa,
        t_salida.numero,
        t_salida.gestion,
        t_cliente.cliente,
        DATE_FORMAT(t_salida.hora_inicio_a,'%H:%i') as hora_inicio_a,
        DATE_FORMAT(t_salida.hora_fin_a,'%H:%i') as hora_fin_a,
        LEFT(TIMEDIFF(t_salida.hora_fin_a,t_salida.hora_inicio_a),5) as horas_a,
        t_salida.cantidad_estibadores_a,
        DATE_FORMAT(t_salida.hora_inicio_cable,'%H:%i') as hora_inicio_cable,
        DATE_FORMAT(t_salida.hora_fin_cable,'%H:%i') as hora_fin_cable,
        LEFT(TIMEDIFF(t_salida.hora_fin_cable,t_salida.hora_inicio_cable),5) as horas_cable,
        DATE_FORMAT(t_salida.fecha,'%d/%m/%Y') as fecha,
        t_salida.solicitado_por,
        t_salida.autorizado_por,
        t_salida.delivery_note,
        t_salida.proyecto_no,
        t_salida.contrato_no,
        t_salida.direccion_entrega,
        t_salida.transporte,
        t_salida.placa,
        t_salida.ciudad,
        DATE_FORMAT(t_salida.hora_inicio_b,'%H:%i') as hora_inicio_b,
        DATE_FORMAT(t_salida.hora_fin_b,'%H:%i') as hora_fin_b,
        LEFT(TIMEDIFF(t_salida.hora_fin_b,t_salida.hora_inicio_b),5) as horas_b,
        t_salida.cantidad_estibadores_b,
        t_usuario.nombre,
        t_usuario.ci,
        t_salida.nombre_recibido,
        t_salida.ci_recibido,
        t_salida.empresa_recibido,
        DATE_FORMAT(t_salida.fecha_recibido,'%d/%m/%Y') as fecha_recibido,
        t_salida.nota_adicional
        FROM
        t_salida
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario ON t_salida.idusuario_entrega=t_usuario.idusuario
        WHERE t_salida.idsalida=$idsalidanum;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $numero=$row["numero"];
        $gestion=$row["gestion"];
        $cliente=$row["cliente"];
        $hora_inicio_a=$row["hora_inicio_a"];
