        $horas_a=$row["horas_a"];
        $cantidad_estibadores_a=$row["cantidad_estibadores_a"];
        $hora_inicio_cable=$row["hora_inicio_cable"];
        $hora_fin_cable=$row["hora_fin_cable"];
        $horas_cable=$row["horas_cable"];
        $fecha=$row["fecha"];
        $solicitado_por=$row["solicitado_por"];
        $autorizado_por=$row["autorizado_por"];
        $delivery_note=$row["delivery_note"];
        $proyecto_no=$row["proyecto_no"];
        $contrato_no=$row["contrato_no"];
        $direccion_entrega=$row["direccion_entrega"];
        $transporte=$row['transporte'];
        $placa=$row['placa'];
        $ciudad=$row["ciudad"];
        $hora_inicio_b=$row["hora_inicio_b"];
        $hora_fin_b=$row["hora_fin_b"];
        $horas_b=$row["horas_b"];
        $cantidad_estibadores_b=$row["cantidad_estibadores_b"];
        $nombre=$row["nombre"];
        $ci=$row["ci"];
        $nombre_recibido=$row["nombre_recibido"];
        $ci_recibido=$row["ci_recibido"];
        $empresa_recibido=$row["empresa_recibido"];
        $fecha_recibido=$row["fecha_recibido"];
        $nota_adicional=$row["nota_adicional"];
        $idempresa=$row['idempresa'];
    }
    
    $creacion=new Carpetas();
