function generarConstanciaSalida($idsalida, $conexion){
    $idsalidanum=0;
    $idempresa=0;
    $idcliente=0;
    $resultsalida = $conexion->query("SELECT 
        t_salida.idsalida,
        t_cliente.idempresa,
        t_salida.idcliente
        FROM 
        t_salida 
        LEFT JOIN t_cliente ON t_salida.idcliente=t_cliente.idcliente
        WHERE 
        md5(t_salida.idsalida)='$idsalida';");
    while ($rowsalida =  $resultsalida ->fetch(PDO::FETCH_ASSOC)){
        $idsalidanum=$rowsalida['idsalida'];
        $idempresa=$rowsalida['idempresa'];
        $idcliente=$rowsalida['idcliente'];
    }
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);
    
    $salida= getSalida($idsalida, $conexion);
    
    $estado="Pendiente de Finalización";
    if($salida["finalizado"]){
        $estado="Pendiente de Recepción";
    }
    
    $cabecera='<table border="0" cellspacing="0" cellpadding="3" width="100%">
            <tr>
                <td width="100%" align="center">
                    <b>
                        <font style="font-family: Helvetica; font-size: 14pt">CONSTANCIA DE SALIDA DE VEHICULO</font>
                    </b><br />
                    <font style="font-family: Helvetica; font-size: 10pt">ID: '.$salida["numero"].'/'.$salida["gestion"].'</font><br />
                    <font style="font-family: Helvetica; font-size: 10pt">Fecha: '.date("d/m/Y H:i:s", strtotime($salida["fecha"])).'</font>
                </td>
            </tr>
        </table>
        ';
    $html='<hr /><table border="0" cellspacing="3" cellpadding="4" width="100%">
                <tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">INFORMACIÓN DE LA TRANSFERENCIA</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">SALÓN ORIGEN<br />'.$salida["codigo_almacen"].' '.$salida["almacen"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">SALÓN DESTINO<br />'.$salida["codigo_almacen_destino"].' '.$salida["almacen_destino"].'</font>
                    </td>
                </tr>
                
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MOVILIZADOR<br />'.$salida["movilizador"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">ESTADO<br />'.$estado.'</font>
                    </td>
                </tr>';
    $salidadetalle=$salida["detalle"] ?? [];
    for($it=0;$it<count($salidadetalle);$it++){
        $html=$html.'<tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">'.($it+1).'. DETALLES DEL VEHÍCULO</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">CHASIS (VIN)<br />'.$salidadetalle[$it]["serie"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MARCA<br />'.$salidadetalle[$it]["marca"].'</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MODELO<br />'.$salidadetalle[$it]["modelo"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">COLOR<br />'.$salidadetalle[$it]["color_vehiculo"].'</font>
                    </td>
                </tr>
                <tr>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">MOTOR<br />'.$salidadetalle[$it]["modelo"].'</font>
                    </td>
                    <td width="50%">
                        <font style="font-family: Helvetica; font-size: 9pt;">KILOMETRAJE<br />'.$salidadetalle[$it]["kilometraje"].'</font>
                    </td>
                </tr>
                <tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
                        <font style="font-family: Helvetica; font-size: 10pt;">INVENTARIO DEL VEHÍCULO</font>
                    </td>
                </tr>
                <tr>
                    <td colspan="2">
                        <table border="0" cellspacing="0" cellpadding="3" width="100%">
                ';
                $columnas=1;
                $resultaccesorio = $conexion->query("select 
                    * 
                    from 
                    t_accesorios_vehiculos
                    WHERE idcliente=$idcliente;");
                while ($rowaccesorio =  $resultaccesorio ->fetch(PDO::FETCH_ASSOC)){
                    if($columnas==1){
                        $html=$html.'<tr>';
                    }
                    $index = array_search((int)$rowaccesorio["idaccesorios_vehiculos"], array_column($salidadetalle[$it]["accesorios_vehiculos"], 'idaccesorios_vehiculos'));
                    $marcado="";
                    $cantidad="";
                    //$especifique="";
                    if(is_numeric($index)){
                        $marcado='checked="checked"';
                        if((int)$rowaccesorio["requiere_texto"]==1){
                            $cantidad=" (".$salidadetalle[$it]["accesorios_vehiculos"][$index]["texto"].")";
                        }
                        if((int)$rowaccesorio["requiere_cantidad"]==1){
                            $cantidad=" (".$salidadetalle[$it]["accesorios_vehiculos"][$index]["texto"].": ".$salidadetalle[$it]["accesorios_vehiculos"][$index]["cantidad"].")";
                        }
                    }
                    $html=$html.'<td width="33%"><input type="checkbox" '.$marcado.' /><font style="font-family: Helvetica; font-size: 10pt;">'.$rowaccesorio["accesorios_vehiculos"].$cantidad.'</font></td>';
                    if($columnas==3){
                        $html=$html.'</tr>';
                    }
                    $columnas=($columnas==3) ? 1 : $columnas+1;

                }
                $html=$html.'</table>';
                $html=$html.'</td></tr>';

                $texto_danios="No se ha registrado ningún daño en el vehículo";
                $texto_faltantes="No se ha registrado ningún faltante en el vehículo";
