                    $texto_danios=$salidadetalle[$it]["danios"];
                }
                if($salidadetalle[$it]["tiene_faltante"]){
                    $texto_faltantes=$salidadetalle[$it]["faltante"];
                }

                $html=$html.'<tr>
                    <td colspan="2" style="background-color: #CCCCCC; border-left-style: solid; border-left-width: 2pt;">
