                        <td width="50">&nbsp;</td>
                    </tr>
                </table>
            </td>
            <td width="10%">&nbsp;</td>
            <td width="45%" align="center">
                <table border="0" width="300">
                    <tr>
                        <td colspan="3">&nbsp;<br />&nbsp;</td>
                    </tr>
                    <tr>
                        <td width="50">&nbsp;</td>
                        <td width="200" style="border-top-style: solid; border-top-width: 1pt;"><font style="font-family: Helvetica; font-size: 7pt">Nombre y Firma<br />Recibi Conforme<br />Movilizador: '.$salida["movilizador"].'</font></td>
                        <td width="50">&nbsp;</td>
                    </tr>
                </table>
            </td>
        </tr>
    </table>';
    
    
    $mpdf = new \Mpdf\Mpdf([
        'mode' => 'utf-8',
        'format' => 'Letter',
        'orientation' => 'P',
        'margin_left' => 15,
        'margin_right'=> 15,
        'margin_top'=> 25,
        'margin_bottom'=> 16,
        'margin_header'=> 9,
        'margin_footer'=> 12
    ]);
    $mpdf->SetHTMLHeader($cabecera);
    $mpdf->WriteHTML($html);
    $mpdf->SetHTMLFooter($firma.$piedepagina);
    
    $mpdf->Output(folder_files.$idempresa.DIRECTORY_SEPARATOR."documentos/constanciasalida/constanciasalida$idsalidanum.pdf");
}

function getDetalleItem($idingresodetalle,$conexion){
    $cantidadinicial=0;
    $bultosinicial=0;
    $pesoinicial=0;
    $cantidad_no_confinicial=0;
    $codigo='';
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidas;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidas (idingresodetalle INT, cantidad DECIMAL(13,2), bultos DECIMAL(13,0), peso DECIMAL(13,2), cantidad_no_conf DECIMAL(13,2));");
    $conexion->query("INSERT INTO tmp_salidas (idingresodetalle, cantidad, bultos, peso, cantidad_no_conf)
        SELECT 
        t_salidadetalle.idingresodetalle,
        SUM(t_salidadetalle.cantidad) as cantidad, 
        SUM(t_salidadetalle.bultos) as bultos, 
        SUM(t_salidadetalle.peso) as peso,
        SUM(t_salidadetalle.cantidad_no_conf) as cantidad_no_conf 
        from 
        t_salidadetalle 
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        WHERE 
        t_salidadetalle.idingresodetalle=$idingresodetalle
        AND IFNULL(t_salida.finalizado,0)=1
        GROUP BY
        t_salidadetalle.idingresodetalle;");
    $conexion->query("ALTER TABLE tmp_salidas ADD INDEX idingresodetalle (idingresodetalle);");
    
    $result = $conexion->query("SELECT 
        t_ingresodetalle.codigo, 
        t_ingresodetalle.idingresodetalle, 
        IFNULL(t_ingresodetalle.cantidad,0)-IFNULL(tmp_salidas.cantidad,0) as cantidad, 
        IFNULL(t_ingresodetalle.bultos,0)-IFNULL(tmp_salidas.bultos,0) as bultos, 
        IFNULL(t_ingresodetalle.peso,0)-IFNULL(tmp_salidas.peso,0) as peso,
        IFNULL(t_ingresodetalle.cantidad_no_conf,0)-IFNULL(tmp_salidas.cantidad_no_conf,0) as cantidad_no_conf
        from 
        t_ingresodetalle 
        LEFT JOIN tmp_salidas ON t_ingresodetalle.idingresodetalle=tmp_salidas.idingresodetalle
        WHERE 
        t_ingresodetalle.idingresodetalle=$idingresodetalle;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        /*
        $cantidadinicial=$row['cantidad'];
        $bultosinicial=$row['bultos'];
        $pesoinicial=$row['peso'];
        $codigo=$row['codigo'];
        */
        $detalle_item=array(
            'idingresodetalle'=>$idingresodetalle,
            'codigo'=>$row['codigo'],
            'cantidadactual'=>$row['cantidad'],
            'bultosactual'=>$row['bultos'],
            'pesoactual'=>$row['peso'],
            'cantidad_no_confactual'=>$row['cantidad_no_conf']
        );
    }
    
    /*
    $cantidadextraida=0;
    $bultosextraida=0;
    $pesoextraida=0;
    $result = $conexion->query("SELECT 
        SUM(t_salidadetalle.cantidad) as cantidad, 
        SUM(t_salidadetalle.bultos) as bultos, 
        SUM(t_salidadetalle.peso) as peso 
        from 
        t_salidadetalle 
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        WHERE 
        t_salidadetalle.idingresodetalle=$idingresodetalle
        AND IFNULL(t_salida.finalizado,0)=1");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $cantidadextraida=$row['cantidad'];
        $bultosextraida=$row['bultos'];
        $pesoextraida=$row['peso'];
    }
    */
    //$detalle_item=[];
    /*
    $detalle_item=array(
        'idingresodetalle'=>$idingresodetalle,
        'codigo'=>$codigo,
        'cantidadactual'=>($cantidadinicial-$cantidadextraida),
        'bultosactual'=>($bultosinicial-$bultosextraida),
        'pesoactual'=>($pesoinicial-$pesoextraida)
    );
    */
    return $detalle_item;
    
}
