        CONCAT(t_ingresodetalle.fechavencimiento,' 12:00:00') as fechavencimiento,
        DATEDIFF(t_ingresodetalle.fechavencimiento,CURRENT_DATE()) as diasavencer,
        IFNULL(t_clientediasvencimiento.diasvencimiento,dv.diasvencimiento) as diasvencimiento,
        IF(t_ingresodetalle.fechavencimiento IS NULL,1, IF(DATEDIFF(t_ingresodetalle.fechavencimiento,CURRENT_DATE())>=IFNULL(t_clientediasvencimiento.diasvencimiento,dv.diasvencimiento),1,0)) as vancimientohabilitado,
        t_ingresodetalle.relacion_caja,
        t_ingresodetalle.volumen,
        0 as bultos,
        0 as peso,
        t_ingresodetalle.temperatura,
        t_ingresodetalle.observaciones,
        t_almacendetalle.idalmacendetalle,
        t_almacendetalle.texto as ubicacionalmacencorto,
        t_almacendetalle.nombre as ubicacionalmacen,
        t_almacendetalle.orden,
        t_tipoalmacendetalle.tipoalmacendetalle,
        t_categoriaalmacendetalle.categoriaalmacendetalle,
        IFNULL(IFNULL(t_baseproductos.color,t_cliente.color),'transparent') as color,
        IFNULL(t_referenciacolor.referenciacolor,t_cliente.cliente) as referenciacolor,
        IF(IFNULL(t_referenciacolor.idreferenciacolor,0)=0,CONCAT('1_',t_ingreso.idcliente),CONCAT('2_',t_referenciacolor.idreferenciacolor)) as idreferenciacolor,
        '[]' as salidaspendientes,
        tmp_utlimasalida.fecha_ultima_salida,
        IF(t_ingresodetalle.dividido IS NULL,0,1) as dividido,
        CAST(t_ingresodetalle.dividido as DATE) as fechadividido,
        t_ingresodetalle.idingresodetallepadre,
        IFNULL(t_cliente.dias_por_vencer,60) as dias_por_vencer,
        IFNULL(t_ingresodetalle.cerrado,0) as cerrado,
        IFNULL(t_embalaje_salida.codigoembalaje,t_embalaje.codigoembalaje) as codigoembalaje_salida,
        IFNULL(t_baseproductos.factor_conversion,1) as factor_conversion
        FROM
        t_ingresodetalle
        LEFT JOIN t_ingreso ON t_ingresodetalle.idingreso=t_ingreso.idingreso
        LEFT JOIN t_cliente ON t_ingreso.idcliente=t_cliente.idcliente
        LEFT JOIN t_tipocamion ON t_ingreso.idtipocamion=t_tipocamion.idtipocamion
        LEFT JOIN t_tipoingreso ON t_ingreso.idtipoingreso=t_tipoingreso.idtipoingreso
        LEFT JOIN t_tipocontenedor ON t_ingreso.idtipocontenedor=t_tipocontenedor.idtipocontenedor
        LEFT JOIN t_tipodescarga ON t_ingreso.idtipodescarga=t_tipodescarga.idtipodescarga
        LEFT JOIN t_tipoproducto ON t_ingreso.idtipoproducto=t_tipoproducto.idtipoproducto
        LEFT JOIN t_usuario ON t_ingreso.idusuario_recibido=t_usuario.idusuario
        LEFT JOIN t_embalaje ON t_ingresodetalle.idembalaje=t_embalaje.idembalaje
        LEFT JOIN t_no_conf ON t_ingresodetalle.idno_conf=t_no_conf.idno_conf
        LEFT JOIN t_merma ON t_ingresodetalle.idmerma=t_merma.idmerma
        LEFT JOIN tmp_utlimasalida ON t_ingresodetalle.idingresodetalle=tmp_utlimasalida.idingresodetalle
        LEFT JOIN t_ubicacionitem ON t_ingresodetalle.idingresodetalle=t_ubicacionitem.idingresodetalle AND t_ubicacionitem.fechasalida IS NULL
        LEFT JOIN t_almacendetalle ON t_ubicacionitem.idalmacendetalle=t_almacendetalle.idalmacendetalle
        LEFT JOIN t_tipoalmacendetalle ON t_almacendetalle.idtipoalmacendetalle=t_tipoalmacendetalle.idtipoalmacendetalle
        LEFT JOIN t_categoriaalmacendetalle ON t_almacendetalle.idcategoriaalmacendetalle=t_categoriaalmacendetalle.idcategoriaalmacendetalle
        LEFT JOIN t_clientediasvencimiento ON t_clientediasvencimiento.idclientediasvencimiento=(SELECT idclientediasvencimiento FROM t_clientediasvencimiento WHERE CONCAT(t_clientediasvencimiento.idcliente,'-',t_clientediasvencimiento.rubro_producto)=CONCAT(t_ingreso.idcliente,'-',t_ingreso.rubro_producto) ORDER BY idclientediasvencimiento DESC LIMIT 1)
        JOIN (select * FROM t_diasvencimiento ORDER BY iddiasvencimiento LIMIT 1) as dv
        LEFT JOIN t_baseproductos ON t_ingresodetalle.codigo=t_baseproductos.codigo AND t_ingreso.idcliente=t_baseproductos.idcliente AND t_ingresodetalle.idembalaje=t_baseproductos.idembalaje
        LEFT JOIN t_referenciacolor ON UPPER(t_baseproductos.color)=UPPER(t_referenciacolor.color) AND t_baseproductos.idcliente=t_referenciacolor.idcliente
        LEFT JOIN t_embalaje as t_embalaje_salida ON t_baseproductos.idembalaje_salida=t_embalaje_salida.idembalaje
        WHERE
        CAST(t_ingreso.fecha as DATE)<=CURRENT_DATE()
        AND t_ingreso.idalmacen=$idalmacen
        AND IFNULL(t_ingresodetalle.cerrado,0)=1
        AND t_ingresodetalle.dividido IS NULL
        $filtroclienteingresos
        ORDER BY
        codigo,
        CASE IFNULL(fechavencimiento_real,'1979-11-06')
            WHEN '1979-11-06' THEN 2
            ELSE IF(fechavencimiento_real>=CURRENT_DATE(),0,3)
        END,
        fechavencimiento_real,
        fechaingreso,
        orden,
        ubicacionalmacen");
