function getInventario($idcliente,$idalmacen,$fechacorte,$conexion,$externo=false, $corte=false, $fecha_para_vencimiento, $finalizado=false){
    
    $filtroclienteingresos="";
    $filtroclientesalidas="";
    
    if($idcliente<>'0'){
        $result = $conexion->query("SELECT idcliente FROM t_cliente WHERE md5(idcliente)='$idcliente';");
        while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
            $idclientenum= $row["idcliente"];
        }

        if((int)$idclientenum>0){
            $filtroclienteingresos=" AND t_ingreso.idcliente=$idclientenum ";
        }

        if((int)$idclientenum>0){
            $filtroclientesalidas=" AND t_salida.idcliente=$idclientenum ";
        }
    }
    
    $filtrofinalizado="";
    if($finalizado){
        $filtrofinalizado=" AND IFNULL(t_salida.finalizado,0)=1";
    }
        
    
    $inventario=[];
    
    $filtrocortesalida='';
    if($corte){
        $fechasep= explode(" ", $fechacorte);
        if(count($fechasep)==1){
            $filtrocortesalida=" AND CAST(t_salida.fecha as DATE)<='$fechacorte'";
        }else{
            $filtrocortesalida=" AND t_salida.fecha<='$fechacorte'";
        }
    }
    
    $fechasep= explode(" ", $fechacorte);
    if(count($fechasep)==1){
        $fechacortefiltro_externo=" AND CAST(t_salida.fecha as DATE)>'$fechacorte'";
        $fechacortefiltro_matriz="CAST(t_ingreso.fecha as DATE)<='$fechacorte'";
        $campo_dividido="CAST(t_ingresodetalle.dividido as DATE)";
    }else{
        $fechacortefiltro_externo=" AND t_salida.fecha>'$fechacorte'";
        $fechacortefiltro_matriz="t_ingreso.fecha<='$fechacorte'";
        $campo_dividido="t_ingresodetalle.dividido";
    }
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidadetalle;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidadetalle (idingresodetalle INT, cantidad DECIMAL(13,2), bultos INT, peso DECIMAL(13,2), cantidad_no_conf DECIMAL(13,2), fecha_ultima_salida DATE);");
    $conexion->query("INSERT INTO tmp_salidadetalle (idingresodetalle, cantidad, bultos, peso, cantidad_no_conf, fecha_ultima_salida)
        SELECT
        t_salidadetalle.idingresodetalle,
        SUM(t_salidadetalle.cantidad) as cantidad,
        SUM(t_salidadetalle.bultos) as bultos,
        SUM(t_salidadetalle.peso) as peso,
        SUM(t_salidadetalle.cantidad_no_conf) as cantidad_no_conf,
        MAX(t_salida.fecha) as fecha_ultima_salida
        FROM
        t_salidadetalle
        LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
        LEFT JOIN t_ingresodetalle ON t_salidadetalle.idingresodetalle=t_ingresodetalle.idingresodetalle
        WHERE
        t_salida.idalmacen=$idalmacen
        $filtrocortesalida
        $filtroclientesalidas
        $filtrofinalizado
        GROUP BY
        t_salidadetalle.idingresodetalle;");
    $conexion->query("ALTER TABLE tmp_salidadetalle ADD INDEX idingresodetalle (idingresodetalle);");
    
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_salidaspendientes;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_salidaspendientes (idingresodetalle INT, salidaspendientes TEXT);");
    if(!$externo){
        $conexion->query("INSERT INTO tmp_salidaspendientes (idingresodetalle, salidaspendientes)
            SELECT
            t_salidadetalle.idingresodetalle,
            GROUP_CONCAT(CONCAT('{\"idalida\": ',t_salida.idsalida,', \"numero\": ',t_salida.numero,', \"gestion\": ',t_salida.gestion,', \"fecha\": \"',t_salida.fecha,'\"}') ORDER BY t_salida.fecha, t_salida.numero SEPARATOR ',') as salidaspendientes
            FROM
            t_salidadetalle
            LEFT JOIN t_salida ON t_salidadetalle.idsalida=t_salida.idsalida
            WHERE
            (IFNULL(t_salida.finalizado,0)=0 OR (IFNULL(t_salida.finalizado,0)=1 $fechacortefiltro_externo))
            $filtroclientesalidas
            GROUP BY
            t_salidadetalle.idingresodetalle;");
    }
        
    $conexion->query("ALTER TABLE tmp_salidaspendientes ADD INDEX idingresodetalle (idingresodetalle);");
    
    $matrizmadre=[];
    $result = $conexion->query("SELECT
        t_ingresodetalle.idingresodetalle,
        t_ingresodetalle.idingreso,
        md5(t_ingreso.idcliente) as idcliente,
        t_cliente.cliente,
        CONCAT(t_ingreso.numero,'/',t_ingreso.gestion) as numeroingreso,
        t_ingreso.fecha as fechaingreso,
        t_ingreso.placa,
        t_ingreso.contenedor,
        t_ingreso.idtipoingreso,
        t_tipoingreso.tipoingreso,
        t_ingreso.precinto,
        t_ingreso.idtipodescarga,
        t_tipodescarga.tipodescarga,
        t_ingreso.idtipocamion,
        t_tipocamion.tipocamion,
        t_ingreso.idtipocontenedor,
        t_ingreso.idtipoproducto,
        t_tipoproducto.tipoproducto,
        t_tipocontenedor.tipocontenedor,
        t_ingreso.piezas_manifestadas,
        t_ingreso.peso_total,
        t_ingreso.proveedor,
        t_ingreso.no_contrato,
        t_ingreso.delivery_batch,
        t_ingreso.rubro_producto,
        t_ingreso.project,
        t_ingreso.invoice,
        t_ingreso.dui,
        t_ingreso.cantidad_pallet,
        t_ingreso.cantidad_cajas,
        t_ingreso.hora_inicio,
        t_ingreso.hora_fin,
        t_ingreso.cantidad_estibadores,
        t_ingreso.nota_adicional,
        t_ingreso.idusuario_recibido,
        t_usuario.nombre as usuario_recibido,
        CONCAT(t_ingreso.fechasistema,' ',t_ingreso.horasistema) as fechasistema,
        t_ingreso.nombre_entrega,
        t_ingreso.ci_entrega,
        t_ingreso.empresa_entrega,
        t_ingresodetalle.codigo,
        t_ingresodetalle.serie,
        t_ingresodetalle.descripcion,
        t_ingresodetalle.centro_distribucion,
        IFNULL(t_ingresodetalle.sustanciascontroladas,0) as sustanciascontroladas,
        t_ingresodetalle.categoria,
        t_ingresodetalle.cantidad-IFNULL(tmp_salidadetalle.cantidad,0) as cantidad,
        t_ingresodetalle.idembalaje,
        t_embalaje.codigoembalaje,
        t_ingresodetalle.lote,
        t_ingresodetalle.costo_un,
        t_ingresodetalle.cantidad_no_conf-IFNULL(tmp_salidadetalle.cantidad_no_conf,0) as cantidad_no_conf,
        t_ingresodetalle.idno_conf,
        t_no_conf.no_conf,
