                'idno_conf'=>$matrizmadre[$ii]['idno_conf'],
                'no_conf'=>$matrizmadre[$ii]['no_conf'],
                'idclasificacion'=>$matrizmadre[$ii]['idclasificacion'],
                'clasificacion'=>$matrizmadre[$ii]['clasificacion'],
                'idmerma'=>$matrizmadre[$ii]['idmerma'],
                'merma'=>$matrizmadre[$ii]['merma'],
                //'fechaproduccion'=>$matrizmadre[$ii]['fechaproduccion'],
                'fechavencimiento'=>$matrizmadre[$ii]['fechavencimiento'],
                'diasavencer'=>$matrizmadre[$ii]['diasavencer'],
                'diasvencimiento'=>$matrizmadre[$ii]['diasvencimiento'],
                'vancimientohabilitado'=>$matrizmadre[$ii]['vancimientohabilitado'],
                'relacion_caja'=>$matrizmadre[$ii]['relacion_caja'],
                'volumen'=>(float)$matrizmadre[$ii]['volumen'],
                'bultos'=>(int)$matrizmadre[$ii]["bultos"],
                'peso'=>(float)$matrizmadre[$ii]["peso"],
                'pallet'=>$matrizmadre[$ii]['pallet'],
                'temperatura'=>$matrizmadre[$ii]['temperatura'],
                'modelo'=>$matrizmadre[$ii]['modelo'],
                'marca'=>$matrizmadre[$ii]['marca'],
                'color_vehiculo'=>$matrizmadre[$ii]['color_vehiculo'],
                'observaciones'=>$matrizmadre[$ii]['observaciones'],
                'idalmacendetalle'=>(int)$matrizmadre[$ii]['idalmacendetalle'],
                'ubicacionalmacencorto'=>$matrizmadre[$ii]['ubicacionalmacencorto'],
                'ubicacionalmacen'=>$matrizmadre[$ii]['ubicacionalmacen'],
                'orden'=>(int)$matrizmadre[$ii]['orden'],
                'tipoalmacendetalle'=>$matrizmadre[$ii]['tipoalmacendetalle'],
                'categoriaalmacendetalle'=>$matrizmadre[$ii]['categoriaalmacendetalle'],
                'color'=>$matrizmadre[$ii]['color'],
                'referenciacolor'=>$matrizmadre[$ii]['referenciacolor'],
                'idreferenciacolor'=>$matrizmadre[$ii]['idreferenciacolor'],
                'fecha_ultima_salida'=>$matrizmadre[$ii]['fecha_ultima_salida'],
                'dias_por_vencer'=>$matrizmadre[$ii]['dias_por_vencer'],
                'dias_vencido'=>$matrizmadre[$ii]['dias_vencido'],
                'factor_conversion'=>$matrizmadre[$ii]['factor_conversion'],
                'cantidad_salida'=>$matrizmadre[$ii]['cantidad_salida'],
                'codigoembalaje_salida'=>$matrizmadre[$ii]['codigoembalaje_salida'],
                'partida'=>$matrizmadre[$ii]['partida'],
                'es_vehiculo'=>$matrizmadre[$ii]['es_vehiculo'],
                'salidaspendientes'=> json_decode($matrizmadre[$ii]["salidaspendientes"], true)
            );
        }
    }

    return $inventario;
}

function getPedidoData($idpedido,$conexion,$resumen=false){
    $pedido=[];
    $cantidadubicaciones=0;
    $result = $conexion->query("SELECT
        md5(t_pedido.idpedido) as idpedido,
        t_pedido.idalmacen,
        t_pedido.numero,
        t_pedido.gestion,
        CONCAT(t_pedido.numero,'/',t_pedido.gestion) as numeropedido,
        md5(t_pedido.idcliente) as idcliente,
        t_cliente.cliente,
        t_pedido.fecha,
        t_pedido.no_pedido,
        t_pedido.fecha_entrega,
        t_usuario.nombre,
        t_pedido.rubro,
        t_pedido.idusuario_revisado,
        t_usuario_revisado.nombre as nombre_revisado,
        t_pedido.nota_adicional
        FROM
        t_pedido
        LEFT JOIN t_cliente ON t_pedido.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario ON t_pedido.idusuario=t_usuario.idusuario
        LEFT JOIN t_usuario as t_usuario_revisado ON t_pedido.idusuario_revisado=t_usuario_revisado.idusuario
        WHERE
        md5(t_pedido.idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $pedidodetalle=[];
        $resultdetalle = $conexion->query("SELECT
            md5(idpedidodetalle) as idpedidodetalle,
            codigo,
            serie,
            descripcion,
            lote,
            unidadmedida
            FROM
            t_pedidodetalle
            WHERE 
            md5(idpedido)='$idpedido';");
        while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
            $pedidodisponibilidad=[];
            $cantidadubicacionesactual=0;
            $resultdisponibilidad = $conexion->query("select 
                md5(t_pedidodisponibilidad.idpedidodisponibilidad) as idpedidodisponibilidad,
                t_pedidodisponibilidad.idingresodetalle,
                t_pedidodisponibilidad.cantidad,
                t_pedidodisponibilidad.ubicacionalmacen,
                IFNULL(t_almacendetalle.sector,'S/U') as sector,
                t_pedidodisponibilidad.ppt,
                t_pedidodisponibilidad.fechavencimiento,
                t_pedidodisponibilidad.diasavencer,
                t_pedidodisponibilidad.lote,
                t_pedidodisponibilidad.fechaingreso
                from 
                t_pedidodisponibilidad
                LEFT JOIN t_almacendetalle ON t_pedidodisponibilidad.ubicacionalmacen=t_almacendetalle.nombre
                WHERE
                md5(t_pedidodisponibilidad.idpedidodetalle)='".$rowdetalle['idpedidodetalle']."'
                ORDER BY
                t_pedidodisponibilidad.idpedidodisponibilidad;");
            while ($rowdisponibilidad =  $resultdisponibilidad ->fetch(PDO::FETCH_ASSOC)){
                $cantidadubicacionesactual++;
                $pedidodisponibilidad[]=array(
                    'idpedidodisponibilidad'=>$rowdisponibilidad['idpedidodisponibilidad'],
                    'idingresodetalle'=>$rowdisponibilidad['idingresodetalle'],
                    'cantidad'=>(float)$rowdisponibilidad['cantidad'],
                    'ubicacionalmacen'=>$rowdisponibilidad['ubicacionalmacen'],
                    'sector'=>$rowdisponibilidad['sector'],
                    'ppt'=>$rowdisponibilidad['ppt'],
                    'fechavencimiento'=>$rowdisponibilidad['fechavencimiento'],
                    'diasavencer'=>$rowdisponibilidad['diasavencer'],
                    'lote'=>$rowdisponibilidad['lote'],
                    'fechaingreso'=>$rowdisponibilidad['fechaingreso']
                );
            }
            
            if($cantidadubicacionesactual>$cantidadubicaciones){
                $cantidadubicaciones=$cantidadubicacionesactual;
            }
            
            
            
            $pedidodetalle[]=array(
                'idpedidodetalle'=>$rowdetalle['idpedidodetalle'],
                'codigo'=>$rowdetalle['codigo'],
                'serie'=>$rowdetalle['serie'],
                'descripcion'=>$rowdetalle['descripcion'],
                'lote'=>$rowdetalle['lote'],
                'unidadmedida'=>$rowdetalle['unidadmedida'],
                'pedidodisponibilidad'=>$pedidodisponibilidad
            );
        }
        
        $pedidotienda=[];
        $resulttienda = $conexion->query("select 
            md5(t_pedidotienda.idpedidotienda) as idpedidotienda, 
            t_pedidotienda.tienda, 
            IFNULL(t_pedidotienda.no_pedido,t_pedido.no_pedido) as no_pedido,
            md5(IFNULL(t_pedidotienda_aux.idpedido,t_pedidotienda.idpedido)) as idpedido_origen,
            IFNULL(t_pedido_aux.fecha,t_pedido.fecha) as fecha_creacion,
            DAYOFWEEK(IFNULL(t_pedido_aux.fecha,t_pedido.fecha)) as dia_semana_creacion,
            t_pedido.fecha_entrega,
            (IF(CAST(t_pedido.fecha_entrega as DATE)>CAST(IFNULL(t_pedido_aux.fecha,t_pedido.fecha) as DATE),1,-1))*DAYOFWEEK(t_pedido.fecha_entrega) as dia_semana_entrega
            FROM 
            t_pedidotienda
            LEFT JOIN t_pedidotienda as t_pedidotienda_aux ON t_pedidotienda.idpedidotienda_aux=t_pedidotienda_aux.idpedidotienda
            LEFT JOIN t_pedido ON t_pedidotienda.idpedido=t_pedido.idpedido
            LEFT JOIN t_pedido as t_pedido_aux ON t_pedidotienda_aux.idpedido=t_pedido_aux.idpedido
            WHERE 
            md5(t_pedidotienda.idpedido)='$idpedido';");
        while ($rowtienda =  $resulttienda ->fetch(PDO::FETCH_ASSOC)){
            $pedidotienda[]=array(
                'idpedidotienda'=>$rowtienda['idpedidotienda'],
                'tienda'=>$rowtienda['tienda'],
                'no_pedido'=>$rowtienda['no_pedido'],
                'idpedido_origen'=>$rowtienda['idpedido_origen'],
                'fecha_creacion'=>$rowtienda['fecha_creacion'],
                'dia_semana_creacion'=>(int)$rowtienda['dia_semana_creacion'],
                'fecha_entrega'=>$rowtienda['fecha_entrega'],
                'dia_semana_entrega'=>(int)$rowtienda['dia_semana_entrega'],
            );
        }
        
        $pedidodetalletienda=[];
        $resultdetalletienda = $conexion->query("select idpedidotienda as idpedidotienda2, md5(idpediodetalletienda) as idpediodetalletienda, md5(idpedidodetalle) as idpedidodetalle, md5(idpedidotienda) as idpedidotienda, cantidad FROM t_pediodetalletienda WHERE idpedidotienda IN (select idpedidotienda FROM t_pedidotienda WHERE md5(idpedido)='$idpedido') ORDER BY idpedidotienda;");
        while ($rowdetalletienda =  $resultdetalletienda ->fetch(PDO::FETCH_ASSOC)){
            $pedidodetalletienda[]=array(
                'idpedidotienda2'=>$rowdetalletienda['idpedidotienda2'],
                'idpediodetalletienda'=>$rowdetalletienda['idpediodetalletienda'],
                'idpedidodetalle'=>$rowdetalletienda['idpedidodetalle'],
                'idpedidotienda'=>$rowdetalletienda['idpedidotienda'],
                'cantidad'=>(float)$rowdetalletienda['cantidad']
            );
        }
        
        $ubicaciones=[];
        for($ub=0;$ub<$cantidadubicaciones;$ub++){
            $ubicaciones[]=array(
                'ubicacion'=>$ub
            );
        }
        
        $salidas=[];
    
        $resultsalidas = $conexion->query("SELECT md5(idsalida) as idsalida FROM t_salida WHERE md5(idpedido)='$idpedido';");
        while ($rowsalidas =  $resultsalidas ->fetch(PDO::FETCH_ASSOC)){
            $salidas[]= getSalida($rowsalidas["idsalida"], $conexion, $resumen);
        }
        
        $preparacion=[];
    
        $resultpreparacion = $conexion->query("select 
            t_pedidopreparacion.idpedidopreparacion,
            t_pedidopreparacion.idpreparador,
            t_preparador.nombre as preparador,
            CONCAT('[',IFNULL(GROUP_CONCAT(CONCAT('{\"sector\": \"',t_pedidopreparacionsector.sector,'\"}') SEPARATOR ','),''),']') as sector,
            GROUP_CONCAT(t_pedidopreparacionsector.sector) as texto_sector,
            t_pedidopreparacion.hora_inicio,
            t_pedidopreparacion.hora_fin,
            t_pedidopreparacion.demora,
            IFNULL(t_pedidopreparacion.conforme,0) as conforme,
            IFNULL(t_pedidopreparacion.conforme2,0) as conforme2,
            IFNULL(t_pedidopreparacion.conforme3,0) as conforme3,
            t_pedidopreparacion.notas
            FROM 
            t_pedidopreparacion
            LEFT JOIN t_usuario as t_preparador ON t_pedidopreparacion.idpreparador=t_preparador.idusuario
            LEFT JOIN t_pedidopreparacionsector ON t_pedidopreparacion.idpedidopreparacion=t_pedidopreparacionsector.idpedidopreparacion
            WHERE
            md5(t_pedidopreparacion.idpedido)='$idpedido'
            GROUP BY
            t_pedidopreparacion.idpedidopreparacion,
            t_pedidopreparacion.idpreparador,
            t_preparador.nombre,
            t_pedidopreparacion.hora_inicio,
            t_pedidopreparacion.hora_fin,
            t_pedidopreparacion.demora,
            IFNULL(t_pedidopreparacion.conforme,0),
            t_pedidopreparacion.notas;");
        while ($rowpreparacion =  $resultpreparacion ->fetch(PDO::FETCH_ASSOC)){
            $preparacion[]= array(
                'idpedidopreparacion'=>(int)$rowpreparacion['idpedidopreparacion'],
                'idpreparador'=>(int)$rowpreparacion['idpreparador'],
                'preparador'=>$rowpreparacion['preparador'],
                'sector'=> json_decode($rowpreparacion['sector'],true),
                'texto_sector'=>$rowpreparacion['texto_sector'],
                'hora_inicio'=>$rowpreparacion['hora_inicio'],
                'hora_fin'=>$rowpreparacion['hora_fin'],
                'demora'=>$rowpreparacion['demora'],
                'conforme'=> boolval($rowpreparacion['conforme']),
                'conforme2'=> boolval($rowpreparacion['conforme2']),
                'conforme3'=> boolval($rowpreparacion['conforme3']),
                'notas'=> $rowpreparacion['notas']
            );
        }
        
        $pedidotabla=[];
        for($dp=0; $dp<count($pedidodetalle); $dp++){
            if(count($pedidodetalle[$dp]['pedidodisponibilidad'])>0){
                $total_disponibilidad=0;
                $total_item=0;
                for($pdd=0;$pdd<count($pedidodetalle[$dp]['pedidodisponibilidad']);$pdd++){
                    $pedidotabla[]=array(
                        'idpedidodetalle'=>$pedidodetalle[$dp]['idpedidodetalle'],
                        'codigo'=>$pedidodetalle[$dp]['codigo'],
                        'descripcion'=>$pedidodetalle[$dp]['descripcion'],
                        'serie'=>$pedidodetalle[$dp]['serie'],
                        'lote_ini'=>$pedidodetalle[$dp]['lote'],
                        'unidadmedida'=>$pedidodetalle[$dp]['unidadmedida'],
                        'idpedidodisponibilidad'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['idpedidodisponibilidad'],
                        'idingresodetalle'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['idingresodetalle'],
                        'ubicacion'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['ubicacionalmacen'],
                        'cantidad_disponible'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['cantidad'],
                        'saldo_disponible'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['cantidad'],
                        'ppt'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['ppt'],
                        'fechavencimiento'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['fechavencimiento'],
                        'lote'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['lote'],
                        'diasavencer'=>$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['diasavencer']
                    );
                    $total_disponibilidad=$total_disponibilidad+$pedidodetalle[$dp]['pedidodisponibilidad'][$pdd]['cantidad'];
                }
                
                for ($pdt = 0; $pdt < count($pedidodetalletienda); $pdt++){
                    if ($pedidodetalle[$dp]['idpedidodetalle'] == $pedidodetalletienda[$pdt]['idpedidodetalle']){
                        $total_item = $total_item + $pedidodetalletienda[$pdt]['cantidad'];
                    }
                }

                if ($total_disponibilidad < $total_item){
                    $pedidotabla[]=array(
                        'idpedidodetalle'=>$pedidodetalle[$dp]['idpedidodetalle'],
                        'codigo'=>$pedidodetalle[$dp]['codigo'],
                        'descripcion'=>$pedidodetalle[$dp]['descripcion'],
                        'serie'=>$pedidodetalle[$dp]['serie'],
                        'lote_ini'=>$pedidodetalle[$dp]['lote'],
                        'unidadmedida'=>$pedidodetalle[$dp]['unidadmedida'],
                        'idpedidodisponibilidad'=>null,
                        'idingresodetalle'=>null,
                        'ubicacion'=>'',
                        'cantidad_disponible'=>null,
                        'saldo_disponible'=>0,
                        'ppt'=>'',
                        'fechavencimiento'=>'',
                        'lote'=>'',
                        'diasavencer'=>null
                    );
                }


            }else{
                $pedidotabla[]=array(
                    'idpedidodetalle'=>$pedidodetalle[$dp]['idpedidodetalle'],
                    'codigo'=>$pedidodetalle[$dp]['codigo'],
                    'descripcion'=>$pedidodetalle[$dp]['descripcion'],
                    'serie'=>$pedidodetalle[$dp]['serie'],
                    'lote_ini'=>$pedidodetalle[$dp]['lote'],
                    'unidadmedida'=>$pedidodetalle[$dp]['unidadmedida'],
                    'idpedidodisponibilidad'=>null,
                    'idingresodetalle'=>null,
                    'ubicacion'=>'',
                    'cantidad_disponible'=>null,
                    'saldo_disponible'=>0,
                    'ppt'=>'',
                    'fechavencimiento'=>'',
                    'lote'=>'',
                    'diasavencer'=>null
                );
            }
        }

        for ($tt = 0; $tt < count($pedidotienda); $tt++){
            for($pd=0;$pd<count($pedidotabla);$pd++){
                $pedidotabla[$pd]["t_".$pedidotienda[$tt]["idpedidotienda"]]=null;
            }
        }

        $idpedidodetalle_aux=null;
        for ($pp = 0; $pp < count($pedidotabla); $pp++){
            if($idpedidodetalle_aux!=$pedidotabla[$pp]['idpedidodetalle']){
                for ($dd = 0; $dd < count($pedidodetalletienda); $dd++){
                    if ($pedidotabla[$pp]['idpedidodetalle'] == $pedidodetalletienda[$dd]['idpedidodetalle']){
                        $pedidotabla[$pp]['t_'.$pedidodetalletienda[$dd]['idpedidotienda']] = $pedidodetalletienda[$dd]['cantidad'];
                    }
                }
            }
            $idpedidodetalle_aux=$pedidotabla[$pp]['idpedidodetalle'];

        }
        
        for ($dd = 0; $dd < count($pedidotabla); $dd++){
            if ($pedidotabla[$dd]['idpedidodisponibilidad']!=null){
                for ($dt = 0; $dt < count($pedidotienda); $dt++){
                    if($pedidotabla[$dd]['t_'.$pedidotienda[$dt]['idpedidotienda']]>0){
                        if ($pedidotabla[$dd]['saldo_disponible']>=$pedidotabla[$dd]['t_'.$pedidotienda[$dt]['idpedidotienda']]){
                            $pedidotabla[$dd]['saldo_disponible']=$pedidotabla[$dd]['saldo_disponible']-$pedidotabla[$dd]['t_'.$pedidotienda[$dt]['idpedidotienda']];
                        }else{
                            $faltante=$pedidotabla[$dd]['t_'.$pedidotienda[$dt]['idpedidotienda']]-$pedidotabla[$dd]['saldo_disponible'];
                            $pedidotabla[$dd]['t_'.$pedidotienda[$dt]['idpedidotienda']]=$pedidotabla[$dd]['saldo_disponible'];
                            if(($dd+1)<=(count($pedidotabla)-1)){
                                if($pedidotabla[$dd]['idpedidodetalle']==$pedidotabla[$dd+1]['idpedidodetalle']){
                                    $pedidotabla[$dd+1]['t_'.$pedidotienda[$dt]['idpedidotienda']]=$faltante;
                                }
                            }
                            $pedidotabla[$dd]['saldo_disponible']=0;
                        }
                    }

                }
            }
        }
        
        for ($tt = 0; $tt < count($pedidotienda); $tt++){
            $total_pedido_tienda=0;
            $total_disponible_tienda=0;
            for ($pt = 0; $pt < count($pedidotabla); $pt++){
                $total_pedido_tienda=$total_pedido_tienda+(float)$pedidotabla[$pt]["t_".$pedidotienda[$tt]["idpedidotienda"]];
                if((float)$pedidotabla[$pt]["cantidad_disponible"]>0){
                    $total_disponible_tienda=$total_disponible_tienda+(float)$pedidotabla[$pt]["t_".$pedidotienda[$tt]["idpedidotienda"]];
                }
            }
            $pedidotienda[$tt]["total_pedido_tienda"]=$total_pedido_tienda;
            $pedidotienda[$tt]["total_disponible_tienda"]=$total_disponible_tienda;
        }

        $salidas_automaticas=[];
    
        $resultsalidas = $conexion->query("SELECT 
            md5(t_salida.idsalida) as idsalida, 
            CONCAT(t_salida.numero,'/',t_salida.gestion) as numero, 
            t_salida.almacen_destino, 
            t_salida.pedido_consolidado,
            CONCAT(t_pedido.numero,'/',t_pedido.gestion) as numero_pedido,
            IFNULL(t_salida.finalizado,0) as finalizado
            FROM 
            t_salida 
            LEFT JOIN t_pedido ON t_salida.idpedido=t_pedido.idpedido
            WHERE 
            md5(t_salida.idpedido_consolidado)='$idpedido';");
        while ($rowsalidas =  $resultsalidas ->fetch(PDO::FETCH_ASSOC)){
            $salidas_automaticas[]= array(
                'idsalida'=>$rowsalidas['idsalida'],
                'numero'=>$rowsalidas['numero'],
                'almacen_destino'=>$rowsalidas['almacen_destino'],
                'pedido_consolidado'=>$rowsalidas['pedido_consolidado'],
                'numero_pedido'=>$rowsalidas['numero_pedido'],
                'finalizado'=> boolval($rowsalidas['finalizado'])
            );
        }
        
        
        $pedido=array(
            'idpedido'=>$row['idpedido'],
            'idalmacen'=>$row['idalmacen'],
            'numero'=>(int)$row['numero'],
            'gestion'=>(int)$row['gestion'],
            'numeropedido'=>$row['numeropedido'],
            'idcliente'=>$row['idcliente'],
            'cliente'=>$row['cliente'],
            'fecha'=>$row['fecha'],
            'no_pedido'=>$row['no_pedido'],
            'fecha_entrega'=>$row['fecha_entrega'],
            'nombre'=>$row['nombre'],
            'rubro'=>$row['rubro'],
            'idusuario_revisado'=>$row['idusuario_revisado'],
            'nombre_revisado'=>$row['nombre_revisado'],
            'nota_adicional'=>$row['nota_adicional'],
            'pedidodetalle'=>$pedidodetalle,
            'pedidotienda'=>$pedidotienda,
            'pedidodetalletienda'=>$pedidodetalletienda,
            //'pedidodisponibilidad'=>$pedidodisponibilidad,
            'ubicaciones'=>$ubicaciones,
            'salidas'=>$salidas,
            'salidas_automaticas'=>$salidas_automaticas,
            'preparacion'=>$preparacion,
            'pedidotabla'=>$pedidotabla
        );
    }
    
    return $pedido;
}

function getDetalleTimbrado($idtimbrado, $fecha_inicio, $fecha_fin, $conexion){
    $detalle=[];
    
    $filtrofecha="";
    if($fecha_inicio=='null' && $fecha_fin<>'null'){
        $filtrofecha=" AND t_timbradodetalle.fecha<='$fecha_fin'";
    }
    if($fecha_inicio<>'null' && $fecha_fin=='null'){
        $filtrofecha=" AND t_timbradodetalle.fecha>='$fecha_inicio'";
    }
    if($fecha_inicio<>'null' && $fecha_fin<>'null'){
        $filtrofecha=" AND t_timbradodetalle.fecha BETWEEN '$fecha_inicio' AND '$fecha_fin'";
    }
    
    
    $resultdetalle = $conexion->query("SELECT 
        t_timbradodetalle.idtimbradodetalle,
        t_timbradoturno.timbradoturno,
        t_diasemana.diasemana,
        t_timbradodetalle.fecha,
        t_timbradodetalle.codigo_producto,
        t_timbradodetalle.sku,
        t_timbradodetalle.nro_tcf,
        t_timbradodetalle.factura_timbrada,
        t_timbradodetalle.cantidad_timbrado,
        IF(IFNULL(t_timbradodetalle.umalterna,0)=0,0,IFNULL(t_timbradodetalle.cantidad_timbrado,0)*IFNULL(t_timbradodetalle.umcompra,0)/t_timbradodetalle.umalterna) as cantidad_paquetes_timbrado,
        t_timbradodetalle.meta_timbrado,
        IF(t_timbradodetalle.meta_timbrado>0,t_timbradodetalle.cantidad_timbrado/t_timbradodetalle.meta_timbrado*100,NULL) as cumplimiento,
        t_timbradodetalle.umcompra,
        t_timbradodetalle.umalterna,
        t_timbradodetalle.cantidad_timbrado*t_timbradodetalle.umcompra as total_unidades,
        t_timbradodetalle.precio_timbrado,
        IF(t_timbradodetalle.umalterna>0,t_timbradodetalle.precio_timbrado/t_timbradodetalle.umalterna,NULL) as precio_por_timbre,
        t_timbradodetalle.metodo,
        t_timbradodetalle.precio_metodo,
        IF(t_timbradodetalle.umalterna>0,IFNULL(t_timbradodetalle.precio_timbrado/t_timbradodetalle.umalterna,0),0)+IFNULL(t_timbradodetalle.precio_metodo,0) as precio_total,
        t_timbradodetalle.cantidad_timbrado*t_timbradodetalle.umcompra*(IF(t_timbradodetalle.umalterna>0,IFNULL(t_timbradodetalle.precio_timbrado/t_timbradodetalle.umalterna,0),0)+IFNULL(t_timbradodetalle.precio_metodo,0)) as precio,
        t_timbradodetalle.observaciones,
        t_timbradodetalle.personal,
        t_timbradodetalle.lotes_permiso_senasag,
        t_timbradodetalle.faltantes_senasag,
        t_timbradodetalle.lote_senasag,
        t_timbradodetalle.faltante,
        t_timbradodetalle.lote_faltante,
        t_timbradodetalle.danados,
        t_timbradodetalle.lote_danados,
        t_timbradodetalle.quebrados,
        t_timbradodetalle.lote_quebrados,
        t_timbradodetalle.sin_tapa,
        t_timbradodetalle.lote_sin_tapa,
        t_timbradodetalle.borrosos,
        t_timbradodetalle.lote_borrosos,
        t_timbradodetalle.film,
        t_timbradodetalle.cinta,
        t_timbradodetalle.silicona,
        t_timbradodetalle.hora_hinicio,
        t_timbradodetalle.hora_fin,
        SEC_TO_TIME(
            IF(
                TIMESTAMPDIFF(MINUTE, t_timbradodetalle.hora_hinicio, t_timbradodetalle.hora_fin) < 0,
                (TIMESTAMPDIFF(MINUTE, t_timbradodetalle.hora_hinicio, t_timbradodetalle.hora_fin) + 1440) * 60,
                TIMESTAMPDIFF(MINUTE, t_timbradodetalle.hora_hinicio, t_timbradodetalle.hora_fin) * 60
            )
        ) AS horas_trabajadas,
        IFNULL(t_timbradodetalle.faltantes_senasag,0)+IFNULL(t_timbradodetalle.faltante,0)+IFNULL(t_timbradodetalle.danados,0)+IFNULL(t_timbradodetalle.quebrados,0)+IFNULL(t_timbradodetalle.sin_tapa,0) as timbres_sobrantes,
        t_timbradodetalle.no_se_cumplio_por,
        t_timbradodetalle.lotes_validos,
        t_timbradodetalle.lotes_adicionales,
        t_timbradodetalle.transportadora,
        t_timbradodetalle.total_unidades_timbradas,
        t_timbradodetalle.total_u_factura,
        t_timbradodetalle.carpicola_de_balde_20,
        t_timbradodetalle.clasificacion,
        t_timbradodetalle.abolladas,
        t_timbradodetalle.lote_abolladas,
        t_timbradodetalle.mojadas,
        t_timbradodetalle.lote_mojadas,
        t_timbradodetalle.mermadas,
        t_timbradodetalle.lote_mermadas,
        t_timbradodetalle.tapa_extra,
        t_timbradodetalle.lote_tapa_extra,
        t_timbradodetalle.legales_extra_portugues,
        t_timbradodetalle.lote_legales_extra,
        t_timbradodetalle.caja_extra,
        t_timbradodetalle.lote_caja_extra,
        t_timbradodetalle.sarro_leve,
        t_timbradodetalle.lote_sarro_leve,
        t_timbradodetalle.sarro_severo,
        t_timbradodetalle.lote_sarro_severo
        FROM 
        t_timbradodetalle
        LEFT JOIN t_timbradoturno ON t_timbradodetalle.idtimbradoturno=t_timbradoturno.idtimbradoturno
        LEFT JOIN t_diasemana ON t_timbradodetalle.iddiasemana=t_diasemana.iddiasemana
        WHERE
        t_timbradodetalle.idtimbrado=$idtimbrado
        AND t_timbradodetalle.deleted_at IS NULL
        $filtrofecha
        ORDER BY
        t_timbradodetalle.fecha DESC;");
    while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
        $detalle[]=array(
            'idtimbradodetalle'=>(int)$rowdetalle['idtimbradodetalle'],
            'timbradoturno'=>$rowdetalle['timbradoturno'],
