            'precio_total'=>$rowdetalle['precio_total'],
            'precio'=>$rowdetalle['precio'],
            'observaciones'=>$rowdetalle['observaciones'],
            'personal'=>$rowdetalle['personal'],
            'lotes_permiso_senasag'=>$rowdetalle['lotes_permiso_senasag'],
            'faltantes_senasag'=>$rowdetalle['faltantes_senasag'],
            'lote_senasag'=>$rowdetalle['lote_senasag'],
