function getDisponibilidadPedido($idpedido,$conexion){
    
    
    $conexion->query("DELETE FROM t_pedidodisponibilidad WHERE idpedidodetalle IN (SELECT idpedidodetalle FROM t_pedidodetalle WHERE md5(idpedido)='$idpedido');");
    
    $idcliente=0;
    $idcliente_md5='';
    $idalmacen=0;
    $fecha_entrega='';
    $result = $conexion->query("SELECT 
        idcliente,
        md5(idcliente) as idcliente_md5,
        idalmacen,
        IFNULL(fecha_entrega,CURRENT_DATE()) as fecha_entrega
        from 
        t_pedido
        WHERE 
        md5(idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idcliente=$row['idcliente'];
        $idcliente_md5=$row['idcliente_md5'];
        $idalmacen=$row['idalmacen'];
        $fecha_entrega=$row['fecha_entrega'];
    }
    
    $no_considerar=array();
    $result = $conexion->query("SELECT 
        idno_conf
        from 
        t_cliente_no_conf_no_considerar
        WHERE 
        idcliente='$idcliente';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        array_push($no_considerar, (int)$row['idno_conf']);
    }
    
    
    $inventario=getInventario($idcliente_md5, $idalmacen, date('Y-m-d'), $conexion, true, false,$fecha_entrega, false);
    $inventarioFiltrado=[];
    
    for($ii=0;$ii<count($inventario);$ii++){
        if((int)$inventario[$ii]['vancimientohabilitado']==1 && !is_numeric(strpos(strtoupper($inventario[$ii]['serie']), 'DEVOLUCION')) && !in_array((int)$inventario[$ii]['idno_conf'], $no_considerar)){
            $inventarioFiltrado[]=array(
                'idingresodetalle'=>$inventario[$ii]['idingresodetalle'],
                'codigo'=>$inventario[$ii]['codigo'],
                'codigoembalaje'=>$inventario[$ii]['codigoembalaje'],
                'cantidad'=>$inventario[$ii]['cantidad'],
                'ubicacionalmacen'=>$inventario[$ii]['ubicacionalmacen'],
                'relacion_caja'=>$inventario[$ii]['relacion_caja'],
                'orden'=>$inventario[$ii]['orden'],
                'lote'=>$inventario[$ii]['lote'],
                'fechavencimiento'=>$inventario[$ii]['fechavencimiento'],
                'diasavencer'=>$inventario[$ii]['diasavencer'],
                'fechaingreso'=>$inventario[$ii]['fechaingreso'],
                'serie'=>$inventario[$ii]['serie']
            );
        }
    }
    
    $sorted = array_orderby($inventarioFiltrado, 'fechavencimiento', SORT_ASC, 'fechaingreso', SORT_ASC, 'orden', SORT_ASC, 'ubicacionalmacen', SORT_ASC);
    
    $disponibilidad=[];
    
    $result = $conexion->query("select 
        t_pedidodetalle.idpedidodetalle,
        TRIM(LEADING '0' FROM t_pedidodetalle.codigo) as codigo,
        t_pedidodetalle.lote,
        t_pedidodetalle.unidadmedida,
        SUM(t_pediodetalletienda.cantidad) as cantidad
        FROM
        t_pedidodetalle
        LEFT JOIN t_pediodetalletienda ON t_pedidodetalle.idpedidodetalle=t_pediodetalletienda.idpedidodetalle
        WHERE
        md5(t_pedidodetalle.idpedido)='$idpedido'
        GROUP BY
        t_pedidodetalle.idpedidodetalle,
        t_pedidodetalle.codigo,
        t_pedidodetalle.lote,
        t_pedidodetalle.unidadmedida
        ORDER BY
        t_pediodetalletienda.idpedidotienda;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $cantidadtotal=0;
        $ubicaciones=[];
        $conexion->query("UPDATE t_pedidodetalle SET serie='' WHERE idpedidodetalle=".$row["idpedidodetalle"].";");
        for($ii=0;$ii<count($sorted);$ii++){
            if($row['codigo']==$sorted[$ii]['codigo'] && $row['unidadmedida']==$sorted[$ii]['codigoembalaje'] && $sorted[$ii]["cantidad"]>0 && ($row["lote"]=="" || $row["lote"]==$sorted[$ii]['lote'])){
                $agregar=true;
                if($agregar){
                    $cantidadtotal=$cantidadtotal+$sorted[$ii]["cantidad"];
                    
                    $fechavencimientog="NULL";
                    if($sorted[$ii]['fechavencimiento']<>null){
                        $fechavencimientog="'".$sorted[$ii]['fechavencimiento']."'";
                    }
                    
                    $diasavencerg="NULL";
                    if($sorted[$ii]['diasavencer']<>null){
                        $diasavencerg="'".$sorted[$ii]['diasavencer']."'";
                    }
                    
                    $conexion->query("INSERT INTO t_pedidodisponibilidad (idpedidodetalle,              idingresodetalle,                       cantidad,                       ubicacionalmacen,                          ppt,                                     fechavencimiento,   diasavencer,     lote,                       fechaingreso) 
                                                                  VALUES (".$row['idpedidodetalle'].",  ".$sorted[$ii]['idingresodetalle'].",   ".$sorted[$ii]['cantidad'].",   '".$sorted[$ii]['ubicacionalmacen']."',    '".$sorted[$ii]['relacion_caja']."',     $fechavencimientog, $diasavencerg,   '".$sorted[$ii]['lote']."', '".$sorted[$ii]['fechaingreso']."');");
                    
                    $conexion->query("UPDATE t_pedidodetalle SET serie='".$sorted[$ii]['serie']."' WHERE idpedidodetalle=".$row["idpedidodetalle"].";");
                    
                    $ubicaciones[]=array(
                        'idingresodetalle'=>$sorted[$ii]['idingresodetalle'],
                        'cantidad'=>(float)$sorted[$ii]['cantidad'],
                        'ubicacionalmacen'=>$sorted[$ii]['ubicacionalmacen'],
                        'fechavencimiento'=>$sorted[$ii]['fechavencimiento'],
                        'lote'=>$sorted[$ii]['lote'],
                        'query'=>"INSERT INTO t_pedidodisponibilidad (idpedidodetalle,              idingresodetalle,                       cantidad,                       ubicacionalmacen,                          fechavencimiento,   lote,                       fechaingreso) VALUES (".$row['idpedidodetalle'].",  ".$sorted[$ii]['idingresodetalle'].",   ".$sorted[$ii]['cantidad'].",   '".$sorted[$ii]['ubicacionalmacen']."',    $fechavencimientog, '".$sorted[$ii]['lote']."', '".$sorted[$ii]['fechaingreso']."');"
                    );
                    
                    
                    if($cantidadtotal>=$row['cantidad']){
                        break;
                    }
                }
            }
        }
        
        $disponibilidad[]=array(
            'idpedidodetalle'=>(int)$row['idpedidodetalle'],
            'codigo'=>$row['codigo'],
            'cantidad'=>$row['cantidad'],
            'ubicaciones'=>$ubicaciones
        );
    }
    
    
    return $disponibilidad;
}

function generarActaPedido($idpedido, $conexion, $membretado = false){
    
    $pedido= getPedidoData($idpedido, $conexion, false);
    
    $result = $conexion->query("select 
        t_cliente.idempresa
        FROM
        t_pedido
        LEFT JOIN t_cliente ON t_pedido.idcliente=t_cliente.idcliente
        WHERE
        md5(t_pedido.idpedido)='$idpedido';");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $idempresa=$row['idempresa'];
    }
    
    
    $reader = new \PhpOffice\PhpSpreadsheet\Reader\Xlsx();
    $spreadsheet = $reader->load('../app/files/ActaPedido.xlsx');


    $worksheet = $spreadsheet->getActiveSheet();

    $worksheet->getCell('C4')->setValue($pedido["numeropedido"]);
    $worksheet->getCell('C5')->setValue($pedido["cliente"]);
    $worksheet->getCell('C6')->setValue(date_format(date_create($pedido["fecha"]),"d/m/Y"));
    
    
    $styleArray = [
        'font' => [
            'bold' => true,
            'color' => array('rgb' => 'FFFFFF'),
        ],
        'borders' => [
            'top' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'left' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'right' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'bottom' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ]
        ],
        'fill' => [
            'fillType' => \PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID,
            'startColor' => [
                'argb' => '4472C4',
            ]
        ],
    ];
    
    $styleArrayYellow = [
        'font' => [
            'bold' => true,
            'color' => array('rgb' => 'FF0000'),
        ],
        'borders' => [
            'top' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'left' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'right' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'bottom' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ]
        ],
        'fill' => [
            'fillType' => \PhpOffice\PhpSpreadsheet\Style\Fill::FILL_SOLID,
            'startColor' => [
                'argb' => 'FFFF00',
            ]
        ],
    ];
    
    $styleArrayBorders = [
        'borders' => [
            'top' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'left' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'right' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ],
            'bottom' => [
                'borderStyle' => \PhpOffice\PhpSpreadsheet\Style\Border::BORDER_THIN,
            ]
        ]
    ];
    
    $pedidotienda=$pedido["pedidotienda"] ?? [];
    
    for($tie=0;$tie<count($pedidotienda);$tie++){
        $datocabecera=$pedidotienda[$tie]["tienda"];
        if($pedidotienda[$tie]["no_pedido"]<>'' && $pedidotienda[$tie]["no_pedido"]<>null){
            $datocabecera=$pedidotienda[$tie]["no_pedido"]."\n".$pedidotienda[$tie]["tienda"];
        }
        $worksheet->getCell(convert_n2s($tie+6).'8')->setValue($datocabecera);
        $worksheet->getStyle(convert_n2s($tie+6).'8')->getAlignment()->setWrapText(true);
        $worksheet->getColumnDimension(convert_n2s($tie+6))->setWidth(20);
        $worksheet->getStyle(convert_n2s($tie+6).'8')->applyFromArray($styleArray);
    }
    
    
    $worksheet->getCell(convert_n2s(count($pedidotienda)+6).'8')->setValue("Total");
    $worksheet->getColumnDimension(convert_n2s(count($pedidotienda)+6))->setWidth(11);
    $worksheet->getStyle(convert_n2s(count($pedidotienda)+6).'8')->applyFromArray($styleArray);
    
    for($ubi=0;$ubi<1;$ubi++){
        $posicion1=count($pedidotienda)+6+(($ubi+1)*5-4);
        $posicion2=count($pedidotienda)+6+(($ubi+1)*5-3);
        $posicion3=count($pedidotienda)+6+(($ubi+1)*5-2);
        $posicion4=count($pedidotienda)+6+(($ubi+1)*5-1);
        $posicion5=count($pedidotienda)+6+(($ubi+1)*5-0);
        $worksheet->getCell(convert_n2s($posicion1).'8')->setValue("Ubicacion");
        $worksheet->getColumnDimension(convert_n2s($posicion1))->setWidth(14);
        $worksheet->getStyle(convert_n2s($posicion1).'8')->applyFromArray($styleArrayYellow);
        $worksheet->getCell(convert_n2s($posicion2).'8')->setValue("Cantidad");
        $worksheet->getColumnDimension(convert_n2s($posicion2))->setWidth(14);
        $worksheet->getStyle(convert_n2s($posicion2).'8')->applyFromArray($styleArrayYellow);
        $worksheet->getCell(convert_n2s($posicion3).'8')->setValue("PPT");
        $worksheet->getColumnDimension(convert_n2s($posicion3))->setWidth(14);
        $worksheet->getStyle(convert_n2s($posicion3).'8')->applyFromArray($styleArrayYellow);
        $worksheet->getCell(convert_n2s($posicion4).'8')->setValue("Vencimiento");
