    $anchototal=count($pedidotienda)+6+1*5;
    //$worksheet->getCell('A1')->setValue($anchototal);
    //$worksheet->getCell('B1')->setValue(base_convert_alpha($anchototal,10,26));
    
    $worksheet->mergeCells('D2:'.convert_n2s($anchototal-2).'2');
    $worksheet->getStyle('D2:'.convert_n2s($anchototal-2).'2')->applyFromArray($styleArrayBorders);
    
    $worksheet->mergeCells(convert_n2s($anchototal-1).'2:'.convert_n2s($anchototal).'2');
