    $worksheet->getStyle(convert_n2s($anchototal-1).'2:'.convert_n2s($anchototal).'2')->applyFromArray($styleArrayBorders);
    $worksheet->getStyle(convert_n2s($anchototal-1).'2')->getAlignment()->setHorizontal(\PhpOffice\PhpSpreadsheet\Style\Alignment::HORIZONTAL_CENTER);
    $worksheet->getStyle(convert_n2s($anchototal-1).'2')->getAlignment()->setVertical(\PhpOffice\PhpSpreadsheet\Style\Alignment::VERTICAL_CENTER);
    
    $pedidotabla=$pedido["pedidotabla"] ?? [];
    
    $fila=8;
    for($dt=0;$dt<count($pedidotabla);$dt++){
        $fila++;
        $total=0;
