function getDataInventarioFisico($idinventariofisico, $incluir_almacen_encontrado, $conexion){
    $inventariofisico=array();
    $result = $conexion->query("SELECT
        t_inventariofisico.idinventariofisico,
        t_inventariofisico.idcliente,
        t_inventariofisico.idalmacen,
        t_almacen.codigo_almacen,
        t_almacen.almacen,
        md5(t_inventariofisico.idcliente) as idcliente_cifrado,
        t_cliente.cliente,
        IFNULL(t_inventariofisico.es_vehiculo,0) as es_vehiculo,
        t_inventariofisico.fecha,
        IFNULL(t_inventariofisico.idasignado,t_inventariofisico.idusuario_fin_inventario) as idasignado,
        IFNULL(t_asignado.nombre,t_asignado_vehiculos.nombre) as asignado,
        IFNULL(t_inventariofisico.idapoyo,t_inventariofisico.idusuario_conteo) as idapoyo,
        IFNULL(t_apoyo.nombre,t_apoyo_vehiculos.nombre) as apoyo,
        t_inventariofisico.fecha_inicio,
        t_inventariofisico.fecha_fin,
        t_inventariofisico.idstatus,
        t_inventariofisico.categoria,
        t_inventariofisico.fecha_inicio_conteo,
        t_inventariofisico.fecha_fin_conteo,
        t_inventariofisico.fecha_fin_inventario
        FROM
        t_inventariofisico
        LEFT JOIN t_cliente ON t_inventariofisico.idcliente=t_cliente.idcliente
        LEFT JOIN t_usuario as t_asignado ON t_inventariofisico.idasignado=t_asignado.idusuario
        LEFT JOIN t_usuario as t_apoyo ON t_inventariofisico.idapoyo=t_apoyo.idusuario
        LEFT JOIN t_almacen ON t_inventariofisico.idalmacen=t_almacen.idalmacen
        LEFT JOIN t_usuario as t_asignado_vehiculos ON t_inventariofisico.idusuario_fin_inventario=t_asignado_vehiculos.idusuario
        LEFT JOIN t_usuario as t_apoyo_vehiculos ON t_inventariofisico.idusuario_conteo=t_apoyo_vehiculos.idusuario
        WHERE
        t_inventariofisico.idinventariofisico=$idinventariofisico;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $detalleitems=getDetalleInventarioFisico($idinventariofisico, $incluir_almacen_encontrado, $conexion);
        
        
        
        $pendientes=0;
        $encontrados=0;
        $sobrantes=0;
        $faltantes=0;
        $estado=false;
        for($dd=0;$dd<count($detalleitems);$dd++){
            if($row["fecha_inicio_conteo"]<>''){
                if((float)$detalleitems[$dd]["cantidad"]==(float)$detalleitems[$dd]["cantidad_real"]){
                    $encontrados++;
                    $estado=true;
                }
                if((float)$detalleitems[$dd]["cantidad"]>(float)$detalleitems[$dd]["cantidad_real"]){
                    if($row["fecha_fin_conteo"]<>''){
                        $faltantes++;
                        $estado=true;
                    }else{
                        $pendientes++;
                        $estado=true;
                    }
                }
                if((float)$detalleitems[$dd]["cantidad"]<(float)$detalleitems[$dd]["cantidad_real"]){
                    $sobrantes++;
                    $estado=true;
                }
                if(!$estado){
                    $pendientes++;
                }
            }else{
                $pendientes++;
            }
                
        }
        
        
        $inventariofisico=array(
            'idinventariofisico'=>(int)$row['idinventariofisico'],
            'idalmacen'=>(int)$row['idalmacen'],
            'idcliente'=>(int)$row['idcliente'],
            'codigo_almacen'=>$row['codigo_almacen'],
            'almacen'=>$row['almacen'],
            'idcliente_cifrado'=>$row['idcliente_cifrado'],
            'cliente'=>$row['cliente'],
            'fecha'=>$row['fecha'],
            'es_vehiculo'=> boolval($row['es_vehiculo']),
            'idasignado'=>$row['idasignado'],
            'asignado'=>$row['asignado'],
            'idapoyo'=>$row['idapoyo'],
            'apoyo'=>$row['apoyo'],
            'fecha_inicio'=>$row['fecha_inicio'],
            'fecha_fin'=>$row['fecha_fin'],
            'idstatus'=>$row['idstatus'],
            'categoria'=>$row['categoria'],
            'fecha_inicio_conteo'=>$row['fecha_inicio_conteo'],
            'fecha_fin_conteo'=>$row['fecha_fin_conteo'],
            'fecha_fin_inventario'=>$row['fecha_fin_inventario'],
            'pendientes'=>$pendientes,
            'encontrados'=>$encontrados,
            'sobrantes'=>$sobrantes,
            'faltantes'=>$faltantes,
            'detalle'=> $detalleitems
        );
    }
    
    return $inventariofisico;
}

function getDetalleInventarioFisico($idinventariofisico, $incluir_almacen_encontrado, $conexion){
    $detalle=[];
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_archivos;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_archivos (idinventariofisicodetalle INT, archivos TEXT);");
    $conexion->query("INSERT INTO tmp_archivos (idinventariofisicodetalle, archivos)
        select 
        t_inventariofisicodetallearchivo.idinventariofisicodetalle,
        GROUP_CONCAT(CONCAT('{\"idinventariofisicodetallearchivo\": ',t_inventariofisicodetallearchivo.idinventariofisicodetallearchivo,', \"inventariofisicodetallearchivo\": \"',IFNULL(t_inventariofisicodetallearchivo.inventariofisicodetallearchivo,''),'\"}') SEPARATOR ',') as archivos
        FROM 
        t_inventariofisicodetallearchivo
        LEFT JOIN t_inventariofisicodetalle ON t_inventariofisicodetallearchivo.idinventariofisicodetalle=t_inventariofisicodetalle.idinventariofisicodetalle
        WHERE
        t_inventariofisicodetalle.idinventariofisico=$idinventariofisico
        GROUP BY
        t_inventariofisicodetallearchivo.idinventariofisicodetalle;");
    $conexion->query("ALTER TABLE tmp_archivos ADD INDEX idinventariofisicodetalle (idinventariofisicodetalle);");
    
    $conexion->query("DROP TEMPORARY TABLE IF EXISTS tmp_imagenes;");
    $conexion->query("CREATE TEMPORARY TABLE tmp_imagenes (idinventariofisicodetalle INT, cantidad_imagenes INT);");
    $conexion->query("INSERT INTO tmp_imagenes (idinventariofisicodetalle, cantidad_imagenes)
        select 
        t_inventariofisicodetalle.idinventariofisicodetalle,
        COUNT(t_inventariofisicoconteoimagen.idinventariofisicoconteoimagen) as cantidad_imagenes
        FROM 
        t_inventariofisicoconteoimagen
        LEFT JOIN t_inventariofisicoconteo ON t_inventariofisicoconteoimagen.idinventariofisicoconteo=t_inventariofisicoconteo.idinventariofisicoconteo
        LEFT JOIN t_inventariofisicodetalle ON t_inventariofisicoconteo.idinventariofisico=t_inventariofisicodetalle.idinventariofisico AND t_inventariofisicoconteo.serie=t_inventariofisicodetalle.serie
        WHERE
        t_inventariofisicoconteo.idinventariofisico=$idinventariofisico
        GROUP BY
        t_inventariofisicodetalle.idinventariofisicodetalle;");
    $conexion->query("ALTER TABLE tmp_imagenes ADD INDEX idinventariofisicodetalle (idinventariofisicodetalle);");
    
    if($incluir_almacen_encontrado){
        $query="WITH tmp_almacenes as (
            SELECT
            t_almacen.codigo_almacen,
            t_almacen.almacen,
            t_inventariofisicoconteo.serie
            FROM
            t_inventariofisico
            LEFT JOIN t_inventariofisico as tmp_inventariofisico_general ON t_inventariofisico.idcliente=tmp_inventariofisico_general.idcliente AND t_inventariofisico.fecha=tmp_inventariofisico_general.fecha AND tmp_inventariofisico_general.deleted_at IS NULL
            LEFT JOIN t_inventariofisicoconteo ON tmp_inventariofisico_general.idinventariofisico=t_inventariofisicoconteo.idinventariofisico
            LEFT JOIN t_almacen ON tmp_inventariofisico_general.idalmacen=t_almacen.idalmacen
            WHERE
            t_inventariofisico.idinventariofisico=$idinventariofisico
            AND IFNULL(t_inventariofisicoconteo.serie,'')<>''
            AND t_inventariofisico.deleted_at IS NULL)
            select
            t_inventariofisicodetalle.idinventariofisico,
            t_inventariofisicodetalle.idinventariofisicodetalle,
            t_inventariofisicodetalle.codigo,
            t_inventariofisicodetalle.serie,
            t_inventariofisicodetalle.descripcion,
            t_inventariofisicodetalle.ubicacion,
            t_inventariofisicodetalle.categoria,
            t_inventariofisicodetalle.cantidad,
            t_inventariofisicodetalle.cantidad_real,
            IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0) as diferencia,
            t_inventariofisicodetalle.embalaje,
            t_inventariofisicodetalle.lote,
            t_inventariofisicodetalle.fecha_vencimiento,
            t_inventariofisicodetalle.observaciones,
            t_inventariofisico.fecha_inicio_conteo,
            t_inventariofisico.fecha_fin_conteo,
            t_inventariofisicoconteo.idinventariofisicoconteo,
            t_inventariofisicodetalle.idinventariofisicoetiqueta,
            t_inventariofisicoetiqueta.inventariofisicoetiqueta,
            tmp_almacenes.codigo_almacen,
            tmp_almacenes.almacen,
            tmp_usuario_conteo.nombre as usuario_conteo,
            CONCAT('[',IFNULL(tmp_archivos.archivos,''),']') as archivos,
            IFNULL(tmp_imagenes.cantidad_imagenes,0) as cantidad_imagenes
            FROM
            t_inventariofisicodetalle
            LEFT JOIN t_inventariofisico ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisico.idinventariofisico
            LEFT JOIN t_inventariofisicoconteo ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisicoconteo.idinventariofisico AND t_inventariofisicodetalle.serie=t_inventariofisicoconteo.serie
            LEFT JOIN tmp_archivos ON t_inventariofisicodetalle.idinventariofisicodetalle=tmp_archivos.idinventariofisicodetalle
            LEFT JOIN tmp_imagenes ON t_inventariofisicodetalle.idinventariofisicodetalle=tmp_imagenes.idinventariofisicodetalle
            LEFT JOIN t_inventariofisicoetiqueta ON t_inventariofisicodetalle.idinventariofisicoetiqueta=t_inventariofisicoetiqueta.idinventariofisicoetiqueta
            LEFT JOIN tmp_almacenes ON t_inventariofisicodetalle.serie=tmp_almacenes.serie -- AND (IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0))>=0
            LEFT JOIN t_usuario as tmp_usuario_conteo ON t_inventariofisicoconteo.idusuario=tmp_usuario_conteo.idusuario
            WHERE
            t_inventariofisicodetalle.idinventariofisico=$idinventariofisico;";
    }else{
        $query="select
            t_inventariofisicodetalle.idinventariofisico,
            t_inventariofisicodetalle.idinventariofisicodetalle,
            t_inventariofisicodetalle.codigo,
            t_inventariofisicodetalle.serie,
            t_inventariofisicodetalle.descripcion,
            t_inventariofisicodetalle.ubicacion,
            t_inventariofisicodetalle.categoria,
            t_inventariofisicodetalle.cantidad,
            t_inventariofisicodetalle.cantidad_real,
            IFNULL(t_inventariofisicodetalle.cantidad_real,0)-IFNULL(t_inventariofisicodetalle.cantidad,0) as diferencia,
            t_inventariofisicodetalle.embalaje,
            t_inventariofisicodetalle.lote,
            t_inventariofisicodetalle.fecha_vencimiento,
            t_inventariofisicodetalle.observaciones,
            t_inventariofisico.fecha_inicio_conteo,
            t_inventariofisico.fecha_fin_conteo,
            t_inventariofisicoconteo.idinventariofisicoconteo,
            t_inventariofisicodetalle.idinventariofisicoetiqueta,
            t_inventariofisicoetiqueta.inventariofisicoetiqueta,
            NULL as codigo_almacen,
            NULL as almacen,
            tmp_usuario_conteo.nombre as usuario_conteo,
            CONCAT('[',IFNULL(tmp_archivos.archivos,''),']') as archivos,
            IFNULL(tmp_imagenes.cantidad_imagenes,0) as cantidad_imagenes
            FROM
            t_inventariofisicodetalle
            LEFT JOIN t_inventariofisico ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisico.idinventariofisico
            LEFT JOIN t_inventariofisicoconteo ON t_inventariofisicodetalle.idinventariofisico=t_inventariofisicoconteo.idinventariofisico AND t_inventariofisicodetalle.serie=t_inventariofisicoconteo.serie
            LEFT JOIN tmp_archivos ON t_inventariofisicodetalle.idinventariofisicodetalle=tmp_archivos.idinventariofisicodetalle
            LEFT JOIN tmp_imagenes ON t_inventariofisicodetalle.idinventariofisicodetalle=tmp_imagenes.idinventariofisicodetalle
            LEFT JOIN t_inventariofisicoetiqueta ON t_inventariofisicodetalle.idinventariofisicoetiqueta=t_inventariofisicoetiqueta.idinventariofisicoetiqueta
            LEFT JOIN t_usuario as tmp_usuario_conteo ON t_inventariofisicoconteo.idusuario=tmp_usuario_conteo.idusuario
            WHERE
            t_inventariofisicodetalle.idinventariofisico=$idinventariofisico;";
    }
    
    
    $resultdetalle = $conexion->query($query);
    while ($rowdetalle =  $resultdetalle ->fetch(PDO::FETCH_ASSOC)){
        $existe=false;
        $estado_conteo="";
        $idestado_conteo=null;
        if($rowdetalle['fecha_inicio_conteo']<>''){
            if((float)$rowdetalle['diferencia']==0){
                $estado_conteo="ENCONTRADO";
                $idestado_conteo=1;
            }
            if((float)$rowdetalle['diferencia']>0){
                $estado_conteo="SOBRANTE";
                $idestado_conteo=2;
            }
            if((float)$rowdetalle['diferencia']<0){
                if($rowdetalle['fecha_fin_conteo']<>''){
                    $estado_conteo="FALTANTE";
                    $idestado_conteo=3;
                }else{
                    $estado_conteo="PENDIENTE";
                    $idestado_conteo=4;
                }
                    
            }
        }
        $detalle[]=array(
            'idinventariofisico'=>(int)$rowdetalle['idinventariofisico'],
            'idinventariofisicodetalle'=>(int)$rowdetalle['idinventariofisicodetalle'],
            'codigo'=>$rowdetalle['codigo'],
            'serie'=>$rowdetalle['serie'],
            'descripcion'=>$rowdetalle['descripcion'],
            'ubicacion'=>$rowdetalle['ubicacion'],
            'categoria'=>$rowdetalle['categoria'],
            'cantidad'=>(float)$rowdetalle['cantidad'],
            'cantidad_real'=>(float)$rowdetalle['cantidad_real'],
            'diferencia'=>(float)$rowdetalle['diferencia'],
            'embalaje'=>$rowdetalle['embalaje'],
            'lote'=>$rowdetalle['lote'],
            'fecha_vencimiento'=>$rowdetalle['fecha_vencimiento'],
            'observaciones'=>$rowdetalle['observaciones'],
            'existe'=>$existe,
            'estado_conteo'=>$estado_conteo,
            'idestado_conteo'=>$idestado_conteo,
            'idinventariofisicoetiqueta'=>$rowdetalle['idinventariofisicoetiqueta'],
            'inventariofisicoetiqueta'=>$rowdetalle['inventariofisicoetiqueta'],
            'idinventariofisicoconteo'=>(int)$rowdetalle['idinventariofisicoconteo'],
            'codigo_almacen'=>$rowdetalle['codigo_almacen'],
            'almacen'=>$rowdetalle['almacen'],
            'usuario_conteo'=>$rowdetalle['usuario_conteo'],
            'cantidad_imagenes'=> (int)$rowdetalle['cantidad_imagenes'],
            'archivos'=> json_decode($rowdetalle["archivos"], true)
        );
    }
    
    return $detalle;
}

function getImagenesInventarioFisicoConteo($idinventariofisicoconteo, $conexion){
    $imagenes=[];
    $resultimagenes = $conexion->query("SELECT
        t_inventariofisicoconteoimagen.idinventariofisicoconteoimagen,
        t_inventariofisicoconteoimagen.imagen,
        t_cliente.idempresa
        FROM
        t_inventariofisicoconteoimagen
        LEFT JOIN t_inventariofisicoconteo ON t_inventariofisicoconteoimagen.idinventariofisicoconteo=t_inventariofisicoconteo.idinventariofisicoconteo
        LEFT JOIN t_inventariofisico ON t_inventariofisicoconteo.idinventariofisico=t_inventariofisico.idinventariofisico
        LEFT JOIN t_cliente ON t_inventariofisico.idcliente=t_cliente.idcliente
        WHERE
        t_inventariofisicoconteoimagen.idinventariofisicoconteo='$idinventariofisicoconteo';");
    while ($rowimagenes =  $resultimagenes ->fetch(PDO::FETCH_ASSOC)){
        $filePath = folder_files.$rowimagenes["idempresa"].DIRECTORY_SEPARATOR.'almacen/inventario_fisico/conteo/imagenes/'.$idinventariofisicoconteo.'/'.$rowimagenes["imagen"];
        if (file_exists($filePath)) {
            $imageData = file_get_contents($filePath);
            $mimeType = mime_content_type($filePath); // e.g., image/png, image/jpeg
            $base64 = base64_encode($imageData);
            $fileBase64 = "data:$mimeType;base64,$base64";
            $imagenes[]=array(
                'idinventariofisicoconteoimagen'=>(int)$rowimagenes['idinventariofisicoconteoimagen'],
                'itemImageSrc'=>$fileBase64
            );
        }else{
            $fileBase64=null;
        }
    }
    
    return $imagenes;
}
    
