function array_orderby(){
    $args = func_get_args();
    $data = array_shift($args);
    foreach ($args as $n => $field) {
        if (is_string($field)) {
            $tmp = array();
            foreach ($data as $key => $row)
                $tmp[$key] = $row[$field];
            $args[$n] = $tmp;
            }
    }
    $args[] = &$data;
    call_user_func_array('array_multisort', $args);
    return array_pop($args);
}

function base_convert_alpha(  $str,  $from,  $to  ){
    $r = range( 'A', 'Z' );
    $clean = str_replace( $r, array_keys($r), $str );
    return base_convert( $clean, $from, $to );
}

function convert_n2s($numero){
    $letter = 'A';
  	for ($i = 1; $i <= $numero; ++$i) {
      	++$letter;
  	}
  	return $letter;

}

function isValidDate($date, $format = 'Y-m-d') {
    $dateTime = DateTime::createFromFormat($format, $date);
    return $dateTime && $dateTime->format($format) === $date;
}

function savePedidoLog($idusuario, $url, $cuerpo, $respuesta, $conexion){
    $query="INSERT INTO t_pedidolog (fecha,               idusuario,  url,    cuerpo,     respuesta) VALUES 
                                    (CURRENT_TIMESTAMP(), $idusuario, '$url', :cuerpo,    :respuesta);";
    $stmt = $conexion->prepare($query);
    $stmt->bindParam(':cuerpo', $cuerpo);
    $stmt->bindParam(':respuesta', $respuesta);
    
    $stmt->execute();
    
}

function generarAteGasInventario($idate_gas, $idate_gas_etapa, $conexion){
    
    $filtro="t_ate_gas_etapa.idate_gas=$idate_gas";
    if((int)$idate_gas_etapa>0){
        $filtro="t_ate_gas_etapa.idate_gas_etapa=$idate_gas_etapa";
    }
    
    $result = $conexion->query("SELECT
        DISTINCT
        t_ate_gas.chasis,
        t_ate_gas.marca,
        t_ate_gas.modelo,
        t_ate_gas.color,
        t_ate_gas.configuracion,
        t_ate_gas.tipo_tanque,
        t_cliente.idempresa
        FROM
        t_ate_gas
        LEFT JOIN t_ate_gas_etapa ON t_ate_gas.idate_gas=t_ate_gas_etapa.idate_gas
        LEFT JOIN t_cliente ON t_ate_gas.idcliente=t_cliente.idcliente
        WHERE
        $filtro;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $chasis=$row["chasis"];
        $marca=$row["marca"];
        $modelo=$row["modelo"];
        $color=$row["color"];
        $configuracion=$row["configuracion"];
        $tipo_tanque=$row["tipo_tanque"];
        $idempresa=$row["idempresa"];
    }
    
    $creacion=new Carpetas();
    $respuesta=$creacion->procesarCarpeta($idempresa);

    $danios=[];
    $result = $conexion->query("select * FROM t_danios_vehiculos;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $danios[]=array(
            'iddanios_vehiculos'=>$row['iddanios_vehiculos'],
            'danios_vehiculos'=>$row['danios_vehiculos']
        );
    }

    $html='';
    $contador=0;
    $result = $conexion->query("WITH tmp_ate_gas_etapa as (
        SELECT
        t_ate_gas_etapa.idate_gas_etapa,
        t_etapa.etapa,
        t_estado_etapa.estado_etapa,
        t_ate_gas_etapa.observaciones_inventario
        FROM
        t_ate_gas_etapa
        LEFT JOIN t_etapa ON t_ate_gas_etapa.idetapa=t_etapa.idetapa
        LEFT JOIN t_estado_etapa ON t_ate_gas_etapa.idestado_etapa=t_estado_etapa.idestado_etapa
        WHERE
        t_ate_gas_etapa.deteled_at IS NULL
        AND $filtro
        ORDER BY
        t_ate_gas_etapa.paso DESC
        ), tmp_cantidad_ate_gas_etapa as (
        SELECT 
        COUNT(idate_gas_etapa) as cantidad_ate_gas_etapa
        FROM
        tmp_ate_gas_etapa
        ), tmp_ate_gas_etapa_tiempos as (
        SELECT 
        t_ate_gas_etapa_tiempos.idate_gas_etapa,
        t_ate_gas_etapa_tiempos.idusuario,
        MIN(t_ate_gas_etapa_tiempos.inicio) as inicio,
        MAX(t_ate_gas_etapa_tiempos.fin) as fin,
        SUM(TIMESTAMPDIFF(SECOND, t_ate_gas_etapa_tiempos.inicio, IFNULL(t_ate_gas_etapa_tiempos.fin,CURRENT_TIMESTAMP()))) as tiempo
        FROM 
        t_ate_gas_etapa_tiempos
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_tiempos.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        WHERE
        t_ate_gas_etapa_tiempos.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_tiempos.idate_gas_etapa
        ), tmp_ate_gas_inventario as (
        SELECT
        t_ate_gas_etapa_inventario.idate_gas_etapa,
        JSON_ARRAYAGG(
            JSON_OBJECT(
                'iddanios_vehiculos', t_ate_gas_etapa_inventario.iddanios_vehiculos,
                'descripcion', t_ate_gas_etapa_inventario.descripcion
            )
        ) AS inventario
        FROM
        t_ate_gas_etapa_inventario
        INNER JOIN tmp_ate_gas_etapa ON t_ate_gas_etapa_inventario.idate_gas_etapa=tmp_ate_gas_etapa.idate_gas_etapa
        WHERE
        t_ate_gas_etapa_inventario.deleted_at IS NULL
        GROUP BY
        t_ate_gas_etapa_inventario.idate_gas_etapa
        )
        SELECT 
        tmp_ate_gas_etapa.idate_gas_etapa,
        tmp_ate_gas_etapa.etapa,
        tmp_ate_gas_etapa.estado_etapa,
        tmp_ate_gas_etapa.observaciones_inventario,
        tmp_ate_gas_etapa_tiempos.inicio,
        tmp_ate_gas_etapa_tiempos.fin,
        tmp_ate_gas_etapa_tiempos.tiempo,
        t_usuario.nombre as responsable,
        tmp_cantidad_ate_gas_etapa.cantidad_ate_gas_etapa,
        IFNULL(tmp_ate_gas_inventario.inventario,'[]') as inventario
        FROM 
        tmp_ate_gas_etapa
        LEFT JOIN tmp_ate_gas_etapa_tiempos ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_etapa_tiempos.idate_gas_etapa
        LEFT JOIN t_usuario ON tmp_ate_gas_etapa_tiempos.idusuario=t_usuario.idusuario
        LEFT JOIN tmp_ate_gas_inventario ON tmp_ate_gas_etapa.idate_gas_etapa=tmp_ate_gas_inventario.idate_gas_etapa
        JOIN tmp_cantidad_ate_gas_etapa;");
    while ($row =  $result ->fetch(PDO::FETCH_ASSOC)){
        $contador++;
        $html=$html.'
        <table border="0" cellspacing="0" cellpadding="3" width="100%" style="background-color: #2664eb">
            <tr>
                <td width="50%" style="padding-left: 20px" rowspan="4"><b><font style="font-family: Helvetica; font-size: 18pt; color: white">INVENTARIO ID '.$row["idate_gas_etapa"].'</font></b></td>
                <td width="50%"><font style="font-family: Helvetica; font-size: 12pt; color: white"><b>Etapa Actual:</b> '.$row["etapa"].'</font></td>
            </tr>
            <tr>
                <td width="50%"><font style="font-family: Helvetica; font-size: 12pt; color: white"><b>Fecha Inicio:</b> '.date("d/m/Y H:i", strtotime($row["inicio"])).'</font></td>
            </tr>
