function normalizarFechaExcel($valor)
{
    if ($valor === null) {
        return null;
    }

    $valor = trim((string)$valor);

    if ($valor === '') {
        return null;
    }

    /*
    |--------------------------------------------------------------------------
    | Fecha numérica interna de Excel
    |--------------------------------------------------------------------------
    |
    | Ejemplo: 45853
    |
    */
    if (is_numeric($valor)) {
        try {
            $fecha = Date::excelToDateTimeObject((float)$valor);

            return $fecha->format('Y-m-d');
        } catch (Throwable $e) {
            return null;
        }
    }

    /*
    |--------------------------------------------------------------------------
    | Formatos de texto permitidos
    |--------------------------------------------------------------------------
    */
    $formatos = [
        'Y-m-d',
        'Y/m/d',
        'd/m/Y',
        'd-m-Y',
        'd.m.Y',
        'm/d/Y',
        'Y-m-d H:i:s',
        'd/m/Y H:i:s',
        'd-m-Y H:i:s'
    ];

    foreach ($formatos as $formato) {

        $fecha = DateTime::createFromFormat('!' . $formato, $valor);
        $errores = DateTime::getLastErrors();

        /*
        DateTime::getLastErrors() puede devolver false cuando no existen
        advertencias ni errores.
        */
        $sinErrores = (
            $errores === false ||
            (
                $errores['warning_count'] === 0 &&
                $errores['error_count'] === 0
            )
        );

        if ($fecha !== false && $sinErrores) {
            return $fecha->format('Y-m-d');
        }
    }

    return null;
}
